export const recipes: CountryRecipe[] = [{"country":"th","id":"pad-thai","slug":"pad-thai","title":{"zh-TW":"經典泰式炒金邊粉","en":"Classic Bangkok Street Pad Thai","th":"ผัดไทยกุ้งสดต้นตำรับ","ja":"本場バンコクのパッタイ（タイ風焼きそば）","ko":"클래식 방콕 스트리트 팟타이"},"subtitle":{"zh-TW":"羅望子酸甜黃金醬汁・豆乾蝦仁花生香脆碎粒","en":"Tamarind-Glazed Rice Noodles with Prawns & Peanuts","th":"น้ำซอสมะขามเปียกเข้มข้น กุ้งสดตัวโตและถั่วลิสงคั่วบด","ja":"タマリンドの甘酸っぱい黄金ダレと香ばしいピーナッツ","ko":"타마린드 소스의 새콤달콤함과 고소한 땅콩 분태"},"tagline":{"zh-TW":"曼谷街頭最耀眼的國家級名菜，鑊氣與羅望子酸香的極致融合","en":"The undisputed global ambassador of Thai street food","th":"อาหารประจำชาติยอดนิยม ผัดเส้นเหนียวนุ่มหอมกลิ่นกระทะ","ja":"タイ屋台を代表する国民食。強火の香ばしさとタマリンドの酸味が絶品","ko":"태국을 대표하는 세계적인 볶음 쌀국수 요리"},"heroImage":"/images/th/pad-thai.jpg","difficulty":"medium","prepTimeMinutes":20,"cookTimeMinutes":10,"defaultServings":2,"caloriesPerServing":520,"category":"mains","dietaryTags":["classic","halal"],"supportedCookware":["traditional","airFryer"],"culture":{"originRegion":{"zh-TW":"中部・曼谷","en":"Central / Bangkok","th":"กรุงเทพมหานคร","ja":"中部・バンコク","ko":"방콕 / 중부"},"famousStreetMarkets":[{"zh-TW":"耀華力唐人街","en":"Yaowarat Chinatown","th":"ถนนเยาวราช","ja":"ヤワラート中華街","ko":"야오와랏 차이나타운"},{"zh-TW":"水門市場周邊","en":"Pratunam Market","th":"ประตูน้ำ","ja":"プラトゥーナム市場","ko":"프라투남 시장"}],"historyStory":{"zh-TW":"Pad Thai 誕生於二戰期間泰國總理鑾披汶時期，政府為了推廣泰國米粉並降低白米消耗，融合了潮汕炒麵技法與泰國羅望子、棕櫚糖調味，創造出兼具甜、鹹、酸、微辣的國家代表小吃。","en":"Invented during WWII under Prime Minister Plaek Phibunsongkhram to promote national identity and rice noodle consumption. It fuses Chinese stir-fry wok technique with quintessential Thai tamarind, palm sugar and fish sauce.","th":"ผัดไทยถือกำเนิดขึ้นในช่วงสงครามโลกครั้งที่ 2 โดยจอมพล ป. พิบูลสงคราม เพื่อรณรงค์ให้ประชาชนหันมาบริโภคก๋วยเตี๋ยวเส้นจันทน์แทนข้าวสาร จนกลายเป็นเมนูเอกลักษณ์ระดับโลก","ja":"第二次世界大戦中、米の消費を抑えタイ米麺を普及させる国家プロジェクトとして誕生。中華風の炒め技法とタイ固有のタマリンドやパームシュガーが融合した至高の一皿。","ko":"제2차 세계대전 당시 쌀 소비를 줄이고 쌀국수를 장려하기 위해 국가적으로 개발된 요리입니다. 타마린드의 새콤달콤함이 쫄깃한 면발과 어우러집니다."},"thaiScript":"ผัดไทยกุ้งสด","thaiPhonetics":"Pad Thai Goong Sod","audioPronunciationText":"เอาผัดไทยกุ้งสดหนึ่งจาน ไม่ใส่ผงชูรสครับ","nativeName":"ผัดไทยกุ้งสด"},"ingredients":[{"id":"rice-noodles","name":{"zh-TW":"泰國尖竹汶乾米粉 (金邊粉)","en":"Chantaburi Dry Rice Noodles","th":"ก๋วยเตี๋ยวเส้นจันทน์","ja":"センレック（タイ中細米麺）","ko":"팟타이 쌀국수 면 (중면)"},"amount":160,"unitMetric":"g","unitUS":"5.5 oz","isKeyFlavor":true,"thaiName":"เส้นจันทน์","thaiPronunciation":"Sen Chantaburi","substitute":{"substituteName":{"zh-TW":"中等寬度越南河粉或米線","en":"Pho medium rice noodles or linguine","th":"เส้นเล็กทั่วไป","ja":"フォー用ライスヌードル","ko":"베트남 쌀국수 중면"},"ratio":"1:1","explanation":{"zh-TW":"用室溫水浸泡 40 分鐘至微白柔軟即可，勿用熱水燙煮否則下鍋易斷成碎條","en":"Soak in room temp water for 40 mins. Never boil with hot water.","th":"แช่น้ำอุณหภูมิห้อง 40 นาที ห้ามลวกน้ำร้อน","ja":"常温の水で40分戻します。熱湯で茹でると炒める際に千切れるので注意","ko":"찬물에 40분 불려 사용하세요. 뜨거운 물에 삶으면 볶을 때 뚝뚝 끊어집니다."},"whereToBuy":{"zh-TW":"各大超市亞洲食材區或網購","en":"Asian aisle of supermarkets or Amazon","th":"ตลาดสดทั่วไป","ja":"アジア系スーパー","ko":"대형마트 아시안 코너"}}},{"id":"fresh-prawns","name":{"zh-TW":"新鮮大白蝦或草蝦 (去殼留尾)","en":"Fresh Jumbo Prawns (Peeled, tail-on)","th":"กุ้งสดแกะเปลือก","ja":"新鮮な海老（殻むき・尾つき）","ko":"신선한 새우 (탈각, 꼬리 유지)"},"amount":8,"unitMetric":"piece","unitUS":"piece","thaiName":"กุ้งสด","thaiPronunciation":"Goong Sod"},{"id":"firm-tofu","name":{"zh-TW":"黃色硬豆乾 (切細丁)","en":"Firm Yellow Tofu (Diced)","th":"เต้าหู้เหลืองหั่นเต๋า","ja":"固めの木綿豆腐または焼き豆腐","ko":"단단한 두부 (작게 깍둑썰기)"},"amount":60,"unitMetric":"g","unitUS":"2 oz","thaiName":"เต้าหู้เหลือง","thaiPronunciation":"Tao-Hoo Lueang"},{"id":"tamarind-paste","name":{"zh-TW":"泰國濃縮無籽羅望子膏","en":"Thai Concentrated Tamarind Paste","th":"น้ำมะขามเปียก","ja":"タイ産 タマリンドペースト","ko":"태국산 타마린드 페이스트"},"amount":2.5,"unitMetric":"tbsp","unitUS":"2.5 tbsp","isKeyFlavor":true,"thaiName":"น้ำมะขามเปียก","thaiPronunciation":"Nam Makham Piak","substitute":{"substituteName":{"zh-TW":"烏醋 1.5 匙 + 蘋果醋 1 匙 + 糖少許","en":"1.5 tbsp Black vinegar + 1 tbsp apple cider vinegar","th":"น้ำส้มสายชูหมักผสมน้ำตาล","ja":"黒酢大さじ1.5 ＋ リンゴ酢大さじ1 ＋ 砂糖少々","ko":"흑초 1.5큰술 + 사과식초 1큰술 + 설탕 약간"},"ratio":"1:1","explanation":{"zh-TW":"羅望子帶有柔和果酸，若無可混合果醋與烏醋，切勿單獨使用刺鼻白醋","en":"Tamarind provides a mellow fruity tartness. Blend fruit vinegar with black vinegar.","th":"ผสมน้ำส้มสายชูผลไม้เพื่อเลียนแบบความเปรี้ยวละมุน","ja":"タマリンドのフルーティーな酸味を再現するため、果実酢と黒酢をブレンドします","ko":"타마린드의 부드러운 과일 산미를 위해 과일식초와 흑초를 섞어 사용합니다."},"whereToBuy":{"zh-TW":"泰國雜貨店或 Amazon 網購","en":"Asian grocery stores or Amazon","th":"ซูเปอร์มาร์เก็ตทั่วไป","ja":"アジア食品店またはネット通販","ko":"아시안 식료품점 또는 온라인"}}},{"id":"palm-sugar","name":{"zh-TW":"泰國椰糖 (碎塊)","en":"Thai Palm Sugar (Chopped)","th":"น้ำตาลปี๊บ","ja":"パームシュガー（ヤシ樹液糖）","ko":"태국 팜슈가 (다진 것)"},"amount":2,"unitMetric":"tbsp","unitUS":"2 tbsp","isKeyFlavor":true,"thaiName":"น้ำตาลปี๊บ","thaiPronunciation":"Nam Tan Peep"},{"id":"fish-sauce","name":{"zh-TW":"泰國頂級純魚露","en":"Thai Premium Fish Sauce","th":"น้ำปลาแท้","ja":"タイ産 高級ナンプラー","ko":"태국 피시소스 (남쁠라)"},"amount":2,"unitMetric":"tbsp","unitUS":"2 tbsp","isKeyFlavor":true,"thaiName":"น้ำปลาแท้","thaiPronunciation":"Nam Pla"},{"id":"crushed-peanuts","name":{"zh-TW":"熟碎花生仁","en":"Roasted Crushed Peanuts","th":"ถั่วลิสงคั่วบด","ja":"ローストピーナッツ（粗砕き）","ko":"볶은 땅콩 분태"},"amount":3,"unitMetric":"tbsp","unitUS":"3 tbsp","thaiName":"ถั่วลิสงคั่ว","thaiPronunciation":"Thua Li-Song Khua"},{"id":"garlic-chives","name":{"zh-TW":"新鮮韭菜段","en":"Fresh Garlic Chives (Cut in 2-inch pieces)","th":"ใบกุยช่าย","ja":"ニラ（5cm長さに切る）","ko":"부추 (5cm 길이)"},"amount":50,"unitMetric":"g","unitUS":"1.8 oz","thaiName":"ใบกุยช่าย","thaiPronunciation":"Bai Gui-Chai"},{"id":"bean-sprouts","name":{"zh-TW":"鮮脆綠豆芽","en":"Fresh Crisp Bean Sprouts","th":"ถั่วงอกสด","ja":"新鮮なもやし","ko":"신선한 숙주나물"},"amount":100,"unitMetric":"g","unitUS":"3.5 oz","thaiName":"ถั่วงอก","thaiPronunciation":"Thua-Ngok"},{"id":"eggs","name":{"zh-TW":"新鮮雞蛋","en":"Large Fresh Eggs","th":"ไข่ไก่สด","ja":"新鮮な卵","ko":"신선한 달걀"},"amount":2,"unitMetric":"piece","unitUS":"piece","thaiName":"ไข่ไก่","thaiPronunciation":"Khai Gai"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"冷水浸泡米粉與調製黃金羅望子醬汁","en":"Soak Noodles & Simmer Golden Tamarind Sauce","th":"แช่เส้นและเคี่ยวน้ำซอสผัดไทย","ja":"麺の戻しとタマリンドタレ作り","ko":"면 불리기 및 황금 타마린드 소스 끓이기"},"instruction":{"zh-TW":"將乾金邊粉放入冷水中浸泡 40 分鐘，直到用手指能輕易彎折但無軟爛。小鍋中加入羅望子膏、椰糖、魚露與少許水，微火加熱至椰糖完全融化，醬汁濃稠微滾後熄火備用。","en":"Soak dry rice noodles in room temperature water for 40 mins until pliable. In a small saucepan, combine tamarind paste, palm sugar, fish sauce, and 2 tbsp water. Simmer gently on low heat until palm sugar melts into a glossy sauce.","th":"แช่เส้นจันทน์ในน้ำอุณหภูมิห้อง 40 นาทีจนเส้นนิ่ม จากนั้นเคี่ยวน้ำมะขามเปียก น้ำตาลปี๊บ และน้ำปลาในหม้อเล็กจนละลายเข้ากันดี พักไว้","ja":"センレックを常温の水に40分浸けてしなやかに戻します。小鍋にタマリンドペースト、パームシュガー、ナンプラー、水大さじ2を入れて弱火にかけ、砂糖が溶けてとろみがつくまで煮詰めます。","ko":"쌀국수 면을 찬물에 40분간 불려 준비합니다. 작은 냄비에 타마린드 페이스트, 팜슈가, 피시소스, 물 2큰술을 넣고 약불에서 설탕이 녹을 때까지 끓여 소스를 완성합니다."},"durationSeconds":180,"image":"/images/th/pad-thai-step1.jpg","crucialTips":{"zh-TW":"米粉絕對不能用熱水燙！熱水會使米粉澱粉糊化，下鍋熱炒時會黏成一團爛泥。","en":"Never boil rice noodles in hot water before stir-frying! It makes them turn to mush in the wok.","th":"ห้ามลวกเส้นด้วยน้ำร้อนเด็ดขาด เพราะจะทำให้เส้นเละเหนียวติดกระทะ","ja":"熱湯で茹でるのは厳禁！炒めた時にベチャベチャになりコシが失われます。","ko":"절대 끓는 물에 면을 삶지 마세요! 볶을 때 떡처럼 뭉쳐버립니다."}},{"stepNumber":2,"title":{"zh-TW":"爆香鮮蝦與豆腐丁","en":"Sear Fresh Prawns & Firm Tofu","th":"ผัดกุ้งสดและเต้าหู้เหลือง","ja":"海老と豆腐の香ばし炒め","ko":"새우와 두부 노릇하게 굽기"},"instruction":{"zh-TW":"炒鍋大火熱油，放入鮮蝦兩面各煎 45 秒至八分熟且飄出蝦油香氣，先撈出備用。原鍋利用剩餘紅亮蝦油放入豆腐丁與紅蔥頭碎爆香至金黃微焦。","en":"Heat 2 tbsp oil in a wok over high heat. Sear prawns for 45 secs per side until just pink, then transfer to a plate. In the remaining flavorful prawn oil, add diced firm tofu and shallots, frying until golden.","th":"ตั้งกระทะไฟแรง ใส่น้ำมัน ผัดกุ้งจนสุก 80% ตักขึ้นพักไว้ นำเต้าหู้เหลืองและหอมแดงลงผัดต่อในน้ำมันกุ้งจนเหลืองกรอบ","ja":"中華鍋に油を強火で熱し、海老を両面45秒ずつサッと焼き、取り出します。残った海老油で刻み豆腐とエシャロットをキツネ色になるまで炒めます。","ko":"팬에 기름을 두르고 센 불에서 새우를 앞뒤로 45초씩 구워 덜어둡니다. 남은 새우 기름에 깍둑썬 두부와 샬롯을 넣고 노릇하게 볶습니다."},"durationSeconds":120,"image":"/images/th/pad-thai-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"下米粉吸收羅望子醬汁與爆炒入味","en":"Toss Noodles with Tamarind Sauce","th":"ผัดเส้นจันทน์คลุกเคล้าน้ำซอส","ja":"麺の投入とタマリンドタレの絡め炒め","ko":"면 투하 및 타마린드 소스 코팅"},"instruction":{"zh-TW":"轉中大火，放入瀝乾水份的米粉，淋入 3-4 大匙黃金羅望子醬汁與 3 大匙水。快速翻炒讓米粉吸飽紅褐色醬汁，直到米粉變軟並透出琥珀光澤。","en":"Add drained soaked noodles into the wok. Pour in 3-4 tbsp tamarind sauce and 3 tbsp water. Stir-fry vigorously until noodles soften and absorb the reddish-golden sauce completely.","th":"ใส่เส้นจันทน์ลงไป ราดน้ำซอสผัดไทย 3-4 ช้อนโต๊ะและน้ำเปล่า ผัดเร็วๆ จนเส้นดูดน้ำซอสเหนียวนุ่มเงางาม","ja":"水気を切った麺を投入し、タマリンドタレ大さじ3〜4と水大さじ3を加えます。麺がタレを吸って琥珀色にしなやかになるまで手早く炒め合わせます。","ko":"불린 면을 넣고 타마린드 소스 3~4큰술과 물 3큰술을 붓습니다. 면이 소스를 흠뻑 머금고 윤기 날 때까지 빠르게 볶아줍니다."},"durationSeconds":150,"image":"/images/th/pad-thai-step3.jpg"},{"stepNumber":4,"title":{"zh-TW":"推鍋炒蛋與包裹粉條","en":"Scramble Eggs & Fold Noodles","th":"เขี่ยเส้นตอกไข่ใส่กระทะ","ja":"卵の炒め合わせと麺の包み込み","ko":"달걀 스크램블 및 면과 합체"},"instruction":{"zh-TW":"將炒好的米粉推至炒鍋一側，空出底部淋少許油，打入 2 顆雞蛋。用鍋鏟將蛋黃輕輕劃破，待底部半凝固時迅速將米粉覆蓋上來翻炒，讓金黃蛋花碎碎包裹在每根米粉上。","en":"Push noodles to one side of the wok. Add a drizzle of oil to the bare space and crack in 2 eggs. Scramble lightly, and when half-set, fold the noodles over the eggs, tossing to distribute ribbons of egg throughout.","th":"ดันเส้นไปไว้ข้างกระทะ ใส่น้ำมันเล็กน้อย ตอกไข่ไก่ลงไป ยีพอแตก พอไข่เริ่มสุกตลบเส้นกลับมาคลุกเคล้าให้ทั่ว","ja":"麺を鍋の端に寄せ、空いたスペースに油を足して卵2個を割り入れます。半熟状になったら麺をかぶせるように混ぜ、卵のそぼろを麺全体にまとわせます。","ko":"면을 한쪽으로 밀어두고 빈 공간에 기름을 살짝 둘러 달걀 2개를 깨 넣습니다. 반숙 상태가 되면 면을 덮어 고루 섞어줍니다."},"durationSeconds":90,"image":"/images/th/pad-thai-step4.jpg"},{"stepNumber":5,"title":{"zh-TW":"回鍋鮮蝦、加入豆芽韭菜大火出鍋","en":"Return Prawns, Fold Chives & High-Heat Finish","th":"ใส่กุ้ง ถั่วงอก กุยช่าย เร่งไฟแรง","ja":"海老戻し・もやし・ニラの強火フィニッシュ","ko":"새우 복귀, 숙주와 부추 넣고 센 불 마무리"},"instruction":{"zh-TW":"將煎好的大蝦、綠豆芽與韭菜段倒回鍋中。開最大火快速顛鍋翻炒 20-30 秒，豆芽保持爽脆即可起鍋！盛盤後旁邊附上半顆新鮮檸檬角、一匙碎花生與一小撮泰國辣椒粉。","en":"Return the cooked prawns, fresh bean sprouts, and garlic chives to the wok. Blast on maximum heat for 20-30 secs so veggies stay crunchy. Plate immediately with crushed roasted peanuts, fresh lime wedge, and dry chili flakes on the side.","th":"ใส่กุ้งที่ผัดไว้ ถั่วงอกสด และใบกุยช่าย เร่งไฟแรงสุด ผัดสะบัดกระทะ 20 วินาที ตักใส่จาน เคียงด้วยมะนาว ถั่วลิสงป่น และพริกป่น","ja":"取り出しておいた海老、もやし、ニラを戻し入れます。最大火力で20〜30秒だけ素早く煽り、もやしのシャキシャキ感を残して盛り付けます。刻みピーナッツ、生ライム、一味唐辛子を添えて完成！","ko":"구워둔 새우와 숙주, 부추를 넣고 가장 센 불에서 20~30초간 빠르게 볶아냅니다. 접시에 담고 땅콩 분태, 라임 조각, 고춧가루를 곁들여 완성합니다."},"durationSeconds":45,"image":"/images/th/pad-thai-step5.jpg","dangerWarnings":{"zh-TW":"最後大火翻炒切勿過久，超過 30 秒豆芽會大量出水導致整盤炒粉變爛！","en":"Do not overcook bean sprouts! Over 30 seconds will release water and make the dish soggy.","th":"ระวังอย่าผัดผักนานเกินไป ถั่วงอกจะคายน้ำทำให้ผัดไทยแฉะ","ja":"最後の炒め過ぎに注意！もやしから水が出てベタつく原因になります。","ko":"마지막 채소는 너무 오래 볶지 마세요! 채소에서 물이 나와 눅눅해집니다."}}],"troubleshooting":[{"id":"pad-thai-soggy","problem":{"zh-TW":"炒出來的米粉爛成一團、黏在一起或斷成碎塊","en":"Noodles clumped together, mushy, or broke into pieces","th":"เส้นผัดไทยขาด เละ เหนียวติดกันเป็นก้อน","ja":"麺がベチャベチャにちぎれて団子状になってしまった","ko":"면이 떡처럼 뭉치고 뚝뚝 끊어져요"},"cause":{"zh-TW":"1. 米粉用了熱水燙煮而不是冷水浸泡；2. 下鍋時加了過多水分；3. 鍋溫不夠高導致米粉在溫水中煮爛而非高溫爆炒。","en":"1. Soaked in hot water instead of cool water; 2. Added too much water; 3. Wok heat was too low.","th":"ใช้น้ำร้อนลวกเส้น หรือใส่น้ำมากเกินไปขณะผัด และไฟไม่แรงพอ","ja":"1. 麺をお湯で戻した。2. 炒める時の水分が多すぎた。3. フライパンの火力が弱かった。","ko":"1. 면을 찬물이 아닌 뜨거운 물에 불렸거나, 2. 물을 너무 많이 넣었거나, 3. 팬의 온도가 낮았습니다."},"solution":{"zh-TW":"嚴格使用室溫冷水泡米粉 40 分鐘，瀝乾水分後再下鍋。全程保持大火，若米粉偏硬每次僅能少量灑水 (每次 1 大匙)。","en":"Soak strictly in room temp water for 40 mins. Keep high wok heat and sprinkle water in tiny 1-tbsp increments only if needed.","th":"แช่เส้นด้วยน้ำเย็นเสมอ และผัดด้วยไฟแรง สาดน้ำทีละช้อนโต๊ะหากเส้นยังแข็ง","ja":"必ず常温の水で40分戻し、しっかり水気を切ります。常に強火を保ち、水分は少しずつ大さじ1ずつ足してください。","ko":"반드시 찬물에 40분간 불려 물기를 뺀 후, 센 불에서 볶으며 뻑뻑할 때만 물을 1큰술씩 소량 추가하세요."}}],"proTips":[{"zh-TW":"正宗吃法：泰國攤販絕不會把辣椒粉炒進鍋裡，而是盛盤後附在盤子旁邊，由食客依個人喜好混入花生粉與辣椒粉！","en":"Authentic dining tip: Thai street vendors never stir chili flakes into the wok. They serve it on the side for you to mix with peanuts and lime!","th":"คนไทยแท้จะไม่ผัดพริกป่นลงในกระทะ แต่จะตักเคียงไว้ข้างจานให้ผู้ทานปรุงเองตามชอบ","ja":"本場の食べ方：唐辛子粉は鍋で一緒に炒めず、お皿の脇に添えて食べる人が自分で好みの量を混ぜ合わせるのが正統派スタイル！","ko":"현지 꿀팁: 태국 노점에서는 고춧가루를 볶을 때 넣지 않고, 접시 옆에 따로 곁들여 각자 취향껏 비벼 먹습니다!"}]},{"country":"th","id":"pad-kra-pao","slug":"pad-kra-pao","title":{"zh-TW":"正宗泰式打拋豬肉飯","en":"Authentic Holy Basil Minced Pork (Pad Kra Pao)","th":"ผัดกะเพราหมูสับไข่ดาว","ja":"本場ガパオライス（豚ひき肉のホーリーバジル炒め）","ko":"정통 팟카파오무쌉 (바질 돼지고기 덮밥)"},"subtitle":{"zh-TW":"鮮摘打拋葉辛香爆發・酥脆金黃流心炸荷包蛋","en":"Peppery Holy Basil Blast with Crispy Runny Fried Egg","th":"หอมกลิ่นใบกะเพราแท้ พร้อมไข่ดาวกรอบไข่แดงเยิ้ม","ja":"フレッシュホーリーバジルの刺激的な香りとカリカリ半熟目玉焼き","ko":"매콤한 홀리 바질 향과 바삭하고 촉촉한 반숙 달걀 후라이"},"tagline":{"zh-TW":"泰國街頭快炒第一名國民美食，真打拋葉辛香與辣椒蒜香交織","en":"The ultimate Thai fast-food street classic ordered by millions every day","th":"เมนูสิ้นคิดที่อร่อยที่สุดอันดับหนึ่งในใจคนไทย","ja":"タイ人が毎日食べても飽きない国民的人気No.1屋台メシ","ko":"태국인들이 매일 찾는 국민 볶음밥 요리"},"heroImage":"/images/th/pad-kra-pao.jpg","difficulty":"easy","prepTimeMinutes":10,"cookTimeMinutes":8,"defaultServings":2,"caloriesPerServing":580,"category":"stirFry","dietaryTags":["classic"],"supportedCookware":["traditional","airFryer"],"culture":{"originRegion":{"zh-TW":"中部・曼谷街頭","en":"Central / Bangkok Street Carts","th":"กรุงเทพมหานคร","ja":"中部・バンコク","ko":"방콕 / 중부"},"famousStreetMarkets":[{"zh-TW":"曼谷各路邊熱炒攤","en":"Bangkok Raan Ahan Tam Sang","th":"ร้านอาหารตามสั่งทั่วไป","ja":"バンコクの街角大衆食堂","ko":"방콕 길거리 로컬 식당"},{"zh-TW":"洽圖洽週末市集","en":"Chatuchak Market","th":"ตลาดนัดจตุจักร","ja":"チャトゥチャック市場","ko":"짜뚜짝 주말시장"}],"historyStory":{"zh-TW":"打拋肉起源於20世紀中期的曼谷華人移民大排檔，將潮州碎肉炒法與泰國野生聖羅勒（打拋葉 Bai Kaphrao）結合。在泰國它被暱稱為「不用思考的點餐之王」，只要聞到鑊氣飄出的打拋葉與朝天椒香，便無可自拔。","en":"Pad Kra Pao originated in mid-20th century Bangkok street stalls, marrying Chinese minced meat techniques with indigenous peppery Holy Basil (Bai Kaphrao). Known affectionately as Thailand’s national \"no-brainer\" meal.","th":"ผัดกะเพราเป็นอาหารยอดฮิตตลอดกาลของคนไทย ผสมผสานศิลปะการผัดไฟแรงเข้ากับกลิ่นฉุนเฉพาะตัวของใบกะเพราป่า ทานคู่กับข้าวสวยร้อนๆ และไข่ดาวกรอบ","ja":"20世紀中葉にバンコクの屋台街で生まれた国民食。中華のひき肉炒め技法にタイ特有のスパイシーなホーリーバジルを合わせた、タイ人が最も愛する日常の味。","ko":"20세기 중반 방콕의 노점에서 시작된 태국인들의 솔 푸드입니다. 매콤한 고추와 마늘, 알싸한 홀리 바질이 어우러져 밥도둑의 진수를 보여줍니다."},"thaiScript":"ผัดกะเพราหมูสับ","thaiPhonetics":"Pad Kra Pao Moo Sap","audioPronunciationText":"เอากะเพราหมูสับไข่ดาว เผ็ดปานกลางครับ","nativeName":"ผัดกะเพราหมูสับ"},"ingredients":[{"id":"minced-pork","name":{"zh-TW":"豬梅花絞肉 (肥瘦比 3:7)","en":"Minced Pork Shoulder (30% fat)","th":"หมูสับติดมัน","ja":"豚ひき肉（赤身7：脂身3）","ko":"돼지고기 다짐육 (목살/앞다리살)"},"amount":300,"unitMetric":"g","unitUS":"10.5 oz","thaiName":"หมูสับ","thaiPronunciation":"Moo Sap"},{"id":"holy-basil","name":{"zh-TW":"新鮮泰國聖羅勒 (打拋葉)","en":"Fresh Thai Holy Basil (Bai Kaphrao)","th":"ใบกะเพราแท้","ja":"タイ産 ホーリーバジル（生）","ko":"신선한 태국 홀리 바질"},"amount":40,"unitMetric":"g","unitUS":"1.4 oz","isKeyFlavor":true,"thaiName":"ใบกะเพรา","thaiPronunciation":"Bai Kaphrao","substitute":{"substituteName":{"zh-TW":"九層塔 + 研磨黑胡椒 1/3 茶匙","en":"Thai Sweet Basil + 1/3 tsp cracked black pepper","th":"ใบโหระพา + พริกไทยดำ","ja":"スイートバジル ＋ 粗挽き黒胡椒","ko":"스위트 바질 + 굵은 흑후추"},"ratio":"1:1","explanation":{"zh-TW":"打拋葉帶有丁香與胡椒辛烈香氣，若買不到可用九層塔加少許現磨黑胡椒模擬","en":"Holy basil is more peppery than sweet basil. Add black pepper to regular basil to mimic heat.","th":"หากไม่มีกะเพราใช้โหระพาผสมพริกไทยดำแทนได้","ja":"ホーリーバジルは刺激的な香りが特徴。スイートバジルに黒胡椒を足して代用します","ko":"홀리 바질 특유의 알싸한 향을 스위트 바질과 흑후추로 비슷하게 낼 수 있습니다."},"whereToBuy":{"zh-TW":"東南亞超市生鮮區或 Amazon","en":"Asian produce aisle or Amazon","th":"ตลาดสด","ja":"アジア食品店または通販","ko":"아시안 식료품점 또는 온라인"}}},{"id":"birds-eye-chili","name":{"zh-TW":"泰國新鮮朝天椒 (紅綠混搭)","en":"Thai Bird's Eye Chilies (Prik Kee Noo)","th":"พริกขี้หนูสวน","ja":"タイ産 プリッキーヌ（生青唐辛子）","ko":"태국 프릭키누 (쥐똥고추)"},"amount":6,"unitMetric":"piece","unitUS":"piece","isKeyFlavor":true,"thaiName":"พริกขี้หนู","thaiPronunciation":"Prik Kee Noo"},{"id":"garlic","name":{"zh-TW":"新鮮蒜頭 (連皮拍碎)","en":"Fresh Garlic Cloves","th":"กระเทียมไทย","ja":"にんにく","ko":"마늘"},"amount":6,"unitMetric":"clove","unitUS":"clove","thaiName":"กระเทียม","thaiPronunciation":"Kra-Thiam"},{"id":"fish-sauce","name":{"zh-TW":"泰國純魚露","en":"Thai Fish Sauce","th":"น้ำปลาแท้","ja":"タイ産 ナンプラー","ko":"피시소스"},"amount":1.5,"unitMetric":"tbsp","unitUS":"1.5 tbsp","isKeyFlavor":true,"thaiName":"น้ำปลา","thaiPronunciation":"Nam Pla"},{"id":"oyster-sauce","name":{"zh-TW":"泰國蠔油","en":"Thai Oyster Sauce","th":"ซอสหอยนางรม","ja":"オイスターソース","ko":"굴소스"},"amount":1.5,"unitMetric":"tbsp","unitUS":"1.5 tbsp","thaiName":"ซอสหอยนางรม","thaiPronunciation":"Sauce Hoi Nang Rom"},{"id":"dark-soy-sauce","name":{"zh-TW":"泰國黑甜醬油 (老抽上色)","en":"Thai Dark Sweet Soy Sauce","th":"ซีอิ๊วดำหวาน","ja":"タイ産 シーユーダム（濃口黒醤油）","ko":"태국 다크 스위트 간장"},"amount":1,"unitMetric":"tsp","unitUS":"1 tsp","thaiName":"ซีอิ๊วดำ","thaiPronunciation":"See-Ew Dam"},{"id":"sugar","name":{"zh-TW":"椰糖或白糖","en":"Palm Sugar or Cane Sugar","th":"น้ำตาลทราย","ja":"砂糖またはパームシュガー","ko":"설탕 또는 팜슈가"},"amount":1,"unitMetric":"tsp","unitUS":"1 tsp","thaiName":"น้ำตาล","thaiPronunciation":"Nam Tan"},{"id":"eggs","name":{"zh-TW":"雞蛋 (炸泰式流心荷包蛋)","en":"Eggs (for Crispy Fried Egg)","th":"ไข่ไก่ (ทำไข่ดาวกรอบ)","ja":"卵（カリカリ目玉焼き用）","ko":"달걀 (바삭한 튀김 후라이용)"},"amount":2,"unitMetric":"piece","unitUS":"piece","thaiName":"ไข่ดาว","thaiPronunciation":"Khai Dao"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"石臼搗碎辣椒與蒜頭","en":"Crush Chilies & Garlic in Mortar","th":"โขลกพริกกับกระเทียม","ja":"唐辛子とにんにくを粗く叩き潰す","ko":"고추와 마늘 굵게 빻기"},"instruction":{"zh-TW":"將朝天椒與蒜頭放入石臼中粗擣，破壞纖維即可，切忌擣成細泥，這樣爆炒時蒜香與辛辣汁液能瞬間在熱油中炸裂。","en":"Roughly pound bird's eye chilies and garlic in a mortar. Keep it coarse—crushing releases essential oils without burning.","th":"โขลกพริกขี้หนูกับกระเทียมพอหยาบ ไม่ต้องละเอียด เพื่อให้น้ำมันหอมระเหยกระจายตัวได้ดีเมื่อลงกระทะ","ja":"すり鉢で青唐辛子とにんにくを粗めに叩き潰します。すり潰しすぎず、粗さを残すのが香りを引き出す秘訣。","ko":"절구에 고추와 마늘을 넣고 굵직하게 빻아줍니다. 굵게 빻아야 볶을 때 타지 않고 풍미가 살아납니다."},"durationSeconds":60,"image":"/images/th/pad-kra-pao-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"炸製正宗泰式脆皮荷包蛋 (Khai Dao)","en":"Fry Crispy Thai-Style Egg (Khai Dao)","th":"ทอดไข่ดาวกรอบไข่แดงเยิ้ม","ja":"カリカリ半熟目玉焼き（カイダーオ）を揚げる","ko":"바삭한 튀김 후라이 (카이다오) 만들기"},"instruction":{"zh-TW":"炒鍋倒入約 3 大匙油，大火燒至冒白煙（極高油溫）。將蛋直接打入熱油中央，邊緣會立即起泡炸出蕾絲般金黃酥脆脆邊，用鍋鏟將熱油淋在蛋白上，蛋黃保持流心狀態，起鍋瀝油備用。","en":"Heat 3 tbsp oil over high heat until smoking hot. Crack in an egg—it will violently sizzle and balloon with crispy ruffled edges. Ladle hot oil over whites while keeping the yolk silky and runny. Drain and set aside.","th":"ใส่น้ำมันในกระทะให้ร้อนจัดจนควันขึ้น ตอกไข่ลงไป ขอบไข่จะฟูกรอบทันที ตักน้ำมันร้อนราดไข่ขาวจนสุกแต่ไข่แดงยังเยิ้ม ตักขึ้นพักไว้","ja":"多めの油を煙が出るまで熱し、卵を割り入れます。白身の縁がチリチリと揚がり、きつね色にカリカリになったら取り出します。黄身は必ず半熟をキープ！","ko":"팬에 기름을 넉넉히 두르고 연기가 날 정도로 달군 뒤 달걀을 깨 넣습니다. 가장자리가 튀겨지듯 바삭해지면 기름을 끼얹으며 익혀 반숙으로 건져냅니다."},"durationSeconds":90,"image":"/images/th/pad-kra-pao-step2.jpg","cookwareVariations":[{"cookware":"airFryer","tempAndSetting":"200°C (390°F) for 4 mins","instructionOverride":{"zh-TW":"氣炸鍋小烤盤刷油，打入雞蛋，以 200°C 氣炸 3.5-4 分鐘，同樣能達到蛋白酥脆、蛋黃流心的效果！","en":"Brush oil in air fryer dish, crack egg in, air fry at 200°C for 4 mins until edges blister and yolk remains runny.","th":"ทอดด้วยหม้อทอดไร้น้ำมัน 200°C นาน 4 นาที ไข่ขาวกรอบไข่แดงเยิ้ม","ja":"ノンフライヤーの耐熱皿に油を塗り、200℃で約4分加熱するとカリカリ半熟目玉焼きが完成します。","ko":"에어프라이어 전용 용기에 기름을 바르고 달걀을 깨 넣어 200도에서 4분간 돌리면 바삭한 반숙 후라이가 됩니다."}}]},{"stepNumber":3,"title":{"zh-TW":"大火爆香辣椒蒜頭與快速翻炒絞肉","en":"Sear Chili-Garlic & Minced Pork","th":"ผัดพริกกระเทียมและเนื้อหมูสับ","ja":"にんにく唐辛子とひき肉の強火炒め","ko":"고추, 마늘 볶기 및 다짐육 투하"},"instruction":{"zh-TW":"利用鍋中底油，大火下擣碎的蒜蓉辣椒快速翻炒 15 秒至香氣刺鼻。隨即下入絞肉，用鏟子快速劃散，大火翻炒至絞肉完全變白並煸炒出油脂。","en":"In the remaining oil, stir-fry pounded chili and garlic for 15 seconds until intensely aromatic. Add minced pork immediately, breaking it apart with the spatula over blazing high heat until cooked through and slightly caramelized.","th":"ผัดพริกกระเทียมในกระทะ 15 วินาทีจนหอมฉุน ใส่หมูสับลงไป ยีให้กระจาย ผัดไฟแรงจนหมูสุกแห้งและเริ่มมีน้ำมันซึม","ja":"残った油でにんにくと唐辛子を15秒強火で炒め、香りが立ったらひき肉を投入。ヘラでほぐしながらパラパラになるまで一気に強火で炒めます。","ko":"남은 기름에 빻은 고추와 마늘을 15초간 볶아 매운 향을 올린 뒤, 다짐육을 넣고 뭉치지 않게 흩트려가며 센 불에서 빠르게 볶아줍니다."},"durationSeconds":120,"image":"/images/th/pad-kra-pao-step3.jpg"},{"stepNumber":4,"title":{"zh-TW":"淋入黃金醬汁焦糖化包裹肉末","en":"Caramelize with Sauce Trio","th":"ปรุงรสด้วยน้ำปลา ซอสหอย และซีอิ๊วดำ","ja":"合わせ調味料の投入と香ばしコーティング","ko":"양념 소스 넣고 센 불에 조리기"},"instruction":{"zh-TW":"沿著高溫鍋邊淋入魚露、蠔油、黑甜醬油與糖。高溫能讓醬油在鍋邊瞬間焦糖化，快速翻炒使深琥珀色醬汁緊緊裹住每一顆豬肉末，鍋底保持乾爽無積水。","en":"Pour in fish sauce, oyster sauce, dark soy sauce, and sugar around the scorching edges of the wok to caramelize. Stir-fry rapidly until every bit of meat is coated in a savory, dark glossy glaze.","th":"ราดน้ำปลา ซอสหอยนางรม ซีอิ๊วดำ และน้ำตาลรอบขอบกระทะ ผัดคลุกเคล้าให้น้ำซอสเคลือบหมูสับจนแห้งเงางาม","ja":"鍋肌からナンプラー、オイスターソース、黒醤油、砂糖を回し入れます。焦がし醤油の香ばしさをひき肉全体に素早く絡め、水分を飛ばします。","ko":"팬 가장자리로 피시소스, 굴소스, 다크 간장, 설탕을 둘러 넣습니다. 소스가 눌어붙으며 캐러멜화되도록 빠르게 볶아 고기에 진한 양념을 입힙니다."},"durationSeconds":60,"image":"/images/th/pad-kra-pao-step4.jpg"},{"stepNumber":5,"title":{"zh-TW":"熄火投入打拋葉餘溫翻炒出鍋","en":"Kill Heat & Fold Fresh Holy Basil","th":"ปิดไฟ ใส่ใบกะเพรา ผัดสลบ","ja":"火を止めてホーリーバジルを余熱で和える","ko":"불 끄고 홀리 바질 넣어 숨 죽이기"},"instruction":{"zh-TW":"關鍵一步：立刻關火！投入大把洗淨擦乾的新鮮打拋葉，利用炒鍋餘溫翻炒 10-15 秒，讓打拋葉受熱變軟釋放精油香氣即可起鍋。將打拋肉鋪在熱茉莉香米飯上，頂部蓋上流心炸荷包蛋！","en":"Crucial step: TURN OFF HEAT IMMEDIATELY! Drop in the fresh holy basil leaves. Toss gently with the residual heat for 10-15 seconds until just wilted. Spoon over hot Jasmine rice and crown with the crispy fried egg.","th":"ปิดเตาทันที! ใส่ใบกะเพราสดลงไป ผัดด้วยความร้อนที่เหลือ 10 วินาทีจนใบกะเพราสลดหอมฟุ้ง ตักราดข้าวสวยร้อนๆ โปะด้วยไข่ดาวกรอบ","ja":"最重要の極意：ここで必ず火を消します！たっぷりのホーリーバジルを投入し、鍋の余熱で10秒ほどサッと和えて香りを立たせます。炊きたてのジャスミンライスの横に盛り、目玉焼きを乗せて完成！","ko":"가장 중요한 포인트: 즉시 불을 끕니다! 홀리 바질을 듬뿍 넣고 팬의 잔열로 10~15초만 가볍게 뒤섞어 숨을 죽입니다. 밥 위에 얹고 달걀 후라이를 올려 즐기세요."},"durationSeconds":20,"image":"/images/th/pad-kra-pao-step5.jpg","crucialTips":{"zh-TW":"打拋葉千萬不能開大火久煮，否則其珍貴的揮發性精油會揮發殆盡，並產生苦澀味！","en":"Never cook holy basil over active heat—it destroys the floral essential oils and turns bitter.","th":"ห้ามผัดใบกะเพราบนไฟแรงนานๆ เพราะจะทำให้กลิ่นหอมระเหยหายไปและมีรสขม","ja":"ホーリーバジルに火を通し過ぎると爽快な香りが消えて苦味が出ます。必ず余熱で！","ko":"바질을 불 위에서 오래 볶으면 향이 다 날아가고 쓴맛이 나므로 반드시 불을 끄고 잔열로 익히세요!"}}],"troubleshooting":[{"id":"pad-kra-pao-watery","problem":{"zh-TW":"炒出來的打拋豬水汪汪的，像煮肉末湯而非焦香快炒","en":"Minced pork turned out soggy and watery, lacking dry wok sear","th":"ผัดกะเพราแฉะ มีน้ำนอง ไม่แห้งหอมกระทะ","ja":"炒め物が水っぽくなり、香ばしさが足りない","ko":"물이 흥건해져서 볶음이 아니라 조림 같아요"},"cause":{"zh-TW":"1. 鍋溫不夠高或肉量過多；2. 絞肉剛從冰箱拿出來帶有大量冰霜水氣；3. 調味料加了水。","en":"Wok wasn't hot enough, cold meat steamed in its own liquid, or added water to sauce.","th":"กระทะไม่ร้อนจัด หรือเนื้อหมูเย็นชื้นทำให้คายน้ำ","ja":"フライパンの温度が低かったか、冷蔵庫から出したての冷たい肉で温度が下がって水が出ました。","ko":"팬의 온도가 낮았거나 차가운 고기에서 수분이 배어 나와 쪄지듯이 익었습니다."},"solution":{"zh-TW":"絞肉務必提前回溫擦乾水氣。全程保持大火，不加一滴水，待肉汁炒乾析出純油再下調味料！","en":"Let pork come to room temp. Keep heat blasting high, don't add water, and evaporate liquid completely before saucing.","th":"ใช้ไฟแรงสุดตลอดเวลา ซับหมูให้แห้งก่อนลงผัด และห้ามเติมน้ำเปล่า","ja":"ひき肉は常温に戻し、水分を飛ばして油が透き通るまで炒めてから調味料を入れます。","ko":"고기는 실온 상태로 물기를 닦아 사용하고, 가장 센 불에서 수분이 완전히 날아갈 때까지 볶은 후 양념을 넣으세요."}}],"proTips":[{"zh-TW":"吃法靈魂：用叉子戳破金黃酥脆的炸荷包蛋，讓金黃蛋黃液與香辣打拋豬、熱騰騰泰國香米飯攪拌在一起，滋味昇華！","en":"How to eat: Pierce the crispy fried egg with your spoon and let the luscious yolk mingle with fiery pork and fragrant Jasmine rice!","th":"วิธีทานให้อร่อยที่สุด: เจาะไข่แดงให้เยิ้มคลุกเคล้ากับข้าวสวยและหมูกะเพรา เผ็ดร้อนตัดกับความมันกลมกล่อม","ja":"最高の食べ方：半熟目玉焼きの黄身を崩し、スパイシーなひき肉と熱々のジャスミンライスに絡めて頬張るのが至福の瞬間です！","ko":"맛있게 먹는 법: 반숙 노른자를 톡 터뜨려 매콤한 고기와 향긋한 자스민 밥을 함께 쓱쓱 비벼 드세요!"}]},{"country":"th","id":"tom-yum-goong","slug":"tom-yum-goong","title":{"zh-TW":"正宗泰式冬陰功湯 (濃湯版)","en":"Authentic Creamy Tom Yum Goong","th":"ต้มยำกุ้งน้ำข้นโบราณ","ja":"本場クリーミー・トムヤムクン（濃厚海老スープ）","ko":"정통 크리미 똠얌꿍 (새우 매운탕)"},"subtitle":{"zh-TW":"鮮蝦頭紅油・南薑香茅檸檬葉三劍客・酸辣椰奶濃郁湯頭","en":"Aromatic Trio of Galangal, Lemongrass & Kaffir Lime in Rich Prawn Broth","th":"หอมกลิ่นสมุนไพร ข่า ตะไคร้ ใบมะกรูด น้ำพริกเผาและมันกุ้งเข้มข้น","ja":"海老味噌のコクとハーブ三銃士が奏でる極上の甘酸っぱ辛いハーモニー","ko":"새우 내장의 진한 풍미와 허브 3총사의 매콤새콤한 조화"},"tagline":{"zh-TW":"泰國國寶級酸辣濃湯，喝一口便瞬間喚醒味蕾的靈魂料理","en":"The world-famous Thai hot and sour soup bursting with fiery herbs","th":"ซุปสมุนไพรอันดับหนึ่งของไทย เปรี้ยวเผ็ดกลมกล่อมระดับตำนาน","ja":"世界三大スープの一つ。一口飲むだけで五感が覚醒するタイの魂の味","ko":"세계 3대 수프로 꼽히는 태국의 독보적인 매콤새콤 명품 요리"},"heroImage":"/images/th/tom-yum-goong.jpg","difficulty":"medium","prepTimeMinutes":15,"cookTimeMinutes":15,"defaultServings":4,"caloriesPerServing":280,"category":"soups","dietaryTags":["classic","halal","pescatarian"],"supportedCookware":["traditional","instantPot"],"culture":{"originRegion":{"zh-TW":"中部・安帕瓦水上市場","en":"Central / Amphawa Floating Market","th":"ภาคกลาง / อัมพวา","ja":"中部・アンパワー水上マーケット","ko":"중부 / 암파와 수상시장"},"famousStreetMarkets":[{"zh-TW":"安帕瓦水上市場","en":"Amphawa Floating Market","th":"ตลาดน้ำอัมพวา","ja":"アンパワー水上マーケット","ko":"암파와 수상시장"},{"zh-TW":"曼谷米其林街頭名攤 Jay Fai","en":"Jay Fai Michelin Street Stall","th":"เจ๊ไฝ ประตูผี","ja":"ジェイ・ファイ（ミシュラン屋台）","ko":"제이 파이 미슐랭 노점"}],"historyStory":{"zh-TW":"「Tom」意為煮沸，「Yum」是酸辣調味，「Goong」是大蝦。相傳十八世紀吞武里王朝時期，鄭王因母親重病食慾不振，命宮廷御廚以湄南河鮮蝦與驅寒草藥熬煮開胃湯品，母親喝後精神大振，遂成為泰式宮廷傳世名湯，後風靡全泰大街小巷。","en":"'Tom' means boiled, 'Yum' denotes the spicy-sour seasoning balance, and 'Goong' means prawns. Originating during the Thonburi era when King Taksin requested an invigorating herbal brew to revive his mother's appetite, this royal broth evolved into Thailand's national culinary jewel.","th":"ต้มยำกุ้งสืบทอดมาตั้งแต่สมัยกรุงธนบุรี โดยรวมคำว่า ต้ม คือการเคี่ยว ยำ คือรสเปรี้ยวเผ็ดจัดจ้าน และ กุ้ง สดจากแม่น้ำเจ้าพระยา จนกลายเป็นมรดกทางวัฒนธรรมที่คนทั่วโลกรู้จัก","ja":"「トム（煮る）」「ヤム（和える・酸辛）」「クン（海老）」。18世紀トンブリー王朝時代、食欲不振に悩む母のために王が薬効ハーブと川海老を煮出させたのが始まりとされる宮廷伝来の名物スープ。","ko":"'똠(끓이다)', '얌(새콤매콤 버무리다)', '꿍(새우)'의 합성어입니다. 18세기 톤부리 왕조 시절 식욕을 잃은 왕실 가족을 위해 강새우와 약선 허브를 달여 만든 보양식에서 유래했습니다."},"thaiScript":"ต้มยำกุ้งน้ำข้น","thaiPhonetics":"Tom Yum Goong Nam Khon","audioPronunciationText":"ขอต้มยำกุ้งน้ำข้นหนึ่งหม้อ เผ็ดกลางครับ","nativeName":"ต้มยำกุ้งน้ำข้น"},"ingredients":[{"id":"river-prawns","name":{"zh-TW":"泰國大頭蝦或鮮白蝦 (保留蝦頭與蝦膏)","en":"Fresh Giant River Prawns (Heads intact with tomalley)","th":"กุ้งแม่น้ำติดมันหัว","ja":"有頭エビ（海老味噌・頭付き）","ko":"대가리 달린 생새우 (내장 필수)"},"amount":8,"unitMetric":"piece","unitUS":"piece","isKeyFlavor":true,"thaiName":"กุ้งแม่น้ำ","thaiPronunciation":"Goong Mae Nam","substitute":{"substituteName":{"zh-TW":"大草蝦 + 蝦高湯塊","en":"Black tiger prawns + shrimp bouillon","th":"กุ้งกุลาดำสด","ja":"ブラックタイガー海老 ＋ 鶏がらスープ","ko":"블랙타이거 새우 + 새우 육수큐브"},"ratio":"1:1","explanation":{"zh-TW":"冬陰功湯的迷人紅亮色澤來自煎蝦頭釋出的天然蝦青素與蝦膏，盡量保留蝦頭！","en":"The iconic crimson sheen comes naturally from searing prawn heads and tomalley.","th":"ความมันและสีแดงสวยมาจากมันกุ้งที่หัว","ja":"トムヤムクンの美しい赤色は海老味噌と殻から出る天然アスタキサンチンです","ko":"똠얌꿍의 붉은 기름과 깊은 풍미는 새우 대가리의 내장에서 우러나옵니다."},"whereToBuy":{"zh-TW":"傳統市場海鮮攤或好市多","en":"Seafood market or H-Mart","th":"ตลาดสดอาหารทะเล","ja":"鮮魚店またはアジアスーパー","ko":"수산시장 또는 대형마트"}}},{"id":"lemongrass","name":{"zh-TW":"新鮮香茅 (拍扁切斜段)","en":"Fresh Lemongrass (Bruised and cut on diagonal)","th":"ตะไคร้สดหั่นเฉียง","ja":"フレッシュレモングラス（叩いて斜め切り）","ko":"신선한 레몬그라스 (칼등으로 으깬 뒤 어슷썰기)"},"amount":3,"unitMetric":"stalk","unitUS":"stalk","isKeyFlavor":true,"thaiName":"ตะไคร้","thaiPronunciation":"Ta-Khrai"},{"id":"galangal","name":{"zh-TW":"新鮮南薑 (切薄片)","en":"Fresh Galangal (Sliced thin)","th":"ข่าแก่หั่นแว่น","ja":"フレッシュガランガル（南薑・薄切り）","ko":"생 갈랑갈 (생강 대용 가능, 얇게 편 썰기)"},"amount":40,"unitMetric":"g","unitUS":"1.4 oz","isKeyFlavor":true,"thaiName":"ข่า","thaiPronunciation":"Kha","substitute":{"substituteName":{"zh-TW":"老薑薄片 3 片 + 檸檬皮屑少許","en":"Fresh mature ginger slices + lime zest pinch","th":"ขิงแก่สด","ja":"根生姜のスライス3枚 ＋ ライムの皮少々","ko":"생강 편 3장 + 라임 제스트 한 꼬집"},"ratio":"1:1","explanation":{"zh-TW":"南薑帶有松木與柑橘清香，辣度比老薑溫和，若無可用老薑搭配檸檬皮微量模擬","en":"Galangal has piney, citrus notes. Sliced ginger with lime zest is the closest substitute.","th":"ใช้ขิงแก่แทนได้แต่รสชาติจะเผ็ดร้อนต่างกัน","ja":"ガランガルは松や柑橘の香り。生姜とライムピールで代用可能です","ko":"갈랑갈은 솔잎과 시트러스 향이 납니다. 없으면 생강에 라임 껍질을 살짝 곁들이세요."},"whereToBuy":{"zh-TW":"東南亞雜貨店或生鮮超市","en":"Asian/Thai groceries or Amazon","th":"ซูเปอร์มาร์เก็ตทั่วไป","ja":"タイ食材店またはネット通販","ko":"아시안 식료품점 또는 온라인몰"}}},{"id":"kaffir-lime-leaves","name":{"zh-TW":"新鮮泰國檸檬葉 (去中梗撕碎)","en":"Fresh Kaffir Lime Leaves (Torn, stems removed)","th":"ใบมะกรูดฉีก","ja":"コブミカンの葉（バイマックルー・ちぎる）","ko":"카피르 라임 잎 (가운데 줄기 떼고 찢은 것)"},"amount":6,"unitMetric":"leaf","unitUS":"leaf","isKeyFlavor":true,"thaiName":"ใบมะกรูด","thaiPronunciation":"Bai Ma-Krut"},{"id":"thai-chili-paste","name":{"zh-TW":"泰國冬陰辣椒膏 (Nam Prik Pao)","en":"Thai Roasted Chili Jam (Nam Prik Pao)","th":"น้ำพริกเผาแม่ประนอม","ja":"タイローストチリペースト（ナムプリックパオ）","ko":"태국 칠리 페이스트 (남프릭파오)"},"amount":2.5,"unitMetric":"tbsp","unitUS":"2.5 tbsp","isKeyFlavor":true,"thaiName":"น้ำพริกเผา","thaiPronunciation":"Nam Prik Pao"},{"id":"evaporated-milk","name":{"zh-TW":"黑白淡奶或全脂椰奶 (濃湯秘密)","en":"Evaporated Milk or Thick Coconut Milk","th":"นมข้นจืดหรือหัวกะทิ","ja":"無糖エバミルクまたは濃厚ココナッツミルク","ko":"무가당 연유(에바포레이티드 밀크) 또는 진한 코코넛밀크"},"amount":80,"unitMetric":"ml","unitUS":"2.7 fl oz","thaiName":"นมข้นจืด","thaiPronunciation":"Nom Khon Jeet"},{"id":"fish-sauce","name":{"zh-TW":"頂級純魚露","en":"Premium Fish Sauce","th":"น้ำปลาแท้","ja":"高級ナンプラー","ko":"프리미엄 피시소스"},"amount":3,"unitMetric":"tbsp","unitUS":"3 tbsp","isKeyFlavor":true,"thaiName":"น้ำปลา","thaiPronunciation":"Nam Pla"},{"id":"fresh-lime-juice","name":{"zh-TW":"新鮮壓榨檸檬汁 (關火後加入)","en":"Fresh Squeezed Lime Juice (Add off heat)","th":"น้ำมะนาวคั้นสด","ja":"搾りたて生ライム果汁（火を止めてから加える）","ko":"갓 짠 생라임즙 (반드시 불 끄고 첨가)"},"amount":3.5,"unitMetric":"tbsp","unitUS":"3.5 tbsp","isKeyFlavor":true,"thaiName":"น้ำมะนาว","thaiPronunciation":"Nam Ma-Nao"},{"id":"straw-mushrooms","name":{"zh-TW":"草菇或秀珍菇 (切半)","en":"Straw Mushrooms or Oyster Mushrooms (Halved)","th":"เห็ดฟางหรือเห็ดนางฟ้า","ja":"フクロタケまたはヒラタケ（半分に切る）","ko":"총각버섯(초고버섯) 또는 느타리버섯"},"amount":120,"unitMetric":"g","unitUS":"4.2 oz","thaiName":"เห็ดฟาง","thaiPronunciation":"Hed Fang"},{"id":"birds-eye-chilies","name":{"zh-TW":"泰國朝天椒 (拍破裂開)","en":"Thai Bird's Eye Chilies (Bruised)","th":"พริกขี้หนูสวนบุบ","ja":"タイ産赤青プリッキーヌー（叩き割り）","ko":"태국 쥐똥고추 (칼등으로 으깬 것)"},"amount":6,"unitMetric":"piece","unitUS":"piece","thaiName":"พริกขี้หนู","thaiPronunciation":"Prik Khee Noo"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"炒出鮮紅蝦膏油與香氣","en":"Sear Prawn Heads for Rich Shrimp Oil","th":"ผัดหัวกุ้งจนได้มันกุ้งสีส้มหอม","ja":"海老頭を炒めて香ばしい海老油を引き出す","ko":"새우 대가리를 볶아 붉은 새우 기름 뽑아내기"},"instruction":{"zh-TW":"鮮蝦剪下蝦頭並去除砂囊，蝦身開背去泥腸備用。鍋中下 1 大匙油，放入蝦頭中火煸炒 2 分鐘，用鍋鏟輕壓蝦頭釋放鮮紅蝦膏，直到鍋底溢滿迷人蝦油香氣。","en":"Separate prawn heads and devein tails. Heat 1 tbsp oil in a pot over medium heat. Press prawn heads with spatula for 2 minutes to extract rich crimson tomalley and aromatic shrimp oil.","th":"เด็ดหัวกุ้ง ผ่าหลังกักเส้นดำ ตั้งกระทะใส่น้ำมัน 1 ช้อนโต๊ะ ผัดหัวกุ้ง ใช้ตะหลิวกดหัวกุ้งจนมันกุ้งไหลออกเป็นสีส้มเงางาม","ja":"海老の頭を切り離し、背わたを取ります。鍋に大さじ1の油を温め、頭を入れて木べらで軽く押しつぶしながら2分炒め、濃厚な海老味噌と赤いオイルを引き出します。","ko":"새우 대가리를 떼고 몸통 내장을 제거합니다. 냄비에 기름 1큰술을 두르고 새우 대가리를 주걱으로 꾹꾹 누르며 2분간 볶아 붉은 내장 기름을 우려냅니다."},"durationSeconds":120,"image":"/images/th/tom-yum-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"注入高湯，熬煮三大香草芬芳精華","en":"Simmer Aromatic Trio: Lemongrass, Galangal & Lime Leaves","th":"ต้มสมุนไพร ข่า ตะไคร้ ใบมะกรูด","ja":"ハーブ3種の香りをブロスに煮出す","ko":"육수에 레몬그라스, 갈랑갈, 라임잎 넣고 끓이기"},"instruction":{"zh-TW":"倒入 800ml 清水或雞高湯大火煮沸。加入拍破的香茅段、南薑片與撕碎的檸檬葉，轉中火滾煮 4-5 分鐘，讓天然植物精油徹底融入湯頭。","en":"Pour in 800ml water or chicken stock and bring to a rolling boil. Add bruised lemongrass, galangal slices, and torn kaffir lime leaves. Simmer over medium heat for 4-5 minutes to release fragrant essential oils.","th":"เทน้ำเปล่าหรือน้ำซุปไก่ 800 มล. ใส่ตะไคร้บุบ ข่าแว่น และใบมะกรูดฉีก ต้มไฟกลาง 4-5 นาทีจนกลิ่นสมุนไพรอบอวล","ja":"水またはチキンスープ800mlを注ぎ沸騰させます。潰したレモングラス、ガランガル、ちぎったコブミカンの葉を加え、中火で4〜5分煮出してハーブオイルを溶け込ませます。","ko":"물 또는 닭 육수 800ml를 붓고 끓입니다. 으깬 레몬그라스, 갈랑갈, 찢은 카피르 라임 잎을 넣고 중불에서 4~5분간 끓여 깊은 허브 향을 우려냅니다."},"durationSeconds":270,"image":"/images/th/tom-yum-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"下草菇與調入冬陰辣椒膏","en":"Add Mushrooms & Whisk in Roasted Chili Jam","th":"ใส่เห็ดและละลายน้ำพริกเผา","ja":"キノコ投入とナムプリックパオ（チリペースト）のブレンド","ko":"버섯 투하 및 칠리 페이스트 풀기"},"instruction":{"zh-TW":"撈出煮透變乾癟的蝦頭。放入切半的草菇，舀入 2.5 大匙冬陰辣椒膏攪拌至完全融化於紅潤高湯中，加入拍破的朝天椒。","en":"Discard depleted prawn heads. Add halved mushrooms, whisk in 2.5 tbsp Nam Prik Pao chili jam until soup turns glowing red, and add bruised bird's eye chilies.","th":"ตักหัวกุ้งที่หมดรสชาติออก ใส่เห็ดฟาง ละลายน้ำพริกเผา 2.5 ช้อนโต๊ะลงในน้ำซุปจนแดงระเรื่อ ใส่พริกขี้หนูสวนบุบ","ja":"出汁の出た海老頭を取り出します。キノコを加え、ナムプリックパオ大さじ2.5をしっかり溶かしてスープを鮮烈な赤に染め、潰した唐辛子を加えます。","ko":"맛이 다 우러난 새우 대가리는 건져냅니다. 버섯을 넣고 칠리 페이스트 2.5큰술을 곱게 풀어준 뒤, 으깬 쥐똥고추를 넣습니다."},"durationSeconds":150,"image":"/images/th/tom-yum-step3.jpg"},{"stepNumber":4,"title":{"zh-TW":"下大蝦、淡奶滑湯，精準烹熟","en":"Poach Prawns & Swirl in Evaporated Milk","th":"ใส่กุ้งสดและเติมนมข้นจืด","ja":"海老を投入しエバミルクでまろやか仕上げ","ko":"새우 넣고 무가당 연유 부어 크리미하게 완성"},"instruction":{"zh-TW":"調入 3 大匙魚露。放入剝好殼的鮮蝦，轉中大火煮 90 秒至蝦肉緊緻彈牙蜷曲成 C 字型。倒入淡奶（或濃椰奶）輕輕推勻，湯頭立即化為滑順金紅的奶香濃湯，隨即關火！","en":"Season with 3 tbsp fish sauce. Drop in raw prawns and simmer for 90 seconds until they turn opaque pink and curl into a C-shape. Pour in evaporated milk, stir gently into a creamy terracotta broth, and immediately kill the heat!","th":"ปรุงรสด้วยน้ำปลา ใส่เนื้อกุ้งสดต้ม 90 วินาทีจนสุกเด้ง เทนมข้นจืดลงไปคนให้เนียนเป็นสีส้มละมุน แล้วดับไฟทันที!","ja":"ナンプラー大さじ3で味を調えます。海老を入れ90秒煮てプリッとしたら、無糖エバミルクを注いで優しく混ぜ、クリーミーなテラコッタ色になったら即火を止めます！","ko":"피시소스 3큰술을 넣습니다. 손질한 새우살을 넣고 90초간 끓여 C자 모양으로 익으면, 무가당 연유를 부어 부드럽게 섞은 뒤 즉시 불을 끕니다!"},"durationSeconds":100,"image":"/images/th/tom-yum-step4.jpg"},{"stepNumber":5,"title":{"zh-TW":"關火淋入生檸檬汁與撒芫荽 (關鍵秘訣)","en":"Off-Heat Fresh Lime Splash & Fresh Cilantro Finish","th":"ปิดไฟบีบมะนาวสด โรยผักชีฝรั่ง","ja":"火を消してから生ライム果汁を回し入れ、香菜を添える","ko":"불 끄고 생라임즙 뿌리기 & 고수 올려 완성"},"instruction":{"zh-TW":"重要警告：務必關火後再淋入新鮮檸檬汁！滾沸的檸檬汁會產生苦味並破壞果酸。輕輕拌勻後灑上香菜碎，即可趁熱享用酸辣鮮香的曼谷頂級濃湯！","en":"Crucial: Only add freshly squeezed lime juice AFTER the heat is turned off! Boiling lime juice turns bitter. Stir gently, scatter fresh cilantro leaves, and serve piping hot.","th":"เคล็ดลับสำคัญ: ต้องดับไฟก่อนบีบน้ำมะนาวเสมอ มิเช่นนั้นน้ำซุปจะขม คนให้เข้ากัน โรยผักชีฝรั่งและผักชีไทย เสิร์ฟร้อนๆ","ja":"最重要ポイント：生ライム果汁は必ず【火を止めてから】加えること！加熱すると苦味が出て風味が損なわれます。ちぎったパクチーを散らしてアツアツをお召し上がりください。","ko":"필수 팁: 생라임즙은 반드시 【불을 끈 상태에서】 넣어야 합니다! 펄펄 끓는 상태에서 넣으면 떫은맛이 나고 상큼함이 파괴됩니다. 고수를 듬뿍 얹어 뜨거울 때 드세요."},"durationSeconds":40,"image":"/images/th/tom-yum-step5.jpg","dangerWarnings":{"zh-TW":"切勿開火滾煮檸檬汁！高溫沸騰會破壞維他命C並產生強烈苦澀味。","en":"Never boil fresh lime juice! Boiling temperature degrades the freshness and causes severe bitterness.","th":"ห้ามต้มมะนาวขณะเดือด จะทำให้แกงมีรสขมปร่า","ja":"沸騰している鍋にライム汁を入れて煮立たせないこと。強い苦味が生じます。","ko":"라임즙을 넣은 채로 펄펄 끓이지 마세요. 쓴맛이 올라옵니다."}}],"troubleshooting":[{"id":"tom-yum-bitter","problem":{"zh-TW":"冬陰湯喝起來帶有苦澀味或酸味不自然","en":"Tom Yum soup tastes bitter or has an unpleasant medicinal sourness","th":"น้ำต้มยำมีรสขมปร่าหรือเปรี้ยวแหลมเกินไป","ja":"スープに不快な苦味が出たり、酸味がトゲトゲしくなった","ko":"국물에서 쓴맛이 나거나 자극적인 신맛이 돌아요"},"cause":{"zh-TW":"1. 檸檬汁在開火沸騰時倒入被過度加熱；2. 香茅或南薑皮切太厚久煮反苦；3. 使用了濃縮還原化學檸檬汁。","en":"1. Lime juice was added while boiling; 2. Aromatics steeped too long under violent boil; 3. Used artificial bottled lime juice.","th":"ใส่มะนาวตอนน้ำเดือด หรือใช้มะนาวขวดสังเคราะห์","ja":"1. ライム果汁を火にかけたまま煮立たせた。2. 煮込みすぎ。3. 市販の濃縮還元レモン果汁を使用した。","ko":"1. 불을 켠 채로 라임즙을 넣고 끓였거나, 2. 허브를 너무 오래 달였거나, 3. 시판 가공 레몬즙을 사용했습니다."},"solution":{"zh-TW":"絕對要關火離火後再調入現擠檸檬汁！並且務必使用新鮮青檸檬 (綠皮檸檬)，天然果酸最為柔和芬芳。","en":"Strictly kill heat before stirring in freshly squeezed green limes. Real fresh lime juice has mellow aromatic fruit acids.","th":"ดับเตาก่อนปรุงน้ำมะนาวสดแท้เสมอ","ja":"必ず火を止めてから、生のグリーンライムを絞り入れます。市販瓶詰めではなく生果汁を使うのが決め手です。","ko":"반드시 가스불을 완전히 끄고 나서 갓 짠 생라임즙을 둘러주세요."}}],"proTips":[{"zh-TW":"道地吃法：冬陰功湯中的香茅、南薑、檸檬葉是為了熬煮出植物香氣精華，泰國人在食用時通常是不吞食這些硬草藥的，只需品嚐湯汁與蝦肉！","en":"Authentic dining rule: The galangal, lemongrass stalks, and lime leaves are there strictly for aroma infusion. Thais leave them in the bowl and do not chew them!","th":"คนไทยรับประทานต้มยำโดยตักเฉพาะน้ำซุป เห็ด และกุ้ง ส่วนข่า ตะไคร้ ใบมะกรูด มีไว้เพื่อแต่งกลิ่น ไม่นิยมเคี้ยวกลืน","ja":"現地の作法：スープに入っているレモングラス、ガランガル、コブミカンの葉は香り出し用です。タイ人はこれらを噛まずにお椀に残し、スープと具材だけを楽しみます！","ko":"현지 에티켓: 똠얌 국물 속의 레몬그라스, 갈랑갈, 라임잎은 향을 내기 위한 약재입니다. 태국인들은 이를 씹어먹지 않고 그릇에 남겨둡니다!"}]},{"country":"th","id":"som-tum","slug":"som-tum","title":{"zh-TW":"伊森經典青木瓜沙拉","en":"Authentic Isan Green Papaya Salad (Som Tum)","th":"ส้มตำไทยต้นตำรับอีสาน","ja":"本場イサーン風ソムタム（青パパイヤの激辛サラダ）","ko":"정통 이산 쏨땀 타이 (그린 파파야 샐러드)"},"subtitle":{"zh-TW":"青木瓜爽脆・魚露椰糖檸檬汁黃金比例・石臼搗出靈魂","en":"Crisp Green Papaya Pounded in Mortar with Lime, Palm Sugar & Peanuts","th":"เส้นมะละกอกรอบ ตำในครกหิน รสชาติเปรี้ยวหวานเค็มเผ็ดครบรส","ja":"青パパイヤの快音シャキシャキ食感。クロック（臼）で叩き出す酸辛の極致","ko":"절구에 빻아 아삭함을 극대화한 새콤달콤 매콤한 파파야 샐러드"},"tagline":{"zh-TW":"泰國東北伊森的靈魂之光，酸、辣、甜、鹹在味蕾上四重奏爆發","en":"The iconic national salad pounding fresh green papaya into vibrant refreshment","th":"เมนูประจำชาติไทยจากแดนอีสาน แซ่บถึงใจ อร่อยไม่รู้ลืม","ja":"タイ東北地方（イサーン）が世界に誇る、五感を刺激する爽快サラダ","ko":"태국 이산 지방의 혼이 담긴 마성의 국민 샐러드"},"heroImage":"/images/th/som-tum.jpg","difficulty":"easy","prepTimeMinutes":15,"cookTimeMinutes":5,"defaultServings":2,"caloriesPerServing":160,"category":"salads","dietaryTags":["classic","glutenFree"],"supportedCookware":["traditional"],"culture":{"originRegion":{"zh-TW":"東北部・伊森 (Isan)","en":"Northeast / Isan","th":"ภาคตะวันออกเฉียงเหนือ (อีสาน)","ja":"東北部・イサーン地方","ko":"태국 북동부 이산"},"famousStreetMarkets":[{"zh-TW":"恰圖恰週末市集","en":"Chatuchak Weekend Market","th":"ตลาดนัดจตุจักร","ja":"チャトゥチャック・ウィークエンドマーケット","ko":"짜뚜짝 주말시장"},{"zh-TW":"曼谷勝利紀念碑街頭","en":"Victory Monument Food Street","th":"อนุสาวรีย์ชัยสมรภูมิ","ja":"アヌサワリー（戦勝記念塔）屋台街","ko":"빅토리 모뉴먼트 먹거리 거리"}],"historyStory":{"zh-TW":"「Som」在泰語中代表酸，「Tum」是木臼搗擊的聲響。青木瓜沙拉起源於泰國東北部農村，當地居民利用自家栽種的未熟青木瓜，搭配鳥眼椒、長豆、蒜頭與自釀魚露，在黏土木臼（Krok）中用力搗拌入味。配上一籃熱騰騰的竹筒糯米飯與烤雞，就是全泰國最令人上癮的街邊午餐組合。","en":"'Som' means sour in Lao/Isan dialect, and 'Tum' mimics the thumping rhythm of the wooden pestle in the mortar. Born in rural Northeast Thailand, farmers pounded crisp unripened papaya with chilies, garlic, long beans, and fish sauce. Paired with sticky rice in bamboo baskets and grilled chicken, it has conquered tables worldwide.","th":"คำว่า ส้ม แปลว่า เปรี้ยว และ ตำ คือเสียงครกสาก ส้มตำไทยเป็นมรดกภูมิปัญญาของชาวอีสาน ผสานความกรอบของมะละกอดิบกับรสเปรี้ยวหวานเค็มเผ็ดอย่างลงตัว รับประทานคู่กับข้าวเหนียวและไก่ย่าง","ja":"「ソム」は東北方言で酸っぱい、「タム」はすり鉢でトントン叩く音。タイ東北部で未熟な青パパイヤに唐辛子やニンニク、ナンプラーをクロック（素焼き臼）で叩き和えたのが始まり。もち米（カオニャオ）やガイヤーンとの相性は抜群です。","ko":"'쏨'은 이산 방언으로 시큼함, '땀'은 절구로 빻는 소리를 뜻합니다. 덜 익은 푸른 파파야를 마늘, 쥐똥고추, 피시소스와 함께 절구에 빻아 만듭니다. 따끈한 찹쌀밥과 숯불구이 치킨에 곁들이는 최고의 소울푸드입니다."},"thaiScript":"ส้มตำไทย","thaiPhonetics":"Som Tum Thai","audioPronunciationText":"ขอส้มตำไทยหนึ่งครก เผ็ดน้อยใส่ถั่วเยอะๆ ครับ","nativeName":"ส้มตำไทย"},"ingredients":[{"id":"green-papaya","name":{"zh-TW":"新鮮青木瓜 (去皮刨細絲並冰鎮)","en":"Firm Green Unripe Papaya (Shredded & iced)","th":"มะละกอดิบสับเส้นกรอบ","ja":"青パパイヤ（千切り・氷水で締める）","ko":"그린 파파야 (채 썰어 얼음물에 담가둔 것)"},"amount":250,"unitMetric":"g","unitUS":"8.8 oz","isKeyFlavor":true,"thaiName":"มะละกอดิบ","thaiPronunciation":"Ma-La-Kor Dib","substitute":{"substituteName":{"zh-TW":"白大頭菜絲或結球甘藍 (高麗菜絲)","en":"Shredded kohlrabi, green cabbage, or jicama","th":"กะหล่ำปลีหรือแครอทสับ","ja":"コールラビまたはキャベツの芯の千切り","ko":"콜라비 채 또는 단단한 양배추 채"},"ratio":"1:1","explanation":{"zh-TW":"青木瓜主要提供無味的爽脆口感。大頭菜或結球甘藍洗淨切絲冰鎮，爽脆度可達 90% 相似！","en":"Green papaya has a neutral, extra-crunchy snap. Iced shredded kohlrabi replicates the texture perfectly.","th":"ใช้กะหล่ำปลีหรือแครอทแทนได้ กรอบอร่อยไม่แพ้กัน","ja":"青パパイヤの命はシャキシャキ感。氷水で締めたコールラビやキャベツで驚くほど近く再現できます","ko":"그린 파파야는 식감이 핵심입니다. 얼음물에 담근 채 썬 콜라비나 양배추로 완벽하게 대체할 수 있습니다."},"whereToBuy":{"zh-TW":"東南亞生鮮店或一般超市蔬果區","en":"Asian supermarkets or standard produce aisle","th":"ตลาดสดทั่วไป","ja":"アジア青果店または大型スーパー","ko":"아시안 식료품점 또는 대형마트"}}},{"id":"garlic-cloves","name":{"zh-TW":"蒜瓣 (帶皮)","en":"Garlic Cloves (Skin-on)","th":"กระเทียมไทย","ja":"タイ産ニンニク","ko":"마늘 3쪽"},"amount":3,"unitMetric":"clove","unitUS":"clove","thaiName":"กระเทียม","thaiPronunciation":"Kra-Thiam"},{"id":"birds-eye-chilies","name":{"zh-TW":"泰國朝天椒 (依辣度調整)","en":"Thai Bird's Eye Chilies (Adjust to taste)","th":"พริกขี้หนูสวน","ja":"タイ産赤唐辛子（プリッキーヌー）","ko":"태국 쥐똥고추"},"amount":3,"unitMetric":"piece","unitUS":"piece","isKeyFlavor":true,"thaiName":"พริกขี้หนู","thaiPronunciation":"Prik Khee Noo"},{"id":"yardlong-beans","name":{"zh-TW":"泰國長豆 (切 3cm 段)","en":"Yardlong Snake Beans (Cut into 1-inch pieces)","th":"ถั่วฝักยาวหั่นท่อน","ja":"ササゲ（ジュウロクササゲまたはインゲン）","ko":"줄기콩 (롱빈, 3cm 크기로 자른 것)"},"amount":40,"unitMetric":"g","unitUS":"1.4 oz","thaiName":"ถั่วฝักยาว","thaiPronunciation":"Thua Fak Yao"},{"id":"cherry-tomatoes","name":{"zh-TW":"小番茄 (切半)","en":"Cherry Tomatoes (Halved)","th":"มะเขือเทศสีดาผ่าซีก","ja":"ミニトマト（半分にカット）","ko":"방울토마토 (반으로 썬 것)"},"amount":6,"unitMetric":"piece","unitUS":"piece","thaiName":"มะเขือเทศ","thaiPronunciation":"Ma-Khuea Thet"},{"id":"dried-shrimp","name":{"zh-TW":"泰國優質金鉤蝦米 (略溫水洗淨瀝乾)","en":"Thai Dried Baby Shrimp (Rinsed & drained)","th":"กุ้งแห้งเกรดเอ","ja":"干し海老（ぬるま湯で洗う）","ko":"건새우 (살짝 헹군 것)"},"amount":2,"unitMetric":"tbsp","unitUS":"2 tbsp","isKeyFlavor":true,"thaiName":"กุ้งแห้ง","thaiPronunciation":"Goong Haeng"},{"id":"roasted-peanuts","name":{"zh-TW":"香脆熟花生粒","en":"Roasted Crushed Peanuts","th":"ถั่วลิสงคั่วใหม่","ja":"ローストピーナッツ（粗砕き）","ko":"볶은 땅콩 분태"},"amount":3,"unitMetric":"tbsp","unitUS":"3 tbsp","isKeyFlavor":true,"thaiName":"ถั่วลิสงคั่ว","thaiPronunciation":"Thua Li-Song Khua"},{"id":"palm-sugar","name":{"zh-TW":"泰國純椰糖","en":"Thai Palm Sugar","th":"น้ำตาลปี๊บ","ja":"パームシュガー","ko":"태국 팜슈가"},"amount":1.5,"unitMetric":"tbsp","unitUS":"1.5 tbsp","isKeyFlavor":true,"thaiName":"น้ำตาลปี๊บ","thaiPronunciation":"Nam Tan Peep"},{"id":"fish-sauce","name":{"zh-TW":"特級純魚露","en":"Premium Fish Sauce","th":"น้ำปลาแท้","ja":"高級ナンプラー","ko":"피시소스"},"amount":2,"unitMetric":"tbsp","unitUS":"2 tbsp","isKeyFlavor":true,"thaiName":"น้ำปลา","thaiPronunciation":"Nam Pla"},{"id":"fresh-lime-juice","name":{"zh-TW":"新鮮現擠檸檬汁 (保留檸檬皮瓣)","en":"Fresh Lime Juice (Keep half a squeezed rind for pounding)","th":"น้ำมะนาวแท้พร้อมเปลือก","ja":"搾りたて生ライム果汁（搾った皮も一緒に叩く）","ko":"생라임즙 (짠 라임 껍질 1조각 포함)"},"amount":2.5,"unitMetric":"tbsp","unitUS":"2.5 tbsp","isKeyFlavor":true,"thaiName":"น้ำมะนาว","thaiPronunciation":"Nam Ma-Nao"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"冰鎮青木瓜絲，保持極致爽脆","en":"Ice-Water Papaya Bath for Super Crispness","th":"แช่เส้นมะละกอในน้ำแข็ง","ja":"青パパイヤの氷水締め","ko":"파파야 채 얼음물에 담가 아삭함 살리기"},"instruction":{"zh-TW":"將青木瓜去皮後，用菜刀密集敲擊瓜肉表面再薄切成細絲（或用刨絲刀刨出均勻細條）。將木瓜絲立即浸入冰水 10 分鐘，撈出徹底瀝乾水份備用。這個步驟能讓木瓜絲吸收冰水達到清脆彈牙的極致境界！","en":"Peel green papaya and shred into thin matchsticks using a Thai wavy peeler or knife chops. Plunge papaya shreds into ice water for 10 minutes, then drain thoroughly. This locks in extraordinary crispness!","th":"สับมะละกอเป็นเส้น แช่ในน้ำเย็นจัดผสมน้ำแข็ง 10 นาที แล้วสะเด็ดน้ำให้แห้งสนิท เส้นจะกรอบเด้ง","ja":"青パパイヤの皮をむき、包丁で細かく叩いてそぎ切りにするか千切りスライサーで麺状にします。すぐに氷水に10分間浸し、水気をしっかり切ります。これで驚くほどのシャキシャキ感が生まれます！","ko":"껍질 벗긴 그린 파파야를 칼집을 내어 채 썰거나 채칼로 얇게 썹니다. 즉시 얼음물에 10분간 담갔다가 물기를 완전히 빼주세요. 아삭함이 극대화됩니다!"},"durationSeconds":600,"image":"/images/th/som-tum-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"臼中擣碎大蒜與朝天椒","en":"Pound Garlic & Bird's Eye Chilies","th":"ตำพริกกระเทียมพอหยาบ","ja":"ニンニクと唐辛子を粗く叩き潰す","ko":"절구에 마늘과 쥐똥고추 빻기"},"instruction":{"zh-TW":"在木臼或陶臼（若無可用大鋼盆配木擀麵棍）中放入蒜瓣與朝天椒。用木杵輕快擣碎至粗粒狀，釋放出蒜油與辣椒素，切勿搗成泥狀。","en":"In a mortar (or a deep stainless bowl with a rolling pin), add garlic and bird's eye chilies. Pound rhythmically into a coarse mash to release aromatic garlic oils and fiery capsaicin.","th":"ใส่กระเทียมและพริกขี้หนูลงในครก ตำบุบพอแหลก ไม่ต้องละเอียดจนเกินไป","ja":"すり鉢にニンニクと赤唐辛子を入れます。すりこぎでトントンとリズミカルに叩き、粗く潰して香りオイルを引き出します（ペースト状にしないこと）。","ko":"절구에 마늘과 쥐똥고추를 넣고 방망이로 쿵쿵 찧어 거칠게 으깨어 매운 향을 끌어냅니다. 곱게 갈지 마세요."},"durationSeconds":60,"image":"/images/th/som-tum-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"加入長豆、蝦米與調製靈魂醬汁","en":"Bruise Long Beans, Dried Shrimp & Dissolve Palm Sugar","th":"ใส่ถั่วฝักยาว กุ้งแห้ง ปรุงน้ำยำ","ja":"長豆・干し海老を軽く潰し、合わせダレを溶かす","ko":"롱빈, 건새우 넣고 팜슈가 양념 녹이기"},"instruction":{"zh-TW":"加入切段長豆與蝦米，用杵輕輕敲扁讓豆肉裂開入味。加入椰糖、魚露、現擠檸檬汁，甚至可投入半顆擠乾的檸檬皮瓣（帶出精油果香）。用木杵一邊研磨椰糖一邊用湯匙翻動，直至糖粒完全融化成金黃濃稠醬汁。","en":"Add long beans and dried shrimp. Lightly bruise them with the pestle. Add palm sugar, fish sauce, lime juice, and toss in half a squeezed lime wedge. Grind sugar with pestle while scraping with spoon until fully melted.","th":"ใส่ถั่วฝักยาวและกุ้งแห้ง ตำพอแตก ใส่น้ำตาลปี๊บ น้ำปลา น้ำมะนาว และเปลือกมะนาว ใช้สากบดน้ำตาลพร้อมช้อนคนจนละลาย","ja":"長豆と干し海老を加え、トントンと軽く叩いて味を染み込ませます。パームシュガー、ナンプラー、ライム汁、さらに絞った皮1切れを加えます。スプーンで混ぜながらパームシュガーをすり潰し完全に溶かします。","ko":"롱빈과 건새우를 넣고 살짝 으깹니다. 팜슈가, 피시소스, 라임즙, 즙 짠 라임 껍질을 넣고 숟가락으로 긁어가며 팜슈가가 다 녹을 때까지 섞어줍니다."},"durationSeconds":90,"image":"/images/th/som-tum-step3.jpg"},{"stepNumber":4,"title":{"zh-TW":"下木瓜絲與小番茄，一手臼杵一手匙輕搗拌勻","en":"Pound & Spoon-Fold Papaya Shreds and Cherry Tomatoes","th":"ใส่มะละกอ มะเขือเทศ ตำเคล้าด้วยสากและช้อน","ja":"パパイヤとトマトを入れ、叩きながらスプーンで和える","ko":"파파야와 방울토마토를 넣고 빻으며 버무리기"},"instruction":{"zh-TW":"投入冰鎮瀝乾的青木瓜絲與切半小番茄。一手拿木杵輕柔搗擊，另一手拿大湯匙不斷由下往上翻拌。重點在於「輕敲快拌」讓木瓜纖維稍稍受力吸收醬汁，切忌死命重搗把木瓜搗爛成泥！翻拌約 30 秒至均勻浸潤。","en":"Toss in drained papaya shreds and tomato halves. Using a synchronized motion: lightly tap with pestle in one hand while lifting and folding with a large spoon in the other. Bruise just enough for juices to penetrate without turning to mush (about 30 secs).","th":"ใส่มะละกอและมะเขือเทศ มือหนึ่งตำเบาๆ อีกมือใช้ช้อนตลบจากก้นครกขึ้นมา ให้เส้นดูดซับน้ำส้มตำอย่างทั่วถึงโดยไม่เละ","ja":"水気を切った青パパイヤとミニトマトを加えます。片手ですしこぎをトントンと優しく落とし、もう片方の手のスプーンで底からすくい上げるようにリズミカルに30秒和えます。パパイヤの食感を潰さないよう優しく！","ko":"파파야 채와 방울토마토를 넣습니다. 한 손으로는 절굿공이로 톡톡 가볍게 두드리고, 다른 손으로는 숟가락으로 아래에서 위로 퍼 올리며 30초간 버무립니다. 절대 짓이기지 마세요!"},"durationSeconds":45,"image":"/images/th/som-tum-step4.jpg"},{"stepNumber":5,"title":{"zh-TW":"撒上大量香脆花生，盛盤上桌","en":"Fold in Roasted Peanuts & Plate Immediately","th":"โรยถั่วลิสงคั่ว ตักใส่จานเสิร์ฟ","ja":"ローストピーナッツをたっぷり散らして盛り付け","ko":"볶은 땅콩 듬뿍 뿌려 완성"},"instruction":{"zh-TW":"撒入 3 大匙香脆烤花生碎，用湯匙最後輕輕拌勻兩下。連同鮮美酸甜的醬汁一同盛入盤中，旁邊可擺上高麗菜塊或長豆生食搭配。建議立即享用，青木瓜最為爽脆！","en":"Fold in 3 tbsp of crunchy roasted peanuts. Transfer salad along with its vibrant tangy juices onto a platter. Serve immediately alongside raw cabbage wedges and long beans for the authentic Isan experience!","th":"ใส่ถั่วลิสงคั่วบด คลุกเคล้าให้เข้ากัน ตักเสิร์ฟพร้อมกะหล่ำปลีสดและถั่วฝักยาว ทานทันทีขณะเส้นกรอบที่สุด","ja":"香ばしいピーナッツをたっぷり加え、スプーンでサッとひと混ぜ。溢れる旨み果汁ごと器に盛り付けます。生のキャベツやもち米を添えて、出来立ての最高にクリスピーな状態でお召し上がりください！","ko":"고소한 볶은 땅콩을 듬뿍 넣고 가볍게 섞어줍니다. 상큼한 즙과 함께 접시에 담고, 생양배추 조각이나 찹쌀밥을 곁들여 바로 드세요!"},"durationSeconds":30,"image":"/images/th/som-tum-step5.jpg"}],"troubleshooting":[{"id":"som-tum-watery","problem":{"zh-TW":"沙拉出水嚴重、木瓜絲變軟不脆","en":"Salad became soggy, watery, and lost its crunch","th":"ส้มตำแฉะ เส้นเหี่ยวไม่กรอบ","ja":"水っぽくなり、パパイヤがしんなりしてシャキシャキ感が消えた","ko":"물이 너무 많이 생기고 파파야가 물러졌어요"},"cause":{"zh-TW":"1. 刨絲後沒有冰鎮或瀝乾水份；2. 搗木瓜絲時用力過猛把細胞壁全部搗破出水；3. 拌好後放太久未立即食用。","en":"1. Papaya was not iced or drained well; 2. Pounded with excessive force crushing cell walls; 3. Sat too long after dressing.","th":"สะเด็ดน้ำไม่แห้ง ตำเส้นแรงเกินไป หรือทิ้งไว้นานเกินไป","ja":"1. 氷水締めの後の水切り不足。2. すり鉢でパパイヤを強く叩き潰しすぎた。3. 和えてから時間が経ちすぎた。","ko":"1. 얼음물 목욕 후 물기를 덜 털었거나, 2. 너무 세게 빻아서 채소 즙이 다 터졌거나, 3. 무친 후 오래 방치했습니다."},"solution":{"zh-TW":"嚴格將木瓜絲瀝乾，擣拌時採「一手輕搗一手匙翻」，讓木瓜表面吸收調味即可。現拌現吃最美味！","en":"Dry papaya thoroughly. Use synchronized gentle pestle-tapping and spoon-folding. Eat within 15 minutes of tossing.","th":"สะเด็ดน้ำให้แห้งสนิท ตำเบาๆ มือและตักเสิร์ฟทันที","ja":"しっかり水気を切り、叩く力は優しくスプーン主動で和え、和えたら15分以内に食べ切るのが黄金則です。","ko":"물기를 완벽히 제거하고, 힘을 빼고 톡톡 두드리며 숟가락으로 버무리세요. 무치자마자 바로 드셔야 합니다."}}],"proTips":[{"zh-TW":"伊森老饕吃法：將擠乾的檸檬皮瓣（洗淨無蠟）丟進石臼一起輕輕擣兩下，檸檬皮中的柑橘天然芳香精油會完全釋放到魚露汁裡，香氣層次直接連跳三級！","en":"Street master hack: Toss the squeezed fresh lime rinds right into the mortar and bruise them lightly. The aromatic citrus oils in the peel infuse into the fish sauce, elevating the aromatics tenfold!","th":"เคล็ดลับแม่ค้าส้มตำ: ใส่เปลือกมะนาวที่คั้นแล้วลงไปตำเบาๆ น้ำมันหอมระเหยจากผิวมะนาวจะทำให้ส้มตำหอมชวนน้ำลายสอ","ja":"屋台の裏技：果汁を絞った後のライムの皮をすり鉢に入れて軽くトントン叩くと、皮に含まれる爽やかな柑橘精油が溶け出し、香りの格が劇的にアップします！","ko":"현지 달인의 비법: 즙을 짠 라임 껍질을 절구에 함께 넣고 살짝 빻아주세요. 껍질 속의 천연 시트러스 오일이 양념에 배어들어 풍미가 놀랍도록 깊어집니다!"}]},{"country":"th","id":"khao-soi-gai","slug":"khao-soi-gai","title":{"zh-TW":"清邁正宗泰北金麵 (咖哩雞腿麵)","en":"Northern Chiang Mai Khao Soi Gai (Curry Noodle Soup)","th":"ข้าวซอยไก่เมืองเชียงใหม่","ja":"チェンマイ名物 カオソーイ・ガイ（濃厚カレーヌードル）","ko":"치앙마이 정통 카오소이 가이 (닭다리 카레 국수)"},"subtitle":{"zh-TW":"雙重麵條口感・黃金香濃椰奶咖哩雞腿・泰北酸菜紅蔥頭靈魂配菜","en":"Silky Boiled & Crispy Deep-Fried Egg Noodles in Rich Coconut Curry","th":"เส้นสองแบบ ทั้งลวกนุ่มและกรอบกรุบ แกงกะทิหอมเครื่องเทศล้านนา","ja":"茹で麺とサクサク揚げ麺の二重奏。ココナッツミルク仕立ての奥深いスパイススープ","ko":"부드러운 면과 바삭한 튀김 면의 환상 조합, 진한 코코넛 카레 육수"},"tagline":{"zh-TW":"孤獨星球推薦世界頂級美食，清邁蘭納王朝遺留的味覺傳奇","en":"The crowning culinary jewel of Northern Thailand featuring tender chicken in rich spiced curry","th":"สุดยอดอาหารล้านนาขึ้นชื่อระดับโลก รสชาติกลมกล่อมหอมมันกะทิ","ja":"世界の美食ランキングで絶賛される、北タイ・チェンマイが誇る至高の麺料理","ko":"론리플래닛 세계 최고의 음식으로 선정된 치앙마이의 독보적인 카레 국수"},"heroImage":"/images/th/khao-soi.jpg","difficulty":"medium","prepTimeMinutes":20,"cookTimeMinutes":35,"defaultServings":4,"caloriesPerServing":650,"category":"mains","dietaryTags":["classic","halal"],"supportedCookware":["traditional","instantPot"],"culture":{"originRegion":{"zh-TW":"北部・清邁 (Chiang Mai)","en":"Northern / Chiang Mai","th":"ภาคเหนือ / เชียงใหม่","ja":"北部・チェンマイ","ko":"태국 북부 치앙마이"},"famousStreetMarkets":[{"zh-TW":"清邁週六/週日夜市","en":"Chiang Mai Walking Street Night Market","th":"ถนนคนเดินเชียงใหม่","ja":"チェンマイ・サンデーウォーキングストリート","ko":"치앙마이 선데이 워킹스트리트"},{"zh-TW":"瓦洛洛市場 (Warorot)","en":"Warorot Market (Kad Luang)","th":"ตลาดวโรรส","ja":"ワロロット市場","ko":"와로롯 시장"}],"historyStory":{"zh-TW":"Khao Soi 是泰北蘭納文化與雲南穆斯林商隊貿易融合的歷史瑰寶。十九世紀十九世紀來自雲南的「秦霍人」（Chin Haw）商隊將黑荳蔻、薑黃等乾燥香料與黃金雞蛋麵傳入清邁，泰國廚師進一步融入本地濃郁椰奶與酸辣醃菜，演變成如今頂端鋪滿金黃香脆油炸麵酥、底部是柔嫩燉雞腿的傳奇麵食。","en":"Khao Soi reflects centuries of cultural exchange between Northern Lanna culture and Yunnanese Muslim mule caravans (Chin Haw) traveling the ancient spice roads. The dry whole spices (turmeric, black cardamom) merged with rich Thai coconut milk, culminating in the dish's hallmark: boiled flat egg noodles below, tender chicken drumstick within, and a crispy bird's-nest of fried noodles on top.","th":"ข้าวซอยมีรากเหง้ามาจากการค้าขายของพ่อค้าชาวจีนฮ่อมุสลิม นำเครื่องเทศแห้งอย่างลูกกระวานและขมิ้นมาผสมผสานกับกะทิสดและผักกาดดอง จนกลายเป็นเอกลักษณ์ประจำเมืองเชียงใหม่","ja":"かつて雲南からキャラバンを組んで渡ってきたイスラム系商人（チン・ホー）がもたらしたスパイス文化が、チェンマイの宮廷・郷土料理と結実。カルダモンやターメリックが香るカレースープに、茹で麺と揚げ麺をダブルでトッピングするのが最大の特徴です。","ko":"19세기 윈난에서 건너온 무슬림 상인들의 향신료 문화와 란나 왕국의 코코넛 밀크가 만나 탄생했습니다. 그릇 바닥에는 부드러운 에그누들과 야들야들한 닭다리가, 위에는 바삭하게 튀긴 면이 둥지처럼 얹어집니다."},"thaiScript":"ข้าวซอยไก่","thaiPhonetics":"Khao Soi Gai","audioPronunciationText":"ขอข้าวซอยไก่หนึ่งชาม พิเศษผักกาดดองครับ","nativeName":"ข้าวซอยไก่"},"ingredients":[{"id":"chicken-drumsticks","name":{"zh-TW":"優質土雞腿或全雞大腿","en":"Bone-in Chicken Drumsticks or Thighs","th":"น่องไก่สดติดกระดูก","ja":"骨付き鶏もも肉または手羽元","ko":"북채(닭다리) 또는 닭 넓적다리"},"amount":4,"unitMetric":"piece","unitUS":"piece","isKeyFlavor":true,"thaiName":"น่องไก่","thaiPronunciation":"Nong Gai"},{"id":"egg-noodles","name":{"zh-TW":"新鮮廣式扁全蛋麵 (分煮麵與炸脆麵兩用)","en":"Fresh Flat Egg Noodles (Divided: for boiling & deep-frying)","th":"บะหมี่ไข่เส้นแบน","ja":"生中華麺（平打ちエッグヌードル・茹で用と揚げ用）","ko":"생 에그누들 (삶는용과 튀김용으로 분리)"},"amount":350,"unitMetric":"g","unitUS":"12 oz","isKeyFlavor":true,"thaiName":"บะหมี่ไข่","thaiPronunciation":"Ba-Mee Khai"},{"id":"coconut-cream","name":{"zh-TW":"泰國特濃椰漿 (頭遍濃椰漿)","en":"Thick Coconut Cream (First press)","th":"หัวกะทิแท้ 100%","ja":"濃厚ココナッツクリーム（チャオコーまたはアロイディー）","ko":"진한 코코넛 크림"},"amount":400,"unitMetric":"ml","unitUS":"13.5 fl oz","isKeyFlavor":true,"thaiName":"หัวกะทิ","thaiPronunciation":"Hua Ka-Thi"},{"id":"chicken-broth","name":{"zh-TW":"低鹽雞高湯","en":"Low-Sodium Chicken Broth","th":"น้ำซุปกระดูกไก่","ja":"チキンブロス（鶏ガラスープ）","ko":"닭 육수"},"amount":500,"unitMetric":"ml","unitUS":"17 fl oz","thaiName":"น้ำซุปไก่","thaiPronunciation":"Nam Soup Gai"},{"id":"khao-soi-paste","name":{"zh-TW":"泰北金麵咖哩醬 (或紅咖哩醬+黃咖哩粉)","en":"Khao Soi Curry Paste (or Red Curry Paste + Yellow Curry Powder)","th":"พริกแกงข้าวซอย","ja":"カオソーイペースト（またはレッドカレーペースト＋カレー粉）","ko":"카오소이 페이스트 (또는 레드카레 페이스트 + 카레가루)"},"amount":4,"unitMetric":"tbsp","unitUS":"4 tbsp","isKeyFlavor":true,"thaiName":"พริกแกงข้าวซอย","thaiPronunciation":"Prik Gaeng Khao Soi","substitute":{"substituteName":{"zh-TW":"泰國紅咖哩醬 3匙 + 薑黃粉1茶匙 + 咖哩粉1茶匙","en":"3 tbsp Thai Red Curry Paste + 1 tsp Turmeric + 1 tsp Curry powder","th":"พริกแกงเผ็ดผสมผงกะหรี่และผงขมิ้น","ja":"タイ産レッドカレーペースト大さじ3 ＋ カレー粉小さじ1 ＋ ターメリック小さじ1","ko":"레드 카레 페이스트 3큰술 + 카레가루 1작은술 + 강황가루 1작은술"},"ratio":"1:1","explanation":{"zh-TW":"清邁金麵的特色在於紅咖哩基底融入薑黃與小荳蔻的芳香，混合後風味還原度達 95%！","en":"Khao Soi paste differs from standard red curry by its warm turmeric and cardamom notes.","th":"ผสมผงกะหรี่และขมิ้นเพื่อเพิ่มกลิ่นอายเครื่องเทศล้านนา","ja":"レッドカレーにターメリックとカルダモンの香りを加えることで本場の味を完璧に再現できます","ko":"일반 레드카레에 강황과 카레가루를 섞으면 치앙마이 현지의 진한 맛이 그대로 재현됩니다."},"whereToBuy":{"zh-TW":"進口超市或線上泰國香料專賣","en":"Amazon or Asian supermarket","th":"ตลาดสดภาคเหนือ","ja":"輸入食品スーパー","ko":"온라인 아시안 식자재몰"}}},{"id":"palm-sugar","name":{"zh-TW":"泰國椰糖","en":"Thai Palm Sugar","th":"น้ำตาลปี๊บ","ja":"パームシュガー","ko":"팜슈가"},"amount":1.5,"unitMetric":"tbsp","unitUS":"1.5 tbsp","thaiName":"น้ำตาลปี๊บ","thaiPronunciation":"Nam Tan Peep"},{"id":"fish-sauce","name":{"zh-TW":"純魚露","en":"Fish Sauce","th":"น้ำปลาแท้","ja":"ナンプラー","ko":"피시소스"},"amount":2.5,"unitMetric":"tbsp","unitUS":"2.5 tbsp","thaiName":"น้ำปลา","thaiPronunciation":"Nam Pla"},{"id":"pickled-mustard-greens","name":{"zh-TW":"泰式酸菜 (切碎 - 靈魂解膩配菜)","en":"Thai Pickled Mustard Greens (Chopped - Essential side)","th":"ผักกาดดองหั่นซอย","ja":"高菜漬けまたはタイ風からし菜漬け（刻み）","ko":"태국 갓절임 (잘게 썬 것 - 필수 곁들임)"},"amount":80,"unitMetric":"g","unitUS":"2.8 oz","isKeyFlavor":true,"thaiName":"ผักกาดดอง","thaiPronunciation":"Phak Kat Dong"},{"id":"shallots","name":{"zh-TW":"紅蔥頭 (切厚片)","en":"Thai Shallots (Thick sliced)","th":"หอมแดงซอย","ja":"紫エシャロット（赤わけぎ・スライス）","ko":"샬롯 (두껍게 편 썬 것)"},"amount":4,"unitMetric":"piece","unitUS":"piece","thaiName":"หอมแดง","thaiPronunciation":"Hom Daeng"},{"id":"lime-wedges","name":{"zh-TW":"新鮮檸檬角","en":"Fresh Lime Wedges","th":"มะนาวผ่าซีก","ja":"くし形切り生ライム","ko":"생라임 조각"},"amount":4,"unitMetric":"piece","unitUS":"piece","thaiName":"มะนาว","thaiPronunciation":"Ma-Nao"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"煸炒椰漿出油，炒香咖哩金醬","en":"Crack Coconut Cream & Fry Curry Paste","th":"ผัดหัวกะทิให้แตกมัน ผัดพริกแกงให้หอม","ja":"ココナッツミルクの油分分離とペースト炒め","ko":"코코넛 크림 기름 분리 및 카레 페이스트 볶기"},"instruction":{"zh-TW":"在深鍋中倒入 150ml 濃椰漿，以中火慢煮 3-4 分鐘，輕輕攪拌直到椰漿水分蒸發、表面浮現一層清亮芳香的天然椰油（Crack the coconut milk）。加入 4 大匙咖哩醬，在椰油中慢火翻炒 2 分鐘，直至香料紅亮濃香四溢。","en":"In a pot, heat 150ml thick coconut cream over medium heat for 3-4 minutes until it separates ('cracks') into fragrant clear coconut oil on top. Add Khao Soi curry paste and fry in the coconut oil for 2 minutes until intensely aromatic and glistening.","th":"ตั้งหม้อใส่หัวกะทิ 150 มล. เคี่ยวไฟกลางจนกะทิแตกมันลอยหน้า ใส่พริกแกงข้าวซอยลงผัดจนหอมฟุ้งและขึ้นสีเงาสวย","ja":"深鍋にココナッツクリーム150mlを入れ、中火で3〜4分煮詰めて表面に透明なココナッツオイルを分離させます（クラッキング技法）。ペーストを加え、オイルの中で2分じっくり炒めてスパイスの香りを最大限に引き出します。","ko":"냄비에 코코넛 크림 150ml를 붓고 중불에서 3~4분간 끓여 맑은 코코넛 오일이 분리되어 뜰 때까지 졸입니다. 카레 페이스트를 넣고 2분간 볶아 붉은 향신료 기름을 만듭니다."},"durationSeconds":300,"image":"/images/th/khao-soi-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"下雞腿裹滿醬汁，注入高湯溫火慢燉","en":"Sear Drumsticks & Simmer in Spiced Coconut Broth","th":"ใส่น่องไก่ เติมน้ำซุปและกะทิ เคี่ยวจนนุ่ม","ja":"鶏肉を絡め炒め、ブロスを注ぎじっくり煮込む","ko":"닭다리에 양념 코팅 후 육수 붓고 뭉근하게 끓이기"},"instruction":{"zh-TW":"放入雞腿翻炒 2 分鐘讓肉皮均勻裹上金黃咖哩。倒入剩餘椰漿 250ml 與 500ml 雞高湯。大火煮滾後轉小火，調入椰糖與魚露，加蓋慢燉 25 分鐘，直到雞腿肉質鬆軟多汁、骨肉即將分離。","en":"Add chicken drumsticks, turning to coat in golden paste for 2 mins. Pour in remaining 250ml coconut cream and 500ml chicken broth. Bring to a boil, stir in palm sugar and fish sauce, reduce to low, cover and simmer for 25 minutes until chicken is meltingly tender.","th":"ใส่น่องไก่ลงผัดให้เคลือบน้ำแกง เทกะทิที่เหลือและน้ำซุปไก่ลงไป ปรุงรสด้วยน้ำตาลปี๊บและน้ำปลา ปิดฝาตุ๋นไฟอ่อน 25 นาทีจนเนื้อไก่นุ่มร่อน","ja":"鶏肉を入れて2分炒め、残りのココナッツミルク250mlと鶏ガラスープ500mlを注ぎます。パームシュガーとナンプラーを加え、蓋をして弱火で25分煮込み、肉がホロホロに柔らかくなるまで火を通します。","ko":"닭다리를 넣고 2분간 볶아 양념을 고루 입힌 후, 남은 코코넛 크림 250ml와 닭 육수 500ml를 붓습니다. 팜슈가와 피시소스로 간하고 뚜껑을 덮어 약불에서 25분간 닭다리가 야들야들해질 때까지 푹 삶습니다."},"durationSeconds":1500,"image":"/images/th/khao-soi-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"炸出黃金酥脆麵鳥巢 (靈魂口感)","en":"Deep-Fry Golden Crispy Noodle Bird's Nest","th":"ทอดเส้นบะหมี่กรอบสีทอง","ja":"サクサク黄金揚げ麺（鳥の巣トッピング）を作る","ko":"바삭한 황금빛 면 튀김(새둥지) 만들기"},"instruction":{"zh-TW":"取 1/3 的生雞蛋麵（約 100g），抖散多餘麵粉。小油鍋加熱至 180°C，將麵條放入熱油中炸 20-30 秒，麵條會瞬間膨脹酥脆成金黃小鳥巢狀，立刻撈起放在廚房紙巾上瀝油。","en":"Separate 1/3 of raw egg noodles (about 100g) and shake off excess flour. Heat oil to 180°C (350°F). Deep-fry noodles for 20-30 seconds until puffed, golden, and shatteringly crisp. Drain on paper towels.","th":"แบ่งบะหมี่ไข่ 1 ใน 3 มาคลี่เส้น ทอดในน้ำมันร้อนปานกลาง 20-30 วินาทีจนฟูกรอบสีเหลืองทอง ตักขึ้นพักสะเด็ดน้ำมัน","ja":"生麺の1/3（約100g）の打ち粉を払い、180℃の油で20〜30秒サッと揚げます。一瞬でふわっと広がり黄金色の鳥の巣のようにカリカリになったら油を切ります。","ko":"에그누들의 1/3(약 100g) 분량을 털어 180℃ 기름에서 20~30초간 바삭하게 튀겨냅니다. 황금빛 새둥지 모양이 되면 건져 기름을 뺍니다."},"durationSeconds":60,"image":"/images/th/khao-soi-step3.jpg"},{"stepNumber":4,"title":{"zh-TW":"滾水燙熟軟麵條","en":"Boil Soft Egg Noodles","th":"ลวกเส้นบะหมี่นุ่มเหนียว","ja":"残りの生麺をもっちり茹で上げる","ko":"남은 에그누들 쫄깃하게 삶기"},"instruction":{"zh-TW":"另一鍋滾水大火沸騰，放入剩餘 2/3 雞蛋麵燙煮 60-75 秒至剛好斷生且保有彈性。撈起甩乾水分，分裝盛入 4 個深碗底部。","en":"Bring a large pot of water to a rolling boil. Cook remaining 2/3 egg noodles for 60-75 seconds until al dente and bouncy. Drain well and divide into the bottoms of 4 deep serving bowls.","th":"ลวกเส้นบะหมี่ที่เหลือในน้ำเดือด 1 นาที สะเด็ดน้ำให้แห้ง แบ่งใส่ก้นชาม","ja":"大鍋に湯を沸かし、残りの麺を60〜75秒茹でてザルに上げ、湯切りをして丼の底に盛り付けます。","ko":"끓는 물에 남은 2/3의 에그누들을 넣고 60~75초간 알덴테로 쫄깃하게 삶아 물기를 털어내고 그릇 바닥에 담습니다."},"durationSeconds":75,"image":"/images/th/khao-soi-step4.jpg"},{"stepNumber":5,"title":{"zh-TW":"盛碗、淋上金湯、頂端加冕酥脆麵與解膩配菜","en":"Ladle Rich Broth, Crown with Crispy Noodles & Garnish","th":"ตักแกงราด วางไก่ โปะบะหมี่กรอบ เสิร์ฟพร้อมเครื่องเคียง","ja":"スープを注ぎ、骨付き肉と揚げ麺を冠して完成","ko":"진한 국물 붓고 닭다리와 바삭한 튀김면 얹어 완성"},"instruction":{"zh-TW":"將燉得軟爛的大雞腿夾在麵條上，舀入滾燙濃醇的金色咖哩椰汁覆蓋麵條。在最頂端放上一大團金黃酥脆的炸麵巢。旁邊附上一小碟泰式酸菜碎、切片紫紅蔥頭與新鮮檸檬角。食用前擠入大量檸檬汁、混入酸菜，享受清爽與濃醇的衝擊！","en":"Place a tender chicken drumstick over the boiled noodles. Ladle scorching golden curry broth over the top. Crown with the crispy fried noodle nest. Serve with pickled mustard greens, sliced shallots, and fresh lime wedges. Squeeze lime juice and toss in pickled greens before diving in!","th":"ตักน่องไก่วางบนเส้น ราดน้ำแกงข้าวซอยร้อนๆ วางบะหมี่กรอบไว้ด้านบน เสิร์ฟพร้อมผักกาดดอง หอมแดงซอย และมะนาวผ่าซีก บีบมะนาวก่อนทานเพื่อตัดเลี่ยน","ja":"麺の上に骨付きチキンをのせ、熱々のカレースープをたっぷり注ぎます。頂点にサクサクの揚げ麺を贅沢にトッピング。刻み高菜、エシャロット、生ライムを添えて完成。ライムをギュッと絞って召し上がれ！","ko":"삶은 면 위에 부드러운 닭다리를 올리고 뜨거운 카레 육수를 듬뿍 붓습니다. 바삭한 튀김면을 소복이 얹고 갓절임, 샬롯, 라임을 곁들여 냅니다. 라임즙을 듬뿍 짜서 비벼 드세요!"},"durationSeconds":45,"image":"/images/th/khao-soi-step5.jpg"}],"troubleshooting":[{"id":"khao-soi-too-heavy","problem":{"zh-TW":"咖哩湯喝到一半覺得太膩口、油脂厚重","en":"Curry broth feels overly greasy or cloying halfway through","th":"น้ำแกงเลี่ยนเกินไป กะทิข้นจัด","ja":"スープが重すぎて後半くどく感じてしまう","ko":"국물이 너무 기름지거나 먹다 보면 느끼해요"},"cause":{"zh-TW":"泰北咖哩椰奶濃度極高，若少了新鮮檸檬酸度與酸菜的乳酸中和，容易產生飽滯感。","en":"High coconut fat needs high acid contrast from fresh limes and lacto-fermented pickled greens.","th":"ไม่ได้บีบมะนาวหรือใส่ผักกาดดองเพื่อตัดเลี่ยน","ja":"ココナッツのコクが強いため、ライム果汁と高菜漬けの酸味による中和が不可欠です。","ko":"진한 코코넛 지방은 생라임의 산미와 갓절임의 쌉싸름한 산미로 중화시켜야 균형이 맞습니다."},"solution":{"zh-TW":"大膽擠入整瓣新鮮綠檸檬汁，並大量混入泰式酸菜！果酸能瞬間化解椰奶油脂，使湯汁變得回甘無比清新。","en":"Squeeze an entire lime wedge into the bowl and mix in heaps of pickled mustard greens. Acidity cuts right through the richness.","th":"บีบมะนาวสดเพิ่ม 1 ซีกและคลุกผักกาดดองลงในน้ำแกง รสชาติจะสดชื่นกลมกล่อมทันที","ja":"ライムをしっかり1切れ丸ごと絞り入れ、高菜漬けをスープに沈めて一緒にすすってください。驚くほど爽やかに変化します。","ko":"생라임 한 조각을 통째로 즙을 내어 넣고 갓절임을 넉넉히 섞으세요. 기름기가 싹 씻겨 내려가며 감칠맛이 폭발합니다."}}],"proTips":[{"zh-TW":"雙重吃法：剛上桌時先咬一口最頂端乾香酥脆的炸麵條，感受卡滋脆響；隨後把剩餘脆麵壓入熱咖哩湯中浸泡 10 秒，讓麵條半酥半軟吸飽咖哩，這才是清邁人最愛的極致吃法！","en":"Northern dining technique: First take a bite of the pristine crispy noodles dry. Then push the rest down into the piping hot curry for 10 seconds—the noodles become half-crunchy, half-sauce-soaked bliss!","th":"วิธีกินแบบคนเมือง: กัดเส้นกรอบเปล่าๆ ก่อนหนึ่งคำ จากนั้นกดเส้นกรอบที่เหลือลงไปจุ่มในน้ำแกง 10 วินาที ให้เส้นกึ่งกรอบกึ่งนุ่มดูดซับน้ำแกงเข้มข้น","ja":"現地の極上テクニック：まずは乾いたままのサクサク揚げ麺をカリッと一口。次にスープの中に沈めて10秒待ち、スープを吸って『半分カリカリ・半分モチモチ』になった瞬間をすするのが最高峰の味わい方です！","ko":"현지인의 먹는 팁: 처음엔 바삭한 튀김면을 그대로 한 입 베어 문 뒤, 나머지는 뜨거운 카레 국물에 10초간 적셔 '반은 바삭, 반은 쫄깃'하게 육수를 머금었을 때 드셔보세요!"}]},{"country":"th","id":"mango-sticky-rice","slug":"mango-sticky-rice","title":{"zh-TW":"曼谷甜心 芒果糯米飯","en":"Classic Thai Mango Sticky Rice (Khao Niew Mamuang)","th":"ข้าวเหนียวมะม่วงน้ำดอกไม้","ja":"カオニャオ・マムアン（マンゴーともち米のココナッツデザート）","ko":"클래식 망고 스티키 라이스 (카오 니아오 마무앙)"},"subtitle":{"zh-TW":"水仙芒果甜如蜜・班蘭椰漿浸潤溫熱糯米・香脆炸綠豆仁點綴","en":"Ripe Honey Mango with Pandan Coconut Sticky Rice & Crispy Mung Beans","th":"มะม่วงน้ำดอกไม้สุกหวานฉ่ำ ข้าวเหนียวมูนกะทิหอมใบเตย โรยถั่วทองกรุบกรอบ","ja":"完熟マンゴーの濃密な甘みと、温かいココナッツもち米の至福のマリアージュ","ko":"달콤한 완숙 망고와 판단 코코넛 찹쌀밥, 바삭한 볶은 녹두 토핑"},"tagline":{"zh-TW":"曼谷盛夏最銷魂的甜美撫慰，椰香、米香與果蜜的完美協奏曲","en":"The quintessential royal Thai dessert celebrated globally for its harmonious sweet-salty decadence","th":"ขนมหวานยอดนิยมอันดับหนึ่งของไทย มนต์เสน่ห์แห่งรสชาติหวานมัน","ja":"タイのデザート文化の頂点。ほんのり塩気の効いたココナッツミルクが極上マンゴーを引き立てる","ko":"태국 전역을 매료시킨 세계적인 국민 디저트의 정점"},"heroImage":"/images/th/mango-sticky-rice.jpg","difficulty":"easy","prepTimeMinutes":30,"cookTimeMinutes":25,"defaultServings":4,"caloriesPerServing":420,"category":"desserts","dietaryTags":["classic","vegan","glutenFree","halal"],"supportedCookware":["traditional"],"culture":{"originRegion":{"zh-TW":"中部・曼谷","en":"Central / Bangkok","th":"กรุงเทพมหานคร","ja":"中部・バンコク","ko":"방콕 / 중부"},"famousStreetMarkets":[{"zh-TW":"通羅夜市 Mae Varee 芒果名店","en":"Mae Varee Mango Stall (Thong Lo)","th":"แม่วารี ทองหล่อ","ja":"メー・ワーリー（トンロー名物店）","ko":"매와리 망고 (통로)"},{"zh-TW":"考山路街頭夜市","en":"Khao San Road Night Market","th":"ถนนข้าวสาร","ja":"カオサン通り屋台街","ko":"카오산 로드 야시장"}],"historyStory":{"zh-TW":"芒果糯米飯在拉瑪五世朱拉隆功大帝時期便有記載於宮廷食譜中。泰國長久以來盛產優質水仙芒果（Nam Dok Mai），廚師將糯米浸入新鮮椰漿與天然香蘭葉中慢火燜透（稱為「Moon」技法），米粒吸飽油脂化為半透明晶瑩狀態。微鹹的椰漿平衡了芒果濃烈蜜糖般的甜度，成為全球最著名的泰式甜點。","en":"Recorded in royal cookbooks as early as King Chulalongkorn (Rama V)'s reign, 'Khao Niew Moon' involves steeping freshly steamed glutinous rice in warm sweetened coconut cream enriched with fragrant pandan leaves. The pinch of sea salt in the rich coconut drizzle elevates the natural floral sweetness of Thailand's legendary Nam Dok Mai mangoes.","th":"ข้าวเหนียวมะม่วงเป็นภูมิปัญญาชาววังตั้งแต่สมัยรัชกาลที่ 5 โดยใช้กรรมวิธี 'มูน' ข้าวเหนียวด้วยหัวกะทิสดแท้และใบเตย เสิร์ฟคู่กับมะม่วงน้ำดอกไม้สุกสีทองและกะทิข้นรสเค็มปะแล่ม","ja":"ラーマ5世時代の宮廷料理としても記録が残る伝統デザート。蒸したての熱いもち米に熱いココナッツミルクを吸わせる『ムーン技法』により、米粒がキラキラと真珠のように輝きます。ほんの少しの塩気がマンゴーの甘さを劇的に昇華させます。","ko":"라마 5세 시대 왕실 요리로 기록되어 있습니다. 갓 쪄낸 뜨거운 찹쌀에 판단 잎 향을 우린 코코넛 밀크를 흠뻑 흡수시키는 '문(Moon)' 기법으로 만듭니다. 짭조름한 코코넛 소스가 망고의 천연 당도를 극대화합니다."},"thaiScript":"ข้าวเหนียวมะม่วง","thaiPhonetics":"Khao Niew Mamuang","audioPronunciationText":"ขอข้าวเหนียวมะม่วงกล่องใหญ่ มะม่วงหวานๆ ครับ","nativeName":"ข้าวเหนียวมะม่วง"},"ingredients":[{"id":"glutinous-rice","name":{"zh-TW":"泰國長粒圓糯米 (清萊產最佳)","en":"Thai Sweet Sticky Rice (Glutinous rice)","th":"ข้าวเหนียวเขี้ยวงู","ja":"タイ産もち米（カオニャオ）","ko":"태국 찹쌀 (스티키 라이스)"},"amount":250,"unitMetric":"g","unitUS":"8.8 oz","isKeyFlavor":true,"thaiName":"ข้าวเหนียว","thaiPronunciation":"Khao Niew"},{"id":"ripe-mangoes","name":{"zh-TW":"泰國水仙芒果或香蜜金煌芒 (冰鎮後切厚片)","en":"Ripe Thai Nam Dok Mai Mangoes (Chilled & sliced thick)","th":"มะม่วงน้ำดอกไม้สุก","ja":"完熟ナムドクマイ種マンゴー","ko":"완숙 망고 (남독마이 품종 추천)"},"amount":2,"unitMetric":"piece","unitUS":"piece","isKeyFlavor":true,"thaiName":"มะม่วงสุก","thaiPronunciation":"Mamuang Sook"},{"id":"coconut-cream-soak","name":{"zh-TW":"浸潤糯米用特濃椰漿 (頭遍生榨)","en":"Coconut Cream (For soaking warm rice)","th":"หัวกะทิสำหรับมูนข้าว","ja":"もち米用 濃厚ココナッツクリーム","ko":"찹쌀밥 흡수용 진한 코코넛 크림"},"amount":200,"unitMetric":"ml","unitUS":"6.8 fl oz","isKeyFlavor":true,"thaiName":"หัวกะทิมูน","thaiPronunciation":"Hua Ka-Thi Moon"},{"id":"granulated-sugar","name":{"zh-TW":"白細砂糖","en":"Granulated White Sugar","th":"น้ำตาลทรายขาว","ja":"グラニュー糖","ko":"백설탕"},"amount":80,"unitMetric":"g","unitUS":"2.8 oz","thaiName":"น้ำตาลทราย","thaiPronunciation":"Nam Tan Sai"},{"id":"pandan-leaves","name":{"zh-TW":"新鮮香蘭葉 (打結)","en":"Fresh Pandan Leaves (Tied in a knot)","th":"ใบเตยหอมมัดปม","ja":"パンダンリーフ（バイトゥーイ・結び目を作る）","ko":"판단 잎 (매듭지은 것)"},"amount":3,"unitMetric":"leaf","unitUS":"leaf","isKeyFlavor":true,"thaiName":"ใบเตย","thaiPronunciation":"Bai Toey"},{"id":"sea-salt","name":{"zh-TW":"細海鹽 (微鹹襯甜不可少)","en":"Fine Sea Salt","th":"เกลือสมุทร","ja":"天然海塩（甘みを引き立てる）","ko":"천일염 (단맛을 끌어올리는 감초)"},"amount":0.75,"unitMetric":"tsp","unitUS":"0.75 tsp","thaiName":"เกลือ","thaiPronunciation":"Khluea"},{"id":"coconut-cream-topping","name":{"zh-TW":"頂部淋醬用濃椰漿 + 1小匙粘米粉勾芡","en":"Coconut Cream for Drizzle (Thickened with 1 tsp rice flour)","th":"กะทิราดหน้าผสมแป้งข้าวเจ้า","ja":"仕上げ用ココナッツソース（米粉少々でとろみ付け）","ko":"토핑용 코코넛 드리즐 (쌀가루 1작은술로 농도 조절)"},"amount":80,"unitMetric":"ml","unitUS":"2.7 fl oz","thaiName":"กะทิราดหน้า","thaiPronunciation":"Ka-Thi Rad Na"},{"id":"toasted-mung-beans","name":{"zh-TW":"泰國炸香脆去皮綠豆仁 (Thua Thong)","en":"Crispy Fried Split Yellow Mung Beans (Thua Thong)","th":"ถั่วทองทอดกรอบ","ja":"ロースト緑豆（トゥア・トーン・黄色いサクサク豆）","ko":"볶은 깐 녹두 (투아 통 - 바삭한 고명)"},"amount":2,"unitMetric":"tbsp","unitUS":"2 tbsp","isKeyFlavor":true,"thaiName":"ถั่วทอง","thaiPronunciation":"Thua Thong","substitute":{"substituteName":{"zh-TW":"白芝麻 (乾烙金黃) 或烘烤杏仁碎","en":"Toasted white sesame seeds or sliced toasted almonds","th":"งาขาวคั่ว","ja":"煎り白ごま または ローストアーモンドスライス","ko":"볶은 참깨 또는 슬라이스 아몬드 구운 것"},"ratio":"1:1","explanation":{"zh-TW":"主要作用是提供軟糯椰米與滑潤芒果之外的酥脆咀嚼對比感。","en":"Used to provide a satisfying crispy crunch contrast to soft rice and silky mango.","th":"ให้เนื้อสัมผัสกรุบกรอบตัดกับความนุ่มของข้าวเหนียว","ja":"柔らかなもち米と果肉に対する『カリッ』とした食感アクセントです","ko":"부드러운 찹쌀밥과 과육 사이에서 기분 좋은 바삭함을 주기 위한 토핑입니다."},"whereToBuy":{"zh-TW":"一般超市烘焙區","en":"Grocery store baking aisle","th":"ร้านสะดวกซื้อ","ja":"一般スーパー","ko":"일반 마트"}}}],"steps":[{"stepNumber":1,"title":{"zh-TW":"泡透糯米並大火蒸透","en":"Soak & Steam Fragrant Sticky Rice","th":"แช่และนึ่งข้าวเหนียวให้สุกใส","ja":"もち米の浸水と強火蒸し上げ","ko":"찹쌀 불리기 및 판단 잎 향 입혀 찌기"},"instruction":{"zh-TW":"糯米反覆淘洗乾淨至洗米水完全清澈（去除表面多餘澱粉保持顆粒分明），浸泡冷水至少 4 小時（或隔夜）。瀝乾水份，將糯米鋪在墊有蒸布的蒸籠中，表面放上打結的香蘭葉，大火蒸 25 分鐘至米粒完全透明熟軟。","en":"Rinse glutinous rice until water runs completely clear. Soak in room temperature water for at least 4 hours (or overnight). Drain, spread across a cheesecloth-lined steamer, top with knotted pandan leaves, and steam over rolling high boil for 25 minutes until grains are tender and translucent.","th":"ซาวข้าวเหนียวจนน้ำใส แช่น้ำอย่างน้อย 4 ชั่วโมง สะเด็ดน้ำ นำไปนึ่งบนลังถึงปูผ้าขาวบาง วางใบเตยมัดปม นึ่งไฟแรง 25 นาทีจนข้าวสุกใสนุ่ม","ja":"もち米をとぎ汁が透明になるまでしっかり洗い、常温の水に4時間以上（または一晩）浸水させます。水気を切り、蒸し布を敷いた蒸し器に広げ、結んだパンダンリーフをのせて強火で25分、芯まで透明にもっちり蒸し上げます。","ko":"찹쌀을 맑은 물이 나올 때까지 씻어 최소 4시간 이상 찬물에 불립니다. 물기를 뺀 뒤 면포를 깐 찜기에 펼치고 판단 잎을 얹어 센 불에서 25분간 투명하고 부드럽게 쪄냅니다."},"durationSeconds":1500,"image":"/images/th/mango-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"熬製熱椰糖甜漿","en":"Simmer Sweet Coconut Steeping Nectar","th":"เคี่ยวน้ำกะทิสำหรับมูน","ja":"もち米用ココナッツシロップの調合","ko":"찹쌀밥용 달콤한 코코넛 시럽 끓이기"},"instruction":{"zh-TW":"在蒸飯倒數 5 分鐘時，將 200ml 特濃椰漿、80g 白糖與 0.75 茶匙海鹽放入小鍋中。以小火輕輕攪拌加熱至糖與鹽完全融化（切勿大滾沸騰，否則椰油乳化破壞會油水分離），保持溫熱備用。","en":"5 minutes before rice finishes steaming, combine 200ml coconut cream, 80g sugar, and 0.75 tsp fine sea salt in a small saucepan. Heat gently on low, stirring until completely dissolved. Do NOT boil, to prevent the coconut fats from curdling.","th":"ก่อนข้าวนึ่งเสร็จ 5 นาที นำหัวกะทิ 200 มล. น้ำตาลทราย และเกลือ ใส่หม้อเคี่ยวไฟอ่อนพอร้อนให้น้ำตาลละลาย ห้ามเดือดพล่าน","ja":"蒸し上がりの5分前に、小鍋にココナッツクリーム200ml、砂糖80g、塩小さじ0.75を合わせ、弱火で混ぜながら完全に溶かします。油分が分離しないよう沸騰させないのがポイントです。","ko":"밥이 다 쪄지기 5분 전, 냄비에 코코넛 크림 200ml, 설탕 80g, 소금 0.75작은술을 넣고 약불에서 설탕이 녹을 때까지만 데웁니다. 끓어 넘치지 않게 주의하세요."},"durationSeconds":180,"image":"/images/th/mango-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"熱飯撞熱漿：經典「Moon」燜潤吸收 (靈魂工序)","en":"The 'Moon' Technique: Infuse Hot Rice with Warm Coconut Cream","th":"การมูนข้าวเหนียว ปิดฝาให้ดูดซับกะทิ","ja":"秘技『ムーン（浸透密閉）』：熱々同士の奇跡の融合","ko":"비법 '문(Moon)' 기법: 뜨거운 밥에 코코넛 시럽 부어 뜸 들이기"},"instruction":{"zh-TW":"重要秘訣：必須「熱飯配熱漿」！將剛出爐滾燙的糯米立刻倒入深碗中，趁熱一口氣淋入溫熱甜椰漿。用矽膠刮刀輕輕翻拌推勻（此時看起來像稀飯，屬正常現象）。立即蓋緊大碗保鮮膜或鍋蓋，靜置燜透 20 分鐘。米粒會如同海綿般將椰漿精華全部吸飽，變得油潤剔透、粒粒飽滿！","en":"Crucial technique: Both the rice and coconut syrup MUST be steaming hot! Dump freshly steamed rice into a mixing bowl and pour the warm coconut syrup all over. Fold gently. It will look like soupy porridge—this is normal. Seal tightly with a lid or plastic wrap for 20 minutes. Grains will drink every drop like a sponge, emerging plump, glossy, and pearlescent.","th":"เทข้าวเหนียวร้อนๆ ใส่ชาม เทน้ำกะทิอุ่นๆ ลงไปทันที ใช้พายคนเบาๆ ให้เข้ากัน ปิดฝาให้สนิทพักไว้ 20 นาที เม็ดข้าวจะดูดน้ำกะทิจนเงาวาวนุ่มละมุน","ja":"最重要奥義：必ず【熱々の米】に【温かいココナッツ液】を注ぐこと！蒸したてのご飯に液を注いで優しく混ぜ、すぐにラップをして20分間完全に密閉して蒸らします。米粒がスポンジのように液をグングン吸い込み、真珠のように輝く艶やかなもち米に化けます！","ko":"핵심 비법: 반드시 【뜨거운 밥】에 【따뜻한 코코넛 시럽】을 부어야 합니다! 주걱으로 살살 섞은 뒤(이때 죽처럼 묽어도 정상입니다), 즉시 뚜껑을 덮어 20분간 완벽히 밀폐합니다. 찹쌀이 코코넛을 온전히 머금어 보석처럼 윤기가 흐릅니다."},"durationSeconds":1200,"image":"/images/th/mango-step3.jpg"},{"stepNumber":4,"title":{"zh-TW":"調製微鹹濃稠淋醬","en":"Simmer Salted Coconut Drizzle Sauce","th":"ทำกะทิราดหน้ารสเค็มมัน","ja":"仕上げ用 ほの塩ココナッツソースを作る","ko":"단짠 밸런스를 맞출 짭짤한 코코넛 토핑 소스 만들기"},"instruction":{"zh-TW":"小鍋中倒入 80ml 濃椰漿、1/4 茶匙鹽與 1 小匙粘米粉（或玉米澱粉），小火邊煮邊攪動，煮至微滾呈現如煉乳般濃稠順滑的白醬，離火放涼。","en":"In a tiny saucepan, whisk 80ml coconut cream, 1/4 tsp salt, and 1 tsp rice flour. Stir over low heat until it gently bubbles and thickens into a glossy, velvety salted white sauce. Remove from heat.","th":"นำหัวกะทิ 80 มล. ผสมเกลือและแป้งข้าวเจ้า 1 ช้อนชา เคี่ยวไฟอ่อนจนข้นหนืดเป็นครีมขาว พักไว้","ja":"小鍋にココナッツクリーム80ml、塩小さじ1/4、米粉小さじ1を合わせ、弱火でかき混ぜながらとろみがつくまで軽く煮詰めます。コンデンスミルクのような濃厚な白ソースになります。","ko":"작은 팬에 코코넛 크림 80ml, 소금 1/4작은술, 쌀가루 1작은술을 넣고 약불에서 저어가며 연유처럼 부드러운 농도가 될 때까지 끓여 식힙니다."},"durationSeconds":180,"image":"/images/th/mango-step4.jpg"},{"stepNumber":5,"title":{"zh-TW":"切芒果厚片、精緻盛盤加冕","en":"Slice Honey Mango, Plate with Warm Rice & Drizzle","th":"ปอกมะม่วง จัดเสิร์ฟ ราดกะทิและถั่วทอง","ja":"完熟マンゴーをスライスし、華麗に盛り付けて仕上げ","ko":"망고 슬라이스 및 코코넛 소스와 바삭한 녹두 얹어 서빙"},"instruction":{"zh-TW":"將冰鎮芒果沿果核切下兩大片果肉，去皮切成均勻厚片。在盤中舀入一團溫潤油亮的椰香糯米飯，旁邊排上金黃如蜜的芒果切片。在糯米上淋上一大匙微鹹白椰醬，最後撒上炸香脆綠豆仁。溫熱糯米與冰涼蜜芒交織入口，絕美極品！","en":"Slice mango cheeks off the flat pit, peel, and cut into luxurious diagonal slabs. Scoop a mound of warm, glistening sticky rice onto each plate and arrange golden mango fans alongside. Drizzle salted coconut cream across the rice and top with crispy golden mung beans. Serve immediately while rice is comfortably warm!","th":"ปอกมะม่วงน้ำดอกไม้หั่นชิ้นหนา ตักข้าวเหนียวมูนร้อนๆ วางเคียง ราดด้วยน้ำกะทิข้นเค็มมัน และโรยถั่วทองกรอบ พร้อมรับประทาน","ja":"冷やしたマンゴーの種を避けて果肉を切り出し、厚めにスライスします。温かいココナッツもち米を器に盛り、黄金色のマンゴーを添えます。もち米の上にとろりとした塩ココナッツソースを回しかけ、サクサクのロースト緑豆を散らして召し上がれ！","ko":"망고 씨를 피해 과육을 도톰하게 썹니다. 접시에 따뜻한 찹쌀밥을 담고 옆에 황금빛 망고를 부채꼴로 놓습니다. 밥 위에 짭조름한 코코넛 크림을 끼얹고 바삭한 녹두 토핑을 뿌립니다. 따뜻한 밥과 시원한 망고의 조화가 예술입니다!"},"durationSeconds":90,"image":"/images/th/mango-step5.jpg"}],"troubleshooting":[{"id":"mango-sticky-rice-dry","problem":{"zh-TW":"糯米飯放涼後變硬、口感乾澀不油潤","en":"Sticky rice turned hard, dry, and chalky after cooling down","th":"ข้าวเหนียวแข็ง กระด้าง ไม่นุ่มเงา","ja":"冷めたら米がパサパサに固くなってしまった","ko":"식은 후 찹쌀밥이 굳고 퍽퍽해졌어요"},"cause":{"zh-TW":"1. 糯米蒸好冷卻後才倒入冷椰漿，米粒無法有效熱脹冷縮吸收液體；2. 椰漿油脂含量過低（使用了淡椰奶而非特濃生榨椰漿）；3. 放入冰箱冷藏導致澱粉回生老化。","en":"1. Liquid was poured after rice cooled down; 2. Used low-fat coconut milk instead of thick coconut cream; 3. Refrigerated the rice causing starch retrogradation.","th":"เทกะทิตอนข้าวเย็นแล้ว หรือใช้กะทิกล่องไขมันต่ำ และห้ามแช่ตู้เย็น","ja":"1. ご飯が冷めてからココナッツ液を注いだ。2. 低脂肪の薄いココナッツミルクを使った。3. 冷蔵庫に入れてデンプンが劣化した。","ko":"1. 밥이 식은 후에 시럽을 부었거나, 2. 유지방이 적은 라이트 코코넛밀크를 썼거나, 3. 냉장 보관하여 전분이 노화되었습니다."},"solution":{"zh-TW":"嚴格遵守「剛出蒸籠的滾燙糯米倒入熱椰漿」，並密閉燜足 20 分鐘。已硬化的糯米飯可進微波爐微波 20 秒或回蒸 3 分鐘即可恢復 Q 彈！切勿冰冷藏。","en":"Always infuse steaming hot rice with hot coconut cream and tightly cover for 20 mins. Never refrigerate sticky rice; if cold, reheat in microwave for 20 secs.","th":"มูนข้าวเหนียวขณะร้อนจัดเสมอ หากข้าวเย็นให้นำเข้าไมโครเวฟ 20 วินาทีก่อนทาน","ja":"必ず蒸したてアツアツの米に温かい液を注ぎ、20分密閉。保存は常温で。固くなったらレンジで20秒温め直すと炊きたての柔らかさが戻ります。","ko":"반드시 김이 펄펄 나는 뜨거운 밥에 부어 20분간 밀폐하세요. 절대 냉장고에 넣지 마시고, 굳었다면 전자레인지에 20초 데워 드세요."}}],"proTips":[{"zh-TW":"泰國頂級老店秘方：洗糯米時加半顆檸檬或少許明礬水輕搓，洗淨後再浸泡，蒸出來的糯米粒會呈現像珍珠水晶般的通透光澤，絕不暗沉混濁！","en":"Bangkok street master secret: Rub raw rice with a squeeze of fresh lemon juice or a pinch of alum during washing. This yields extraordinarily crystalline, translucent, jewel-like rice grains!","th":"เคล็ดลับร้านดังแม่วารี: ซาวข้าวเหนียวด้วยสารส้มหรือน้ำมะนาวเบาๆ แล้วล้างน้ำให้สะอาด เม็ดข้าวที่นึ่งออกมาจะขาวใสเงาวาวราวไข่มุก","ja":"老舗名店の秘密：もち米を洗う際にライム果汁を少し加えて揉み洗いすると、蒸し上がった米粒がまるで水晶や真珠のように透き通った輝きを放ちます！","ko":"방콕 최고 명점의 비법: 찹쌀을 씻을 때 레몬즙을 몇 방울 떨어뜨려 살살 문질러 헹구면, 쪘을 때 쌀알이 보석처럼 영롱하게 투명해집니다!"}]},{"country":"th","id":"moo-ping","slug":"moo-ping","title":{"zh-TW":"曼谷晨光炭烤椰香豬肉串","en":"Bangkok Street Charcoal Grilled Pork Skewers (Moo Ping)","th":"หมูปิ้งกะทิโบราณสูตรริมทาง","ja":"ムー・ピン（タイ風ココナッツ豚串焼き）","ko":"방콕 스트리트 무핑 (코코넛 숯불 돼지꼬치)"},"subtitle":{"zh-TW":"椰奶醃製焦糖化・芫荽根白胡椒靈魂醃料・炭火刷椰漿甜潤多汁","en":"Coconut Milk-Glazed Caramelized Pork with Coriander Root Marinade","th":"หมักกะทิเข้าเนื้อ หอมสามเกลอ ย่างเตาถ่านหอมกรุ่น ชุ่มฉ่ำ","ja":"ココナッツミルクで漬け込んだ極上ジューシー豚肉。三種の神器（パクチー根・ニンニク・胡椒）の芳醇な香り","ko":"코코넛밀크와 고수 뿌리 양념에 재워 숯불에 구운 단짠 육즙 폭발 꼬치구이"},"tagline":{"zh-TW":"喚醒千萬曼谷人的街頭早餐香氣，軟嫩多汁到每一口都流連忘返","en":"The iconic morning breakfast aroma wafting across every Bangkok skytrain station","th":"กลิ่นหอมคู่ยามเช้าของคนเมืองหลวง อร่อยฟินกินคู่ข้าวเหนียวร้อนๆ","ja":"バンコクの朝、駅前の屋台から漂う魅惑の煙。もち米と一緒に頬張る至福のソウルフード","ko":"방콕의 아침을 깨우는 고소한 숯불 냄새, 따끈한 찹쌀밥과 찰떡궁합인 국민 간식"},"heroImage":"/images/th/moo-ping.jpg","difficulty":"easy","prepTimeMinutes":30,"cookTimeMinutes":12,"defaultServings":4,"caloriesPerServing":380,"category":"mains","dietaryTags":["classic"],"supportedCookware":["traditional","airFryer"],"culture":{"originRegion":{"zh-TW":"中部・曼谷","en":"Central / Bangkok","th":"กรุงเทพมหานคร","ja":"中部・バンコク","ko":"방콕 / 중부"},"famousStreetMarkets":[{"zh-TW":"曼谷席娜卡琳火車夜市","en":"Srinakarin Train Night Market","th":"ตลาดนัดรถไฟศรีนครินทร์","ja":"シーナカリン鉄道市場","ko":"시나카린 기차 야시장"},{"zh-TW":"BTS 席隆站路邊早市","en":"BTS Sala Daeng Morning Street","th":"ศาลาแดง สีลม","ja":"BTSサラデーン駅前 屋台街","ko":"BTS 살라댕역 아침 노점"}],"historyStory":{"zh-TW":"Moo Ping 是泰國無人不曉的平民美食。每天清晨在曼谷 BTS 與 MRT 地鐵出口，都能看見炭烤煙霧與聚集的上班族學生。這道串燒之所以軟嫩多汁，秘密在於泰國經典調味基底「三友」（Sam Gler：芫荽根、蒜頭、白胡椒粒），再以椰奶和棕櫚糖醃透肉質。炭烤過程中不斷反覆刷上厚厚的椰漿，使其表面產生迷人的焦糖化脆皮。","en":"Moo Ping is Thailand's universal wake-up comfort food. At dawn outside every BTS Skytrain station, plumes of sweet, smoky charcoal perfume greet commuters. Its tenderness comes from marinating marbled pork in coconut milk and 'Sam Gler' (the sacred Thai trio of cilantro roots, garlic, and white peppercorns). Continuous basting with thick coconut cream produces irresistible caramelized edges.","th":"หมูปิ้งเป็นเมนูอาหารเช้าขวัญใจคนไทยมาหลายทศวรรษ หมักด้วยเครื่องสามเกลอ (รากผักชี กระเทียม พริกไทย) ผสมกะทิและน้ำตาลมะพร้าว เวลาย่างพรมกะทิสดจนชุ่มฉ่ำหอมกรุ่น เสิร์ฟในถุงร้อนๆ คู่กับข้าวเหนียว","ja":"バンコクの出勤・通学風景に欠かせない大定番。豚肩ロースをココナッツミルクとタイ料理の三種の神器（パクチーの根、ニンニク、白胡椒）でじっくりマリネ。炭火で焼きながらココナッツミルクを何度もハケで塗り重ね、香ばしいキャラメリゼ膜をまとわせます。","ko":"방콕 시민들의 아침을 책임지는 국민 간식입니다. 기름기가 적당한 돼지 목살을 코코넛밀크와 고수 뿌리, 마늘, 백후추 양념에 재워 숯불에 구우며, 굽는 내내 코코넛 크림을 덧발라 윤기와 캐러멜 풍미를 입힙니다."},"thaiScript":"หมูปิ้งกะทิ","thaiPhonetics":"Moo Ping Kati","audioPronunciationText":"ขอหมูปิ้งห้าไม้ ข้าวเหนียวสองห่อครับ","nativeName":"หมูปิ้งกะทิ"},"ingredients":[{"id":"pork-shoulder","name":{"zh-TW":"優質豬梅花肉或梅花肉帶少許肥肉 (切 0.5cm 薄長片)","en":"Pork Shoulder / Butt with some fat marbling (Sliced 0.5cm thick)","th":"สันคอหมูติดมันหั่นบาง","ja":"豚肩ロース（適度に脂身があるもの・薄切り）","ko":"돼지 목살 (기름기가 적당한 것, 0.5cm 두께로 포 뜬 것)"},"amount":500,"unitMetric":"g","unitUS":"1.1 lbs","isKeyFlavor":true,"thaiName":"สันคอหมู","thaiPronunciation":"San Khor Moo"},{"id":"coconut-milk-marinade","name":{"zh-TW":"濃椰奶 (半量用於醃肉，半量用於烤時刷烤)","en":"Thick Coconut Milk (Divided: half for marinade, half for basting)","th":"หัวกะทิสดแท้","ja":"濃厚ココナッツミルク（マリネ用と焼き刷毛用）","ko":"진한 코코넛밀크 (절반은 재우기용, 절반은 덧바르기용)"},"amount":150,"unitMetric":"ml","unitUS":"5 fl oz","isKeyFlavor":true,"thaiName":"หัวกะทิ","thaiPronunciation":"Hua Ka-Thi"},{"id":"cilantro-roots","name":{"zh-TW":"香菜根 (洗淨泥沙)","en":"Cilantro / Coriander Roots (Cleaned thoroughly)","th":"รากผักชี","ja":"パクチーの根（泥を落とす）","ko":"고수 뿌리 (흙을 깨끗이 씻은 것)"},"amount":4,"unitMetric":"piece","unitUS":"piece","isKeyFlavor":true,"thaiName":"รากผักชี","thaiPronunciation":"Raak Phak Chee"},{"id":"garlic-cloves","name":{"zh-TW":"大蒜瓣","en":"Garlic Cloves","th":"กระเทียมกลีบ","ja":"ニンニク","ko":"마늘 5쪽"},"amount":5,"unitMetric":"clove","unitUS":"clove","thaiName":"กระเทียม","thaiPronunciation":"Kra-Thiam"},{"id":"white-peppercorns","name":{"zh-TW":"白胡椒粒 (搗碎)","en":"Whole White Peppercorns (Crushed)","th":"พริกไทยขาวเม็ด","ja":"粒白胡椒（粗挽き）","ko":"통 백후추 (빻은 것)"},"amount":1,"unitMetric":"tsp","unitUS":"1 tsp","thaiName":"พริกไทยขาว","thaiPronunciation":"Prik Thai Khao"},{"id":"palm-sugar","name":{"zh-TW":"泰國椰糖 (切碎)","en":"Thai Palm Sugar (Finely chopped)","th":"น้ำตาลปี๊บ","ja":"パームシュガー","ko":"태국 팜슈가"},"amount":3,"unitMetric":"tbsp","unitUS":"3 tbsp","isKeyFlavor":true,"thaiName":"น้ำตาลปี๊บ","thaiPronunciation":"Nam Tan Peep"},{"id":"oyster-sauce","name":{"zh-TW":"特級蠔油","en":"Premium Oyster Sauce","th":"ซอสหอยนางรม","ja":"オイスターソース","ko":"굴소스"},"amount":2,"unitMetric":"tbsp","unitUS":"2 tbsp","thaiName":"ซอสหอยนางรม","thaiPronunciation":"Sauce Hoi Nang Rom"},{"id":"fish-sauce","name":{"zh-TW":"純魚露","en":"Fish Sauce","th":"น้ำปลาแท้","ja":"ナンプラー","ko":"피시소스"},"amount":2,"unitMetric":"tbsp","unitUS":"2 tbsp","thaiName":"น้ำปลา","thaiPronunciation":"Nam Pla"},{"id":"dark-sweet-soy","name":{"zh-TW":"泰國黑甜醬油 (上漂亮焦糖色)","en":"Thai Sweet Dark Soy Sauce (See Ew Dum)","th":"ซีอิ๊วดำหวาน","ja":"タイ産ダークスイートソイソース（シーユーダム）","ko":"태국 다크 스위트 간장 (씨유담)"},"amount":1,"unitMetric":"tbsp","unitUS":"1 tbsp","thaiName":"ซีอิ๊วดำหวาน","thaiPronunciation":"See Ew Dum Waan"},{"id":"bamboo-skewers","name":{"zh-TW":"竹籤 (提前泡水 30 分鐘防烤焦)","en":"Flat Bamboo Skewers (Soaked in water 30 mins to prevent burning)","th":"ไม้เสียบลูกชิ้นแช่น้ำ","ja":"竹串（焦げ防止のため30分水につける）","ko":"대나무 꼬치 (타지 않게 물에 30분 불린 것)"},"amount":12,"unitMetric":"piece","unitUS":"piece","thaiName":"ไม้เสียบ","thaiPronunciation":"Mai Siap"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"石臼搗出靈魂「三友」醃料","en":"Pound the Sacred 'Sam Gler' Spice Trio","th":"โขลกสามเกลอ รากผักชี กระเทียม พริกไทย","ja":"伝統の香味ペースト『サムグラー』を作る","ko":"비법 양념 '삼글러(고수뿌리+마늘+후추)' 찧기"},"instruction":{"zh-TW":"將洗淨切碎的香菜根、大蒜瓣與白胡椒粒投入石臼中。全力研磨搗成細膩濃郁的香草泥（這就是泰國廚房的靈魂香味基底「Sam Gler」）。","en":"In a stone mortar, combine chopped cilantro roots, garlic cloves, and white peppercorns. Pound vigorously until transformed into an aromatic, fine paste (the legendary Thai aromatic base 'Sam Gler').","th":"ใส่รากผักชี กระเทียม และพริกไทยขาวลงในครก โขลกให้ละเอียดเป็นเนื้อเดียวกัน","ja":"すり鉢に刻んだパクチーの根、ニンニク、白胡椒を入れ、滑らかになるまでしっかりすり潰します（これがタイ料理の魂『サムグラー』です）。","ko":"절구에 고수 뿌리, 마늘, 통 백후추를 넣고 곱게 찧어 향긋한 페이스트('삼글러')를 만듭니다."},"durationSeconds":180,"image":"/images/th/moo-ping-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"調製椰奶醃料，抓醃冷藏入味","en":"Mix Coconut Marinade & Marinate Pork Thoroughly","th":"ผสมน้ำหมัก นวดหมูให้เข้าเนื้อ หมักข้ามคืน","ja":"ココナッツタレを揉み込み、じっくり漬け込む","ko":"코코넛 양념 섞고 돼지고기 주물러 재우기"},"instruction":{"zh-TW":"將切好的梅花肉片放入大碗。加入搗好的三友香料泥、椰糖、蠔油、魚露、黑甜醬油以及 80ml 濃椰奶。用雙手用力抓捏按摩 5 分鐘，讓肉質纖維將液體完全吸飽。加蓋放入冰箱冷藏醃製至少 4 小時（隔夜更佳！）。","en":"Place sliced pork shoulder in a large bowl. Add the pounded paste, palm sugar, oyster sauce, fish sauce, dark sweet soy, and 80ml coconut milk. Massage vigorously with your hands for 5 minutes until meat absorbs the liquids. Cover and refrigerate for at least 4 hours (overnight is supreme!).","th":"ใส่เนื้อหมูในชามผสม ใส่สามเกลอ น้ำตาลปี๊บ ซอสหอยนางรม น้ำปลา ซีอิ๊วดำ และกะทิ 80 มล. ใช้มือนวดขยำ 5 นาทีจนน้ำซอสซึมเข้าเนื้อ ปิดฝาแช่ตู้เย็นอย่างน้อย 4 ชั่วโมง","ja":"ボウルに薄切り豚肉を入れ、すり潰したペースト、パームシュガー、オイスターソース、ナンプラー、ダークソイソース、ココナッツミルク80mlを加えます。手で5分間力強く揉み込み、ラップをして冷蔵庫で最低4時間（一晩置くと最高）寝かせます。","ko":"볼에 썬 돼지고기를 넣고 찧어둔 페이스트, 팜슈가, 굴소스, 피시소스, 다크 간장, 코코넛밀크 80ml를 넣습니다. 손으로 5분간 주물러 양념이 고기에 쏙 배게 한 뒤, 뚜껑을 덮어 냉장고에서 최소 4시간(하룻밤 권장) 재웁니다."},"durationSeconds":300,"image":"/images/th/moo-ping-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"串籤成形：肥瘦相間緊實穿針","en":"Thread Meat Tightly onto Bamboo Skewers","th":"เสียบหมูสลับมันให้แน่นเรียงสวย","ja":"赤身と脂身をバランスよく串打ちする","ko":"고기를 대나무 꼬치에 촘촘하게 꿰기"},"instruction":{"zh-TW":"取浸透泡水過的竹籤，將肉片折疊穿入竹籤中。關鍵技巧：穿籤時必須緊實擠攏，每串中間夾入一片帶油脂的小肉塊，用手掌將串好的肉肉整型成扁平長橢圓片，烤時受熱均勻且鎖住肉汁。","en":"Take water-soaked bamboo skewers. Thread folded meat slices tightly onto each skewer, alternating lean slices with a ribbon of fatty pork in the middle. Flatten firmly with your palms into an even oval paddle shape for uniform cooking.","th":"นำไม้เสียบที่แช่น้ำแล้ว เสียบเนื้อหมูทบไปมาให้แน่น แทรกชิ้นมันไว้ตรงกลาง ใช้ฝ่ามือกดให้เป็นแผ่นแบนหนาเสมอกัน","ja":"水につけておいた竹串に、肉を蛇腹状に折りたたみながらキツく刺していきます。真ん中に脂身を1切れ挟むのがコツ。手のひらで押さえて平らな小判型に成形します。","ko":"물에 불린 꼬치에 고기를 접어가며 단단하게 꿱니다. 중간에 비계가 있는 조각을 하나씩 끼우고, 손바닥으로 꼭꼭 눌러 납작하고 도톰한 모양으로 다듬습니다."},"durationSeconds":360,"image":"/images/th/moo-ping-step3.jpg"},{"stepNumber":4,"title":{"zh-TW":"炭火炙烤或氣炸，邊烤邊刷厚椰漿 (焦糖化靈魂秘訣)","en":"Grill & Continuous Coconut Basting (Caramelization Secret)","th":"ย่างไฟกลาง พรมกะทิตลอดเวลาจนเกรียมหอม","ja":"香ばしく焼き上げ、ココナッツミルクを何度もハケ塗り","ko":"굽는 동안 코코넛밀크를 덧발라 윤기 나는 캐러멜 입히기"},"instruction":{"zh-TW":"【炭火/煎烤盤法】：中火預熱烤網，放入肉串每面烤 3-4 分鐘。翻面時，用刷子大膽刷上剩餘的純濃椰奶。反覆翻面 2-3 次，刷上 3-4 次椰奶，直到外皮焦糖微焦金褐、油脂滋滋作響！\\n【氣炸鍋模式】：預熱 190°C (375°F)，放入肉串烤 7 分鐘，取出翻面刷厚厚椰漿，再烤 4-5 分鐘至焦香四溢。","en":"[Grill Method]: Heat grill/pan to medium. Cook skewers for 3-4 mins per side. Generously baste with remaining thick coconut milk every time you flip. Repeat 2-3 times until glistening, smoky, and blistered with caramel brown marks! [Air Fryer Option]: 190°C (375°F) for 7 mins, flip and brush generously with coconut milk, air fry another 4-5 mins.","th":"ย่างบนเตาถ่านไฟกลาง 3-4 นาทีต่อด้าน ใช้แปรงจุ่มกะทิพรมชุ่มๆ ทุกครั้งที่พลิก ย่างจนหมูสุกเกรียมขอบสวยและมีกลิ่นหอมไหม้เล็กน้อย","ja":"【グリル/フライパン】：中火で両面3〜4分ずつ焼きます。ひっくり返すたびにハケで濃厚ココナッツミルクをたっぷり塗り重ねます。縁が香ばしく焦げて照りが出るまで！【エアフライヤー】：190℃で7分、裏返してココナッツミルクを塗り、さらに4〜5分。","ko":"【그릴/팬 구이】: 중불에서 앞뒤로 3~4분씩 굽습니다. 뒤집을 때마다 남은 코코넛밀크를 붓으로 듬뿍 덧바릅니다. 가장자리가 노릇하고 거뭇하게 캐러멜화될 때까지 굽습니다. 【에어프라이어】: 190℃에서 7분, 뒤집어 코코넛밀크 듬뿍 바른 후 4~5분 더 굽습니다."},"durationSeconds":600,"image":"/images/th/moo-ping-step4.jpg","cookwareVariations":[{"cookware":"airFryer","tempAndSetting":"190°C (375°F) for 11-12 mins","instructionOverride":{"zh-TW":"氣炸鍋預熱 190°C，肉串鋪在炸籃中烤 7 分鐘。拉出炸籃翻面，刷上厚厚一層純椰漿，再烤 4-5 分鐘至焦香金黃。","en":"Preheat Air Fryer to 190°C (375°F). Place skewers in basket and cook 7 mins. Flip, brush lavishly with thick coconut milk, and air fry another 4-5 mins.","th":"หม้อทอดไร้น้ำมัน 190°C 7 นาที พลิกด้านทากะทิฉ่ำๆ ทอดต่ออีก 4-5 นาทีจนสุกเกรียมสวย","ja":"ノンフライヤーを190℃に予熱。7分焼き、裏返してココナッツミルクをたっぷり塗り、さらに4〜5分こんがりするまで加熱します。","ko":"에어프라이어를 190℃로 예열하고 7분간 굽습니다. 뒤집어서 코코넛밀크를 듬뿍 바른 후 4~5분간 더 노릇하게 굽습니다."}}]},{"stepNumber":5,"title":{"zh-TW":"趁熱裝袋，搭配溫熱泰式糯米飯","en":"Serve Piping Hot with Warm Sticky Rice","th":"จัดเสิร์ฟคู่ข้าวเหนียวร้อนๆ ในถุงฟอยล์","ja":"アツアツをもち米と共に提供","ko":"따끈한 찹쌀밥과 함께 담아내기"},"instruction":{"zh-TW":"剛出爐的豬肉串外層油脂晶亮，散發炭火焦香與椰奶清甜。立即裝盤，旁邊備上一小包熱騰騰的泰國糯米飯。捏一小團糯米飯配著烤肉串一同咬下，幸福感爆棚！","en":"Transfer blistering, caramelized skewers to a platter alongside a small bag of warm steamed sticky rice. Pinch a ball of sticky rice and enjoy together in one glorious, savory-sweet bite!","th":"ตักเสิร์ฟร้อนๆ ข้าวเหนียวนุ่มๆ หมูนุ่มฉ่ำหวานมันกลมกล่อม ความอร่อยระดับตำนาน","ja":"ツヤツヤに輝く熱々の豚串を皿に盛り、温かいタイのもち米を添えます。手でもち米を小さく丸め、肉汁滴る串焼きと一緒に口いっぱいに頬張るのが正統派スタイル！","ko":"지글지글 윤기가 흐르는 뜨거운 꼬치를 접시에 담고 따끈한 찹쌀밥을 곁들입니다. 찹쌀밥을 떼어 고기와 함께 한입에 쏙 베어 물면 최고의 맛을 느낄 수 있습니다!"},"durationSeconds":30,"image":"/images/th/moo-ping-step5.jpg"}],"troubleshooting":[{"id":"moo-ping-dry","problem":{"zh-TW":"烤出來的豬肉串乾柴發硬、沒有街頭那種多汁滑潤感","en":"Skewers ended up tough, dry, and lacked street-style juiciness","th":"หมูปิ้งแข็งกระด้าง ไม่นุ่มฉ่ำน้ำ","ja":"肉がパサついて固くなり、屋台のようなジューシーさがない","ko":"고기가 퍽퍽하고 질기며 육즙이 부족해요"},"cause":{"zh-TW":"1. 選用了全瘦豬里肌肉（缺乏天然油脂）；2. 醃製時間過短未讓椰奶脂肪軟化蛋白質；3. 烤時沒有多次刷上純濃椰奶保濕。","en":"1. Used lean tenderloin instead of marbled shoulder; 2. Too brief marinating; 3. Did not baste with coconut milk during grilling.","th":"ใช้เนื้อหมูล้วนไม่มีมัน หรือไม่ได้ทากะทิระหว่างย่าง","ja":"1. 脂身のない赤身肉（ヒレやロース）を使った。2. 漬け込み時間不足。3. 焼いている途中にココナッツミルクを塗らなかった。","ko":"1. 기름기 없는 안심이나 등심을 썼거나, 2. 재우는 시간이 너무 짧았거나, 3. 굽는 도중 코코넛밀크를 덧바르지 않았습니다."},"solution":{"zh-TW":"務必挑選「帶肥肉的梅花肉」，穿籤時每串中間夾入小塊豬油。醃製至少 4 小時，並且翻面時一定大方刷上濃椰漿！","en":"Always use marbled pork shoulder with some fat. Marinate 4+ hours, and baste generously with thick coconut milk upon every flip.","th":"เลือกสันคอติดมัน นวดหมักนาน 4 ชั่วโมง และพรมกะทิฉ่ำๆ ทุกครั้งที่พลิก","ja":"必ず脂の乗った肩ロースを選び、最低4時間漬け込み、ひっくり返すたびにココナッツミルクを惜しみなく塗り重ねてください。","ko":"적당히 기름진 돼지 목살을 사용하고 4시간 이상 재우세요. 굽는 동안 코코넛밀크를 아낌없이 듬뿍 발라주어야 촉촉함이 유지됩니다."}}],"proTips":[{"zh-TW":"街頭小販秘密武器：在醃料中加入 1/2 小匙小蘇打粉（Baking soda）或少許鳳梨汁抓勻醃製，小蘇打會輕柔破壞肉質纖維，即使烤全熟也能達到入口即化的軟嫩神級口感！","en":"Street vendor tenderizing trick: Add 1/2 tsp baking soda into the marinade. It gently tenderizes pork muscle fibers, guaranteeing outrageously velvety, melt-in-your-mouth skewers every time!","th":"สูตรลับแม่ค้าหมูปิ้ง: ใส่เบกกิ้งโซดา 1/2 ช้อนชาลงในน้ำหมัก จะช่วยให้เนื้อหมูนุ่มเด้งละลายในปาก ไม่เหนียวเลยแม้แต่น้อย","ja":"屋台秘伝の裏技：マリネ液に重曹（ベーキングソーダ）小さじ1/2を加えて揉み込むと、肉の繊維が驚くほど柔らかくなり、屋台風のトロけるような食感に仕上がります！","ko":"노점 달인의 비법: 고기 양념에 베이킹소다 1/2작은술을 살짝 넣어 버무려보세요. 육질이 믿을 수 없을 정도로 부드러워져 입안에서 사르르 녹아내립니다!"}]},{"country":"th","id":"tom-kha-gai","slug":"tom-kha-gai","title":{"zh-TW":"泰式椰奶南薑滑雞湯","en":"Aromatic Thai Coconut Galangal Chicken Soup (Tom Kha Gai)","th":"ต้มข่าไก่โบราณหัวกะทิสด","ja":"トム・カー・ガイ（鶏肉とガランガルの濃厚ココナッツミルクスープ）","ko":"정통 똠카가이 (코코넛 밀크 갈랑갈 닭고기 수프)"},"subtitle":{"zh-TW":"高雅南薑松木香・濃郁生榨椰奶・滑嫩雞腿肉與青檸果酸","en":"Velvety Coconut Broth Infused with Piney Galangal, Lemongrass & Lime","th":"หอมกลิ่นข่าแก่ ตะไคร้ ใบมะกรูด น้ำกะทิหวานมันตัดเปรี้ยวมะนาวสด","ja":"南薑（ガランガル）の高貴な香りと、生搾りココナッツのまろやかなコク","ko":"갈랑갈의 은은한 향과 부드러운 코코넛 밀크, 야들야들한 닭다리살의 조화"},"tagline":{"zh-TW":"冬陰功的溫柔姊妹篇，絲滑如天鵝絨般的泰式宮廷名湯","en":"The comforting, velvety royal cousin of Tom Yum with soothing herbal warmth","th":"แกงโบราณรสละมุน หวาน มัน เค็ม เปรี้ยว ครบเครื่องสมุนไพรไทย","ja":"トムヤムクンと双璧をなすタイの至宝スープ。一口で心も温まるベルベットの口溶け","ko":"똠얌꿍보다 부드럽고 온화하게 속을 감싸주는 벨벳 감촉의 태국 왕실 수프"},"heroImage":"/images/th/tom-kha-gai.jpg","difficulty":"easy","prepTimeMinutes":15,"cookTimeMinutes":20,"defaultServings":4,"caloriesPerServing":340,"category":"soups","dietaryTags":["classic","halal","glutenFree"],"supportedCookware":["traditional","instantPot"],"culture":{"originRegion":{"zh-TW":"中部・曼谷宮廷","en":"Central / Bangkok Royal Court","th":"ภาคกลาง / กรุงเทพมหานคร","ja":"中部・バンコク宮廷料理","ko":"방콕 왕실 궁중 요리"},"famousStreetMarkets":[{"zh-TW":"曼谷舊城區邦蘭普市場","en":"Bang Lamphu Market Old Town","th":"บางลำพู","ja":"バンランプー市場","ko":"방람푸 시장"},{"zh-TW":"乍都乍水門夜市","en":"Pratunam Night Market","th":"ประตูน้ำ","ja":"プラトゥーナム市場","ko":"프라투남 야시장"}],"historyStory":{"zh-TW":"「Tom」是煮沸，「Kha」是靈魂香料南薑，「Gai」是雞肉。這道湯品最早記載於十九世紀末拉瑪五世皇室的膳食手冊中，最初是用烤鴨製作（Tom Kha Pet），後來民間改用更溫潤多汁的去骨雞腿肉。南薑有別於一般生薑，散發清幽如柑橘松針的香氣，與滑順的椰奶相融，酸甜溫潤，是泰國家庭餐桌上最受孩童與長輩歡迎的湯品。","en":"'Tom' means boiled, 'Kha' stands for the starring ingredient galangal, and 'Gai' is chicken. First documented in late 19th-century royal recipe collections, it was originally made with roasted duck (Tom Kha Pet) before transitioning into tender chicken thigh simmered in rich coconut milk. Galangal provides an ethereal floral, piney note rather than ginger's fiery heat.","th":"ต้มข่าไก่มีบันทึกในตำราอาหารชาววังตั้งแต่ปลายรัชกาลที่ 5 โดยข่าแก่จะให้กลิ่นหอมเฉพาะตัวที่ต่างจากขิง ต้มในน้ำกะทิสดให้รสสัมผัสนุ่มละมุนลิ้น","ja":"19世紀末のタイ王室宮廷料理集に記された歴史あるスープ。「カー」は南薑（ガランガル）を指し、生姜とは一線を画すウッディで高貴な清涼感を持ちます。ココナッツミルクのクリーミーさとライム果汁の穏やかな酸味が絶妙に調和します。","ko":"19세기 말 라마 5세 왕실 요리책에 처음 등장했습니다. '카'는 이 요리의 주인공인 갈랑갈(생강과 식물)을 의미하며, 매운맛보다는 솔잎과 시트러스 향을 냅니다. 부드러운 코코넛 밀크가 위장을 따뜻하게 달래줍니다."},"thaiScript":"ต้มข่าไก่","thaiPhonetics":"Tom Kha Gai","audioPronunciationText":"ขอต้มข่าไก่หนึ่งชาม รสเปรี้ยวนำหวานตามครับ","nativeName":"ต้มข่าไก่"},"ingredients":[{"id":"chicken-thigh","name":{"zh-TW":"去骨去皮雞腿肉 (切 3cm 適口小塊)","en":"Boneless Skinless Chicken Thigh (Cut into 1-inch pieces)","th":"สะโพกไก่เลาะกระดูกหั่นชิ้น","ja":"鶏もも肉（皮なし・一口大）","ko":"닭다리살(정육) (한 입 크기로 썬 것)"},"amount":350,"unitMetric":"g","unitUS":"12 oz","isKeyFlavor":true,"thaiName":"เนื้อไก่","thaiPronunciation":"Nuea Gai"},{"id":"fresh-galangal","name":{"zh-TW":"新鮮南薑 (切薄圓片 - 靈魂香料)","en":"Fresh Galangal (Thinly sliced into rounds - Star ingredient)","th":"ข่าแก่หั่นแว่นบาง","ja":"フレッシュガランガル（南薑・薄切り）","ko":"생 갈랑갈 (얇게 편 썬 것 - 핵심 향신료)"},"amount":50,"unitMetric":"g","unitUS":"1.8 oz","isKeyFlavor":true,"thaiName":"ข่า","thaiPronunciation":"Kha","substitute":{"substituteName":{"zh-TW":"嫩老薑切薄片 + 檸檬皮 2 片","en":"Fresh ginger slices + 2 strips of lime peel","th":"ขิงอ่อนหั่นแว่น","ja":"生姜の薄切り ＋ ライムの皮2片","ko":"생강 편 + 라임 껍질 2조각"},"ratio":"1:1","explanation":{"zh-TW":"南薑帶有木質清香與薄荷感，若買不到可用生薑搭配綠檸檬皮微量模擬。","en":"Galangal has an earthy, piney citrus aroma. Fresh ginger with lime peel comes closest.","th":"ใช้ขิงแทนได้ แต่ต้มข่าไก่ขนานแท้ต้องใช้ข่าเท่านั้น","ja":"南薑特有の松のような清涼感を再現するため、生姜とライムピールを合わせます","ko":"갈랑갈의 산뜻한 솔잎 향을 위해 생강에 라임 껍질을 곁들여 대체합니다."},"whereToBuy":{"zh-TW":"東南亞香料行或大型生鮮超市","en":"Asian/Thai markets or online","th":"ตลาดสดทั่วไป","ja":"タイ食材店","ko":"아시안 식료품점"}}},{"id":"lemongrass","name":{"zh-TW":"香茅草 (拍扁切斜段)","en":"Fresh Lemongrass (Bruised & cut into 2-inch segments)","th":"ตะไคร้หั่นท่อนบุบ","ja":"レモングラス（叩いて斜め切り）","ko":"레몬그라스 (칼등으로 으깬 뒤 어슷썰기)"},"amount":2,"unitMetric":"stalk","unitUS":"stalk","isKeyFlavor":true,"thaiName":"ตะไคร้","thaiPronunciation":"Ta-Khrai"},{"id":"kaffir-lime-leaves","name":{"zh-TW":"泰國檸檬葉 (去中梗撕大片)","en":"Kaffir / Makrut Lime Leaves (Stems removed, hand-torn)","th":"ใบมะกรูดฉีก","ja":"コブミカンの葉（手でちぎる）","ko":"카피르 라임 잎 (가운데 줄기 빼고 찢은 것)"},"amount":5,"unitMetric":"leaf","unitUS":"leaf","isKeyFlavor":true,"thaiName":"ใบมะกรูด","thaiPronunciation":"Bai Ma-Krut"},{"id":"coconut-milk","name":{"zh-TW":"特濃純椰漿","en":"Full-Fat Coconut Milk / Cream","th":"หัวกะทิแท้ 100%","ja":"無添加 濃厚ココナッツミルク","ko":"진한 무가당 코코넛 밀크"},"amount":400,"unitMetric":"ml","unitUS":"13.5 fl oz","isKeyFlavor":true,"thaiName":"กะทิ","thaiPronunciation":"Ka-Thi"},{"id":"chicken-broth","name":{"zh-TW":"低鹽清雞高湯","en":"Low-Sodium Chicken Broth","th":"น้ำซุปไก่ใส","ja":"クリアチキンブロス","ko":"맑은 닭 육수"},"amount":400,"unitMetric":"ml","unitUS":"13.5 fl oz","thaiName":"น้ำซุปใส","thaiPronunciation":"Nam Soup Sai"},{"id":"straw-mushrooms","name":{"zh-TW":"新鮮秀珍菇或草菇 (撕小塊)","en":"Oyster Mushrooms or Straw Mushrooms (Torn/Halved)","th":"เห็ดนางฟ้าหรือเห็ดฟาง","ja":"ヒラタケまたはフクロタケ","ko":"느타리버섯 또는 초고버섯"},"amount":150,"unitMetric":"g","unitUS":"5.3 oz","thaiName":"เห็ดนางฟ้า","thaiPronunciation":"Hed Nang Fah"},{"id":"fish-sauce","name":{"zh-TW":"優質純魚露","en":"Premium Fish Sauce","th":"น้ำปลาแท้","ja":"純ナンプラー","ko":"피시소스"},"amount":3,"unitMetric":"tbsp","unitUS":"3 tbsp","isKeyFlavor":true,"thaiName":"น้ำปลา","thaiPronunciation":"Nam Pla"},{"id":"palm-sugar","name":{"zh-TW":"椰糖","en":"Palm Sugar","th":"น้ำตาลปี๊บ","ja":"パームシュガー","ko":"팜슈가"},"amount":1,"unitMetric":"tbsp","unitUS":"1 tbsp","thaiName":"น้ำตาลปี๊บ","thaiPronunciation":"Nam Tan Peep"},{"id":"fresh-lime-juice","name":{"zh-TW":"新鮮現擠檸檬汁 (離火後加)","en":"Fresh Squeezed Lime Juice (Off heat)","th":"น้ำมะนาวคั้นสด","ja":"搾りたて生ライム果汁（火を止めてから投入）","ko":"생라임즙 (불을 끄고 넣기)"},"amount":3,"unitMetric":"tbsp","unitUS":"3 tbsp","isKeyFlavor":true,"thaiName":"น้ำมะนาว","thaiPronunciation":"Nam Ma-Nao"},{"id":"birds-eye-chilies","name":{"zh-TW":"泰國紅朝天椒 (拍破微辣)","en":"Thai Bird's Eye Chilies (Lightly bruised)","th":"พริกขี้หนูบุบ","ja":"タイ唐辛子（軽く潰す）","ko":"쥐똥고추 (살짝 으깬 것)"},"amount":4,"unitMetric":"piece","unitUS":"piece","thaiName":"พริกขี้หนู","thaiPronunciation":"Prik Khee Noo"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"溫和釋放南薑、香茅與檸檬葉精油","en":"Gentle Infusion of Galangal, Lemongrass & Lime Leaves","th":"ต้มกะทิผสมน้ำซุปและสมุนไพร","ja":"ハーブをココナッツスープで優しく煮出す","ko":"육수와 코코넛 밀크에 남프릭과 허브 향 우려내기"},"instruction":{"zh-TW":"鍋中倒入 400ml 清雞高湯與 200ml 椰漿（先放一半），加入南薑薄片、拍扁香茅與撕碎檸檬葉。以中小火慢煮 5 分鐘，讓南薑特有的甘醇松木香充分融進椰奶高湯中（切忌大滾狂沸，保持微沸即可避免破壞椰油）。","en":"In a pot, combine 400ml chicken broth and half of the coconut milk (200ml). Add galangal rounds, lemongrass, and torn kaffir lime leaves. Simmer over medium-low heat for 5 minutes so essential oils perfume the broth. Keep at a gentle simmer, never a violent boil.","th":"ใส่หัวกะทิครึ่งหนึ่งและน้ำซุปไก่ลงในหม้อ ใส่ข่า ตะไคร้ ใบมะกรูด ต้มไฟอ่อน 5 นาทีจนสมุนไพรส่งกลิ่นหอม","ja":"鍋にチキンブロス400mlとココナッツミルクの半量（200ml）を合わせます。ガランガル、レモングラス、コブミカンの葉を加え、弱中火で沸騰させすぎないよう5分煮出してアロマを抽出します。","ko":"냄비에 닭 육수 400ml와 코코넛 밀크 절반(200ml)을 붓습니다. 갈랑갈, 레몬그라스, 라임 잎을 넣고 약중불에서 5분간 뭉근하게 끓여 향을 우려냅니다. 팔팔 끓이지 마세요."},"durationSeconds":300,"image":"/images/th/tom-kha-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"滑入雞腿丁與菇類，小火煮至軟嫩","en":"Simmer Chicken Thighs & Mushrooms Until Tender","th":"ใส่เนื้อไก่และเห็ด ต้มจนสุกนุ่ม","ja":"鶏肉とキノコを加え、弱火で柔らかく煮る","ko":"닭다리살과 버섯 넣고 부드럽게 익히기"},"instruction":{"zh-TW":"放入雞腿塊與秀珍菇，保持中小火煨煮 6-8 分鐘直到雞肉熟透柔嫩、蘑菇吸飽湯汁。隨時撇去表面微量浮沫，保持湯頭乳白純淨。","en":"Slide in bite-sized chicken thigh pieces and mushrooms. Simmer gently over medium-low heat for 6-8 minutes until chicken is cooked through and succulent. Skim any foam from the surface to keep the soup snow-white.","th":"ใส่สะโพกไก่และเห็ดนางฟ้า ต้มไฟกลางค่อนอ่อน 6-8 นาทีจนไก่นุ่มสุก ช้อนฟองออกเพื่อให้น้ำซุปขาวเนียน","ja":"鶏もも肉とキノコを加えます。弱中火で6〜8分、肉がふっくら火が通るまで優しく煮ます。表面のアクをすくい取り、シルキーな白さを保ちます。","ko":"닭다리살과 버섯을 넣습니다. 약중불에서 6~8분간 닭고기가 부드럽게 익을 때까지 끓입니다. 거품을 걷어내어 뽀얀 국물을 유지합니다."},"durationSeconds":450,"image":"/images/th/tom-kha-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"倒入剩餘濃椰漿，調入魚露椰糖","en":"Enrich with Remaining Coconut Milk & Season","th":"เติมกะทิส่วนที่เหลือ ปรุงรสน้ำปลาและน้ำตาลปี๊บ","ja":"残りのココナッツミルクでコク増し、味を調える","ko":"남은 코코넛 밀크 붓고 피시소스와 팜슈가로 간하기"},"instruction":{"zh-TW":"倒入剩餘的 200ml 純濃椰漿，調入魚露 3 大匙與椰糖 1 大匙。加入拍破的泰國朝天椒（提供淡淡溫潤微辣而不嗆喉），輕輕攪拌均勻，煮 1-2 分鐘至微沸，隨即關火！","en":"Pour in the remaining 200ml rich coconut milk. Season with 3 tbsp fish sauce and 1 tbsp palm sugar. Drop in bruised bird's eye chilies for gentle warmth. Stir well, let it come to a very gentle bubble for 1-2 minutes, then turn off heat.","th":"เทหัวกะทิส่วนที่เหลือ 200 มล. ปรุงด้วยน้ำปลาและน้ำตาลปี๊บ ใส่พริกขี้หนูบุบ คนให้เข้ากัน ต้มพอเดือดปุดๆ แล้วปิดไฟทันที","ja":"残りのココナッツミルク200mlを加え、ナンプラー大さじ3とパームシュガー大さじ1を入れます。軽く潰した唐辛子を加え、ふつふつと温まったらすぐに火を止めます！","ko":"남은 코코넛 밀크 200ml를 부어 풍미를 더하고 피시소스 3큰술, 팜슈가 1큰술을 넣습니다. 으깬 쥐똥고추를 넣고 1~2분간 살짝 데운 뒤 즉시 불을 끕니다!"},"durationSeconds":120,"image":"/images/th/tom-kha-step3.jpg"},{"stepNumber":4,"title":{"zh-TW":"關火淋上鮮檸檬汁與香菜（防起渣結塊關鍵）","en":"Off-Heat Lime Juice & Fresh Cilantro Splash","th":"ดับไฟ บีบมะนาวสด โรยผักชี","ja":"火を消してから生ライム汁とパクチーを散らす","ko":"불 끄고 생라임즙 두르기 (분리 방지 핵심)"},"instruction":{"zh-TW":"重要秘訣：椰奶遇到酸若在高溫沸騰下極易產生像豆花碎渣般的油水分離（Curdling）。必須關火後，再緩緩淋入 3 大匙新鮮檸檬汁並輕柔攪拌！最後撒入新鮮香菜碎與一抹紅辣椒絲點綴即可盛盤。","en":"Essential rule: Acid curdles boiling coconut milk into graininess! Off the heat, slowly stir in 3 tbsp freshly squeezed lime juice. Garnish with vibrant cilantro leaves and sliced red chilies for a stunning presentation.","th":"เคล็ดลับสำคัญ: ต้องปิดไฟก่อนบีบน้ำมะนาวเสมอ เพื่อป้องกันไม่ให้กะทิแตกตัวเป็นเม็ดทราย โรยผักชีไทยพร้อมเสิร์ฟ","ja":"重要テクニック：沸騰中のココナッツミルクに酸を加えると分離しておから状になってしまいます。必ず火を止めた後に生ライム果汁を回し入れ、優しく混ぜます。パクチーを散らして完成！","ko":"필수 비법: 끓는 코코넛 밀크에 산(라임즙)이 닿으면 순두부처럼 몽글몽글 분리됩니다. 반드시 가스불을 끈 후에 생라임즙을 두르고 살살 저어주세요. 고수를 얹어 완성합니다."},"durationSeconds":45,"image":"/images/th/tom-kha-step4.jpg"}],"troubleshooting":[{"id":"tom-kha-curdled","problem":{"zh-TW":"湯汁看起來像豆花碎渣、表面油水分離不順滑","en":"Soup curdled, looking grainy with oil separation on top","th":"น้ำแกงแตกมันเป็นก้อน ไม่เนียนสวย","ja":"スープがおからのように分離し、ザラザラしてしまった","ko":"국물이 순두부처럼 몽글몽글 뭉치고 기름이 겉돌아요"},"cause":{"zh-TW":"1. 椰奶在猛烈大火下滾沸太久破壞乳化平衡；2. 在開火大滾時倒入檸檬汁導致蛋白質遇酸變性結塊。","en":"1. Boiled coconut milk too aggressively; 2. Squeezed lime juice while soup was violently boiling on the burner.","th":"ต้มกะทิไฟแรงเกินไป หรือบีบมะนาวตอนน้ำเดือด","ja":"1. ココナッツミルクを強火でグツグツ煮立たせすぎた。2. 火にかけたままライム汁を加えた。","ko":"1. 코코넛 밀크를 센 불에서 팔팔 끓였거나, 2. 불을 켠 채로 라임즙을 부어 단백질이 응고되었습니다."},"solution":{"zh-TW":"全程維持「中小火微沸」，且檸檬汁務必於關火後再淋入攪拌。如果已產生輕微結塊，可用手持打蛋器輕輕攪打快速補救。","en":"Maintain gentle simmer on medium-low. Add lime juice strictly off heat. Whisk gently if slight curdling occurs.","th":"ใช้ไฟอ่อนเสมอ และบีบมะนาวหลังปิดไฟเท่านั้น","ja":"終始『弱火でコトコト』を徹底し、ライム汁は必ず火を止めてから加えます。少し分離した場合は泡立て器で優しく撹拌すると滑らかさが戻ります。","ko":"항상 약불에서 뭉근하게 데우고, 라임즙은 반드시 불을 끄고 넣으세요. 만약 살짝 분리되었다면 거품기로 살살 저어주면 회복됩니다."}}],"proTips":[{"zh-TW":"食材小知識：南薑（Galangal）纖維非常粗韌，在湯中是作為「天然芳香劑」，食用時通常不直接咀嚼下肚；如果給小朋友或外國客人吃，可在上桌前將南薑片與香茅段濾除，體驗更加絲滑！","en":"Dining tip: Galangal root slices are intensely fibrous and intended for steeping aroma only. Street stalls leave them in for visual authenticity, but feel free to strain them out before serving kids for a silky experience!","th":"ข่าแก่มีเส้นใยหยาบ มีไว้สำหรับต้มเอากลิ่นหอมเท่านั้น ไม่นิยมเคี้ยวรับประทาน หากทำให้เด็กทานสามารถตักออกก่อนเสิร์ฟได้","ja":"豆知識：ガランガルは繊維が硬いため香りを出す目的で使われます。現地では器に入れたまま具材だけを食べますが、小さなお子様には提供前に取り除いてあげると飲みやすくなります！","ko":"상식 팁: 갈랑갈은 섬유질이 억세어 향을 내는 용도입니다. 현지에서는 그릇에 담긴 채로 국물과 고기만 건져 먹지만, 어린이나 손님을 대접할 때는 미리 건져내면 훨씬 깔끔합니다!"}]},{"country":"th","id":"pad-see-ew","slug":"pad-see-ew","title":{"zh-TW":"曼谷大排檔 泰式鑊氣炒醬油河粉","en":"Bangkok Street Pad See Ew (Stir-Fried Soy Sauce Flat Noodles)","th":"ผัดซีอิ๊วหมูหมักเส้นใหญ่นุ่มหอมกระทะ","ja":"パッシーユ（タイ風極太幅広米麺の焦がし醤油炒め）","ko":"방콕 포장마차 팟씨유 (간장 소스 넓적 쌀국수 볶음)"},"subtitle":{"zh-TW":"高溫鐵鍋鑊氣煙燻焦香・黑甜醬油焦糖化・嫩芥藍爽脆與滑嫩梅花豬","en":"Charred Flat Rice Noodles in Sweet Dark Soy with Tender Pork & Chinese Broccoli","th":"เส้นใหญ่นุ่มเหนียว กลิ่นกระทะไหม้หอมกรุ่น ซีอิ๊วดำหวานและคะน้ากรอบ","ja":"強火の『鍋気（ウォックヘイ）』が香る幅広生麺。黒甘醤油の香ばしいキャラメリゼとカイラン菜","ko":"센 불의 불맛(웍헤이)을 입힌 쫄깃한 넓적 쌀국수, 달콤한 다크 간장과 모닝 카이란"},"tagline":{"zh-TW":"泰國街頭人氣與 Pad Thai 並駕齊驅的爆炒靈魂，濃郁焦香不辣首選","en":"The comforting, savory wok-charred noodle sibling of Pad Thai loved by locals","th":"เมนูผัดเส้นยอดฮิตขวัญใจคนไทยทุกวัย หอมกรุ่นกลิ่นไหม้ติดกระทะ","ja":"パッタイと人気を二分するタイ屋台の炒め麺王道。辛くなく香ばしいコクが後を引く絶品","ko":"팟타이와 어깨를 나란히 하는 태국 현지인들의 부동의 1위 볶음국수"},"heroImage":"/images/th/pad-see-ew.jpg","difficulty":"medium","prepTimeMinutes":15,"cookTimeMinutes":8,"defaultServings":2,"caloriesPerServing":580,"category":"stirFry","dietaryTags":["classic"],"supportedCookware":["traditional"],"culture":{"originRegion":{"zh-TW":"中部・曼谷唐人街","en":"Central / Bangkok Chinatown","th":"เยาวราช กรุงเทพมหานคร","ja":"中部・ヤワラート（バンコク中華街）","ko":"방콕 차이나타운"},"famousStreetMarkets":[{"zh-TW":"曼谷耀華力唐人街","en":"Yaowarat Chinatown Street Stalls","th":"ถนนเยาวราช","ja":"ヤワラート中華街屋台","ko":"야오와랏 차이나타운 노점"},{"zh-TW":"阿索克 (Asok) 街頭午市","en":"Asok Street Food Market","th":"อโศก","ja":"アソーク市場","ko":"아속 먹거리 골목"}],"historyStory":{"zh-TW":"Pad See Ew（意為炒醬油）深受二十世紀初潮汕移民「乾炒牛河」的技法啟發。曼谷泰籍廚師將廣式河粉結合泰國特色的黑甜醬油（See Ew Dum）、泰國特選黃豆醬與爽脆芥藍（Gai Lan），在大鐵鍋烈火高溫下爆炒出迷人的「鑊氣」（Wok Hei）。因其完全不辣、鹹甜濃郁，成為泰國大人小孩無人不愛的深夜暖胃首選。","en":"Translating literally to 'Stir-Fried with Soy Sauce', Pad See Ew showcases the profound Chinese-Chaozhou culinary influence on Thai street food. Bangkok street hawkers adapted the Cantonese beef chow fun technique using wide flat rice noodles (Sen Yai), Thai sweet dark soy sauce, tender marinated pork, and crisp Chinese broccoli (Gai Lan). Charring the noodles over intense wok heat imparts the coveted smoky 'Wok Hei' aroma.","th":"ผัดซีอิ๊วได้รับอิทธิพลมาจากชาวจีนแต้จิ๋ว โดยนำเส้นใหญ่มาผัดในกระทะเหล็กไฟลุก ผสมซีอิ๊วดำหวาน ซีอิ๊วขาว หมูหมักนุ่ม และผักคะน้ากรอบ จนเกิดกลิ่นหอมไหม้เฉพาะตัว","ja":"「パッ（炒める）」「シーユ（醤油）」。20世紀初頭に潮州系華人が伝えた広東風牛河（幅広米麺炒め）がタイの調味料と出会って進化。黒甘醤油の糖分を高熱の中華鍋でわずかに焦がすことで立ち上る、スモーキーな『鍋気（ウォックヘイ）』が真骨頂です。","ko":"'팟(볶다)', '씨유(간장)'라는 뜻으로 광둥식 소고기 볶음 쌀국수에서 유래했습니다. 방콕 노점의 달인들이 센 불의 웍에서 넓적한 쌀국수(센야이)와 카이란 채소, 돼지고기를 검은 단간장과 함께 빠르게 볶아내어 불맛을 입힙니다."},"thaiScript":"ผัดซีอิ๊วหมู","thaiPhonetics":"Pad See Ew Moo","audioPronunciationText":"ขอผัดซีอิ๊วหมูเส้นใหญ่หนึ่งจาน ขอเส้นไหม้ๆ หน่อยครับ","nativeName":"ผัดซีอิ๊วหมู"},"ingredients":[{"id":"wide-rice-noodles","name":{"zh-TW":"新鮮寬幅大河粉 (Sen Yai - 撕開散落)","en":"Fresh Wide Flat Rice Noodles (Sen Yai - Gently separated)","th":"เส้นใหญ่สดแกะเป็นแผ่น","ja":"生幅広米麺（センヤイ・優しくほぐす）","ko":"생 넓적 쌀국수면 (센야이 - 살살 떼어낸 것)"},"amount":300,"unitMetric":"g","unitUS":"10.5 oz","isKeyFlavor":true,"thaiName":"เส้นใหญ่","thaiPronunciation":"Sen Yai","substitute":{"substituteName":{"zh-TW":"乾寬河粉 (溫水泡發 45 分鐘) 或鮮千層麵皮切 3cm 寬條","en":"Dried XL flat rice noodles (soaked 45 mins) or fresh lasagna sheets sliced wide","th":"เส้นก๋วยจั๊บหรือเส้นเล็ก","ja":"乾燥平打ち米麺（45分ぬるま湯戻し）または生ラザニアシートの短冊切り","ko":"건 넓적 쌀국수 (45분 불린 것) 또는 생 라자냐 피를 3cm로 썬 것"},"ratio":"1:1","explanation":{"zh-TW":"正宗 Pad See Ew 講究寬厚大片吸附鍋氣。乾燥河粉需充分泡軟瀝乾再下鍋。","en":"Pad See Ew relies on broad noodles that catch wok char. Dried wide rice noodles work if fully rehydrated and thoroughly dried.","th":"ใช้เส้นแห้งแช่น้ำอุ่นจนนิ่มแล้วสะเด็ดน้ำให้แห้ง","ja":"乾燥麺を使う場合はぬるま湯で柔らかく戻し、ペーパータオルで完全に水気を切ってから使います","ko":"건면 사용 시 찬물이나 미지근한 물에 충분히 불린 뒤 물기를 완벽히 제거해야 떡지지 않습니다."},"whereToBuy":{"zh-TW":"泰國雜貨店冷藏區或亞洲超市","en":"Asian market refrigerated noodle section","th":"ตลาดสดทั่วไป","ja":"アジア食材店 冷蔵コーナー","ko":"아시안 마트 냉장 코너"}}},{"id":"pork-loin","name":{"zh-TW":"豬里肌或梅花肉 (逆紋切薄片)","en":"Pork Loin or Shoulder (Sliced thin against the grain)","th":"เนื้อหมูสันนอกหมักนุ่ม","ja":"豚ロースまたは肩ロース（繊維を断つ薄切り）","ko":"돼지고기 등심 또는 목살 (결 반대로 얇게 썬 것)"},"amount":150,"unitMetric":"g","unitUS":"5.3 oz","thaiName":"เนื้อหมู","thaiPronunciation":"Nuea Moo"},{"id":"chinese-broccoli","name":{"zh-TW":"芥藍菜 (Gai Lan - 粗莖斜切片，葉切大段)","en":"Chinese Broccoli / Gai Lan (Stems sliced on bias, leaves cut into segments)","th":"ผักคะน้าต้นอวบ","ja":"カイラン菜（茎は斜め薄切り、葉はざく切り）","ko":"카이란 (또는 청경채, 줄기는 어슷썰고 잎은 큼직하게)"},"amount":120,"unitMetric":"g","unitUS":"4.2 oz","isKeyFlavor":true,"thaiName":"ผักคะน้า","thaiPronunciation":"Phak Kha-Na"},{"id":"eggs","name":{"zh-TW":"新鮮雞蛋","en":"Fresh Eggs","th":"ไข่ไก่สด","ja":"新鮮な卵","ko":"달걀 2개"},"amount":2,"unitMetric":"piece","unitUS":"piece","thaiName":"ไข่ไก่","thaiPronunciation":"Khai Gai"},{"id":"dark-sweet-soy","name":{"zh-TW":"泰國黑甜醬油 (See Ew Dum - 鑊氣上色靈魂)","en":"Thai Dark Sweet Soy Sauce (See Ew Dum - Crucial for char & color)","th":"ซีอิ๊วดำหวาน","ja":"タイ産ダークスイートソイソース（シーユーダム）","ko":"태국 다크 스위트 간장 (씨유담)"},"amount":1.5,"unitMetric":"tbsp","unitUS":"1.5 tbsp","isKeyFlavor":true,"thaiName":"ซีอิ๊วดำหวาน","thaiPronunciation":"See Ew Dum"},{"id":"light-soy-sauce","name":{"zh-TW":"泰國金山醬油或生抽","en":"Thai Thin Light Soy Sauce (Golden Mountain / Megachef)","th":"ซีอิ๊วขาว","ja":"薄口醤油またはタイ産シーユーカオ","ko":"양조간장 또는 태국 연한 간장 (씨유카오)"},"amount":1.5,"unitMetric":"tbsp","unitUS":"1.5 tbsp","thaiName":"ซีอิ๊วขาว","thaiPronunciation":"See Ew Khao"},{"id":"oyster-sauce","name":{"zh-TW":"蠔油","en":"Oyster Sauce","th":"ซอสหอยนางรม","ja":"オイスターソース","ko":"굴소스"},"amount":1,"unitMetric":"tbsp","unitUS":"1 tbsp","thaiName":"ซอสหอยนางรม","thaiPronunciation":"Sauce Hoi"},{"id":"sugar","name":{"zh-TW":"白砂糖 (幫助高溫焦糖化)","en":"Granulated Sugar (Assists in caramelization)","th":"น้ำตาลทราย","ja":"砂糖","ko":"설탕"},"amount":1,"unitMetric":"tsp","unitUS":"1 tsp","thaiName":"น้ำตาลทราย","thaiPronunciation":"Nam Tan"},{"id":"garlic-minced","name":{"zh-TW":"蒜頭碎","en":"Garlic (Finely chopped)","th":"กระเทียมสับ","ja":"みじん切りニンニク","ko":"다진 마늘"},"amount":1.5,"unitMetric":"tbsp","unitUS":"1.5 tbsp","thaiName":"กระเทียมสับ","thaiPronunciation":"Kra-Thiam Sub"},{"id":"white-pepper","name":{"zh-TW":"純白胡椒粉","en":"Ground White Pepper","th":"พริกไทยป่น","ja":"白胡椒パウダー","ko":"백후춧가루"},"amount":0.5,"unitMetric":"tsp","unitUS":"0.5 tsp","thaiName":"พริกไทยป่น","thaiPronunciation":"Prik Thai Pon"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"河粉提前裹勻黑甜醬油 (攤販不傳秘密)","en":"Pre-Coat Flat Noodles with Dark Sweet Soy Sauce","th":"คลุกเส้นใหญ่กับซีอิ๊วดำหวานก่อนผัด","ja":"炒める前に麺に黒甘醤油を均一に絡めておく（屋台秘伝）","ko":"볶기 전 넓적 쌀국수에 다크 간장 버무려두기 (노점 비법)"},"instruction":{"zh-TW":"大碗中將寬河粉輕輕撕散成一片片。淋入 1.5 大匙黑甜醬油，用雙手輕柔翻拌均勻，讓每一片河粉都披上油潤紅褐色的醬汁外衣。這樣下鍋炒時醬汁不會積在鍋底燒焦，能瞬間在極高溫鐵鍋上均勻焦糖化！","en":"Gently separate wide rice noodle sheets in a bowl. Drizzle 1.5 tbsp dark sweet soy sauce over the noodles and toss gently with your hands until evenly coated in rich caramel brown. This prevents sauce pooling and creates uniform caramelization in the hot wok!","th":"คลี่เส้นใหญ่ไม่ให้ติดกัน ใส่ซีอิ๊วดำหวาน 1.5 ช้อนโต๊ะ ใช้มือเคล้าให้เคลือบเส้นจนทั่วเป็นสีน้ำตาลสม่ำเสมอ วิธีนี้จะทำให้เส้นหอมไหม้สวยเวลาลงกระทะ","ja":"ボウルで幅広麺を一枚ずつほぐします。ダークスイートソイ大さじ1.5を回しかけ、手で優しく和えて麺全体に琥珀色をまとわせます。こうすることで鍋底でタレが焦げ付かず、均一なキャラメリゼ焦げが生まれます！","ko":"볼에 넓적 면을 가닥가닥 떼어 넣습니다. 다크 간장 1.5큰술을 두르고 손으로 살살 버무려 면 전체에 갈색 옷을 입힙니다. 이렇게 하면 웍 바닥에 양념이 뭉치지 않고 균일하게 불맛을 입힐 수 있습니다!"},"durationSeconds":120,"image":"/images/th/pad-see-ew-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"大火爆炒蒜香梅花肉與芥藍粗莖","en":"Wok-Sear Garlic, Pork Slices & Chinese Broccoli Stems","th":"ผัดกระเทียม เนื้อหมู และก้านคะน้าไฟแรง","ja":"ニンニク・豚肉・カイランの茎を強火で一気に炒める","ko":"센 불에 마늘, 돼지고기, 카이란 줄기 볶기"},"instruction":{"zh-TW":"中式炒鍋以最大火燒到冒起第一縷青煙，倒入 2 大匙油晃鍋潤壁。放入蒜碎與醃好的肉片快速翻炒 1 分鐘至表面變白。放入厚切的芥藍粗莖翻炒 30 秒至翡翠翠綠，全部推至炒鍋一側。","en":"Heat wok over highest flame until wisps of smoke rise. Swirl in 2 tbsp oil. Add minced garlic and sliced pork, stir-frying rapidly for 1 minute until pork is 80% cooked. Add sliced Gai Lan stems, toss for 30 secs until vivid green, then push everything to one side.","th":"ตั้งกระทะไฟแรงสุดจนควันขึ้น ใส่น้ำมัน 2 ช้อนโต๊ะ ใส่กระเทียมและหมูผัดเร็วๆ จนสุก ใส่ก้านคะน้าผัด 30 วินาที ดันเครื่องทั้งหมดไปไว้ข้างกระทะ","ja":"中華鍋から煙が立ち上るまで最大火力で熱し、油大さじ2を回し入れます。ニンニクと豚肉を投入し手早く1分炒めます。カイランの茎を加え30秒煽ったら、具材を鍋の端に寄せます。","ko":"웍에서 연기가 날 정도로 가장 센 불로 달군 후 기름 2큰술을 두릅니다. 다진 마늘과 돼지고기를 넣고 1분간 빠르게 볶다가 카이란 줄기를 넣고 30초간 볶은 뒤 팬 한쪽으로 밀어둡니다."},"durationSeconds":90,"image":"/images/th/pad-see-ew-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"滑蛋成形，合體炒出蛋香","en":"Scramble Eggs & Fold with Pork","th":"ตอกไข่ ยีพอแตก ผัดรวมกับหมู","ja":"卵を割り入れ、大きめのスクランブル状にして具材と合体","ko":"달걀 스크램블 만들어 고기와 합체하기"},"instruction":{"zh-TW":"在空出的鍋底淋少許油，打入 2 顆雞蛋。待蛋白底部起泡定型後，用鍋鏟將蛋黃劃破推散成大塊金黃炒蛋，隨即將一旁的肉片與芥藍撥回翻炒均勻，盛起在盤中備用。","en":"Drizzle a drop of oil onto the bare wok surface. Crack in 2 eggs. Let bottom bubble and set, break yolks into large golden ribbons, then toss together with the pork and greens. Transfer to a temporary plate.","th":"ใส่น้ำมันนิดหน่อยที่ก้นกระทะ ตอกไข่ 2 ฟอง ยีพอแตก พอไข่เริ่มสุกตลบหมูกลับมาผัดรวมกัน ตักขึ้นพักไว้","ja":"空いたスペースに油を少し足し、卵2個を割り入れます。底が固まったら黄身を崩して大きめの炒り卵を作り、横の肉と野菜を一気に合わせてサッと混ぜ、一度皿に取り出します。","ko":"빈 공간에 기름을 살짝 두르고 달걀 2개를 깨 넣습니다. 바닥이 익으면 노른자를 터뜨려 큼직한 스크램블을 만든 후 옆의 고기와 섞어 잠시 접시에 덜어둡니다."},"durationSeconds":60,"image":"/images/th/pad-see-ew-step3.jpg"},{"stepNumber":4,"title":{"zh-TW":"高溫烙鐵！烙出靈魂「鑊氣」（Wok Hei）","en":"Blast-Char the Noodles for Smoky Wok Hei (Do Not Stir!)","th":"ลงเส้นไฟลุก เผาก้นกระทะให้หอมกลิ่นควัน","ja":"最高火力で麺を焼き付け、極上の『鍋気（焦がし煙）』をまとう","ko":"초강력 센 불에 면을 눌러 붙여 불맛(웍헤이) 입히기"},"instruction":{"zh-TW":"原鍋補 1 大匙油，再次燒至冒大煙！一口氣倒入裹好醬汁的河粉，平鋪在熾熱鍋底。【千萬不要馬上翻炒！】讓河粉在鍋底烙煎整整 15-20 秒，聽見滋滋聲響，直到河粉邊緣烙出微焦黑斑與迷人煙燻氣息。隨後快速顛鍋翻面，重複烙煎另一面 15 秒！","en":"Add 1 tbsp oil back to the wok and heat until smoking hot again! Dump in the pre-sauced noodles and spread them flat against the roaring steel. CRUCIAL: Do NOT stir immediately! Let noodles scorch against the metal for 15-20 seconds to develop blistered char and intense smokiness. Flip and repeat for 15 seconds!","th":"ใส่น้ำมันเพิ่ม 1 ช้อนโต๊ะ เร่งไฟแรงสุดจนควันโขมง ใส่เส้นใหญ่ลงไป แผ่เส้นให้แนบก้นกระทะ ห้ามคนทันที! ปล่อยให้เส้นไหม้เกรียมติดกระทะ 15-20 วินาทีจนมีกลิ่นหอมควัน แล้วสะบัดพลิกกลับด้าน","ja":"油大さじ1を足し、再び煙がモクモク立つまで最大加熱！タレを絡めた麺を一気に入れ、中華鍋の底に広げます。【絶対にすぐかき混ぜないこと！】15〜20秒間じっと焼き付け、焦げ目がついてスモーキーな香りが立ち上ったら、一気に鍋をあおって裏面も同様に15秒焼き付けます！","ko":"기름 1큰술을 두르고 다시 연기가 피어오를 때까지 최고 화력으로 달굽니다! 양념된 면을 붓고 넓게 폅니다. 【절대 바로 뒤적거리지 마세요!】 15~20초간 그대로 눌러 붙여 불맛 가득한 갈색 누룽지 자국을 낸 뒤, 웍을 흔들어 뒤집어 반대쪽도 15초간 지집니다!"},"durationSeconds":60,"image":"/images/th/pad-see-ew-step4.jpg","crucialTips":{"zh-TW":"如果瘋狂翻炒，鍋溫會暴跌出水，河粉會碎裂成泥！必須「烙」大於「炒」，才能擁有夜市大排檔的炭香焦邊。","en":"Constant stirring drops the temperature and turns noodles to mush. Press and sear rather than constantly flipping!","th":"ห้ามคนเส้นไปมาบ่อยๆ เส้นจะเละขาด ต้องปล่อยให้แนบผิวกระทะให้ได้กลิ่นไหม้","ja":"ガチャガチャ絶え間なく混ぜると鍋の温度が下がり、麺がボロボロに崩れます。『炒める』のではなく『焼き付ける』意識が肝心！","ko":"계속 저으면 팬의 온도가 식어 면이 다 부서집니다! 볶는 것이 아니라 '눌러 굽는다'는 느낌으로 지져내야 합니다."}},{"stepNumber":5,"title":{"zh-TW":"回鍋炒料、下芥藍綠葉與調味大火合炒出鍋","en":"Combine Pork, Add Gai Lan Leaves & Final Seasoning","th":"ใส่หมูผัด คะน้าใบ ปรุงรส ผัดสะบัดกระทะตักเสิร์ฟ","ja":"具材戻し・カイラン葉投入・調味して一気呵成に仕上げ","ko":"고기 복귀, 카이란 잎 넣고 양념 둘러 센 불 완성"},"instruction":{"zh-TW":"倒回炒好的豬肉滑蛋，放入芥藍嫩綠葉。淋入 1.5 大匙生抽、1 大匙蠔油、1 小匙糖與半小匙白胡椒粉。開最大火快速翻顛 20 秒，芥藍葉剛好斷生變軟即可關火出鍋！盛盤後可隨個人喜好淋上醃辣椒醋（Prik Nam Som）。","en":"Toss the cooked pork, eggs, and leafy Gai Lan into the wok. Drizzle with light soy, oyster sauce, sugar, and white pepper. Toss vigorously over maximum heat for 20 seconds until green leaves just wilt. Plate piping hot and serve with pickled chili vinegar on the side!","th":"เทหมู ไข่ และใบผักคะน้าลงไป ปรุงด้วยซีอิ๊วขาว ซอสหอยนางรม น้ำตาล และพริกไทยป่น เร่งไฟแรงสะบัดกระทะ 20 วินาที ตักใส่จาน เสิร์ฟพร้อมพริกดองน้ำส้มสายชู","ja":"取り出しておいた豚肉と卵、カイランの柔らかい葉を戻し入れます。薄口醤油、オイスターソース、砂糖、白胡椒を回しかけ、最大火力で20秒豪快に煽り、葉がしんなりしたら即盛り付けます。唐辛子入りの酢を添えて完成！","ko":"볶아둔 고기와 달걀, 카이란 잎을 넣습니다. 간장, 굴소스, 설탕, 백후추를 두르고 센 불에서 20초간 빠르게 웍질하여 잎이 숨이 죽으면 즉시 불을 끕니다. 고추식초를 곁들여 맛있게 드세요!"},"durationSeconds":45,"image":"/images/th/pad-see-ew-step5.jpg"}],"troubleshooting":[{"id":"pad-see-ew-broken-noodles","problem":{"zh-TW":"炒出來的寬河粉全部斷成爛碎塊、黏成一大坨糊糊","en":"Flat noodles broke into fragmented shreds and turned mushy","th":"เส้นใหญ่ขาดเละ เหนียวติดกันเป็นแป้งเปียก","ja":"幅広麺がバラバラに千切れて粉々になり、ベチャッと団子状になった","ko":"넓적 면이 다 끊어지고 떡처럼 뭉개졌어요"},"cause":{"zh-TW":"1. 剛從冰箱拿出來的冰冷河粉直接下鍋，澱粉受冷變脆一碰就斷；2. 翻炒太過頻繁鏟斷麵條；3. 鍋底溫度不夠高導致出水糊化。","en":"1. Cold refrigerated noodles straight into wok; 2. Over-stirred vigorously with sharp metal spatula; 3. Insufficient wok heat causing water condensation.","th":"ใช้เส้นที่เพิ่งเอาออกจากตู้เย็น หรือใช้ตะหลิวสับเส้นไปมาบ่อยเกินไป","ja":"1. 冷蔵庫から出したばかりの冷たい麺をそのまま使った（デンプンが脆くなっている）。2. ヘラで細かくかき回しすぎた。3. 火力不足。","ko":"1. 냉장고에서 꺼낸 차가운 면을 바로 볶았거나(전분이 굳어 잘 끊어짐), 2. 조리도구로 너무 많이 휘저었거나, 3. 화력이 약했습니다."},"solution":{"zh-TW":"冷藏河粉務必微波 30-40 秒或室溫回溫軟化，輕柔撕散後裹醬。下鍋後以「烙」代替頻繁翻炒，用甩鍋或輕托翻拌！","en":"Microwave cold noodles for 30 secs to soften before separating. Sear flat against hot wok; toss gently rather than chopping.","th":"อุ่นเส้นในไมโครเวฟ 30 วินาทีให้นิ่มก่อนแกะ และใช้การสะบัดกระทะแทนการใช้ตะหลิวยีเส้น","ja":"冷蔵の麺はレンジで30秒温めてしなやかに戻してから優しくほぐします。炒める際はヘラで刻まず、焼き付けて鍋をあおるように返してください。","ko":"차가운 면은 전자레인지에 30초 데워 부드럽게 한 뒤 떼어내세요. 주걱으로 면을 자르지 말고 팬을 흔들어 가볍게 뒤집어주세요."}}],"proTips":[{"zh-TW":"曼谷街頭四寶配料秘招：Pad See Ew 本身不辣微甜，泰國老饕吃之前一定會淋上 2 小匙「醃朝天椒白醋」（Prik Nam Som）！清亮的醋酸與朝天椒的脆辣，能瞬間提升河粉鑊氣的立體感，好吃到停不下來！","en":"Bangkok condiment master tip: Pad See Ew is savory and mildly sweet. Thais always spoon 2 teaspoons of 'Prik Nam Som' (pickled bird's eye chilies in vinegar) over the plate before eating. The tart acid cuts through the wok oils beautifully!","th":"เคล็ดลับคนไทย: ผัดซีอิ๊วต้องตัก พริกดองน้ำส้มสายชู ราด 2 ช้อน ความเปรี้ยวเผ็ดจะช่วยชูรสกลิ่นไหม้ของกระทะให้อร่อยขึ้นอีกหลายเท่าตัว","ja":"屋台の必須アイテム：パッシーユは甘辛味付けなので、現地のタイ人は必ず卓上の『唐辛子入り白酢（プリック・ナムソム）』を小さじ2杯回しかけます。ツンとくる爽快な酸味が油っぽさを一瞬で消し去り、旨みを何段階も引き上げます！","ko":"방콕 현지인의 필수 조합: 팟씨유는 달콤 짭조름하므로, 식탁에 놓인 '식초에 절인 쥐똥고추(프릭남쏨)'를 2작은술 둘러 드세요! 산뜻한 산미가 기름기를 싹 잡아주며 맛의 차원이 달라집니다!"}]},{"country":"th","id":"guay-tiew-ruea","slug":"guay-tiew-ruea","title":{"zh-TW":"曼谷運河正宗泰式濃郁船麵","en":"Bangkok Canal Authentic Boat Noodles (Guay Tiew Ruea)","th":"ก๋วยเตี๋ยวเรืออยุธยาสูตรโบราณน้ำตกเข้มข้น","ja":"クイッティオ・ルア（アユタヤ伝統 濃厚ハーブ牛船麺）","ko":"방콕 운하 정통 보트 누들 (꾸에이띠어우 루어)"},"subtitle":{"zh-TW":"八角桂皮黑草藥牛骨濃湯・空心菜脆口・彈牙牛肉片與炸豬皮冠頂","en":"Deep Spiced Beef Herbal Broth with Water Spinach, Tender Beef & Pork Cracklings","th":"น้ำซุปพะโล้สมุนไพรหอมกรุ่น เนื้อตุ๋นเปื่อย ผักบุ้งกรอบ แคบหมูทอง","ja":"スターアニスとシナモンが香る漆黒の牛骨薬膳スープ。空心菜とカリカリ豚皮揚げ","ko":"팔각과 계피 향이 깊게 밴 진한 소고기 약선 육수, 아삭한 모닝글로리와 바삭한 돼지껍질 튀김"},"tagline":{"zh-TW":"曼谷運河水上人家划艇販售的傳奇小碗麵，一碗接一碗欲罷不能","en":"The legendary petite-bowl noodle soup once paddled through Bangkok's canal networks","th":"ตำนานก๋วยเตี๋ยวชามเล็กจากลำคลอง รสชาติจัดจ้านเข้มข้นถึงใจ","ja":"かつてバンコクの運河を行き交う小舟で売られていた伝説の麺。濃厚な旨みに一口で虜になる一杯","ko":"방콕의 운하를 오가던 작은 나룻배에서 시작된 전설의 깊고 진한 보트 누들"},"heroImage":"/images/th/boat-noodles.jpg","difficulty":"medium","prepTimeMinutes":25,"cookTimeMinutes":45,"defaultServings":4,"caloriesPerServing":490,"category":"soups","dietaryTags":["classic"],"supportedCookware":["traditional","instantPot"],"culture":{"originRegion":{"zh-TW":"中部・大城 (Ayutthaya) 與曼谷運河","en":"Central / Ayutthaya & Bangkok Canals","th":"พระนครศรีอยุธยา / คลองรังสิต","ja":"中部・アユタヤおよびバンコク運河","ko":"아유타야 및 방콕 운하"},"famousStreetMarkets":[{"zh-TW":"勝利紀念碑船麵一條街","en":"Victory Monument Boat Noodle Alley","th":"ก๋วยเตี๋ยวเรืออนุสาวรีย์","ja":"戦勝記念塔（アヌサワリー）ボートヌードル通り","ko":"빅토리 모뉴먼트 보트 누들 골목"},{"zh-TW":"大城水上市場","en":"Ayutthaya Floating Market","th":"ตลาดน้ำอโยธยา","ja":"アユタヤ水上マーケット","ko":"아유타야 수상시장"}],"historyStory":{"zh-TW":"船麵（Guay Tiew Ruea）誕生於二十世紀中葉泰國運河密佈的年代。當時小販划著窄小扁舟穿梭於曼谷與大城運河之間，為了避免波浪搖晃使滾燙熱湯潑灑出來，特意將麵條份量縮小至僅裝半碗，湯汁極致濃縮，香料飽滿。顧客在河畔往往一疊就是十幾碗空碗，成為曼谷運河文明最具代表性的飲食記憶。","en":"Dating back to the canal-dominated era of mid-20th century Siam, vendors paddled narrow wooden canoes along the waterways of Bangkok and Ayutthaya. To prevent hot soup from sloshing over during rocking waves, bowls were served in tiny portions with deeply concentrated broth. Diners famously stack up empty bowls by the dozen along the riverbanks.","th":"ก๋วยเตี๋ยวเรือมีต้นกำเนิดมาจากพ่อค้าแม่ค้าที่พายเรือขายในคลองรังสิตและอยุธยา เพื่อความปลอดภัยไม่ให้น้ำซุปร้อนๆ ลวกมือขณะเรือโคลงเคลง จึงตักน้ำซุปเพียงเล็กน้อยแต่เข้มข้นจนกลายเป็นเอกลักษณ์ชามเล็กซ้อนเป็นคอนโด","ja":"水運が発達していた20世紀半ば、細長い小舟の上で調理・販売されていたことに由来します。波に揺られて熱いスープがこぼれないよう、あえて小さな器に濃厚なスープを少量だけ注いで提供されました。今でも椀を何段も積み重ねて食べるのがバンコクの風物詩です。","ko":"20세기 중반 방콕과 아유타야의 운하를 오가던 노 젓는 배 위에서 탄생했습니다. 배가 출렁일 때 뜨거운 국물이 쏟아지지 않도록 일부러 작은 그릇에 진하게 우려낸 국물을 조금만 담아 팔았습니다. 그릇을 탑처럼 쌓아가며 먹는 재미가 일품입니다."},"thaiScript":"ก๋วยเตี๋ยวเรือ","thaiPhonetics":"Guay Tiew Ruea","audioPronunciationText":"ขอก๋วยเตี๋ยวเรือเนื้อน้ำตกสองชาม เผ็ดปกติครับ","nativeName":"ก๋วยเตี๋ยวเรือ"},"ingredients":[{"id":"sen-lek-noodles","name":{"zh-TW":"中等寬度泰國乾米粉 (Sen Lek - 泡水 30 分鐘)","en":"Thai Medium Thin Rice Noodles (Sen Lek - Soaked 30 mins)","th":"เส้นเล็กสดหรือแห้งแช่น้ำ","ja":"センレック（タイ中細米麺・30分水戻し）","ko":"센렉 (태국 중면 쌀국수 - 찬물에 30분 불린 것)"},"amount":250,"unitMetric":"g","unitUS":"8.8 oz","isKeyFlavor":true,"thaiName":"เส้นเล็ก","thaiPronunciation":"Sen Lek"},{"id":"beef-slices","name":{"zh-TW":"優質牛里肌或牛五花薄片 (汆燙用)","en":"Tender Beef Sirloin or Ribeye (Thinly sliced for flash-boiling)","th":"เนื้อวัวสไลซ์บางนุ่ม","ja":"牛サーロインまたはリブロース薄切り","ko":"소고기 등심 또는 차돌박이 얇게 썬 것"},"amount":250,"unitMetric":"g","unitUS":"8.8 oz","thaiName":"เนื้อวัวสไลซ์","thaiPronunciation":"Nuea Wua Slice"},{"id":"beef-broth","name":{"zh-TW":"濃郁牛骨高湯","en":"Rich Beef Bone Broth","th":"น้ำซุปกระดูกวัว","ja":"濃厚牛骨スープ","ko":"진한 사골 육수"},"amount":1000,"unitMetric":"ml","unitUS":"34 fl oz","isKeyFlavor":true,"thaiName":"น้ำซุปกระดูก","thaiPronunciation":"Nam Soup Kra-Dook"},{"id":"boat-noodle-spices","name":{"zh-TW":"黑香料包 (八角 2 顆、桂皮 1 支、芫荽籽 1 茶匙、黑荳蔻 1 顆)","en":"Spiced Bouquet (2 Star Anise, 1 Cinnamon stick, 1 tsp Coriander seeds, 1 Black Cardamom)","th":"เครื่องพะโล้ โป๊ยกั๊ก อบเชย ลูกผักชี","ja":"スパイスセット（八角2個、シナモン1本、コリアンダーシード小さじ1）","ko":"약선 향신료 (팔각 2개, 계피 1스틱, 고수씨 1작은술)"},"amount":1,"unitMetric":"packet","unitUS":"packet","isKeyFlavor":true,"thaiName":"เครื่องพะโล้","thaiPronunciation":"Khrueang Pa-Lo"},{"id":"dark-sweet-soy","name":{"zh-TW":"泰國黑甜醬油 (造就招牌漆黑深色湯頭)","en":"Thai Dark Sweet Soy Sauce (For signature dark mahogany broth)","th":"ซีอิ๊วดำหวาน","ja":"タイ産ダークスイートソイソース","ko":"태국 다크 스위트 간장 (짙은 국물 색감의 핵심)"},"amount":2.5,"unitMetric":"tbsp","unitUS":"2.5 tbsp","isKeyFlavor":true,"thaiName":"ซีอิ๊วดำหวาน","thaiPronunciation":"See Ew Dum"},{"id":"water-spinach","name":{"zh-TW":"泰式空心菜 (切 4cm 段 - 經典爽脆配菜)","en":"Morning Glory / Water Spinach (Cut into 1.5-inch sections)","th":"ผักบุ้งไทยหั่นท่อน","ja":"空心菜（4cmの長さにカット）","ko":"모닝글로리(공심채) (4cm 길이로 썬 것)"},"amount":120,"unitMetric":"g","unitUS":"4.2 oz","thaiName":"ผักบุ้ง","thaiPronunciation":"Phak Boong"},{"id":"crispy-pork-rinds","name":{"zh-TW":"香脆泰式炸豬皮 (Khaep Moo - 靈魂冠頂)","en":"Crispy Thai Pork Rinds / Cracklings (Khaep Moo)","th":"แคบหมูกรอบไร้มัน","ja":"カリカリ豚皮揚げ（ケープムー）","ko":"바삭한 태국식 돼지껍질 튀김 (캡무)"},"amount":50,"unitMetric":"g","unitUS":"1.8 oz","isKeyFlavor":true,"thaiName":"แคบหมู","thaiPronunciation":"Khaep Moo","substitute":{"substituteName":{"zh-TW":"油條碎丁 (烤酥) 或餛飩脆皮碎","en":"Crispy toasted croutons or fried wonton strips","th":"เกี๊ยวกรอบ","ja":"ワンタンの皮の素揚げ または クルトン","ko":"바삭하게 구운 나초 또는 튀긴 만두피 조각"},"ratio":"1:1","explanation":{"zh-TW":"浸在濃郁黑湯中吸收湯汁、外軟內脆的口感對比。","en":"Provides delicious textural crunch when dipped into the rich, velvety broth.","th":"ให้ความกรุบกรอบดูดซับน้ำซุปเข้มข้น","ja":"濃厚な黒スープに浸して、外はジュワッ・中はカリッとした食感を楽しめます","ko":"진한 국물에 적셔 겉은 촉촉하고 속은 바삭한 식감을 즐기기 위함입니다."},"whereToBuy":{"zh-TW":"超市東南亞專區或進口零食店","en":"Supermarket snack aisle (Pork rinds/Chicharrones)","th":"ร้านขายของฝาก","ja":"アジア食品店またはスーパーの菓子売場","ko":"대형마트 스낵 코너"}}},{"id":"fried-garlic-oil","name":{"zh-TW":"泰式金黃炸蒜油 ( กระเทียมเจียว )","en":"Thai Golden Crispy Fried Garlic in Oil","th":"กระเทียมเจียวหอมเจียวในน้ำมัน","ja":"ガーリックチップオイル（焦がしニンニク油）","ko":"바삭한 마늘 기름 (크라티암 치아오)"},"amount":2,"unitMetric":"tbsp","unitUS":"2 tbsp","isKeyFlavor":true,"thaiName":"กระเทียมเจียว","thaiPronunciation":"Kra-Thiam Jiao"},{"id":"thai-basil","name":{"zh-TW":"九層塔 / 甜羅勒葉 (Bai Horapha)","en":"Fresh Thai Sweet Basil Leaves","th":"ใบโหระพาสด","ja":"タイスイートバジル（ホーラパー）","ko":"태국 바질(호라파) 잎"},"amount":20,"unitMetric":"g","unitUS":"0.7 oz","thaiName":"ใบโหระพา","thaiPronunciation":"Bai Horapha"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"乾鍋煸香八角桂皮，慢熬漆黑藥膳牛湯","en":"Toast Aromatics & Simmer Dark Spiced Beef Broth","th":"คั่วเครื่องพะโล้ เคี่ยวน้ำซุปเนื้อจนเข้มข้น","ja":"スパイスを乾煎りし、漆黒の薬膳牛骨スープを煮出す","ko":"팔각과 계피 덖은 후 진한 소고기 약선 육수 끓이기"},"instruction":{"zh-TW":"小鍋中將八角、桂皮、芫荽籽乾鍋乾烙 1 分鐘逼出香氣。將香料裝入棉布香料袋，投入 1000ml 牛骨高湯中。加入黑甜醬油、生抽 2 大匙、魚露 2 大匙與椰糖 1 大匙。大火煮沸後轉微火加蓋慢熬 30 分鐘，直到湯色濃郁漆黑、四溢中藥草本芳香。","en":"Dry-toast star anise, cinnamon stick, and coriander seeds in a skillet for 1 minute until fragrant. Place in a spice sachet and plunge into 1000ml beef broth. Add dark sweet soy sauce, 2 tbsp light soy, 2 tbsp fish sauce, and 1 tbsp palm sugar. Simmer covered on low heat for 30 minutes until deep mahogany and warmly spiced.","th":"คั่วโป๊ยกั๊กและอบเชยจนหอม ใส่ในถุงกรองเครื่องเทศ ใส่ลงในน้ำซุปเนื้อ เติมซีอิ๊วดำหวาน ซีอิ๊วขาว น้ำปลา และน้ำตาลปี๊บ เคี่ยวไฟอ่อน 30 นาทีจนน้ำซุปดำข้นหอมกรุ่น","ja":"小鍋で八角、シナモン、コリアンダーシードを油を引かずに1分乾煎りします。出汁パックに入れ、牛骨スープ1000mlに投入。ダークソイソース、醤油大さじ2、ナンプラー大さじ2、パームシュガー大さじ1を加え、蓋をして弱火で30分コトコト煮出します。","ko":"마른 팬에 팔각, 계피, 고수씨를 1분간 덖어 향을 냅니다. 다시백에 담아 사골 육수 1000ml에 넣고 다크 간장, 양조간장 2큰술, 피시소스 2큰술, 팜슈가 1큰술을 넣은 뒤 뚜껑을 덮고 약불에서 30분간 푹 달입니다."},"durationSeconds":1800,"image":"/images/th/boat-noodles-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"大火滾水汆燙空心菜與米粉 (關鍵秒數)","en":"Flash-Blanch Morning Glory & Rice Noodles (Precise Seconds)","th":"ลวกผักบุ้งและเส้นเล็กสะบัดน้ำ","ja":"空心菜と米麺を沸騰湯で素早く湯通し","ko":"공심채와 쌀국수 면 끓는 물에 초스피드로 데치기"},"instruction":{"zh-TW":"另備一深鍋大火沸水。先將空心菜段投入滾水中燙 10 秒即撈出，鋪在 4 個碗底。隨即將泡軟的米粉放入濾網撈勺中，浸入滾水劇烈晃動燙煮 15-20 秒至剛好透明彈牙，立刻提起甩乾多餘水分，覆蓋在空心菜上方。","en":"In a separate pot of rapidly boiling water: blanch morning glory for precisely 10 seconds, divide into 4 bowls. Next, lower the soaked rice noodles in a mesh strainer into boiling water, shaking vigorously for 15-20 seconds until springy and translucent. Shake dry and place over greens.","th":"ต้มน้ำเดือดจัด ลวกผักบุ้ง 10 วินาทีตักใส่ชาม จากนั้นนำเส้นเล็กลงลวกในกระชอน 15-20 วินาทีจนเหนียวนุ่ม สะบัดน้ำให้แห้งสนิทใส่ชาม","ja":"別の深鍋に湯を沸騰させます。まず空心菜を10秒サッと茹でてザルに上げ、4つの器の底に敷きます。水戻しした米麺を振りザルに入れ、沸騰湯の中で15〜20秒激しく揺すって湯切りし、空心菜の上に重ねます。","ko":"다른 냄비에 끓는 물을 준비합니다. 공심채를 10초간 데쳐 그릇 바닥에 깔고, 불린 쌀국수 면을 채망에 담아 끓는 물에서 15~20초간 빠르게 흔들어 익힌 뒤 물기를 털어 얹습니다."},"durationSeconds":60,"image":"/images/th/boat-noodles-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"牛肉片高湯微灼八分熟","en":"Poach Tender Beef Slices in Spiced Broth","th":"ลวกเนื้อสไลซ์ในน้ำซุปให้สุกนุ่ม 80%","ja":"牛肉を薬膳スープでしゃぶしゃぶ状に火通し","ko":"진한 육수에 소고기 살짝 데치기"},"instruction":{"zh-TW":"用長筷夾住薄牛肉片，直接在翻滾的黑香料高湯中涮煮 15-20 秒，肉片變粉紅斷生即可撈起，鋪在每一碗麵條上（切勿煮老）。","en":"Using long chopsticks, swish thin beef slices directly in the simmering dark spiced broth for 15-20 seconds until just cooked through and tender pink. Distribute atop noodles in each bowl.","th":"ใช้ตะเกียบคีบเนื้อวัวสไลซ์ลงแกว่งในน้ำซุปเดือด 15-20 วินาทีจนเนื้อสุกนุ่มฉ่ำ วางบนชามก๋วยเตี๋ยว","ja":"菜箸で牛肉を挟み、煮立っている黒スープの中で15〜20秒しゃぶしゃぶします。ほんのりピンク色が残る柔らかい状態で引き上げ、麺の上にのせます。","ko":"긴 젓가락으로 얇은 소고기를 집어 끓는 육수에 15~20초간 살랑살랑 흔들어 샤부샤부처럼 데쳐 면 위에 올립니다."},"durationSeconds":45,"image":"/images/th/boat-noodles-step3.jpg"},{"stepNumber":4,"title":{"zh-TW":"舀入漆黑滾燙濃湯，撒蒜油與九層塔","en":"Ladle Boiling Broth, Drizzle Garlic Oil & Thai Basil","th":"ตักน้ำซุปร้อนๆ ราด ใส่กระเทียมเจียวและใบโหระพา","ja":"熱々の黒スープを注ぎ、ガーリックオイルとバジルを散らす","ko":"뜨거운 육수 붓고 마늘 기름과 바질 얹기"},"instruction":{"zh-TW":"在每碗麵上澆入一大勺滾燙的黑香料牛高湯（船麵的傳統只淋半碗濃湯，保留高度濃郁）。淋上一茶匙香脆炸蒜油，放上一小撮新鮮九層塔嫩葉。","en":"Ladle scorching dark spiced broth into each bowl (authentic boat noodles are served with just half a bowl of intensely concentrated soup). Drizzle 1 tsp golden fried garlic oil and tuck in fresh Thai basil leaves.","th":"ตักน้ำซุปเข้มข้นร้อนจัดราดลงในชาม (ราดพอท่วมเส้นแบบดั้งเดิม) หยอดกระเทียมเจียว 1 ช้อนชา และใส่ใบโหระพาสด","ja":"熱々の濃厚黒スープを注ぎます（伝統に則り、スープは麺がひたひたになる程度が本場流）。焦がしニンニク油小さじ1を回しかけ、バジルの葉を添えます。","ko":"펄펄 끓는 진한 육수를 붓습니다(전통 보트 누들은 자작하게 반 그릇 정도만 붓습니다). 마늘 기름 1작은술을 두르고 신선한 바질 잎을 얹습니다."},"durationSeconds":30,"image":"/images/th/boat-noodles-step4.jpg"},{"stepNumber":5,"title":{"zh-TW":"頂端堆疊炸豬皮，浸泡半軟半脆趁熱大快朵頤","en":"Crown with Crispy Pork Cracklings & Feast","th":"โรยแคบหมูกรอบ พร้อมเสิร์ฟความอร่อย","ja":"カリカリ豚皮揚げを山盛りに冠して完成","ko":"바삭한 돼지껍질 튀김(캡무) 얹어 완성"},"instruction":{"zh-TW":"最後在每碗頂端大方堆上一小把金黃炸豬皮（Khaep Moo）！吃之前把炸豬皮壓入黑湯浸泡 5 秒，豬皮外層吸附了藥膳八角牛湯的精華，咬下去卻依然喀嚓香脆，此乃曼谷船麵的無上極致吃法！","en":"Generously crown each bowl with crispy Thai pork cracklings (Khaep Moo). Push the cracklings down into the dark broth for 5 seconds before your first mouthful: the exterior absorbs the rich beef essence while the core maintains an explosive crunch!","th":"โปะแคบหมูกรอบด้านบน กดแคบหมูจุ่มน้ำซุป 5 วินาทีก่อนทาน ความกรอบฟูที่ดูดซับน้ำซุปเข้มข้นจะทำให้คุณติดใจ","ja":"最後に黄金色のケープムー（豚皮揚げ）を贅沢にトッピング！食べる直前にスープに5秒だけ沈めると、外側が濃厚なスープを吸ってジューシーになり、中はカリッとした最高の食感のコントラストが口いっぱいに広がります！","ko":"마지막으로 바삭한 캡무(돼지껍질 튀김)를 듬뿍 올립니다! 먹기 전 국물에 5초간 살짝 적셔 드세요. 겉은 진한 육수를 머금고 속은 바삭바삭하여 잊을 수 없는 감동을 선사합니다!"},"durationSeconds":20,"image":"/images/th/boat-noodles-step5.jpg"}],"troubleshooting":[{"id":"boat-noodle-bland","problem":{"zh-TW":"湯頭喝起來太清淡、缺乏船麵標誌性的厚重深沈色澤與草藥底蘊","en":"Broth tastes watery and lacks the iconic deep mahogany color and herbal punch","th":"น้ำซุปใส จืดชืด ไม่หอมเครื่องพะโล้","ja":"スープの色が薄く、船麺特有のドッシリとした薬膳のコクが出ない","ko":"국물이 맑고 밍밍하며 특유의 짙은 색과 한방 향이 덜해요"},"cause":{"zh-TW":"1. 八角與桂皮未提前乾鍋烙出精油；2. 黑甜醬油放太少；3. 熬煮時間不足未讓香料完全釋放於骨湯中。","en":"1. Whole spices were not dry-toasted; 2. Under-seasoned with dark sweet soy; 3. Did not simmer long enough to extract spice oils.","th":"ไม่ได้คั่วเครื่องพะโล้ก่อน หรือใส่ซีอิ๊วดำน้อยเกินไป","ja":"1. スパイスの乾煎り不足。2. ダークソイソースの量が足りない。3. 煮出し時間が短すぎた。","ko":"1. 향신료를 마른 팬에 충분히 덖지 않았거나, 2. 다크 간장 양이 적었거나, 3. 약불에서 충분히 우려내지 않았습니다."},"solution":{"zh-TW":"務必先將八角桂皮乾烙至飄香，並加入足量的泰國黑甜醬油（See Ew Dum）。至少以加蓋微火燜熬 30 分鐘！","en":"Always dry-toast the spices in a dry skillet, use authentic Thai dark sweet soy sauce, and simmer covered for at least 30 minutes.","th":"คั่วเครื่องเทศให้หอม ใส่ซีอิ๊วดำหวานเพิ่ม และเคี่ยวไฟอ่อนปิดฝาอย่างน้อย 30 นาที","ja":"八角とシナモンを香りが立つまでしっかり乾煎りし、タイ産ダークソイソースを適量加え、必ず蓋をして30分以上じっくり煮出してください。","ko":"향신료를 먼저 타지 않게 덖고 태국 다크 간장을 충분히 넣은 뒤 뚜껑을 덮고 30분 이상 푹 우려내세요."}}],"proTips":[{"zh-TW":"傳統文化小常識：泰國傳統船麵小攤會在湯底調入新鮮豬血（Nam Tok），現代都市與家庭版通常以極致慢熬的黑甜醬油配草藥骨湯完美重現濃郁口感。食用時務必在旁邊備好一碗朝天椒乾辣椒粉與白醋，辣爽交加才最過癮！","en":"Cultural insight: Traditional canal boats seasoned the broth with raw blood (Nam Tok) for thickness. Modern home kitchens replicate this luscious body with caramelized dark soy and rich marrow broth. Always serve with dry roasted chili powder and pickled chili vinegar!","th":"เกร็ดความรู้: ก๋วยเตี๋ยวเรือแท้ดั้งเดิมจะใส่น้ำตก (เลือดหมูหรือวัวสด) ปรุงในน้ำซุป ในสูตรโฮมเมดเราใช้ซีอิ๊วดำหวานและน้ำซุปเคี่ยวเข้มข้นแทนได้อย่างยอดเยี่ยม ปรุงด้วยพริกป่นคั่วเองเพื่อความแซ่บ","ja":"文化の豆知識：伝統的な船麺は生の豚や牛の血（ナムトック）を入れてスープにとろみをつけていましたが、現代の家庭料理では黒甘醤油と濃厚牛骨スープで完璧にコクを再現できます。卓上の一味唐辛子とお酢をたっぷり加えて食べるのが本場流！","ko":"문화 상식: 전통 보트 누들은 국물에 생피(남똑)를 넣어 농도를 잡았으나, 현대 가정식에서는 다크 간장과 진한 사골 육수로 안전하고 진하게 재현합니다. 볶은 고춧가루와 고추식초를 취향껏 넣어 드세요!"}]},{"country":"th","id":"gai-tod-hat-yai","slug":"gai-tod-hat-yai","title":{"zh-TW":"泰南傳奇 合艾香酥炸雞 (附香酥紅蔥酥)","en":"Southern Thai Hat Yai Fried Chicken with Crispy Shallots","th":"ไก่ทอดหาดใหญ่สูตรดั้งเดิมโรยหอมเจียวกรอบ","ja":"ガイトード・ハートヤイ（タイ南部式 黄金フライドチキン 揚げエシャロット添え）","ko":"핫야이 프라이드 치킨 (바삭한 샬롯 튀김 토핑)"},"subtitle":{"zh-TW":"小茴香芫荽籽深層醃漬・極致薄脆輕盈外皮・如落雪般的香脆紅蔥酥","en":"Coriander & Cumin Spiced Chicken with Crackly Skin & Mountain of Crispy Shallots","th":"หมักลูกผักชี ยี่หร่า หนังกรอบสะท้านฟัน โรยหอมเจียวทอดกรอบฟูสีทอง","ja":"クミンとコリアンダーの深遠なスパイス香。極薄パリパリの衣と黄金色に輝くフライドエシャロット","ko":"코리앤더와 큐민의 깊은 풍미, 얇고 바삭한 껍질 위에 눈처럼 수북한 샬롯 튀김"},"tagline":{"zh-TW":"全泰國公認最頂級炸雞天花板，咬下的瞬間卡滋作響、肉汁奔湧","en":"Universally crowned as Thailand's greatest fried chicken masterpiece","th":"ที่สุดของไก่ทอดสไตล์ไทย รสชาติเข้มข้นถึงเนื้อใน กรอบนอกนุ่มฉ่ำใน","ja":"タイ全土が認めるフライドチキンの最高峰。噛んだ瞬間、肉汁が弾け飛ぶ","ko":"태국 전역에서 손꼽히는 바삭함과 육즙의 끝판왕 치킨"},"heroImage":"/images/th/hat-yai-chicken.jpg","difficulty":"medium","prepTimeMinutes":30,"cookTimeMinutes":20,"defaultServings":4,"caloriesPerServing":580,"category":"mains","dietaryTags":["classic","halal"],"supportedCookware":["traditional","airFryer"],"culture":{"originRegion":{"zh-TW":"南部・宋卡府合艾 (Hat Yai)","en":"Southern / Hat Yai, Songkhla","th":"หาดใหญ่ สงขลา ภาคใต้","ja":"南部・ソンクラー県ハートヤイ","ko":"태국 남부 핫야이"},"famousStreetMarkets":[{"zh-TW":"合艾金榮市場 (Kim Yong Market)","en":"Kim Yong Market Hat Yai","th":"ตลาดกิมหยง หาดใหญ่","ja":"キムヨン市場（ハートヤイ）","ko":"김용 시장 (핫야이)"},{"zh-TW":"曼谷米奇林街頭名攤 Polo Fried Chicken","en":"Polo Fried Chicken (Soi Polo Bangkok)","th":"ไก่ทอดเจ๊หงษ์ ซอยโปโล","ja":"ポロ・フライドチキン（ソイ・ポロ）","ko":"폴로 프라이드 치킨 (방콕)"}],"historyStory":{"zh-TW":"合艾炸雞誕生於泰國南部的交通樞紐「合艾」。當地的泰國穆斯林攤販結合了馬來亞的辛香料傳統與潮汕的炸物手法，將茴香、芫荽籽、白胡椒與大蒜搗成芳香泥醬醃漬全雞。最精妙的靈魂在於起鍋時鋪天蓋地撒上的金黃炸紅蔥酥（Hom Daeng Tod），濃郁蔥甜與酥脆雞皮交織，配上一包熱糯米飯與甜辣醬，令人神魂顛倒。","en":"Born in the southern transit hub of Hat Yai near the Malaysian border, this masterpiece was pioneered by Thai-Muslim street hawkers. They combined toasted cumin and coriander seeds with garlic and pepper into a deep savory marinade. The defining signature is the colossal mountain of crackly, golden deep-fried Thai shallots (Hom Daeng Tod) heaped on top.","th":"ไก่ทอดหาดใหญ่ถือกำเนิดขึ้นจากชาวไทยมุสลิมในอำเภอหาดใหญ่ จังหวัดสงขลา โดดเด่นด้วยการหมักเครื่องเทศเม็ดผักชีและยี่หร่าจนเข้าถึงกระดูก และมีเอกลักษณ์สำคัญคือการโรยหอมแดงเจียวกรอบๆ กรุ่นกลิ่นหอม","ja":"マレーシア国境に近いタイ南部の商業都市ハートヤイで、タイ系イスラム教徒の屋台が考案した傑作。クミンシードやコリアンダーシードなどのスパイスで骨まで染み渡るように下味をつけ、極薄の衣で二度揚げ。大量の揚げエシャロット（ホムデーン・トート）をどっさり乗せるのが最大のシンボルです。","ko":"말레이시아 국경 근처 남부 교통 요충지인 핫야이의 무슬림 상인들이 개발한 걸작 치킨입니다. 큐민, 고수씨, 통후추를 빻은 특제 양념에 재워 튀기며, 황금빛 샬롯 튀김(홈댕텃)을 눈처럼 수북이 얹어내는 것이 상징입니다."},"thaiScript":"ไก่ทอดหาดใหญ่","thaiPhonetics":"Gai Tod Hat Yai","audioPronunciationText":"ขอไก่ทอดหาดใหญ่สองชิ้น ข้าวเหนียวหนึ่ง และขอหอมเจียวเยอะๆ ครับ","nativeName":"ไก่ทอดหาดใหญ่"},"ingredients":[{"id":"chicken-quarters","name":{"zh-TW":"帶骨雞大腿或雞翅 (表面劃深斜刀入味)","en":"Bone-in Chicken Thighs or Drumsticks (Scored deeply with knife)","th":"สะโพกไก่ติดน่องสด","ja":"骨付き鶏もも肉または手羽先（骨に沿って切り込みを入れる）","ko":"뼈 있는 닭 넓적다리 또는 닭다리 (칼집을 깊게 낸 것)"},"amount":600,"unitMetric":"g","unitUS":"1.3 lbs","isKeyFlavor":true,"thaiName":"สะโพกไก่","thaiPronunciation":"Sa-Phok Gai"},{"id":"shallots-crispy","name":{"zh-TW":"泰國紅蔥頭 (薄切圓圈片 - 靈魂配料)","en":"Thai Red Shallots (Sliced into paper-thin rings - Crucial soul)","th":"หอมแดงไทยซอยบาง","ja":"赤エシャロット（極薄輪切り・フライドオニオン用）","ko":"태국 샬롯 (얇게 링 모양으로 썬 것 - 핵심 영혼 토핑)"},"amount":150,"unitMetric":"g","unitUS":"5.3 oz","isKeyFlavor":true,"thaiName":"หอมแดง","thaiPronunciation":"Hom Daeng"},{"id":"coriander-seeds","name":{"zh-TW":"芫荽籽 (乾鍋烘香)","en":"Whole Coriander Seeds (Dry-toasted)","th":"เม็ดผักชีคั่ว","ja":"コリアンダーシード（乾煎り）","ko":"통 고수씨 (마른 팬에 덖은 것)"},"amount":1,"unitMetric":"tbsp","unitUS":"1 tbsp","isKeyFlavor":true,"thaiName":"เม็ดผักชี","thaiPronunciation":"Met Phak Chee"},{"id":"cumin-seeds","name":{"zh-TW":"小茴香籽 (孜然籽 - 乾鍋烘香)","en":"Whole Cumin Seeds (Dry-toasted)","th":"เม็ดยี่หร่าคั่ว","ja":"クミンシード（乾煎り）","ko":"통 큐민씨 (마른 팬에 덖은 것)"},"amount":1,"unitMetric":"tsp","unitUS":"1 tsp","isKeyFlavor":true,"thaiName":"ยี่หร่า","thaiPronunciation":"Yee-Raa"},{"id":"white-peppercorns","name":{"zh-TW":"白胡椒粒","en":"Whole White Peppercorns","th":"พริกไทยขาว","ja":"粒白胡椒","ko":"통 백후추"},"amount":1,"unitMetric":"tsp","unitUS":"1 tsp","thaiName":"พริกไทยขาว","thaiPronunciation":"Prik Thai Khao"},{"id":"cilantro-roots","name":{"zh-TW":"芫荽根","en":"Coriander / Cilantro Roots","th":"รากผักชี","ja":"パクチーの根","ko":"고수 뿌리"},"amount":3,"unitMetric":"piece","unitUS":"piece","thaiName":"รากผักชี","thaiPronunciation":"Raak Phak Chee"},{"id":"garlic-cloves","name":{"zh-TW":"蒜頭","en":"Garlic Cloves","th":"กระเทียมไทย","ja":"ニンニク","ko":"마늘 6쪽"},"amount":6,"unitMetric":"clove","unitUS":"clove","thaiName":"กระเทียม","thaiPronunciation":"Kra-Thiam"},{"id":"fish-sauce","name":{"zh-TW":"純魚露","en":"Fish Sauce","th":"น้ำปลาแท้","ja":"ナンプラー","ko":"피시소스"},"amount":2,"unitMetric":"tbsp","unitUS":"2 tbsp","thaiName":"น้ำปลา","thaiPronunciation":"Nam Pla"},{"id":"oyster-sauce","name":{"zh-TW":"蠔油","en":"Oyster Sauce","th":"ซอสหอยนางรม","ja":"オイスターソース","ko":"굴소스"},"amount":1.5,"unitMetric":"tbsp","unitUS":"1.5 tbsp","thaiName":"ซอสหอยนางรม","thaiPronunciation":"Sauce Hoi"},{"id":"sugar","name":{"zh-TW":"白糖","en":"Sugar","th":"น้ำตาลทราย","ja":"砂糖","ko":"설탕"},"amount":1,"unitMetric":"tbsp","unitUS":"1 tbsp","thaiName":"น้ำตาลทราย","thaiPronunciation":"Nam Tan"},{"id":"rice-flour","name":{"zh-TW":"粘米粉 / 在來米粉 (酥脆不硬的秘訣)","en":"Rice Flour (Secret to shatteringly thin crisp skin)","th":"แป้งข้าวเจ้า","ja":"上新粉（米粉・極薄カリカリの秘密）","ko":"멥쌀가루 (바삭하고 가벼운 튀김옷의 비결)"},"amount":4,"unitMetric":"tbsp","unitUS":"4 tbsp","isKeyFlavor":true,"thaiName":"แป้งข้าวเจ้า","thaiPronunciation":"Paeng Khao Chao"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"乾鍋焙香香料，研磨成合艾靈魂醃醬","en":"Toast Whole Spices & Grind Hat Yai Spice Paste","th":"คั่วเครื่องเทศ โขลกสามเกลอผสมยี่หร่า","ja":"スパイスを乾煎りし、伝統の香りペーストをすり潰す","ko":"향신료 덖고 빻아 핫야이 특제 마리네이드 만들기"},"instruction":{"zh-TW":"乾鍋中倒入芫荽籽和小茴香籽，中小火乾烙 1-2 分鐘直至散發迷人異域辛香。將香料倒入石臼，加入白胡椒粒、洗淨香菜根與大蒜瓣，奮力搗成細膩油亮的香料泥。加入魚露、蠔油與糖攪勻成濃黑醃醬。","en":"Dry-toast coriander seeds and cumin seeds in a skillet for 1-2 minutes until warmly fragrant. Transfer to a mortar with white peppercorns, cilantro roots, and garlic. Pound into a fine aromatic paste. Stir in fish sauce, oyster sauce, and sugar to form the signature marinade.","th":"คั่วเม็ดผักชีและยี่หร่าจนหอม โขลกพร้อมพริกไทยขาว รากผักชี และกระเทียมจนละเอียด ผสมน้ำปลา ซอสหอยนางรม และน้ำตาลทรายให้เข้ากัน","ja":"フライパンでコリアンダーシードとクミンシードを1〜2分乾煎りします。すり鉢に白胡椒、パクチーの根、ニンニクと共に入れ、細かくすり潰します。ナンプラー、オイスターソース、砂糖を加えて特製タレを完成させます。","ko":"마른 팬에 고수씨와 큐민씨를 1~2분간 덖어 향을 냅니다. 절구에 백후추, 고수 뿌리, 마늘과 함께 넣고 곱게 찧은 뒤, 피시소스, 굴소스, 설탕을 섞어 특제 양념장을 만듭니다."},"durationSeconds":240,"image":"/images/th/hat-yai-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"深劃刀口按摩抓醃，冷藏浸透入骨","en":"Score Chicken & Deep Marinate Under Refrigeration","th":"บั้งเนื้อไก่ นวดเครื่องหมักให้เข้าเนื้อ แช่ตู้เย็น","ja":"鶏肉に切り込みを入れ、タレを揉み込んで漬け込む","ko":"닭고기에 칼집 내고 양념 꼼꼼히 주물러 재우기"},"instruction":{"zh-TW":"在雞肉兩面劃上 2-3 道深刀口（必須切到接近骨頭，使香氣直達骨髓）。將醃料均勻塗抹在每寸雞皮與刀縫中，用力抓捏按摩 5 分鐘。加蓋放入冰箱冷藏醃製至少 3 小時（隔夜更佳）。","en":"Make 2-3 deep slashes into the chicken meat down to the bone. Rub the spice paste thoroughly into the slashes and under the skin. Massage for 5 minutes. Cover and chill in fridge for at least 3 hours (overnight delivers transcendent flavor).","th":"บั้งไก่ให้ถึงกระดูก ทาน้ำหมักให้ทั่วทุกซอกมุม นวด 5 นาที ปิดฝาแช่ตู้เย็นอย่างน้อย 3 ชั่วโมง","ja":"鶏肉の骨に届く深さまで2〜3本切り込みを入れます。タレを皮の間や切り込みの奥まで擦り込み、5分間力強く揉みます。ラップをして冷蔵庫で3時間以上（一晩推奨）寝かせます。","ko":"닭고기 뼈에 닿을 정도로 깊게 칼집을 2~3개 냅니다. 양념을 칼집 사이사이와 껍질 안쪽까지 꼼꼼히 바르고 5분간 주무른 뒤, 냉장고에서 최소 3시간(하룻밤 권장) 재웁니다."},"durationSeconds":300,"image":"/images/th/hat-yai-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"炸出黃金酥脆紅蔥酥 (落雪般的靈魂)","en":"Deep-Fry Golden Crispy Shallots (The Soul Topping)","th":"เจียวหอมแดงให้เหลืองทองกรอบฟู","ja":"黄金のフライドエシャロット（揚げ玉ねぎ）を作る","ko":"바삭한 황금빛 샬롯 튀김(홈댕텃) 튀겨내기"},"instruction":{"zh-TW":"紅蔥頭切成均勻薄片，撒入 1 茶匙粘米粉輕輕抓拌散開。冷油下鍋（油溫約 140°C），小火慢炸並持續輕輕翻動。當紅蔥頭開始浮起變微黃時立刻關火，利用油的餘溫炸至金黃酥脆，迅速用濾網撈出平鋪在吸油紙巾上。放涼後會如玻璃般極致酥脆！","en":"Toss sliced shallots with 1 tsp rice flour to coat. Add into medium-cool oil (140°C / 285°F). Fry slowly on gentle heat, stirring constantly. When shallots turn pale golden, kill heat instantly and let residual heat carry them to golden perfection. Scoop out immediately onto paper towels—they will crisp up like glass shards as they cool!","th":"คลุกหอมแดงกับแป้งข้าวเจ้า 1 ช้อนชา ลงทอดในน้ำมันไฟอ่อน คนตลอดเวลา พอน้ำมันเริ่มนิ่งและหอมเปลี่ยนเป็นสีเหลืองอ่อนให้ดับไฟทันที ตักขึ้นสะเด็ดน้ำมัน หอมจะกรอบสีทองสวยงาม","ja":"薄切りエシャロットに米粉小さじ1をまぶします。低温の油（140℃）に入れ、弱火で絶えず混ぜながら揚げます。薄いキツネ色になった瞬間に即火を止め、余熱で黄金色に仕上げてペーパーに取り出します。冷めるとパリッパリになります！","ko":"썬 샬롯에 쌀가루 1작은술을 버무립니다. 낮은 온도의 기름(140℃)에 넣고 약불에서 계속 저어가며 튀깁니다. 연한 노란빛이 돌 때 즉시 불을 끄고 건져내어 키친타월에 펼칩니다. 식으면서 극강의 바삭함이 완성됩니다!"},"durationSeconds":360,"image":"/images/th/hat-yai-step3.jpg"},{"stepNumber":4,"title":{"zh-TW":"拍上薄脆粘米粉，高溫炸至焦脆多汁","en":"Dust with Rice Flour & Fry to Blistering Crispness","th":"คลุกแป้งข้าวเจ้าบางๆ ทอดไฟกลางค่อนแรงจนกรอบนอกนุ่มใน","ja":"米粉を薄くまとい、ジューシー＆クリスピーに揚げ切る","ko":"쌀가루 옷 얇게 입혀 겉바속촉으로 튀기기"},"instruction":{"zh-TW":"【傳統油炸法】：取出醃好的雞肉，拌入 4 大匙粘米粉與 2 大匙冷水，使表面裹上一層幾乎看不見的極薄粉漿。油鍋燒至 175°C，下雞肉中火炸 12 分鐘至熟透。撈起靜置 2 分鐘，油溫拉高至 195°C 復炸 60 秒逼油上色！\\n【氣炸鍋模式】：預熱 190°C (375°F)，雞皮朝上氣炸 15 分鐘，翻面再炸 8 分鐘至外皮爆裂酥脆！","en":"[Deep-Fry Method]: Mix chicken with 4 tbsp rice flour and 2 tbsp cold water until a gossamer-thin translucent batter clings to the skin. Fry in 175°C (350°F) oil for 12 mins until cooked through. Rest 2 mins, then flash-fry at 195°C (385°F) for 60 seconds for insane crispness! [Air Fryer Option]: 190°C (375°F) skin-side up for 15 mins, flip and air fry 8 more mins.","th":"ใส่แป้งข้าวเจ้า 4 ช้อนโต๊ะและน้ำเย็น 2 ช้อนโต๊ะลงในไก่หมัก คลุกให้แป้งเคลือบผิวบางๆ ทอดน้ำมัน 175°C 12 นาที ตักพัก 2 นาที เร่งไฟแรง 195°C ทอดซ้ำอีก 1 นาทีให้กรอบสนั่นไม่อมน้ำมัน","ja":"【油揚げ】：漬け込んだ鶏肉に上新粉大さじ4と冷水大さじ2を揉み込み、ごく薄い衣を作ります。175℃の油で12分じっくり揚げ、2分休ませた後、195℃の高温で1分二度揚げして油を切ります。【ノンフライヤー】：190℃で皮目を上に15分、裏返して8分加熱。","ko":"【기름 튀김】: 재운 닭고기에 쌀가루 4큰술과 찬물 2큰술을 넣고 얇은 튀김옷을 입힙니다. 175℃ 기름에서 12분간 튀긴 후 2분 식히고, 195℃ 고온에서 1분간 2차 튀김을 하여 기름을 뺍니다. 【에어프라이어】: 190℃에서 껍질이 위로 오게 15분, 뒤집어서 8분 굽습니다."},"durationSeconds":780,"image":"/images/th/hat-yai-step4.jpg","cookwareVariations":[{"cookware":"airFryer","tempAndSetting":"190°C (375°F) for 22-24 mins","instructionOverride":{"zh-TW":"氣炸鍋預熱 190°C，在炸籃刷薄油。將拍好薄米粉的雞肉皮朝上放入，氣炸 15 分鐘。拉出翻面再炸 7-8 分鐘至金黃酥脆香氣四溢。","en":"Preheat Air Fryer to 190°C (375°F). Lightly oil basket, arrange chicken skin-side up. Air fry 15 mins. Flip and air fry another 7-8 mins until shatteringly crackly.","th":"หม้อทอดไร้น้ำมัน 190°C วางหนังขึ้น 15 นาที พลิกด้านทอดต่อ 7-8 นาทีจนหนังกรอบฟูสีเหลืองทอง","ja":"190℃に予熱したノンフライヤーに皮目を上にして並べ15分。裏返して7〜8分、皮がパチパチ音を立てるまで焼きます。","ko":"에어프라이어를 190℃로 예열하고 껍질이 위를 향하게 놓아 15분간 구운 뒤, 뒤집어서 7~8분간 더 바삭하게 굽습니다."}}]},{"stepNumber":5,"title":{"zh-TW":"堆雪山！鋪滿海量香酥紅蔥酥上桌","en":"Mountain of Crispy Shallots & Street Plating","th":"ตักเสิร์ฟ โรยหอมเจียวล้นจาน คู่ข้าวเหนียวและน้ำจิ้มไก่","ja":"フライドエシャロットを雪崩のように盛り付けて完成","ko":"바삭한 샬롯 튀김을 산더미처럼 얹어 완성"},"instruction":{"zh-TW":"將熱騰騰金黃爆汁的炸雞斬塊盛盤。抓起海量如落雪般的酥脆紅蔥酥，毫不客氣地鋪滿整個雞肉表面！旁邊附上泰式甜辣醬（Nam Chim Kai）與一袋溫熱糯米飯。一口咬下，蔥香、辛香與爆汁雞肉在口中狂響！","en":"Chop blistering fried chicken into pieces and plate. Grab handfuls of golden crispy shallots and bury the chicken beneath an avalanche of crunch! Serve with sweet Thai chili dipping sauce and warm sticky rice. Pure southern bliss!","th":"สับไก่ทอดร้อนๆ ใส่จาน โรยหอมเจียวกรอบๆ จนท่วม เสิร์ฟคู่กับน้ำจิ้มไก่แม่ประนอมและข้าวเหนียวนึ่งร้อนๆ อร่อยจนหยุดไม่อยู่","ja":"アツアツのチキンを切り分けて皿に盛り、先ほど作った大量のフライドエシャロットを雪のようにどっさり覆いかぶせます！タイのスイートチリソースともち米を添えて、ガブリと豪快にかぶりつきましょう！","ko":"뜨거운 치킨을 큼직하게 잘라 담고, 바삭한 샬롯 튀김을 치킨이 보이지 않을 정도로 수북이 쏟아붓습니다! 스위트 칠리소스와 따끈한 찹쌀밥을 곁들여 와삭와삭 뜯어먹는 맛이 최고입니다!"},"durationSeconds":30,"image":"/images/th/hat-yai-step5.jpg"}],"troubleshooting":[{"id":"hat-yai-shallots-burnt","problem":{"zh-TW":"炸出來的紅蔥酥發黑焦苦，完全無法入口","en":"Crispy shallots turned dark brown, burnt, and tasted bitterly acrid","th":"หอมเจียวไหม้ดำ มีรสขม","ja":"揚げエシャロットが焦げて真っ黒になり、苦味が出てしまった","ko":"샬롯 튀김이 까맣게 타고 쓴맛이 나요"},"cause":{"zh-TW":"1. 下鍋油溫太高；2. 在鍋裡等到顏色變成深金黃色才撈起（油的巨大蓄熱會讓紅蔥酥撈起後繼續自熱焦化）。","en":"1. Oil was scorchingly hot; 2. Waited until deep golden in the pan before scooping out (residual heat cooks them further).","th":"ใช้น้ำมันร้อนเกินไป หรือรอจนสีเข้มในกระทะแล้วค่อยตักขึ้น","ja":"1. 油が高温すぎた。2. 鍋の中で濃いキツネ色になるまで待ってしまった（油から上げても余熱でどんどん色が濃くなります）。","ko":"1. 처음부터 기름 온도가 너무 높았거나, 2. 팬 안에서 짙은 갈색이 될 때까지 기다린 후 건졌기 때문입니다."},"solution":{"zh-TW":"全程小火慢炸。看見蔥片開始變淡黃色（象牙白轉淡黃）就必須「立即關火」並撈出！鋪平在紙巾上降溫，餘溫會剛好將其烘至完美金黃。","en":"Fry on low heat. As soon as pale yellow appears, immediately kill heat and fish them out! Residual carryover heat finishes the color.","th":"ใช้ไฟอ่อน พอน้ำมันเริ่มนิ่งและเป็นสีเหลืองอ่อนให้รีบตักขึ้นทันที","ja":"弱火でじっくり揚げ、白から『ごく薄い淡黄色』に色づいた瞬間に即座に引き上げます。余熱を計算して早めに上げるのがプロの掟です。","ko":"약불로 서서히 튀기다가 은은한 연노란색이 돌 때 즉시 불을 끄고 건져내세요. 잔열로 완벽한 황금빛이 완성됩니다."}}],"proTips":[{"zh-TW":"脆皮粉漿絕招：泰國合艾名店絕不使用太厚重的麵粉，而是使用純「粘米粉」（在來米粉）。粘米粉不含麵筋，炸出來的外皮像薄冰糖葫蘆一樣薄脆輕盈，即使冷掉也完全不會軟塌！","en":"Secret batter physics: Hat Yai masters never use heavy wheat flour; they use 100% rice flour! Gluten-free rice flour creates a gossamer crust that shatters like spun glass and stays miraculously crunchy even when cold!","th":"สูตรลับความกรอบ: คนหาดใหญ่ใช้แป้งข้าวเจ้าแท้ในการชุบ จะได้หนังไก่ที่กรอบบางกร๊อบ ไม่หนาเตอะ และกรอบนานแม้ทิ้งจนเย็น","ja":"名店の衣の科学：小麦粉ではなく『米粉（上新粉）』のみを使うのが最大の秘密！グルテンが出ないため、薄氷のようにパリッと軽快な食感になり、冷めても一切ベチャつきません！","ko":"바삭함의 과학: 밀가루 대신 100% '멥쌀가루'를 얇게 입히는 것이 비법입니다! 글루텐이 생기지 않아 유리처럼 얇고 파삭하며, 식어도 눅눅해지지 않고 바삭함이 유지됩니다!"}]},{"country":"th","id":"roti-gluay","slug":"roti-gluay","title":{"zh-TW":"曼谷夜市 泰式香蕉煎餅 (煉乳巧克力)","en":"Bangkok Night Market Crispy Banana Roti","th":"โรตีกล้วยหอมราดนมข้นหวานช็อกโกแลต","ja":"ロティ・グルアイ（タイ風バナナクレープ 練乳＆チョコがけ）","ko":"방콕 야시장 바나나 로티 (연유 초코 시럽)"},"subtitle":{"zh-TW":"手甩延展薄如蟬翼麵皮・奶油慢煎金黃千層酥脆・熱融香蕉與濃甜煉乳","en":"Paper-Thin Dough Pan-Crisped in Butter with Sliced Bananas, Sweet Condensed Milk & Nutella","th":"แป้งนวดฟาดแบนบางกรอบ ทอดเนยหอมฟุ้ง ไส้กล้วยหอมสุก ราดนมข้นฉ่ำๆ","ja":"職人技で紙のように伸ばした極薄生地。バターの香ばしさととろける完熟バナナの甘美な誘惑","ko":"종이처럼 얇게 늘려 버터에 바삭하게 구운 반죽, 따뜻하게 녹아내린 바나나와 달콤한 연유"},"tagline":{"zh-TW":"泰國夜市最令人欲罷不能的散步甜點，油香、奶香與蕉甜的終極暴擊","en":"The universally worshipped street-cart dessert crisping across Thailand's vibrant night markets","th":"ขนมหวานริมทางยอดฮิต กรอบนอกนุ่มใน หวานมันสะใจ","ja":"タイの夜市を歩けば必ず出汁に吸い寄せられる、魅惑の屋台スイーツ代表格","ko":"태국 야시장의 밤거리를 달콤한 버터 향으로 물들이는 최고의 길거리 디저트"},"heroImage":"/images/th/banana-roti.jpg","difficulty":"medium","prepTimeMinutes":20,"cookTimeMinutes":10,"defaultServings":2,"caloriesPerServing":390,"category":"desserts","dietaryTags":["classic","vegetarian","halal"],"supportedCookware":["traditional"],"culture":{"originRegion":{"zh-TW":"南部至曼谷全境夜市","en":"Southern Thai to Bangkok Night Markets","th":"ภาคใต้และกรุงเทพมหานคร","ja":"タイ南部発祥・全土のナイトマーケット","ko":"태국 전역 야시장"},"famousStreetMarkets":[{"zh-TW":"考山路夜市","en":"Khao San Road Night Market","th":"ถนนข้าวสาร","ja":"カオサン通り","ko":"카오산 로드"},{"zh-TW":"喬德夜市 (Jodd Fairs)","en":"Jodd Fairs Night Market","th":"จ๊อดแฟร์","ja":"ジョッドフェアーズ","ko":"쩟페어 야시장"}],"historyStory":{"zh-TW":"Roti 源自印度與馬來穆斯林的無酵扁餅，十九世紀傳入泰國後被街頭小販進行了天才般的「泰式在地化改造」。小販們將麵糰揉入煉乳與奶油，在空中靈巧拋甩至薄如透光蟬翼，平底鐵板上下入大量牛油慢煎，包裹熟透香蕉片摺成九宮格方塊，最後淋上瀑布般的煉乳與美祿巧克力粉，成為風靡全球旅人的泰國街頭代名詞。","en":"Originating from Indian flatbread (roti canai) brought by Muslim traders, Thai street hawkers ingeniously reimagined it into an irresistible dessert. Street artisans rhythmically spin and slap the elastic dough across stainless steel carts until gossamer-thin, crisp it on a buttered griddle around ripe banana slices, fold it into neat parcels, and drown it in condensed milk.","th":"โรตีได้รับอิทธิพลมาจากชาวอินเดียและมุสลิม นำมาดัดแปลงเป็นของหวานสไตล์ไทยโดยใส่กล้วยหอม ทอดด้วยเนยหรือมาการีนจนกรอบฟู ตัดเป็นชิ้นสี่เหลี่ยมพอดีคำ ราดด้วยนมข้นหวานและผงไมโลหรือช็อกโกแลต","ja":"インドの無発酵パン（ロティ）がタイに渡り、屋台の職人たちによってスイーツへと奇跡の進化。宙に舞わせるように極薄に伸ばした生地でバナナを包み、バターで揚げ焼き。仕上げにコンデンスミルクとチョコシロップを浴びせるタイ屋台の名物です。","ko":"인도의 플랫브레드 로티가 태국 남부 무슬림 상인들을 통해 전해져 달콤한 디저트로 변신했습니다. 반죽을 공중에서 돌려 종이처럼 얇게 편 뒤 바나나를 넣고 접어 버터에 튀기듯 구워냅니다."},"thaiScript":"โรตีกล้วยหอม","thaiPhonetics":"Roti Gluay Hom","audioPronunciationText":"ขอโรตีกล้วยหอมใส่ไข่ ราดนมข้นเยอะๆ ครับ","nativeName":"โรตีกล้วยหอม"},"ingredients":[{"id":"all-purpose-flour","name":{"zh-TW":"中筋麵粉","en":"All-Purpose Wheat Flour","th":"แป้งสาลีอเนกประสงค์","ja":"中力粉（または薄力粉と強力粉半々）","ko":"중력분"},"amount":200,"unitMetric":"g","unitUS":"7 oz","thaiName":"แป้งสาลี","thaiPronunciation":"Paeng Salee"},{"id":"condensed-milk-dough","name":{"zh-TW":"甜煉乳 (和麵用)","en":"Sweetened Condensed Milk (For dough)","th":"นมข้นหวานผสมแป้ง","ja":"加糖練乳（生地練り込み用）","ko":"연유 (반죽용)"},"amount":1.5,"unitMetric":"tbsp","unitUS":"1.5 tbsp","thaiName":"นมข้นหวาน","thaiPronunciation":"Nom Khon Waan"},{"id":"salted-butter-dough","name":{"zh-TW":"無鹽奶油或酥油 (室溫軟化)","en":"Unsalted Butter or Ghee (Softened)","th":"เนยสดหรือเนยขาว","ja":"無塩バターまたはギー（常温）","ko":"무염 버터 (실온 연화)"},"amount":25,"unitMetric":"g","unitUS":"0.9 oz","thaiName":"เนยสด","thaiPronunciation":"Noey Sod"},{"id":"warm-water","name":{"zh-TW":"溫水 (加 1/2 小匙鹽化開)","en":"Warm Water (Dissolved with 1/2 tsp salt)","th":"น้ำอุ่นผสมเกลือ","ja":"ぬるま湯（塩小さじ1/2を溶かす）","ko":"미온수 (소금 1/2작은술 녹인 것)"},"amount":90,"unitMetric":"ml","unitUS":"3 fl oz","thaiName":"น้ำอุ่น","thaiPronunciation":"Nam Oon"},{"id":"ripe-bananas","name":{"zh-TW":"熟成香蕉 (切 0.5cm 圓薄片)","en":"Ripe Bananas (Sliced into 0.5cm rounds)","th":"กล้วยหอมสุกหั่นแว่น","ja":"完熟バナナ（5mm輪切り）","ko":"완숙 바나나 (0.5cm 두께로 썬 것)"},"amount":2,"unitMetric":"piece","unitUS":"piece","isKeyFlavor":true,"thaiName":"กล้วยหอม","thaiPronunciation":"Gluay Hom"},{"id":"egg-filling","name":{"zh-TW":"雞蛋 (打散與香蕉混合)","en":"Egg (Beaten with banana slices)","th":"ไข่ไก่ตีผสมกล้วย","ja":"溶き卵（バナナと合わせる）","ko":"달걀 (바나나와 섞을 것)"},"amount":1,"unitMetric":"piece","unitUS":"piece","thaiName":"ไข่ไก่","thaiPronunciation":"Khai Gai"},{"id":"frying-butter","name":{"zh-TW":"煎餅用奶油或植物人造奶油 (Margerine)","en":"Butter or Margarine (For griddling to maximum crispness)","th":"เนยหรือมาการีนสำหรับทอด","ja":"焼き用バターまたはマーガリン","ko":"버터 또는 마가린 (구이용)"},"amount":40,"unitMetric":"g","unitUS":"1.4 oz","isKeyFlavor":true,"thaiName":"เนยทอด","thaiPronunciation":"Noey Thod"},{"id":"sweetened-condensed-milk","name":{"zh-TW":"頂級雀巢甜煉乳 (淋醬靈魂)","en":"Sweetened Condensed Milk (For generous topping drizzle)","th":"นมข้นหวานตรามะลิหรือคาร์เนชัน","ja":"加糖練乳（仕上げ用）","ko":"연유 (토핑 드리즐용)"},"amount":3,"unitMetric":"tbsp","unitUS":"3 tbsp","isKeyFlavor":true,"thaiName":"นมข้นหวาน","thaiPronunciation":"Nom Khon Waan"},{"id":"chocolate-sauce","name":{"zh-TW":"巧克力醬或美祿可可粉 (Milo)","en":"Chocolate Syrup or Milo Malt Powder","th":"ซอสช็อกโกแลตหรือผงไมโล","ja":"チョコシロップ または ミロパウダー","ko":"초콜릿 시럽 또는 마일로 코코아 가루"},"amount":2,"unitMetric":"tbsp","unitUS":"2 tbsp","thaiName":"ซอสช็อกโกแลต","thaiPronunciation":"Sauce Chocolate"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"揉出柔軟麵糰，抹油鬆弛 2 小時 (延展性關鍵)","en":"Knead Silky Dough & Rest 2 Hours (Crucial for Stretch)","th":"นวดแป้งโรตี ทาเนย พักแป้ง 2 ชั่วโมง","ja":"滑らかにこねて油を塗り、2時間休ませる（驚異の伸びの秘密）","ko":"반죽을 치대어 오일을 바르고 2시간 휴지하기 (신축성의 핵심)"},"instruction":{"zh-TW":"將麵粉、煉乳、軟化奶油與加鹽溫水揉合，揉成光滑柔軟且不黏手的麵糰（約 8 分鐘）。均勻分成 4 顆小麵糰（每顆約 75g），表面塗滿厚厚一層軟化奶油或植物油，放入保鮮盒加蓋，室溫鬆弛靜置至少 2 小時（充足的鬆弛才能拉出如薄紙透光的麵皮！）。","en":"Combine flour, condensed milk, softened butter, and salted warm water into a supple dough. Knead for 8 mins until smooth. Divide into 4 equal balls (about 75g each). Coat generously with softened butter or oil, place in a sealed container, and rest at room temperature for at least 2 hours to relax gluten completely.","th":"ผสมแป้ง นมข้น เนย และน้ำอุ่น นวด 8 นาทีจนเนียนนุ่ม แบ่งเป็น 4 ก้อนเท่าๆ กัน ชโลมเนยให้ทั่ว พักไว้ในกล่องปิดสนิท 2 ชั่วโมง","ja":"ボウルに小麦粉、練乳、バター、塩水を合わせ、8分間しっかりこねて滑らかな生地にします。4等分に丸め、表面にバターをたっぷり塗り、密閉容器に入れて室温で2時間休ませます（グルテンが緩み、破れずに極薄に伸びるようになります）。","ko":"볼에 밀가루, 연유, 버터, 소금물을 넣고 8분간 치대어 매끈한 반죽을 만듭니다. 4등분으로 나눠 둥글린 뒤 표면에 버터를 듬뿍 바르고 밀폐 용기에 담아 실온에서 2시간 이상 휴지시킵니다."},"durationSeconds":600,"image":"/images/th/banana-roti-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"甩展推抹成透光薄紙 (街頭特技在家做)","en":"Stretch Paper-Thin Across Oiled Counter","th":"แผ่แป้งให้บางเฉียบจนโปร่งแสง","ja":"作業台で向こうが透けるほど極薄に引き伸ばす","ko":"기름칠한 조리대에 반죽을 종이처럼 얇게 펴기"},"instruction":{"zh-TW":"工作台刷上一層油。取出一顆鬆弛好的麵糰，先用手掌由內往外壓扁。接著雙手抓住麵皮邊緣向外輕輕拉伸延展，或用手掌掌心輕柔推抹，直到麵皮延伸成直徑約 35-40cm、薄如玻璃紙般半透明的大薄片（邊緣略有小破洞無妨）。","en":"Lightly oil your kitchen counter. Take one dough ball and flatten with palm. Gently pull and stretch the edges outward from the center, or use palms to spread it across the counter until it becomes a gossamer, translucent sheet 35-40cm wide (tiny tears in edges are completely fine).","th":"ทาน้ำมันบนโต๊ะ นำแป้งมากดแบน ใช้มือค่อยๆ ดึงและแผ่ขอบแป้งออกจนบางเฉียบมองทะลุเห็นพื้นโต๊ะ","ja":"台に薄く油を引きます。生地を手で平たく押し広げ、端を指先で優しく持ち上げながら外側へ引っ張るようにして、向こう側が透けて見える直径35〜40cmの極薄シートに伸ばします。","ko":"조리대에 오일을 바릅니다. 반죽을 손바닥으로 누른 뒤, 가장자리를 잡고 살살 당겨가며 조리대 바닥이 훤히 비칠 정도로 직경 35~40cm의 얇은 막으로 넓게 펼칩니다."},"durationSeconds":180,"image":"/images/th/banana-roti-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"下奶油平鍋，鋪入熟香蕉蛋液","en":"Griddle in Foaming Butter & Add Banana Slices","th":"ลงกระทะทอดเนย ใส่กล้วยหอมผสมไข่ตรงกลาง","ja":"バターを溶かした鉄板にのせ、バナナ卵液を配置","ko":"버터 녹인 팬에 올리고 바나나와 달걀물 얹기"},"instruction":{"zh-TW":"平底不沾鍋或鑄鐵煎盤以中小火加熱，融化一大塊奶油（約 10g）。雙手小心提起薄透麵皮平鋪入鍋中，發出滋滋聲響。在小碗中將 1 根切片香蕉與半顆蛋液拌勻，迅速倒在麵皮的正中央。","en":"Heat a large flat skillet or nonstick pan over medium-low heat. Melt a generous knob of butter (10g). Gently transfer the thin dough sheet flat onto the bubbling butter. In a bowl, toss sliced banana with beaten egg and pour right onto the center of the dough.","th":"ตั้งกระทะไฟกลางค่อนอ่อน ละลายเนย 10 กรัม วางแผ่นแป้งลงไป ผสมกล้วยหอมกับไข่ไก่แล้วเทลงตรงกลางแผ่นแป้ง","ja":"大きめのフライパンにバター10gを中弱火で溶かし、薄く伸ばした生地を広げ入れます。小鉢でバナナのスライスと溶き卵をサッと合わせ、生地の真ん中に一気に広げます。","ko":"넓은 팬에 버터 10g을 중약불로 녹입니다. 얇은 반죽을 조심스럽게 팬에 펼칩니다. 바나나 슬라이스와 달걀물을 살짝 섞어 반죽 중앙에 부어줍니다."},"durationSeconds":60,"image":"/images/th/banana-roti-step3.jpg"},{"stepNumber":4,"title":{"zh-TW":"四邊向內摺成方包，雙面慢煎金黃酥脆","en":"Fold into Neat Square Packet & Crisp Both Sides","th":"พับสี่ด้านเป็นสี่เหลี่ยม ทอดจนกรอบสีทอง","ja":"四方を折り込んで正方形に包み、両面を黄金色に焼き上げる","ko":"사방을 접어 네모나게 감싼 뒤 앞뒤로 노릇하게 튀기듯 굽기"},"instruction":{"zh-TW":"用鍋鏟迅速將麵皮的上下左右四邊折向中心，嚴密包裹住香蕉片，形成一個整齊的正方形封包。在頂部再抹一點奶油，翻面繼續慢煎 2-3 分鐘，直到雙面呈現如同千層酥般金黃微焦斑紋、用鍋鏟敲擊有清脆卡滋聲響，起鍋！","en":"Use spatula to fold the four overhanging flaps over the filling toward the center, forming a neat square envelope. Add another dab of butter on top and flip. Fry for 2-3 minutes per side until blistered with deep golden crispness and tapping with a spatula produces a hollow crunch!","th":"ใช้ตะหลิวพับแป้ง 4 ด้านเข้าหาตรงกลางเป็นรูปสี่เหลี่ยม ใส่เนยเพิ่ม พลิกทอดทั้งสองด้านจนแป้งกรอบพองสีทองเคาะมีเสียงกรอบ ตักขึ้น","ja":"フライパン返しで生地の四方を中央に向けて折りたたみ、バナナを包む正方形の小包を作ります。上にバターを少し足して裏返し、両面がキツネ色にサクサクになるまで2〜3分じっくり揚げ焼きにします。","ko":"주걱으로 반죽의 네 귀퉁이를 안쪽으로 접어 네모난 봉투 모양으로 감쌉니다. 버터를 살짝 더 두르고 뒤집어, 앞뒤가 황금빛으로 바삭바삭해질 때까지 2~3분간 굽습니다."},"durationSeconds":180,"image":"/images/th/banana-roti-step4.jpg"},{"stepNumber":5,"title":{"zh-TW":"分切九宮格，狂暴淋上甜煉乳與巧克力","en":"Slice into 9 Grid Squares & Generous Condensed Milk Drizzle","th":"ตัด 9 ช่อง ราดนมข้นหวานฉ่ำๆ และช็อกโกแลต","ja":"9等分の格子状にカットし、練乳とチョコを浴びせる","ko":"9조각으로 깍둑 썰고 연유와 초코 시럽 듬뿍 뿌려 완성"},"instruction":{"zh-TW":"將滾燙的煎餅移至砧板，用菜刀俐落地縱橫切成 9 塊一口大小的九宮格小方塊。盛入盤中，以豪邁的手勢淋上大量香甜白煉乳，再交錯畫出美濃巧克力醬線條。趁著剛出鍋香脆、內餡香蕉熱融如蜜時趁熱享用！","en":"Slide sizzling roti onto a cutting board. Chop with a cleaver into 9 bite-sized squares (3x3 grid). Transfer to a plate, generously zigzag sweetened condensed milk and chocolate sauce over the crackly top. Eat immediately while banana filling is molten and sweet!","th":"นำโรตีวางบนเขียง ใช้มีดตัดเป็น 9 ช่องพอดีคำ ราดนมข้นหวานตรามะลิฉ่ำๆ และซอสช็อกโกแลตเข้มข้น ทานร้อนๆ กรอบนอกหวานฉ่ำใน","ja":"まな板に移し、包丁でサクッと縦横に切って9等分のひと口サイズにします。皿に盛り、加糖練乳とチョコレートシロップを格子状にたっぷり回しかけます。中のバナナが熱々とろとろのうちにどうぞ！","ko":"도마로 옮겨 칼로 3x3 격자 모양의 9조각으로 자릅니다. 접시에 담고 달콤한 연유와 초코 시럽을 아낌없이 뿌립니다. 겉은 파삭하고 속의 바나나는 따뜻하게 녹아내릴 때 바로 드세요!"},"durationSeconds":45,"image":"/images/th/banana-roti-step5.jpg"}],"troubleshooting":[{"id":"roti-dough-tears","problem":{"zh-TW":"麵皮一拉就破洞連連，無法拉成薄片","en":"Dough tears instantly and refuses to stretch thinly","th":"แป้งขาดง่าย ไม่ยืดหยุ่น แผ่บางไม่ได้","ja":"生地を伸ばそうとするとすぐに破れてしまい、薄く広がらない","ko":"반죽을 늘릴 때마다 뚝뚝 찢어지고 얇게 펴지지 않아요"},"cause":{"zh-TW":"1. 鬆弛時間不足（麵筋依然緊繃）；2. 表面未塗抹足夠油脂導致乾涸失水；3. 水溫太冷或揉麵未起筋。","en":"1. Insufficient resting time (gluten tight); 2. Dough surface dried out from lacking butter coating; 3. Used cold water.","th":"พักแป้งไม่นานพอ หรือทาเนยน้อยจนแป้งแห้ง","ja":"1. 休ませ時間不足でグルテンが硬い。2. 油の塗り込みが足りず表面が乾燥した。3. 冷水を使った。","ko":"1. 휴지 시간이 부족하여 글루텐이 긴장 상태이거나, 2. 표면에 버터를 덜 발라 말랐거나, 3. 찬물로 반죽했습니다."},"solution":{"zh-TW":"務必抹上足量奶油並室溫靜置「滿 2 小時」。如果拉不開，再蓋上保鮮膜多放 30 分鐘，麵筋徹底鬆弛後甚至能拉長至 3 倍大！","en":"Coat lavishly in butter and rest for the full 2 hours. If resistant, rest 30 mins longer until dough stretches effortlessly.","th":"ทาเนยให้ชุ่ม พักให้ครบ 2 ชั่วโมง หากยังดึงยากให้พักต่ออีก 30 นาที","ja":"たっぷりの油でコーティングし、きっちり2時間休ませます。まだ戻ろうとする場合はさらに30分置くと、信じられないほど滑らかに伸びます。","ko":"버터를 넉넉히 발라 실온에서 반드시 2시간 이상 휴지하세요. 잘 늘어나지 않으면 30분 더 두어 글루텐을 완전히 이완시키세요."}}],"proTips":[{"zh-TW":"夜市靈魂秘密：泰國街頭煎餅之所以有一種獨特的奶香香氣，是因為小販幾乎都使用「植物人造奶油 Margarine」或「發酵黃油」高溫煎製。如果在家追求純天然，可以使用頂級無鹽發酵奶油，香氣更為高貴濃醇！","en":"Street cart secret: The unforgettable aroma wafting from Thai night markets comes from frying in golden margarine or clarified butter (ghee). At home, high-fat cultured European butter creates the most luxurious pastry crust imaginable!","th":"เคล็ดลับกลิ่นหอม: แม่ค้าโรตีใช้มาการีนหรือเนยสดในการทอดกระทะแบน ทำให้แป้งส่งกลิ่นหอมฟุ้งล่อตาล่อใจคนเดินผ่านไปมา","ja":"夜市の香りの正体：タイの屋台から漂うあの魅惑的な匂いは、植物性マーガリンやギーで揚げ焼きすることで生まれます。ご家庭では発酵無塩バターを使うと、極上の芳醇な香りに仕上がります！","ko":"야시장 냄새의 비밀: 노점에서 솔솔 풍기는 특유의 고소한 향은 마가린이나 기(Ghee) 버터로 구워내기 때문입니다. 가정에서는 풍미 좋은 천연 발효 버터를 쓰시면 훨씬 고급스러운 맛을 즐길 수 있습니다!"}]},{"country":"th","id":"hoy-tod","slug":"hoy-tod","title":{"zh-TW":"曼谷唐人街 泰式鐵板酥脆鮮蚵煎 (Hoy Tod)","en":"Bangkok Chinatown Crispy Mussel & Oyster Omelet (Hoy Tod)","th":"หอยทอดกระทะร้อนแป้งกรอบไม่อมน้ำมัน","ja":"ホイトード（タイ風 牡蠣とムール貝のカリカリ鉄板お好み焼き）","ko":"방콕 차이나타운 바삭한 굴/홍합 부침 (호이텃)"},"subtitle":{"zh-TW":"冰水脆漿黃金蕾絲邊・鮮美蚵肉多汁爆漿・鐵板炒豆芽爽脆不膩","en":"Crispy Golden Lacy Crepe with Plump Oysters, Eggs & Wok-Tossed Bean Sprouts","th":"แป้งกรอบนอกนุ่มใน หอยนางรมสดตัวโต ไข่ไก่และถั่วงอกผัดน้ำปลา","ja":"氷水仕込みの衣が生み出す極上のレース状クリスピー食感。プリプリの牡蠣とシャキシャキもやし","ko":"얼음물 반죽으로 빚어낸 레이스처럼 얇고 파삭한 식감, 탱글탱글한 굴과 숙주나물 볶음"},"tagline":{"zh-TW":"曾獲 CNN 評選全球最佳街頭小吃之一，曼谷唐人街排隊鐵板神作","en":"Crowned by CNN as one of the world's most divine street foods, sizzled on blistering steel planchas","th":"หนึ่งในสตรีทฟู้ดที่ดีที่สุดในโลก แป้งกรอบสนั่น หอมกลิ่นกระทะ","ja":"CNNが世界屈指のストリートフードに選出。熱々の鉄板で豪快に焼き上げる至福の海鮮粉もの","ko":"CNN 선정 세계 최고의 길거리 음식 중 하나로 꼽힌 방콕 차이나타운의 전설적인 철판 해물전"},"heroImage":"/images/th/hoy-tod.jpg","difficulty":"medium","prepTimeMinutes":15,"cookTimeMinutes":8,"defaultServings":2,"caloriesPerServing":480,"category":"stirFry","dietaryTags":["classic","pescatarian"],"supportedCookware":["traditional"],"culture":{"originRegion":{"zh-TW":"中部・曼谷唐人街與石龍軍路","en":"Central / Bangkok Chinatown & Charoen Krung","th":"เยาวราชและเจริญกรุง กรุงเทพฯ","ja":"中部・バンコク中華街（ヤワラート）","ko":"방콕 차이나타운 및 짜른끄룽"},"famousStreetMarkets":[{"zh-TW":"唐人街 Nai Mong Hoy Tod (米其林推薦)","en":"Nai Mong Hoy Tod Chinatown (Michelin)","th":"นายหมงหอยทอด เยาวราช","ja":"ナイモン・ホイトード（ミシュラン掲載）","ko":"나이몽 호이텃 (차이나타운 미슐랭)"},{"zh-TW":"席隆夜市路邊鐵板檔","en":"Silom Night Street Food","th":"สีลม","ja":"シーロム屋台街","ko":"실롬 야간 노점"}],"historyStory":{"zh-TW":"Hoy Tod 是十九世紀潮汕移民將「潮州蠔煎」帶至曼谷後，歷經百年演變出的泰式獨特風味。「Hoy」指貝類，「Tod」是香煎油炸。與潮汕版偏濕潤軟糯的口感不同，曼谷街頭大排檔改用樹薯粉與粘米粉調入冰水，在高溫重油的大平底圓鐵板上炸出如同金色蕾絲般極致酥脆的薄殼，搭配快炒豆芽與特製甜酸辣椒醬，被評為曼谷不可錯過的傳奇街頭美味。","en":"Hoy Tod traces its roots to the Teochew oyster omelet brought by Chinese immigrants in the late 19th century. However, Thai street hawkers revolutionized the texture: instead of a gooey gelatinous starch, they formulated an ice-cold slurry of rice flour and tapioca starch that crisps into a delicate, golden lacy wafer on a blistering iron plancha. Served over wok-charred bean sprouts with spicy-sweet chili sauce.","th":"หอยทอดพัฒนามาจากออส่วนของชาวจีนแต้จิ๋ว แต่คนไทยนิยมความกรอบ จึงปรับสูตรแป้งข้าวเจ้าผสมแป้งมันและน้ำเย็นจัด ทอดในกระทะแบนขนาดใหญ่จนแป้งกรอบฟูราวกับรังนกสีทอง รองด้วยถั่วงอกผัดน้ำปลา","ja":"潮州華人が伝えた『牡蠣煎（オアチェン）』がタイで独自進化。台湾や潮州のとろみのあるタイプと異なり、タイのホイトードは氷水で溶いた米粉とタピオカ粉を強火の鉄板で揚げ焼きにし、まるでレース編みのようにカリッカリに仕上げるのが特徴です。","ko":"19세기 조주(차오저우) 화교들이 전파한 굴전(오아젠)이 태국식으로 진화했습니다. 쫄깃한 식감의 원조와 달리, 태국 호이텃은 멥쌀가루와 타피오카 가루를 얼음물에 개어 뜨거운 철판에서 튀기듯 구워내어 레이스처럼 얇고 극도로 바삭한 크러스트를 자랑합니다."},"thaiScript":"หอยทอด","thaiPhonetics":"Hoy Tod","audioPronunciationText":"ขอหอยทอดแป้งกรอบหนึ่งจาน พิเศษหอยนางรมครับ","nativeName":"หอยทอด"},"ingredients":[{"id":"fresh-oysters-mussels","name":{"zh-TW":"新鮮生蚵或鮮熟青口 (淡菜)","en":"Fresh Shucked Oysters or Plump Mussels","th":"หอยนางรมสดหรือหอยแมลงภู่","ja":"生牡蠣 または むき身ムール貝","ko":"신선한 굴 또는 자숙 홍합살"},"amount":200,"unitMetric":"g","unitUS":"7 oz","isKeyFlavor":true,"thaiName":"หอยนางรม","thaiPronunciation":"Hoy Nang Rom"},{"id":"rice-flour","name":{"zh-TW":"粘米粉 / 在來米粉 (酥脆骨架)","en":"Rice Flour (For structural crispness)","th":"แป้งข้าวเจ้า","ja":"上新粉（米粉）","ko":"멥쌀가루"},"amount":4,"unitMetric":"tbsp","unitUS":"4 tbsp","isKeyFlavor":true,"thaiName":"แป้งข้าวเจ้า","thaiPronunciation":"Paeng Khao Chao"},{"id":"tapioca-starch","name":{"zh-TW":"樹薯澱粉或太白粉 (輕盈起泡感)","en":"Tapioca Starch or Cornstarch","th":"แป้งมันสำปะหลัง","ja":"タピオカ澱粉 または 片栗粉","ko":"타피오카 전분 또는 감자전분"},"amount":3,"unitMetric":"tbsp","unitUS":"3 tbsp","thaiName":"แป้งมัน","thaiPronunciation":"Paeng Man"},{"id":"ice-water","name":{"zh-TW":"冰水 (低溫造成熱衝擊起脆關鍵)","en":"Ice-Cold Water (Crucial for thermal crisp shock)","th":"น้ำเย็นจัด","ja":"キンキンに冷えた氷水","ko":"차가운 얼음물 (바삭한 열충격의 핵심)"},"amount":100,"unitMetric":"ml","unitUS":"3.4 fl oz","isKeyFlavor":true,"thaiName":"น้ำเย็น","thaiPronunciation":"Nam Yen"},{"id":"eggs","name":{"zh-TW":"雞蛋","en":"Eggs","th":"ไข่ไก่","ja":"卵","ko":"달걀 2개"},"amount":2,"unitMetric":"piece","unitUS":"piece","thaiName":"ไข่ไก่","thaiPronunciation":"Khai Gai"},{"id":"bean-sprouts","name":{"zh-TW":"綠豆芽 (洗淨去根瀝乾 - 墊底爽脆)","en":"Fresh Bean Sprouts (Washed and dried thoroughly - Crunchy bed)","th":"ถั่วงอกสด","ja":"もやし（水気をしっかり切る）","ko":"숙주나물 (씻어서 물기를 뺀 것 - 바닥 깔기용)"},"amount":150,"unitMetric":"g","unitUS":"5.3 oz","isKeyFlavor":true,"thaiName":"ถั่วงอก","thaiPronunciation":"Thua Ngok"},{"id":"garlic-chives","name":{"zh-TW":"韭菜 (切 3cm 段)","en":"Garlic Chives (Cut into 1-inch sections)","th":"ใบกุยช่ายหั่นท่อน","ja":"ニラ（3cm長さにカット）","ko":"부추 (3cm 길이로 썬 것)"},"amount":30,"unitMetric":"g","unitUS":"1 oz","thaiName":"ใบกุยช่าย","thaiPronunciation":"Bai Kui-Chai"},{"id":"fish-sauce","name":{"zh-TW":"純魚露","en":"Fish Sauce","th":"น้ำปลาแท้","ja":"ナンプラー","ko":"피시소스"},"amount":1.5,"unitMetric":"tbsp","unitUS":"1.5 tbsp","thaiName":"น้ำปลา","thaiPronunciation":"Nam Pla"},{"id":"white-pepper","name":{"zh-TW":"純白胡椒粉","en":"Ground White Pepper","th":"พริกไทยป่น","ja":"白胡椒粉","ko":"백후춧가루"},"amount":0.5,"unitMetric":"tsp","unitUS":"0.5 tsp","thaiName":"พริกไทยป่น","thaiPronunciation":"Prik Thai Pon"},{"id":"sweet-chili-sauce","name":{"zh-TW":"泰式甜辣醬或是拉差辣醬 (沾食靈魂)","en":"Thai Sweet Chili Sauce (Nam Chim Kai) or Sriracha","th":"น้ำจิ้มไก่ผสมซอสพริกศรีราชา","ja":"スイートチリソース または シラチャーソース","ko":"스위트 칠리소스 또는 스리라차 소스"},"amount":3,"unitMetric":"tbsp","unitUS":"3 tbsp","isKeyFlavor":true,"thaiName":"น้ำจิ้มหอยทอด","thaiPronunciation":"Nam Chim Hoy Tod"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"冰水調製極致輕脆粉漿","en":"Whisk Ice-Water Crispy Batter & Fold Seafood","th":"ผสมแป้งกรอบด้วยน้ำเย็นจัด ใส่หอยและกุยช่าย","ja":"氷水で極薄カリカリ衣を作り、魚介とニラを合わせる","ko":"얼음물로 얇고 바삭한 반죽 개어 해물과 부추 섞기"},"instruction":{"zh-TW":"大碗中將粘米粉 4 大匙、樹薯粉 3 大匙、1/2 茶匙鹽與 100ml 冰水攪勻成無顆粒的稀薄水漿。加入韭菜段與洗淨瀝乾的生蚵（或青口）。冰水在接觸滾燙熱油時會產生強烈的熱膨脹微氣孔，這是蕾絲薄脆的終極科學秘訣！","en":"In a bowl, whisk 4 tbsp rice flour, 3 tbsp tapioca starch, 1/2 tsp salt, and 100ml ice-cold water into a fluid, watery slurry. Fold in chopped chives and thoroughly drained oysters/mussels. The ice-water hits boiling oil, creating violent micro-steam explosions that build an ultra-lacy crisp!","th":"ผสมแป้งข้าวเจ้า แป้งมัน เกลือ และน้ำเย็นจัด คนให้ละลาย ใส่ใบกุยช่ายและหอยนางรมสดที่สะเด็ดน้ำแห้งดีแล้วลงไป","ja":"ボウルに上新粉大さじ4、タピオカ粉大さじ3、塩小さじ1/2、冷たい氷水100mlを合わせ、サラサラの衣液を作ります。ニラと水気を切った牡蠣を加えます。氷水が熱い油と出会うことで無数の微細な気泡が生まれ、レース状のサクサク感が誕生します！","ko":"볼에 멥쌀가루 4큰술, 타피오카 전분 3큰술, 소금 1/2작은술, 얼음물 100ml를 넣고 멍울 없이 묽게 갭니다. 부추와 물기 뺀 굴을 넣습니다. 차가운 반죽이 뜨거운 기름에 닿아 미세한 공기구멍을 만들며 극상의 바삭함을 만듭니다!"},"durationSeconds":120,"image":"/images/th/hoy-tod-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"熱油鐵板爆煎！倒漿炸出蕾絲金邊","en":"Pour Batter onto Sizzling Griddle for Lacy Edges","th":"เทแป้งลงกระทะร้อนจัด น้ำมันท่วมพอประมาณจนฟูกรอบ","ja":"カンカンに熱した鉄板に流し込み、レース状に揚げ焼き","ko":"기름 넉넉히 두른 뜨거운 팬에 부어 레이스 테두리 만들기"},"instruction":{"zh-TW":"平底鍋下 3 大匙油，大火加熱至油面起波紋冒微煙。將粉漿與生蚵一口氣倒入鍋中，迅速晃動鍋子讓粉漿向四周攤成薄餅狀。大火煎炸 90 秒，邊緣會迅速炸出像蕾絲般半透明的金黃薄脆網狀邊緣！","en":"Heat 3 tbsp oil in a large skillet over high heat until shimmering. Pour the entire bowl of batter and oysters into the pan at once, swirling so it spreads thin. Fry on high heat for 90 seconds until the edges bubble up into a golden, translucent lacy web!","th":"ตั้งกระทะใส่น้ำมัน 3 ช้อนโต๊ะไฟแรง เทแป้งและหอยลงไป เอียงกระทะให้แป้งแผ่กว้าง ทอดไฟแรง 90 วินาทีจนขอบแป้งฟูกรอบสีทอง","ja":"フライパンに油大さじ3を強火で熱し、煙が出る直前まで温めます。衣と牡蠣を一気に流し入れ、フライパンを回して薄く広げます。強火で90秒、縁がレース状にプツプツと泡立ち黄金色に揚がるまで焼きます！","ko":"팬에 기름 3큰술을 넉넉히 두르고 센 불에서 달굽니다. 반죽과 굴을 한 번에 붓고 팬을 돌려 얇게 폅니다. 센 불에서 90초간 튀기듯 구워 가장자리가 황금빛 레이스처럼 바삭하게 부풀어 오르게 합니다!"},"durationSeconds":90,"image":"/images/th/hoy-tod-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"打入雞蛋劃散，翻面煎脆","en":"Crack Eggs Over Top & Flip to Crisp","th":"ตอกไข่ไก่ใส่บนแป้ง ยีให้ทั่ว กลับด้านทอด","ja":"卵を割り落として崩し、裏返して両面カリカリに","ko":"달걀을 깨 올리고 노른자 터뜨려 뒤집기"},"instruction":{"zh-TW":"在半凝固的煎餅表面直接打入 2 顆雞蛋，用鍋鏟將蛋黃戳破推抹散開。待底層酥脆定型後，大膽用鍋鏟將煎餅翻面（或分切成大塊翻面），繼續中大火煎 1-2 分鐘，讓蛋香焦化並與外皮融合成酥脆金黃整體。","en":"Crack 2 eggs directly onto the sizzling crepe. Break yolks with spatula and spread across the surface. Once bottom is completely crisp, flip the pancake (you can split into halves for easy flipping). Fry another 1-2 mins until egg is deeply caramelized and crispy.","th":"ตอกไข่ 2 ฟองลงบนหน้าแป้ง ยีไข่แดงให้ทั่ว พอแป้งด้านล่างกรอบดีแล้ว ให้พลิกกลับด้าน ทอดต่อ 1-2 นาทีจนไข่หอมสุกเกรียมกรอบ","ja":"生地の上に卵2個を割り入れ、ヘラで黄身を軽く崩して塗り広げます。底が完全にカリッとしたら裏返し（難しければ半分に割ってOK）、さらに1〜2分、卵が香ばしく色づくまで揚げ焼きにします。","ko":"반죽 위에 달걀 2개를 깨 넣고 노른자를 톡 터뜨려 넓게 폅니다. 바닥이 완전히 바삭해지면 주걱으로 뒤집어(어려우면 반으로 잘라 뒤집으세요), 1~2분간 더 구워 달걀의 고소한 불맛을 입힙니다."},"durationSeconds":90,"image":"/images/th/hoy-tod-step3.jpg"},{"stepNumber":4,"title":{"zh-TW":"推鍋旁，大火爆炒爽脆豆芽 (靈魂配菜)","en":"Wok-Toss Bean Sprouts on the Side with Fish Sauce","th":"ดันหอยทอดไว้ข้างกระทะ ผัดถั่วงอกไฟแดงใส่น้ำปลา","ja":"煎餅を端に寄せ、空いた場所でもやしを強火で15秒サッと炒める","ko":"전을 한쪽으로 밀고 빈 공간에 숙주나물 센 불에 볶기"},"instruction":{"zh-TW":"將煎好的香脆海鮮煎餅推至鍋的一邊。在空出的鍋底投入綠豆芽，淋入 1 大匙魚露。開最大火翻炒僅僅 15-20 秒，讓豆芽吸到油香與魚露鹹香但依然爽脆爆汁，立刻關火！將炒豆芽鋪在盤子底部。","en":"Push the crisp seafood pancake to one side of the skillet. Toss fresh bean sprouts into the empty hot space and splash with 1 tbsp fish sauce. Flash-fry on maximum heat for just 15-20 seconds so sprouts stay ultra-crunchy and juicy. Transfer sprouts as a bed onto a serving platter.","th":"ดันหอยทอดไปไว้ด้านหนึ่ง ใส่ถั่วงอกลงในที่ว่าง เหยาะน้ำปลา 1 ช้อนโต๊ะ ผัดไฟแรงสุด 15 วินาทีพอสลด ตักถั่วงอกรองก้นจาน","ja":"カリカリのホイトードを鍋の端に寄せます。空いたスペースにもやしを一気に入れ、ナンプラー大さじ1をジャッと回しかけます。強火でわずか15〜20秒、もやしの水分を飛ばしながらシャキシャキ感を残して炒め、皿に敷きます。","ko":"바삭한 부침을 팬 한쪽으로 밉니다. 빈 공간에 숙주나물을 넣고 피시소스 1큰술을 둘러 센 불에서 15~20초간 빠르게 볶아냅니다. 아삭함이 살아있을 때 꺼내 접시 바닥에 깝니다."},"durationSeconds":30,"image":"/images/th/hoy-tod-step4.jpg"},{"stepNumber":5,"title":{"zh-TW":"蓋上金黃海鮮煎，灑白胡椒，淋甜酸辣醬享用","en":"Assemble Over Sprouts, Dust White Pepper & Serve with Sauce","th":"วางหอยทอดบนถั่วงอก โรยพริกไทย เสิร์ฟคู่น้ำจิ้ม","ja":"もやしの上に重ね、白胡椒を振り、特製タレを添えて完成","ko":"숙주 위에 얹고 백후추 뿌린 뒤 특제 소스 곁들여 완성"},"instruction":{"zh-TW":"用鍋鏟將喀嚓酥脆的金黃鮮蚵煎餅整片覆蓋在清脆豆芽上。表面均勻撒上一層純白胡椒粉增添辛香。附上一小碗泰式甜辣醬。每一口都能吃到酥脆蕾絲粉皮、軟嫩多汁的肥蚵與爽脆豆芽，堪稱曼谷街頭最高傑作！","en":"Slide the golden, shatteringly crispy seafood pancake right over the mound of crunchy bean sprouts. Generously dust with white pepper. Serve immediately with sweet Thai chili dipping sauce. The contrast of crackling batter, tender briny oysters, and crunchy sprouts is out of this world!","th":"ตักหอยทอดกรอบๆ โปะทับถั่วงอก โรยพริกไทยป่น เสิร์ฟพร้อมน้ำจิ้มหอยทอดรสหวานเผ็ดเปรี้ยว ทานทันทีขณะร้อนกรอบสนั่นฟัน","ja":"炒めたもやしの上に、音を立ててサクサクのホイトードを豪快にかぶせます。白胡椒をサッと振り、スイートチリソースを添えて完成！箸を入れると『ザクッ』と快音が響き、濃厚な牡蠣の旨みとシャキシャキもやしが押し寄せます！","ko":"아삭한 숙주나물 위에 바삭바삭 소리가 나는 황금빛 해물전을 덮어 올립니다. 백후춧가루를 솔솔 뿌리고 스위트 칠리소스를 곁들여 냅니다. 바삭한 튀김옷과 육즙 가득한 굴, 아삭한 숙주의 3단 콤보를 만끽하세요!"},"durationSeconds":20,"image":"/images/th/hoy-tod-step5.jpg"}],"troubleshooting":[{"id":"hoy-tod-soggy","problem":{"zh-TW":"煎出來軟趴趴、吸滿厚重油脂，完全沒有酥脆感","en":"Pancake turned soft, gooey, soggy, and heavily oil-logged","th":"แป้งแฉะ นิ่ม อมน้ำมัน ไม่กรอบ","ja":"ベチャッとして油っぽく、カリカリ感が全く出なかった","ko":"바삭하지 않고 눅눅하며 기름을 흠뻑 먹었어요"},"cause":{"zh-TW":"1. 蚵仔沒有徹底瀝乾水份，大量水分進入鍋中使油溫驟降；2. 下鍋油溫不夠高；3. 誤用了全太白粉/木薯粉（太白粉只會變軟糯Q黏，必須搭配粘米粉才會硬脆）。","en":"1. Oysters were not thoroughly drained; 2. Oil wasn't hot enough; 3. Used 100% tapioca starch without rice flour (tapioca alone is chewy, rice flour provides crisp rigidity).","th":"หอยไม่สะเด็ดน้ำ หรือน้ำมันไม่ร้อนพอ และต้องมีแป้งข้าวเจ้าผสมแป้งมัน","ja":"1. 牡蠣の水切り不足。2. 油の温度が低かった。3. タピオカ粉だけで作った（米粉をブレンドしないとカリカリになりません）。","ko":"1. 굴의 물기를 제대로 털지 않았거나, 2. 기름 온도가 낮았거나, 3. 멥쌀가루 없이 전분으로만 반죽했습니다."},"solution":{"zh-TW":"蚵仔用廚房紙巾吸乾水份。粘米粉與樹薯粉採 4:3 黃金比例，務必使用「冰水」調漿，且油溫必須大火燒熱至冒微煙再一口氣倒入！","en":"Pat oysters dry. Use the golden 4:3 ratio of Rice Flour to Tapioca Starch with ice-cold water, and pour only into smoking hot oil.","th":"ซับหอยให้แห้ง ใช้แป้งข้าวเจ้าผสมแป้งมันด้วยน้ำเย็นจัด และทอดในน้ำมันร้อนจัดไฟแรงเสมอ","ja":"牡蠣の水気を拭き取り、上新粉とタピオカ粉を4:3で配合し、必ず【氷水】で溶き、煙が出るほど熱した油に一気に入れてください。","ko":"굴의 물기를 키친타월로 꼭 짜내고, 멥쌀가루와 타피오카 전분을 4:3 비율로 섞어 얼음물로 갠 뒤 연기 나는 뜨거운 기름에 부어 튀기세요."}}],"proTips":[{"zh-TW":"曼谷米其林 Nai Mong 秘訣：粉漿必須「極稀薄如水」！很多人誤以為粉漿要像麵糊一樣濃稠，但正宗泰式脆皮煎餅的粉漿幾乎像淘米水一樣稀，下油鍋才能在瞬間散開形成厚度不到 1 毫米的金黃氣孔蕾絲網！","en":"Michelin Nai Mong secret: The batter must be as watery as skim milk! Thick batter creates heavy pancakes; super-fluid batter spreads instantaneously in hot oil into a micro-thin, gossamer-crisp golden net!","th":"เคล็ดลับระดับมิชลิน: แป้งต้องเหลวเหมือนน้ำนม หากแป้งข้นเกินไปจะหนาและไม่อร่อย แป้งที่เหลวจะแตกตัวในน้ำมันร้อนเป็นตาข่ายกรอบโปร่งแสง","ja":"ミシュラン名店の神髄：衣液は『牛乳のようにサラサラ』にするのが絶対条件！ドロッとした重い衣だと分厚くなってしまいます。水のように薄い液だからこそ、油の中で一瞬で極薄のレース状に広がります！","ko":"미슐랭 달인의 핵심 비법: 반죽은 우유처럼 아주 찰랑거리고 묽어야 합니다! 걸쭉한 반죽은 두껍고 눅눅해집니다. 물처럼 묽어야 뜨거운 기름 속에서 1mm 두께의 그물망처럼 얇고 바삭하게 퍼집니다!"}]},{"country":"th","id":"khao-kha-moo","slug":"khao-kha-moo","title":{"zh-TW":"曼谷老街 慢燉泰式豬腳飯","en":"Bangkok Old Town Braised Pork Leg Rice (Khao Kha Moo)","th":"ข้าวขาหมูพะโล้โบราณเนื้อหนังนุ่มละลาย","ja":"カオ・カームー（とろとろ煮込み豚足ご飯）","ko":"방콕 올드타운 족발 덮밥 (카오 카무)"},"subtitle":{"zh-TW":"五香肉桂八角老滷汁・膠原蛋白入口即化・酸菜辣椒醋絕配","en":"Meltingly Tender Pork Hock in Spiced Master Stock with Pickled Mustard Greens & Chili Vinegar","th":"ตุ๋นเครื่องพะโล้สมุนไพรจีน หนังนุ่มละลายในปาก เสิร์ฟพร้อมผักกาดดองและน้ำส้มพริกดอง","ja":"五香粉とシナモンが香る秘伝ダレ。箸で崩れる極上コラーゲンと酸味ダレの黄金比","ko":"오향과 계피 향이 깊게 밴 야들야들한 족발, 갓절임과 고추식초의 완벽한 조화"},"tagline":{"zh-TW":"米其林必比登連續推薦，曼谷街頭撫慰靈魂的至尊滷肉神作","en":"Michelin Bib Gourmand street legend beloved for its fork-tender gelatinous richness","th":"เมนูในตำนานการันตีมิชลิน รสชาติหวานเค็มกลมกล่อม หอมเครื่องพะโล้ถึงใจ","ja":"ミシュラン・ビブグルマン常連。バンコク屋台が誇る極上煮込み料理の金字塔","ko":"미슐랭 빕구르망이 인정한 방콕 최고의 소울푸드 족발 덮밥"},"heroImage":"/images/th/khao-kha-moo.jpg","difficulty":"easy","prepTimeMinutes":20,"cookTimeMinutes":90,"defaultServings":4,"caloriesPerServing":620,"category":"mains","dietaryTags":["classic"],"supportedCookware":["traditional","instantPot"],"culture":{"originRegion":{"zh-TW":"中部・曼谷石龍軍路 (Charoen Krung)","en":"Central / Charoen Krung, Bangkok","th":"เจริญกรุง กรุงเทพฯ","ja":"中部・バンコク ジャルンクルン通り","ko":"방콕 짜른끄룽"},"famousStreetMarkets":[{"zh-TW":"石龍軍路 Charoen Saeng Silom 豬腳名店","en":"Charoen Saeng Silom Pork Leg","th":"เจริญแสงสีลม","ja":"チャルンセーン・シーロム（ミシュラン店）","ko":"짜른쌩 실롬 (미슐랭)"},{"zh-TW":"勝利紀念碑夜市","en":"Victory Monument Night Market","th":"อนุสาวรีย์ชัยฯ","ja":"アヌサワリー市場","ko":"빅토리 모뉴먼트 야시장"}],"historyStory":{"zh-TW":"Khao Kha Moo 源自早期廣東潮汕移民帶到曼谷的五香滷味技法。石龍軍路的泰籍潮汕廚師將肉桂、八角、香菜根與大量椰糖結合，以文火慢燉數小時使豬皮呈現半透明膠質化，搭配特製酸辣辣椒醋（Prik Nam Som）與酸菜，成功征服了全泰國人的味蕾，甚至成為泰國前總理他信最愛的庶民美食。","en":"Rooted in Teochew Chinese braising traditions brought to Bangkok's riverside districts. Local cooks infused cinnamon, star anise, cilantro roots, and unrefined palm sugar, simmering pork hocks until the collagen dissolves into silk. Paired with tart bird's-eye chili vinegar and pickled greens to slice through richness, it earned worldwide acclaim.","th":"ข้าวขาหมูได้รับอิทธิพลมาจากชาวจีนแต้จิ๋ว นำขาหมูมาเคี่ยวกับเครื่องพะโล้ อบเชย โป๊ยกั๊ก และรากผักชี เติมน้ำตาลปี๊บจนเนื้อนุ่มร่อนละลายในปาก กินคู่กับน้ำจิ้มพริกน้ำส้มและผักกาดดองตัดเลี่ยน","ja":"バンコクの河岸地区に定住した潮州系華人が伝えた煮込み料理がルーツ。シナモン、八角、パクチーの根、パームシュガーで豚足をホロホロになるまで数時間煮込みます。唐辛子入りの酸味ダレ（プリック・ナムソム）と高菜漬けが脂っこさを完璧に消し去ります。","ko":"조주(차오저우) 출신 화교들의 오향 조림 기법이 방콕에서 독자적으로 발전했습니다. 계피, 팔각, 고수 뿌리, 팜슈가를 넣고 푹 삶아 껍질이 입안에서 사르르 녹아내립니다. 매콤한 고추식초 소스와 갓절임을 곁들여 먹습니다."},"thaiScript":"ข้าวขาหมู","thaiPhonetics":"Khao Kha Moo","audioPronunciationText":"ขอข้าวขาหมูเนื้อหนังจานหนึ่ง ใส่ไข่ด้วยครับ","nativeName":"ข้าวขาหมู"},"ingredients":[{"id":"pork-hock","name":{"zh-TW":"豬前蹄或帶皮蹄膀 (切大塊)","en":"Pork Hock or Shank (Bone-in, cut into thick discs)","th":"ขาหมูติดหนัง","ja":"豚足または豚すね肉（皮付き・厚切り）","ko":"돼지 족발 또는 사태 (껍질 붙은 것)"},"amount":1000,"unitMetric":"g","unitUS":"2.2 lbs","isKeyFlavor":true,"thaiName":"ขาหมู","thaiPronunciation":"Kha Moo"},{"id":"palm-sugar","name":{"zh-TW":"泰國椰糖 (炒糖色用)","en":"Thai Palm Sugar (For caramelization & gloss)","th":"น้ำตาลปี๊บ","ja":"パームシュガー","ko":"태국 팜슈가"},"amount":3,"unitMetric":"tbsp","unitUS":"3 tbsp","isKeyFlavor":true,"thaiName":"น้ำตาลปี๊บ","thaiPronunciation":"Nam Tan Peep"},{"id":"five-spice-blend","name":{"zh-TW":"香料組 (肉桂棒 2 根、八角 3 顆、花椒 1 小匙)","en":"Aromatics (2 Cinnamon sticks, 3 Star Anise, 1 tsp Sichuan pepper)","th":"อบเชย โป๊ยกั๊ก","ja":"シナモンスティック2本・スターアニス3個","ko":"계피 스틱 2개, 팔각 3개"},"amount":1,"unitMetric":"packet","unitUS":"packet","isKeyFlavor":true,"thaiName":"เครื่องพะโล้","thaiPronunciation":"Khrueang Pa-Lo"},{"id":"coriander-garlic-paste","name":{"zh-TW":"香菜根 4 根 + 大蒜 8 瓣 + 白胡椒粒 1 大匙 (搗碎)","en":"Cilantro roots, 8 garlic cloves, 1 tbsp white peppercorns (pounded)","th":"สามเกลอตำละเอียด","ja":"パクチーの根、ニンニク、白胡椒のペースト","ko":"고수 뿌리, 마늘, 백후추 빻은 것"},"amount":2,"unitMetric":"tbsp","unitUS":"2 tbsp","isKeyFlavor":true,"thaiName":"สามเกลอ","thaiPronunciation":"Sam Gler"},{"id":"dark-sweet-soy","name":{"zh-TW":"泰國黑甜醬油","en":"Thai Dark Sweet Soy Sauce","th":"ซีอิ๊วดำหวาน","ja":"タイ産ダークスイートソイソース","ko":"태국 다크 스위트 간장"},"amount":3,"unitMetric":"tbsp","unitUS":"3 tbsp","thaiName":"ซีอิ๊วดำ","thaiPronunciation":"See Ew Dum"},{"id":"light-soy-sauce","name":{"zh-TW":"生抽薄鹽醬油","en":"Thin Light Soy Sauce","th":"ซีอิ๊วขาว","ja":"薄口醤油","ko":"양조간장"},"amount":3,"unitMetric":"tbsp","unitUS":"3 tbsp","thaiName":"ซีอิ๊วขาว","thaiPronunciation":"See Ew Khao"},{"id":"hard-boiled-eggs","name":{"zh-TW":"水煮蛋 (去殼同滷)","en":"Hard-Boiled Eggs (Peeled, simmered in broth)","th":"ไข่ต้มปอกเปลือก","ja":"ゆで卵（殻をむいて一緒に煮込む）","ko":"삶은 달걀 (껍질 벗겨 함께 졸이기)"},"amount":4,"unitMetric":"piece","unitUS":"piece","thaiName":"ไข่ต้ม","thaiPronunciation":"Khai Tom"},{"id":"pickled-greens","name":{"zh-TW":"泰式酸菜 (切段汆燙)","en":"Pickled Mustard Greens (Rinsed & blanched)","th":"ผักกาดดองต้ม","ja":"高菜漬け（塩抜きして茹でる）","ko":"태국식 갓절임"},"amount":120,"unitMetric":"g","unitUS":"4.2 oz","isKeyFlavor":true,"thaiName":"ผักกาดดอง","thaiPronunciation":"Phak Kat Dong"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"焦糖化椰糖，爆香五香香料","en":"Caramelize Palm Sugar & Toast Whole Spices","th":"เคี่ยวน้ำตาลปี๊บจนเป็นคาราเมล ผัดเครื่องพะโล้","ja":"パームシュガーをキャラメリゼしスパイスを炒める","ko":"팜슈가를 캐러멜화하고 향신료 볶기"},"instruction":{"zh-TW":"厚底燉鍋下 1 大匙油與 3 大匙椰糖，中小火慢熬至椰糖融化起微泡、呈現琥珀焦糖色。加入肉桂棒、八角與搗好的香菜根蒜泥，爆炒 1 分鐘釋放醇厚香氣。","en":"In a heavy pot, heat 1 tbsp oil with 3 tbsp palm sugar over medium-low heat until melted into a bubbling, amber caramel. Add cinnamon, star anise, and pounded garlic-cilantro paste, stir-frying for 1 minute until fragrant.","th":"ตั้งหม้อใส่น้ำมันและน้ำตาลปี๊บ เคี่ยวไฟอ่อนจนเป็นคาราเมลสีอำพัน ใส่โป๊ยกั๊ก อบเชย และสามเกลอลงผัดจนหอมฟุ้ง","ja":"厚手鍋に油大さじ1とパームシュガー大さじ3を入れ、弱火で琥珀色のキャラメル状になるまで熱します。八角、シナモン、香味ペーストを加えて1分炒めます。","ko":"냄비에 기름과 팜슈가를 넣고 약불에서 거품이 일며 캐러멜색이 될 때까지 녹입니다. 팔각, 계피, 빻은 마늘 고수 페이스트를 넣고 1분간 볶아줍니다."},"durationSeconds":180,"image":"/images/th/khao-kha-moo-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"豬腳上色煎皮，倒入醬油與高湯","en":"Brown Pork Skin & Add Broth with Soy Sauces","th":"ผัดขาหมูให้ตึง เติมน้ำและซีอิ๊ว","ja":"豚足の皮目を焼き付け、スープと醤油を注ぐ","ko":"족발 껍질을 지져 색을 입히고 육수 붓기"},"instruction":{"zh-TW":"放入川燙洗淨的豬腳塊翻炒 3 分鐘，讓琥珀焦糖均勻裹在豬皮上。倒入黑甜醬油、生抽與 1200ml 水（淹沒豬肉）。大火煮沸後撇清浮沫。","en":"Add parboiled pork hock chunks, searing for 3 mins so the caramel coats the skin. Add dark sweet soy, light soy, and 1200ml water to submerge meat. Bring to rolling boil, skimming surface.","th":"ใส่ขาหมูลงผัดให้เคลือบสีคาราเมล เติมซีอิ๊วดำ ซีอิ๊วขาว และน้ำ 1.2 ลิตร ต้มจนเดือดช้อนฟองออก","ja":"下茹でした豚足を加え、皮にキャラメル色がつくまで3分炒めます。ダークソイ、薄口醤油、水1200mlを加え、沸騰したらアクを取ります。","ko":"데쳐낸 족발을 넣고 3분간 볶아 캐러멜 색을 입힙니다. 다크 간장, 양조간장과 물 1200ml를 붓고 끓으면 거품을 걷어냅니다."},"durationSeconds":240,"image":"/images/th/khao-kha-moo-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"慢火煨燉至軟爛，加入水煮蛋浸滷","en":"Simmer Low & Slow; Steep Hard-Boiled Eggs","th":"ตุ๋นไฟอ่อน 90 นาที ใส่ไข่ต้ม","ja":"弱火で90分煮込み、ゆで卵を加えて味を染み込ませる","ko":"약불에서 90분간 뭉근히 조리고 삶은 달걀 넣기"},"instruction":{"zh-TW":"轉微火加蓋慢燉 90 分鐘（壓力鍋只需 35 分鐘）。倒數 20 分鐘時放入水煮蛋一同浸泡入味。燉至筷子能輕易穿透豬皮、膠原蛋白完全融化成滑潤湯汁。","en":"Cover and simmer on low for 90 mins (or 35 mins in Instant Pot). Add peeled hard-boiled eggs in the final 20 mins. The pork is done when a chopstick glides through with zero resistance.","th":"ปิดฝาตุ๋นไฟอ่อน 90 นาที (หรือ 35 นาทีในหม้อแรงดัน) ใส่ไข่ต้มในช่วง 20 นาทีสุดท้าย ตุ๋นจนเนื้อเปื่อยนุ่ม","ja":"蓋をして極弱火で90分（圧力鍋なら35分）煮込みます。残り20分でゆで卵を投入。箸がスッと通る柔らかさになれば完成です。","ko":"뚜껑을 덮고 약불에서 90분간(압력솥은 35분) 푹 익힙니다. 마지막 20분에 삶은 달걀을 넣어 함께 졸입니다. 젓가락이 쑥 들어갈 정도로 부드러워집니다."},"durationSeconds":5400,"image":"/images/th/khao-kha-moo-step3.jpg","cookwareVariations":[{"cookware":"instantPot","tempAndSetting":"Manual High Pressure 35 mins + Natural Release","instructionOverride":{"zh-TW":"使用壓力鍋/萬用鍋『Meat/Stew』高壓模式設定 35 分鐘，結束後自然洩壓 15 分鐘，豬皮即可達到入口即化的最高境界！","en":"Pressure cook on High for 35 mins, followed by 15 mins natural release. Achieves sublime melt-in-the-mouth texture in record time!","th":"ใช้หม้ออัดแรงดันระบบ High 35 นาที ปล่อยแรงดันธรรมชาติ 15 นาที ขาหมูจะนุ่มละลายในปาก","ja":"電気圧力鍋の『高圧』で35分加熱し、15分自然減圧。驚くほど短時間でトロトロに仕上がります！","ko":"압력솥 고압 35분 조리 후 15분간 자연 김빼기를 합니다. 짧은 시간에 완벽한 젤라틴 식감이 완성됩니다!"}}]},{"stepNumber":4,"title":{"zh-TW":"刀削軟嫩豬肉，澆淋老滷金汁盛盤","en":"Carve Pork Leg, Ladle Master Broth Over Rice","th":"หั่นเนื้อหนังขาหมู ตักราดข้าวสวยร้อนๆ","ja":"肉と皮を削ぎ切りにし、熱々ご飯に煮汁ごとかける","ko":"야들야들한 족발 썰어 밥 위에 얹고 육수 끼얹기"},"instruction":{"zh-TW":"熱騰騰茉莉香米盛入盤中。撈出肥美豬腳，用菜刀俐落切成厚片鋪在米飯上。切半個滷至深褐色的雞蛋，配上酸菜。舀上 2 大勺濃稠甘醇的五香滷汁澆在肉與米飯上，配特製生辣椒醋即可享用！","en":"Mound warm jasmine rice onto a plate. Slice the gelatinous pork and arrange over rice alongside half a spiced egg and pickled greens. Ladle generous spoons of warm master stock over everything. Serve with garlic chili vinegar.","th":"ตักข้าวสวยใส่จาน สับเนื้อและหนังขาหมูวางเคียง ผ่าไข่พะโล้ วางผักกาดดอง ราดน้ำพะโล้เข้มข้นฉ่ำๆ เสิร์ฟพร้อมน้ำส้มพริกดอง","ja":"ジャスミンライスの器に、トロトロの肉と皮を切り分けてのせます。煮卵と高菜を添え、熱々の秘伝ダレをたっぷり回しかけます。ニンニク唐辛子酢を添えて完成！","ko":"밥 위에 족발 고기와 껍질을 도톰하게 썰어 올립니다. 반 자른 계란과 갓절임을 곁들이고 진한 조림 육수를 듬뿍 뿌린 뒤, 마늘 고추식초를 곁들여 냅니다."},"durationSeconds":60,"image":"/images/th/khao-kha-moo-step4.jpg"}],"troubleshooting":[{"id":"khao-kha-moo-greasy","problem":{"zh-TW":"滷肉吃起來太油膩、缺乏解膩清爽感","en":"Dish feels excessively fatty and cloying on the palate","th":"ขาหมูเลี่ยนเกินไป น้ำพะโล้มันย่อง","ja":"脂っこすぎて途中で箸が止まってしまう","ko":"족발이 너무 기름지고 느끼해요"},"cause":{"zh-TW":"未撇除湯面多餘豬油，或缺少了泰國特製辣椒醋（Prik Nam Som）與酸菜的中和。","en":"Surface fat was not skimmed, or omitted the crucial bird's eye chili vinegar sauce.","th":"ไม่ได้ช้อนน้ำมันส่วนเกินออก หรือไม่ได้ทานคู่กับพริกน้ำส้ม","ja":"浮き油を取り除いていないか、唐辛子酢（プリック・ナムソム）を添えていないため。","ko":"기름기를 걷어내지 않았거나 산뜻한 고추식초 소스를 곁들이지 않았습니다."},"solution":{"zh-TW":"出鍋前撇除頂層浮油。食用時務必淋上由蒜頭、朝天椒與白醋調製的靈魂辣椒醋，果醋酸能瞬間溶解油膩，轉化為無上甘甜！","en":"Skim surface fat. Always serve with a condiment made of minced garlic, fresh chilies, and white vinegar to cut right through the gelatin.","th":"ช้อนน้ำมันออกก่อนเสิร์ฟ และราดพริกน้ำส้มสูตรกระเทียมสับเพื่อตัดเลี่ยนทันที","ja":"表面の余分な油をすくい取り、ニンニクと唐辛子を漬け込んだお酢をかけて召し上がってください。酸味が油を中和し劇的においしくなります。","ko":"완성 전 냄비 표면의 기름을 걷어내고, 식초에 마늘과 쥐똥고추를 넣은 소스를 꼭 뿌려 드세요."}}],"proTips":[{"zh-TW":"曼谷米其林老店秘密：慢燉時放入一片洗淨的新鮮甘蔗節或半瓶黑麥啤酒，甘蔗的天然果糖會使肉皮極致油亮、軟爛如布丁！","en":"Michelin stall trade secret: Toss a split stalk of fresh sugarcane or half a bottle of dark malt stout into the braise. Natural plant sugars produce an astonishing lacquered sheen and pudding-like tenderness!","th":"เคล็ดลับร้านเจริญแสง: ใส่อ้อยสดท่อนทุบลงไปต้มด้วย น้ำตาลอ้อยธรรมชาติจะทำให้หนังขาหมูมันวาวและนุ่มละมุนลิ้น","ja":"名店の隠し味：煮込み時に生のサトウキビ（または黒ビール少量）を加えると、自然な糖分で皮の照りが格段に増し、プリンのようにとろける仕上がりになります！","ko":"미슐랭 명점의 비법: 끓일 때 사탕수수 토막(또는 흑맥주 약간)을 넣어주면 천연 당분이 껍질을 보석처럼 윤기 나게 하고 푸딩처럼 부드럽게 만들어 줍니다!"}]},{"country":"th","id":"gaeng-keow-wan-gai","slug":"gaeng-keow-wan-gai","title":{"zh-TW":"曼谷名廚 正宗泰式椰香綠咖哩雞","en":"Authentic Bangkok Thai Green Curry with Chicken (Gaeng Keow Wan)","th":"แกงเขียวหวานไก่กะทิสดมะเขือเปราะ","ja":"ゲーン・キョワーン・ガイ（本場タイ風チキンと丸ナスのグリーンカレー）","ko":"방콕 정통 치킨 그린 카레 (깽 키여우 완 까이)"},"subtitle":{"zh-TW":"青辣椒翡翠天然香氣・炒破椰漿融匯綠醬・泰國圓茄水靈甘甜與九層塔","en":"Vibrant Emerald Green Curry Simmered in Cracked Coconut Cream with Thai Eggplants & Sweet Basil","th":"พริกขี้หนูเขียวสดผัดแตกมันหัวกะทิ มะเขือเปราะกรอบหวาน ใบโหระพาหอมฟุ้ง","ja":"青唐辛子の爽快な辛味とハーブの芳香。ココナッツオイルで炒め上げる翡翠色の宮廷名作","ko":"청양 풋고추의 청량한 매운맛, 코코넛 크림의 부드러움, 타이 바질과 동글이 가지의 하모니"},"tagline":{"zh-TW":"泰國皇家代表性咖哩，辛辣與甘醇在椰奶中達致神聖平衡","en":"The quintessential royal Thai curry striking divine harmony between fiery green chili heat and sweet coconut cream","th":"ราชาแห่งแกงไทย รสชาติหวานมันเค็มเผ็ดละมุน กลมกล่อมลงตัว","ja":"タイカレーの頂点に君臨する国民食。ピリッとした辛さとココナッツの甘みが織りなす極上のシンフォニー","ko":"매콤함과 코코넛의 부드러움이 완벽한 균형을 이루는 태국 왕실 카레의 결정체"},"heroImage":"/images/th/green-curry.jpg","difficulty":"easy","prepTimeMinutes":15,"cookTimeMinutes":20,"defaultServings":4,"caloriesPerServing":480,"category":"soups","dietaryTags":["classic","halal","glutenFree"],"supportedCookware":["traditional","instantPot"],"culture":{"originRegion":{"zh-TW":"中部・曼谷宮廷","en":"Central / Bangkok Royal Court","th":"ภาคกลาง / กรุงเทพมหานคร","ja":"中部・バンコク宮廷料理","ko":"방콕 왕실 궁중 요리"},"famousStreetMarkets":[{"zh-TW":"水門夜市咖哩老街","en":"Pratunam Market Curry Stalls","th":"ประตูน้ำ","ja":"プラトゥーナム市場 カレー屋台","ko":"프라투남 시장"},{"zh-TW":"安帕瓦週末市集","en":"Amphawa Food Trail","th":"อัมพวา","ja":"アンパワー市場","ko":"암파와 시장"}],"historyStory":{"zh-TW":"「Gaeng」是咖哩，「Keow」是綠色，「Wan」字面上是甜，但實指「柔和淡雅的翠綠色澤」（甜美綠）。綠咖哩由拉瑪六世皇室宮廷主廚於 1908 年首創，創新地以青朝天椒代替紅辣椒，加入青檸檬皮、香茅與新鮮椰奶。其美麗如翡翠般的色澤與辣中帶甘的味覺層次，使其迅速從宮廷膳房風靡至民間市井。","en":"'Gaeng' means curry, 'Keow' means green, and 'Wan' means sweet—referring specifically to its delicate, creamy pastel green hue rather than sugary taste. Originating in the royal kitchens of King Rama VI around 1908, palace chefs ingeniously substituted red chilies with fresh green bird's eye chilies and makrut lime zest, crafting a milder, herbaceous curry that captivated the world.","th":"แกงเขียวหวานถือกำเนิดขึ้นในรัชสมัยรัชกาลที่ 6 คำว่า 'หวาน' หมายถึงสีเขียวหวานละมุนตาจากพริกขี้หนูเขียวสด มิใช่รสชาติหวานจัด ผสานสมุนไพรไทยและกะทิสดจนเป็นเอกลักษณ์","ja":"1908年頃、ラーマ6世の宮廷で考案されたのが始まり。「キョワーン」は直訳すると『甘い緑』ですが、味の甘さではなくパステル調の淡い美しいエメラルドグリーン色を指します。赤唐辛子の代わりに生の青唐辛子を使うことで、フレッシュで突き抜ける香りを実現しました。","ko":"1908년 라마 6세 시대 왕실 주방에서 탄생했습니다. '완'은 달콤하다는 뜻도 있지만 여기서는 '은은하고 고운 연초록빛'을 의미합니다. 붉은 고추 대신 신선한 청양 풋고추와 라임 제스트를 넣어 상쾌한 매운맛을 완성했습니다."},"thaiScript":"แกงเขียวหวานไก่","thaiPhonetics":"Gaeng Keow Wan Gai","audioPronunciationText":"ขอแกงเขียวหวานไก่หนึ่งถ้วย ข้าวสวยสองจานครับ","nativeName":"แกงเขียวหวานไก่"},"ingredients":[{"id":"chicken-thigh","name":{"zh-TW":"去骨去皮雞腿肉 (切適口塊)","en":"Boneless Skinless Chicken Thigh (Bite-sized pieces)","th":"เนื้อสะโพกไก่หั่นชิ้น","ja":"鶏もも肉（一口大）","ko":"닭다리살(정육) (한 입 크기)"},"amount":400,"unitMetric":"g","unitUS":"14 oz","isKeyFlavor":true,"thaiName":"เนื้อไก่","thaiPronunciation":"Nuea Gai"},{"id":"green-curry-paste","name":{"zh-TW":"泰國道地綠咖哩醬 (Mae Ploy 或 Aroy-D)","en":"Authentic Thai Green Curry Paste","th":"พริกแกงเขียวหวาน","ja":"タイ産グリーンカレーペースト","ko":"태국 그린 카레 페이스트"},"amount":3,"unitMetric":"tbsp","unitUS":"3 tbsp","isKeyFlavor":true,"thaiName":"พริกแกงเขียวหวาน","thaiPronunciation":"Prik Gaeng Keow Wan"},{"id":"coconut-cream","name":{"zh-TW":"濃純生榨椰漿 (分為炒醬與煮湯兩部分)","en":"Thick Coconut Cream (Divided: for cracking oil & soup body)","th":"หัวกะทิแท้ 100%","ja":"濃厚ココナッツクリーム","ko":"진한 코코넛 크림"},"amount":400,"unitMetric":"ml","unitUS":"13.5 fl oz","isKeyFlavor":true,"thaiName":"หัวกะทิ","thaiPronunciation":"Hua Ka-Thi"},{"id":"thai-green-eggplant","name":{"zh-TW":"泰國綠圓茄 (切四瓣，泡鹽水防變黑)","en":"Thai Round Green Eggplants (Quartered, kept in salted water)","th":"มะเขือเปราะแช่น้ำเกลือ","ja":"タイ丸ナス（4等分・塩水につけて変色防止）","ko":"태국 둥근 가지 (4등분, 갈변 방지용 소금물에 담금)"},"amount":4,"unitMetric":"piece","unitUS":"piece","isKeyFlavor":true,"thaiName":"มะเขือเปราะ","thaiPronunciation":"Makhuea Pro","substitute":{"substituteName":{"zh-TW":"日本圓茄、櫛瓜或青椒塊","en":"Zucchini, Japanese round eggplant or bell pepper chunks","th":"มะเขือยาวหรือซูกินี","ja":"ズッキーニまたは米ナス","ko":"쥬키니 호박 또는 일반 가지 깍둑썬 것"},"ratio":"1:1","explanation":{"zh-TW":"泰國綠圓茄口感爽脆帶甜。櫛瓜煮在咖哩中口感極為相近。","en":"Thai eggplants provide crunchy sweetness. Zucchini or Japanese eggplant work great.","th":"ใช้ซูกินีแทนได้ รสสัมผัสหวานฉ่ำ","ja":"ズッキーニを使うと煮崩れせず、本場に近いみずみずしい食感が楽しめます","ko":"태국 가지는 아삭하고 달콤합니다. 주키니 호박으로 대체하면 식감이 매우 비슷합니다."},"whereToBuy":{"zh-TW":"東南亞雜貨生鮮店","en":"Asian/Thai produce market","th":"ตลาดสด","ja":"アジア青果店","ko":"아시안 식료품점"}}},{"id":"kaffir-lime-leaves","name":{"zh-TW":"檸檬葉 (去中梗撕碎)","en":"Kaffir / Makrut Lime Leaves (Torn)","th":"ใบมะกรูดฉีก","ja":"コブミカンの葉（ちぎる）","ko":"카피르 라임 잎"},"amount":5,"unitMetric":"leaf","unitUS":"leaf","thaiName":"ใบมะกรูด","thaiPronunciation":"Bai Ma-Krut"},{"id":"thai-sweet-basil","name":{"zh-TW":"九層塔 / 甜羅勒 (Bai Horapha - 起鍋靈魂)","en":"Thai Sweet Basil (Bai Horapha - Added right at the end)","th":"ใบโหระพาสด","ja":"タイスイートバジル（ホーラパー）","ko":"타이 스위트 바질 (호라파)"},"amount":30,"unitMetric":"g","unitUS":"1 oz","isKeyFlavor":true,"thaiName":"ใบโหระพา","thaiPronunciation":"Bai Horapha"},{"id":"fish-sauce","name":{"zh-TW":"頂級純魚露","en":"Premium Fish Sauce","th":"น้ำปลาแท้","ja":"高級ナンプラー","ko":"피시소스"},"amount":2.5,"unitMetric":"tbsp","unitUS":"2.5 tbsp","thaiName":"น้ำปลา","thaiPronunciation":"Nam Pla"},{"id":"palm-sugar","name":{"zh-TW":"泰國椰糖","en":"Thai Palm Sugar","th":"น้ำตาลปี๊บ","ja":"パームシュガー","ko":"팜슈가"},"amount":1.5,"unitMetric":"tbsp","unitUS":"1.5 tbsp","thaiName":"น้ำตาลปี๊บ","thaiPronunciation":"Nam Tan Peep"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"炒破椰漿 (Crack the Coconut Milk) 炒香翡翠綠醬","en":"Crack the Coconut Cream & Fry the Green Paste","th":"เคี่ยวหัวกะทิให้แตกมัน ผัดพริกแกงเขียวหวาน","ja":"ココナッツミルクの油分を分離させ、ペーストを炒める","ko":"코코넛 크림 기름 분리(크래킹) 후 그린 페이스트 볶기"},"instruction":{"zh-TW":"深鍋中倒入 150ml 濃椰漿，中小火慢煮 3-4 分鐘，直到水分蒸發、表面析出一層清澈天然的天然綠色椰子油。放入 3 大匙綠咖哩醬，在熱椰油中慢火翻炒 2 分鐘，直至香料與油脂完全融為一體，散發清爽辛香與翡翠光澤。","en":"Pour 150ml coconut cream into a pot. Simmer gently over medium heat for 3-4 minutes until water evaporates and clear coconut oil separates on the surface. Add green curry paste and fry in the oil for 2 minutes until glossy, fragrant, and vibrant emerald.","th":"ใส่หัวกะทิ 150 มล. เคี่ยวไฟกลางจนแตกมันลอยหน้า ใส่พริกแกงเขียวหวานลงผัด 2 นาทีจนหอมฟุ้งและขึ้นสีเขียวเงาสวย","ja":"鍋にココナッツクリーム150mlを入れ、中弱火で3〜4分煮詰めてオイルを分離させます。ペーストを加え、オイルの中で2分じっくり炒めて香りとエメラルドの輝きを引き出します。","ko":"냄비에 코코넛 크림 150ml를 붓고 중약불에서 3~4분간 끓여 맑은 코코넛 오일이 분리될 때까지 졸입니다. 그린 카레 페이스트를 넣고 2분간 볶아 영롱한 초록빛 기름을 만듭니다."},"durationSeconds":240,"image":"/images/th/green-curry-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"下雞腿肉翻炒裹醬，注入其餘椰奶與水","en":"Sear Chicken Thighs & Add Remaining Coconut Milk","th":"ใส่เนื้อไก่ลงผัด เติมกะทิและน้ำ","ja":"鶏肉を絡め炒め、残りのココナッツミルクと水を注ぐ","ko":"닭고기 넣어 양념 입히고 남은 코코넛밀크와 물 붓기"},"instruction":{"zh-TW":"放入雞腿塊翻炒 2 分鐘至表面斷生裹滿綠醬。倒入剩餘的 250ml 椰漿與 150ml 清水（或高湯）。大火煮滾後轉中小火，放入撕碎的檸檬葉，煨煮 5 分鐘讓雞肉熟透柔嫩。","en":"Add chicken thigh pieces, tossing for 2 minutes until opaque and well coated. Pour in remaining 250ml coconut cream and 150ml water (or broth). Bring to a boil, toss in torn kaffir lime leaves, and simmer for 5 minutes.","th":"ใส่เนื้อไก่ลงผัดให้สุก เติมกะทิที่เหลือและน้ำ 150 มล. ต้มจนเดือด ใส่ใบมะกรูดฉีก ต้มไฟกลาง 5 นาที","ja":"鶏もも肉を投入し2分炒め合わせます。残りのココナッツミルク250mlと水150mlを加えます。沸騰したらちぎったコブミカンの葉を入れ、中火で5分煮ます。","ko":"닭다리살을 넣고 2분간 볶아 양념을 고루 입힙니다. 남은 코코넛 크림 250ml와 물 150ml를 붓습니다. 끓어오르면 라임 잎을 찢어 넣고 중불에서 5분간 끓입니다."},"durationSeconds":300,"image":"/images/th/green-curry-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"投入泰國圓茄，調入魚露與椰糖","en":"Add Thai Eggplants & Season with Fish Sauce and Palm Sugar","th":"ใส่มะเขือเปราะ ปรุงรสน้ำปลาและน้ำตาลปี๊บ","ja":"タイ丸ナスを加え、ナンプラーとパームシュガーで調味","ko":"둥근 가지 넣고 피시소스와 팜슈가로 간하기"},"instruction":{"zh-TW":"放入切瓣的泰國綠圓茄（浸入湯汁中防止氧化）。調入 2.5 大匙魚露與 1.5 大匙椰糖。繼續滾煮 3-4 分鐘至茄子變軟熟透但仍保有些許爽脆口感。","en":"Drop in quartered Thai eggplants, pressing them beneath the liquid. Season with 2.5 tbsp fish sauce and 1.5 tbsp palm sugar. Simmer for 3-4 minutes until eggplants soften to tender perfection.","th":"ใส่มะเขือเปราะ กดให้จมน้ำแกง ปรุงด้วยน้ำปลาและน้ำตาลปี๊บ ต้มต่อ 3-4 นาทีจนมะเขือสุกนุ่มแต่ยังกรอบหวาน","ja":"切った丸ナスをスープに沈めながら加えます。ナンプラー大さじ2.5、パームシュガー大さじ1.5で味を調え、ナスが柔らかくなるまで3〜4分煮ます。","ko":"둥근 가지를 국물에 푹 잠기게 넣습니다. 피시소스 2.5큰술, 팜슈가 1.5큰술을 넣고 가지가 부드러워질 때까지 3~4분간 끓입니다."},"durationSeconds":240,"image":"/images/th/green-curry-step3.jpg"},{"stepNumber":4,"title":{"zh-TW":"大量投入九層塔與紅椒絲，立刻熄火出鍋","en":"Fold in Heaps of Thai Sweet Basil & Kill Heat","th":"ใส่ใบโหระพาและพริกชี้ฟ้าแดง ดับไฟทันที","ja":"大量のタイバジルと赤唐辛子を入れ、即座に火を止める","ko":"타이 바질 듬뿍 넣고 즉시 불 끄기"},"instruction":{"zh-TW":"倒入整把新鮮九層塔嫩葉與斜切紅辣椒條。用湯勺輕輕壓入滾燙咖哩汁中浸泡 10 秒，待香氣爆發、葉片剛剛變軟翠綠時，【立即關火】！切勿久煮否則九層塔變黑變苦。趁熱盛碗，配熱茉莉香米或泰式米線（Khanom Jeen）享用！","en":"Add fresh Thai sweet basil leaves and red chili strips. Submerge into the hot curry for 10 seconds. The instant the floral aroma blooms, IMMEDIATELY KILL THE HEAT! Overcooking darkens basil and ruins its perfume. Serve piping hot with jasmine rice or rice noodles!","th":"ใส่ใบโหระพาและพริกแดง คนให้จมน้ำแกง 10 วินาทีจนส่งกลิ่นหอม แล้วรีบดับไฟทันที ตักใส่ชาม เสิร์ฟพร้อมข้าวสวยร้อนๆ หรือขนมจีน","ja":"生のタイバジルと赤唐辛子の細切りを投入。スープに10秒沈めてアロマを解き放ったら【即座に火を止めます】！煮込みすぎるとバジルが黒ずみ香りが飛びます。アツアツをご飯にかけて召し上がれ！","ko":"타이 바질 잎과 홍고추 채를 듬뿍 넣습니다. 국물에 10초간 담가 향이 확 피어오르면 【즉시 가스불을 끕니다】! 오래 끓이면 바질이 까맣게 변하고 쓴맛이 납니다. 밥 위에 얹어 맛있게 드세요!"},"durationSeconds":20,"image":"/images/th/green-curry-step4.jpg"}],"troubleshooting":[{"id":"green-curry-discolored","problem":{"zh-TW":"綠咖哩顏色發灰變暗，看起來沒有翠綠食慾","en":"Curry turned dull brownish-grey instead of vibrant pastel green","th":"สีแกงเขียวหวานคล้ำ ดำ ไม่น่ารับประทาน","ja":"カレーの色がくすんで茶色っぽくなってしまった","ko":"카레 색깔이 칙칙한 갈색으로 변했어요"},"cause":{"zh-TW":"1. 九層塔放入後繼續大滾狂煮；2. 泰國圓茄切開後未泡鹽水而氧化發黑；3. 咖哩醬本身受潮變質。","en":"1. Basil leaves were boiled too long; 2. Eggplants oxidized in air before simmering; 3. Overheated the paste.","th":"ต้มใบโหระพานานเกินไป หรือไม่ได้แช่มะเขือในน้ำเกลือ","ja":"1. バジルを入れてからグツグツ煮込みすぎた。2. ナスが空気に触れて酸化変色した。","ko":"1. 바질을 넣고 오래 끓였거나, 2. 자른 가지를 소금물에 담그지 않아 갈변했습니다."},"solution":{"zh-TW":"圓茄切開務必泡淡鹽水防黑。九層塔浸入熱湯 10 秒後必須「立即關火」，利用餘溫激發香氣同時鎖住翡翠綠！","en":"Keep cut eggplants submerged in salted water. Stir in basil and kill heat within 10 seconds to lock in bright green beauty.","th":"แช่มะเขือในน้ำเกลือเสมอ และดับไฟทันทีหลังใส่ใบโหระพา","ja":"ナスは塩水につけ、バジルを加えたら10秒で必ず火を消してください。余熱だけで火を通すのが鮮やかな緑を保つ鉄則です。","ko":"가지는 소금물에 담가두고, 바질을 넣자마자 10초 안에 불을 꺼야 영롱한 초록빛을 지킬 수 있습니다."}}],"proTips":[{"zh-TW":"曼谷米其林星級名廚秘笈：想要綠咖哩呈現如同翡翠般的鮮活綠色，可以在炒醬時加入 1 大匙用料理機打碎的新鮮菠菜葉或泰國九層塔綠泥！純天然葉綠素能讓湯頭色澤驚艷無比，口感更是清幽馥郁！","en":"Michelin chef color secret: For that breathtaking emerald jewel tone seen in fine dining, blend a small handful of fresh spinach or basil leaves with 2 tbsp coconut milk into a vivid green puree and stir it in at the finish!","th":"เคล็ดลับเชฟมิชลิน: หากต้องการสีเขียวมรกตสดใส ให้ปั่นใบโหระพาสดกับหัวกะทิเล็กน้อยแล้วหยอดลงในแกงตอนท้าย สีจะสวยสดและหอมฟุ้ง","ja":"ミシュランスターシェフの技：仕上げに、少量の生ほうれん草またはバジルをココナッツミルクとミキサーにかけた『天然クロロフィル緑液』を大さじ1加えると、息をのむほど美しい宝石のような翡翠色に仕上がります！","ko":"미슐랭 셰프의 비법: 서빙 직전 생 바질 잎 몇 장을 코코넛밀크 약간과 함께 믹서에 곱게 갈아 한 큰술 둘러보세요. 보석처럼 영롱한 천연 에메랄드빛 카레를 연출할 수 있습니다!"}]},{"country":"th","id":"khanom-krok","slug":"khanom-krok","title":{"zh-TW":"曼谷路邊攤 泰式椰香脆皮小圓煎餅 (Khanom Krok)","en":"Bangkok Street Crispy Coconut Rice Pancakes (Khanom Krok)","th":"ขนมครกโบราณแป้งกรอบหน้ากะทิเยิ้มหวานมัน","ja":"カノム・クロック（タイ風ココナッツ焼きカスタード団子）","ko":"방콕 길거리 코코넛 퐁당 팬케이크 (카놈 크록)"},"subtitle":{"zh-TW":"外殼金黃酥脆薄如瓷・中心椰漿如熔岩爆漿・甜玉米蔥花芋頭驚喜點綴","en":"Crisp Golden Outer Shell with Molten Sweet-Salty Coconut Cream Center","th":"เปลือกกรอบร่อน ไส้กะทิหวานมันเค็มเยิ้มละลาย โรยหน้าข้าวโพดหวานและต้นหอม","ja":"外側はパリッと軽快なクリスピーシェル、中は熱々とろけるココナッツカスタード","ko":"겉은 바삭바삭한 쌀 반죽, 속은 달콤 짭조름하게 주르륵 흘러내리는 코코넛 크림"},"tagline":{"zh-TW":"泰國街頭鑄鐵圓孔模具上的神話，剛出爐咬下小心爆漿燙口！","en":"The beloved street-cart delicacy cooked in cast-iron dimpled pans with molten coconut centers","th":"ขนมไทยโบราณในกระทะหลุม กรอบนอกนุ่มใน หวานมันเค็มครบรส","ja":"たこ焼き器のような窪み鍋で作られるタイ伝統の屋台スイーツ。一口噛めば熱々とろ〜り","ko":"태국 전통 무쇠 주물 틀에서 구워내는 겉바속촉 마성의 코코넛 디저트"},"heroImage":"/images/th/khanom-krok.jpg","difficulty":"medium","prepTimeMinutes":20,"cookTimeMinutes":15,"defaultServings":4,"caloriesPerServing":310,"category":"desserts","dietaryTags":["classic","vegan","glutenFree","halal"],"supportedCookware":["traditional"],"culture":{"originRegion":{"zh-TW":"中部・曼谷街頭","en":"Central / Bangkok Street Stalls","th":"ภาคกลาง / กรุงเทพมหานคร","ja":"中部・バンコク全土の屋台","ko":"방콕 길거리 노점"},"famousStreetMarkets":[{"zh-TW":"恰圖恰週末市集","en":"Chatuchak Weekend Market","th":"ตลาดนัดจตุจักร","ja":"チャトゥチャック市場","ko":"짜뚜짝 주말시장"},{"zh-TW":"安帕瓦水上市場","en":"Amphawa Food Carts","th":"อัมพวา","ja":"アンパワー市場","ko":"암파와 수상시장"}],"historyStory":{"zh-TW":"Khanom Krok 的歷史可追溯至大城王國時期（Ayutthaya）。泰國民間將米粉漿與新鮮熟飯攪打做成酥脆外殼，頂部澆淋特濃甜椰漿，放入特製的半球形多孔鑄鐵鍋慢烤。傳統吃法極其講究甜鹹平衡（甘甜椰霜配微鹹表皮），並搭配香甜玉米粒、芋頭丁甚至香蔥花，是泰國市井早市與夜市最溫暖迷人的童年回憶。","en":"Dating back over 400 years to the Ayutthaya Kingdom. Street cooks utilize a two-batter alchemy: a crisp bottom batter made from rice flour and cooked jasmine rice, crowned with a rich sweet-salty coconut custard. Poured into hot dimpled cast-iron pans, they emerge crisp on the edges with a velvety, molten center.","th":"ขนมครกมีประวัติยาวนานตั้งแต่สมัยอยุธยา โดยใช้กระทะดินเผาหรือกระทะเหล็กมีหลุม มีสองส่วนคือตัวแป้งกรอบด้านล่างและหน้ากะทิข้นหวานมันด้านบน โรยหน้าด้วยต้นหอมหรือข้าวโพด","ja":"アユタヤ王朝時代から伝わる伝統菓子。冷やご飯と米粉をブレンドした外側のパリパリ生地と、濃厚なココナッツミルクで作る内側のとろとろカスタードという二重構造。スイートコーンや刻みネギをトッピングするのが本場スタイルです。","ko":"400년 전 아유타야 왕조 시절부터 이어져 온 전통 간식입니다. 멥쌀가루로 만든 바삭한 겉껍질과 달콤 짭조름한 코코넛 크림 필링이 어우러져 타코야키 팬에 구워냅니다. 옥수수나 쪽파 토핑이 매력적입니다."},"thaiScript":"ขนมครก","thaiPhonetics":"Khanom Krok","audioPronunciationText":"ขอขนมครกหนึ่งกล่อง หน้าข้าวโพดกับต้นหอมครับ","nativeName":"ขนมครก"},"ingredients":[{"id":"rice-flour-batter","name":{"zh-TW":"粘米粉 / 在來米粉 (外殼用)","en":"Rice Flour (For crispy shell batter)","th":"แป้งข้าวเจ้า","ja":"上新粉（米粉・皮用）","ko":"멥쌀가루 (바삭한 껍질용)"},"amount":120,"unitMetric":"g","unitUS":"4.2 oz","isKeyFlavor":true,"thaiName":"แป้งข้าวเจ้า","thaiPronunciation":"Paeng Khao Chao"},{"id":"cooked-jasmine-rice","name":{"zh-TW":"煮熟的茉莉香米飯 (與水攪打，外殼柔韌秘密)","en":"Cooked Jasmine Rice (Blended with water for supple crispness)","th":"ข้าวสวยหอมมะลิสุก","ja":"炊いたご飯（米粉と一緒にミキサーにかけ、もっちり感を出す）","ko":"지은 밥 (믹서에 곱게 갈아 부드러운 바삭함 연출)"},"amount":50,"unitMetric":"g","unitUS":"1.8 oz","isKeyFlavor":true,"thaiName":"ข้าวสวย","thaiPronunciation":"Khao Suay"},{"id":"coconut-milk-batter","name":{"zh-TW":"椰奶 (外殼粉漿用)","en":"Coconut Milk (For bottom batter)","th":"กะทิผสมแป้ง","ja":"ココナッツミルク（皮生地用）","ko":"코코넛 밀크 (껍질 반죽용)"},"amount":200,"unitMetric":"ml","unitUS":"6.8 fl oz","thaiName":"กะทิตัวแป้ง","thaiPronunciation":"Ka-Thi Tua Paeng"},{"id":"coconut-cream-topping","name":{"zh-TW":"特濃純椰漿 (中心爆漿熔岩用)","en":"Thick Coconut Cream (For sweet molten filling)","th":"หัวกะทิแท้ทำหน้ากะทิ","ja":"濃厚ココナッツクリーム（とろとろカスタード用）","ko":"진한 코코넛 크림 (속 필링용)"},"amount":200,"unitMetric":"ml","unitUS":"6.8 fl oz","isKeyFlavor":true,"thaiName":"หัวกะทิหน้า","thaiPronunciation":"Hua Ka-Thi Na"},{"id":"granulated-sugar","name":{"zh-TW":"白砂糖 (熔岩調味)","en":"Granulated Sugar (For sweet filling)","th":"น้ำตาลทราย","ja":"砂糖","ko":"설탕"},"amount":50,"unitMetric":"g","unitUS":"1.8 oz","thaiName":"น้ำตาลทราย","thaiPronunciation":"Nam Tan Sai"},{"id":"sea-salt","name":{"zh-TW":"細海鹽 (微鹹甜鹹撞味關鍵)","en":"Fine Sea Salt","th":"เกลือป่น","ja":"天然海塩","ko":"천일염"},"amount":0.5,"unitMetric":"tsp","unitUS":"0.5 tsp","thaiName":"เกลือ","thaiPronunciation":"Khluea"},{"id":"sweet-corn-toppings","name":{"zh-TW":"熟甜玉米粒、蔥花或芋頭丁","en":"Sweet Corn Kernels, Chopped Scallions or Diced Taro","th":"ข้าวโพดหวานสุก ต้นหอมซอย เผือกหั่นเต๋า","ja":"スイートコーン、刻み小ネギ、角切りタロ芋","ko":"스위트콘, 다진 쪽파, 깍둑썬 타로토란"},"amount":3,"unitMetric":"tbsp","unitUS":"3 tbsp","isKeyFlavor":true,"thaiName":"เครื่องโรยหน้า","thaiPronunciation":"Khrueang Roi Na"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"攪打雙層粉漿 (脆殼底漿與甜椰熔岩頂漿)","en":"Blend Two Batters: Crispy Bottom & Sweet Custard Top","th":"ปั่นแป้งตัวขนมและผสมหน้ากะทิ","ja":"外側のパリパリ生地と内側の甘いカスタード液を作る","ko":"바삭한 겉 반죽과 달콤한 코코넛 필링액 만들기"},"instruction":{"zh-TW":"【外殼底漿】：果汁機中放入粘米粉 120g、熟飯 50g、椰奶 200ml 與 100ml 水，高速攪打成絲滑無顆粒米漿。\\n【甜椰頂漿】：小碗中將濃純椰漿 200ml、白糖 50g 與 1/2 茶匙海鹽攪勻至糖完全融化。","en":"[Bottom Shell Batter]: In a blender, combine 120g rice flour, 50g cooked rice, 200ml coconut milk, and 100ml water until silkily smooth. [Molten Custard Topping]: In a bowl, whisk 200ml thick coconut cream with 50g sugar and 1/2 tsp sea salt until dissolved.","th":"ปั่นแป้งข้าวเจ้า ข้าวสวย กะทิ 200 มล. และน้ำเปล่าจนเนียนละเอียด ส่วนหน้ากะทิผสมหัวกะทิ 200 มล. กับน้ำตาลและเกลือคนให้ละลาย","ja":"【外側の生地】：ミキサーに上新粉120g、炊いたご飯50g、ココナッツミルク200ml、水100mlを入れ滑らかに撹拌します。【内側のカスタード】：ボウルに濃厚ココナッツクリーム200ml、砂糖50g、塩小さじ1/2をよく混ぜ合わせます。","ko":"【겉 껍질 반죽】: 믹서에 멥쌀가루 120g, 밥 50g, 코코넛밀크 200ml, 물 100ml를 넣고 곱게 갭니다. 【속 코코넛 필링】: 볼에 코코넛 크림 200ml, 설탕 50g, 소금 1/2작은술을 넣고 잘 녹입니다."},"durationSeconds":180,"image":"/images/th/khanom-krok-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"熱模刷薄油，注入外殼底漿","en":"Heat Dimpled Pan, Brush Oil & Pour Shell Batter","th":"ทาเนยในกระทะหลุม หยอดแป้งตัวขนม","ja":"たこ焼き器（窪み鍋）を熱し、外側の生地を注ぐ","ko":"타코야키 팬에 기름 두르고 겉 반죽 붓기"},"instruction":{"zh-TW":"使用泰式專用圓孔烤盤或章魚燒煎烤盤，中火預熱，用刷子給每個圓孔刷上一層薄油。用小茶壺或湯匙舀入外殼底漿，填滿每個圓孔約 7 分滿，此時會聽到滋滋聲。","en":"Heat a Thai dimpled pan or takoyaki pan over medium heat. Brush each hollow cavity lightly with oil. Pour the crispy bottom batter into each hole until roughly 70% full, sizzling enthusiastically.","th":"ตั้งกระทะหลุมไฟกลาง ทาน้ำมันบางๆ หยอดแป้งตัวลงในหลุมประมาณ 3 ใน 4 ของหลุม","ja":"たこ焼き器またはタイの窪み鍋を中火で熱し、各穴に油を薄く塗ります。外側の生地を各穴の7分目まで流し入れます。","ko":"타코야키 팬을 중불로 달구고 각 구멍에 오일을 얇게 바릅니다. 겉 반죽을 구멍의 70% 높이까지 지글지글 붓습니다."},"durationSeconds":60,"image":"/images/th/khanom-krok-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"迅速澆入甜椰熔岩頂漿，撒上豐富配料","en":"Spoon Molten Coconut Custard on Top & Add Toppings","th":"หยอดหน้ากะทิลงตรงกลาง โรยข้าวโพดและต้นหอม","ja":"中心に濃厚カスタードを重ね、トッピングを散らす","ko":"가운데에 달콤한 코코넛 필링을 채우고 토핑 얹기"},"instruction":{"zh-TW":"在外殼粉漿剛開始在邊緣定型時（約 15 秒內），立即在每個孔的中心舀入 1 大匙甜椰頂漿填至 9 分滿。隨即在頂端撒上一小撮甜玉米粒、鮮翠蔥花或芋頭丁。","en":"As soon as the outer edges begin setting (within 15 seconds), immediately ladle 1 tbsp of the sweet coconut custard directly into the center, filling to 90%. Scatter sweet corn, chopped scallions, or diced taro on top.","th":"พอขอบแป้งเริ่มเซ็ตตัว รีบหยอดหน้ากะทิตามลงไปตรงกลาง โรยด้วยข้าวโพด ต้นหอม หรือเผือก","ja":"外側の生地が固まり始めたらすぐに、中央に甘いカスタード液を大さじ1ずつ流し入れます。スイートコーン、小ネギ、タロ芋をトッピングします。","ko":"가장자리가 익기 시작하면 즉시 가운데에 달콤한 코코넛 필링을 1큰술씩 채웁니다. 그 위에 옥수수, 쪽파, 타로토란을 취향껏 얹습니다."},"durationSeconds":60,"image":"/images/th/khanom-krok-step3.jpg"},{"stepNumber":4,"title":{"zh-TW":"加蓋燜烤 5-6 分鐘，外酥內融","en":"Cover & Steam-Crisp for 5-6 Minutes","th":"ปิดฝาอบ 5-6 นาทีจนขอบกรอบร่อน","ja":"蓋をして蒸し焼きにし、外カリ中トロに仕上げる","ko":"뚜껑 덮고 5~6분간 겉바속촉으로 굽기"},"instruction":{"zh-TW":"蓋上大鍋蓋，保持中小火燜烤 5-6 分鐘。利用蒸汽將頂部椰漿燜熟成柔嫩布丁狀，同時底部受熱烤成金黃硬脆的薄脆碗狀外殼。","en":"Cover pan with a large lid and cook on medium-low heat for 5-6 minutes. The steam sets the coconut cream into a velvety molten pudding while the bottom turns golden brown and rigid.","th":"ปิดฝากระทะอบไฟอ่อน 5-6 นาที ไอน้ำจะทำให้หน้ากะทินุ่มเยิ้มและก้นขนมกรอบร่อน","ja":"蓋をして弱火で5〜6分蒸し焼きにします。蒸気で表面がとろとろのプリン状になり、底面はキツネ色にカリッと焼き上がります。","ko":"뚜껑을 덮고 약불에서 5~6분간 굽습니다. 증기로 속은 부드러운 푸딩처럼 익고, 바닥은 황금빛으로 바삭바삭해집니다."},"durationSeconds":360,"image":"/images/th/khanom-krok-step4.jpg"},{"stepNumber":5,"title":{"zh-TW":"小刀挑起成雙成對，出爐趁熱享用","en":"Pry Out Shells with Butter Knife & Serve Warm","th":"ใช้ช้อนแคะประกบคู่ เสิร์ฟร้อนๆ","ja":"スプーンでくり抜き、2個合わせて熱々を召し上がれ","ko":"숟가락으로 똑 떼어내어 따뜻할 때 즐기기"},"instruction":{"zh-TW":"開蓋，看見邊緣金黃微焦並自然脫模。用小平匙或奶油刀沿著邊緣輕輕一挑即可俐落脫模。傳統泰式吃法常將兩個半球扣合在一起，外皮酥脆微鹹、內裡甜椰漿熱燙爆汁，小心燙舌！","en":"Uncover. The golden edges will have loosened from the pan. Use a small teaspoon to pry each hemisphere out. Traditionally served in pairs joined together. Bite carefully into the molten lava center!","th":"เปิดฝา ขอบจะกรอบร่อน ใช้ช้อนแคะขึ้นมา ประกบคู่เข้าด้วยกัน ทานอุ่นๆ ไส้กะทิจะเยิ้มละลายในปาก","ja":"蓋を開け、縁がカリッと浮いてきたらスプーンで優しく取り出します。現地流に2個を合わせて食べるのもおすすめ。噛んだ瞬間にとろけるココナッツの至福をお楽しみください！","ko":"뚜껑을 열고 바삭하게 일어난 가장자리를 작은 숟가락으로 살짝 떠냅니다. 두 개를 맞대어 포개 먹는 것이 태국 전통 스타일입니다. 속의 뜨거운 크림을 조심하며 맛있게 드세요!"},"durationSeconds":60,"image":"/images/th/khanom-krok-step5.jpg"}],"troubleshooting":[{"id":"khanom-krok-stuck","problem":{"zh-TW":"小圓煎餅黏在烤模上拔不下來、底部破損","en":"Pancakes stuck stubbornly to the pan cavities and tore","th":"ขนมครกติดกระทะ แคะไม่ออก แป้งขาด","ja":"生地が型にくっついてしまい、きれいに取り出せない","ko":"팬에 반죽이 눌어붙어 잘 떨어지지 않아요"},"cause":{"zh-TW":"1. 烤盤預熱溫度不足；2. 油刷得太少；3. 烤的時間不夠久，底部尚未形成硬脆外殼就急著翻動。","en":"1. Pan was not preheated thoroughly; 2. Insufficient oiling; 3. Tried to pry out before bottom fully crisped.","th":"กระทะไม่ร้อนพอ ทาน้ำมันน้อย หรือรีบแคะก่อนที่ก้นจะกรอบร่อน","ja":"1. 予熱不足。2. 油の塗り忘れ。3. 底がカリッとする前に触ってしまった。","ko":"1. 팬 예열이 덜 되었거나, 2. 기름칠이 부족했거나, 3. 바닥이 완전히 바삭해지기 전에 건드렸습니다."},"solution":{"zh-TW":"烤模必須燒至水滴滴入立刻跳動的熱度，均勻抹薄油。加蓋悶烤務必滿 5 分鐘，只要底部硬脆就會自然與模具分離脫模！","en":"Preheat pan until water sizzles into dancing droplets. Oil each cavity and bake covered for a full 5 minutes—the shell releases effortlessly once golden.","th":"วอร์มกระทะให้ร้อนจัด ทาน้ำมันให้ทั่ว และอบปิดฝาให้ครบ 5 นาที ขนมจะร่อนออกเองอย่างง่ายดาย","ja":"水滴が弾けるまでしっかり予熱し、油を塗り、蓋をして5分間触らずにおきます。底が焼き固まれば自然と型から浮き上がります。","ko":"팬을 충분히 달군 후 오일을 꼼꼼히 바르고 5분간 뚜껑을 덮어두면 바닥이 바삭해지며 저절로 쏙 떨어집니다."}}],"proTips":[{"zh-TW":"街頭米香秘招：粉漿中加入少許「煮熟放涼的茉莉白米飯」一起攪打，是曼谷三代老攤的獨門絕學！熟飯中的米澱粉能讓外殼在保持酥脆的同時，內層多了一層如麻糬般的微 Q 彈性，絕不會乾硬！","en":"Old Bangkok street secret: Blending cooked jasmine rice into the raw batter is the master's secret! The gelatinized starch in cooked rice gives the shell a delicate mochi-like tender snap behind the crunch!","th":"สูตรเด็ดชาววัง: ใส่ข้าวสวยหอมมะลิสุกปั่นรวมกับแป้ง จะช่วยให้เปลือกขนมกรอบนุ่ม ไม่แข็งกระด้าง เคี้ยวเพลินละมุนลิ้น","ja":"三代続く名店の秘密：生の米粉だけでなく『炊いたご飯』を少し混ぜてミキサーにかけるのが極意！冷めてもカチカチにならず、もっちりとした極上の歯ごたえが生まれます！","ko":"방콕 3대 전통 노점의 비법: 반죽에 '지은 밥'을 조금 넣어 함께 갈아보세요! 익은 밥의 전분이 겉은 바삭하면서도 속은 쫀득한 마성의 식감을 만들어 냅니다!"}]},{"country":"th","id":"rad-na","slug":"rad-na","title":{"zh-TW":"曼谷老街 泰式香濃滑蛋燴河粉 (Rad Na)","en":"Bangkok Old Town Gravy Flat Noodles (Rad Na Moo)","th":"ราดหน้าหมูหมักยอดผัก","ja":"バンコク旧市街 豚肉とカイラン菜のあんかけ米麺（ラートナー）","ko":"방콕 올드타운 돼지고기 청경채 앙카케 쌀국수 (랏나 무)"},"subtitle":{"zh-TW":"大火炙烙河粉鑊氣焦香，覆蓋甘醇黃豆醬滑蛋高湯芡汁","en":"Wok-charred wide rice noodles blanketed in silky savory bean-paste gravy","th":"เส้นใหญ่คั่วหอมกลิ่นกระทะ ราดน้ำข้นเต้าเจี้ยวหมูนุ่มยอดผัก","ja":"強火で香ばしく焼き付けた幅広米麺に、豆味噌香る熱々のとろみ餡","ko":"웍에서 지져낸 불맛 넓적면에 고소한 콩된장 계란 앙카케 소스"},"tagline":{"zh-TW":"「鑊氣如鐵，芡汁如絲」——與炒河粉、金邊粉齊名的曼谷三大國民麵食","en":"Crisp charred noodles meet velvety Thai-Cantonese gravy perfection","th":"เส้นไหม้กระทะ น้ำราดเหนียวนุ่ม กลมกล่อมลงตัว","ja":"カリッと焦がした麺と、とろける餡の絶妙なコントラスト","ko":"바삭하게 눌은 면과 부드러운 전분 소스의 완벽한 조화"},"heroImage":"/images/th/rad-na.jpg","difficulty":"medium","prepTimeMinutes":20,"cookTimeMinutes":10,"defaultServings":2,"caloriesPerServing":520,"category":"mains","dietaryTags":["classic"],"supportedCookware":["traditional"],"culture":{"originRegion":{"zh-TW":"中部曼谷 (潮汕移民融合飲食文化)","en":"Central Thailand / Bangkok (Teochew-Thai Heritage)","th":"ภาคกลาง กรุงเทพฯ (วัฒนธรรมไทย-จีนแต้จิ๋ว)","ja":"タイ中部 バンコク（潮州系中華とタイの融合文化）","ko":"중부 방콕 (조주계 중국 이민자 퓨전 요리 문화)"},"famousStreetMarkets":[{"zh-TW":"曼谷 耀華力路唐人街 (Chinatown Yaowarat)","en":"Yaowarat Chinatown, Bangkok","th":"เยาวราช กรุงเทพฯ","ja":"バンコク ヤワラート中華街","ko":"방콕 야오와랏 차이나타운"},{"zh-TW":"曼谷 拍那空老城區 民主紀念碑周邊老店","en":"Phra Nakhon Old Town Heritage Stalls","th":"ย่านพระนคร กรุงเทพฯ","ja":"プラナコーン旧市街の老舗屋台群","ko":"프라나콘 올드타운 전통 노점거리"}],"historyStory":{"zh-TW":"Rad Na（ราดหน้า，字面意為「淋在表面」）源自 20 世紀初潮汕移民帶至暹羅的「廣府燴麵」。泰國廚師發揮熱帶創意，將大豆發酵的泰式黃豆醬（Tao Jiew）、白胡椒粉與椰糖融入大骨高湯，並用木薯粉勾出瑩潤薄芡。烹調關鍵在於將寬河粉（Sen Yai）於燒得通紅的碳鋼炒鍋中以極高溫猛烈烙出微焦黑斑與炭火香，再淋上熱氣騰騰的芥藍滑肉芡汁，焦香與滑潤在舌尖交織！","en":"Rad Na (literally \"poured over face/top\") originated from Teochew Chinese immigrants in early 20th-century Bangkok. Thai street cooks elevated the dish by infusing the pork broth with aromatic fermented yellow bean paste (Tao Jiew), palm sugar, and white pepper, bound by silky tapioca starch. The secret to a Michelin-street-stall Rad Na is blast-charring the wide rice noodles in a roaring carbon steel wok until speckled with smoky wok hei blisters before drenching in boiling gravy.","th":"ราดหน้ามีรากเหง้ามาจากอาหารจีนแต้จิ๋ว นำมาปรับสูตรให้เข้ากับลิ้นคนไทยโดยใส่เต้าเจี้ยวหวาน น้ำตาลปี๊บ และพริกไทยขาว เสน่ห์ที่แท้จริงคือการคั่วเส้นใหญ่ในกระทะเหล็กร้อนจัดจนมีรอยไหม้หอมควันกระทะ (กลิ่นกระทะ) ก่อนราดด้วยน้ำซุปหมูหมักนุ่มและคะน้ายอดอ่อนกรอบ","ja":"ラートナー（直訳で「表面にかける」）は、20世紀初頭にバンコクへ渡った潮州系移民がもたらした広東風あんかけ麺がルーツです。タイの料理人たちは現地の黄豆味噌（タオチオ）やパームシュガーを加え、南国風の深みある味へと昇華させました。最大の特徴は、真っ赤に熱した中華鍋で平打ち麺をあえて焦げ目がつくまで焼き付け、スモーキーな「鍋気（ウォックヘイ）」をまとわせることです。","ko":"랏나(Rad Na, 면 위에 붓는다는 뜻)는 20세기 초 방콕에 정착한 조주계 중국인들의 울면/광둥식 앙카케 면 요리에서 유래했습니다. 태국 현지인들은 태국식 콩된장(따오찌우)과 팜슈가, 백후추를 더해 독창적인 맛을 완성했습니다. 섭씨 300도가 넘는 웍에서 넓적 쌀국수를 지져 바삭하고 그을린 불맛을 낸 후, 걸쭉한 전분 소스를 끼얹어 먹는 방콕의 소울푸드입니다."},"thaiScript":"ราดหน้าหมูหมักยอดผัก","thaiPhonetics":"Rad Na Moo Mak Yot Phak","audioPronunciationText":"ราดหน้าหมูหมัก","nativeName":"ราดหน้าหมูหมักยอดผัก"},"ingredients":[{"id":"sen-yai","name":{"zh-TW":"鮮寬河粉 (大片粿條)","en":"Fresh Wide Rice Noodles (Sen Yai)","th":"เส้นใหญ่สด","ja":"生幅広米麺（センヤイ）","ko":"생 넓적 쌀국수 면 (센야이)"},"amount":300,"unitMetric":"g","unitUS":"10.5 oz","isKeyFlavor":true,"thaiName":"เส้นใหญ่","thaiPronunciation":"Sen Yai","substitute":{"substituteName":{"zh-TW":"乾寬河粉 (溫水浸泡 40 分鐘瀝乾)","en":"Dried extra-wide rice noodles (soaked 40 mins)","th":"เส้นใหญ่กึ่งสำเร็จรูป","ja":"乾燥きしめん風平打ち米麺（ぬるま湯で40分戻す）","ko":"건 넓적 쌀국수 (미지근한 물에 40분 불림)"},"ratio":"1:1","explanation":{"zh-TW":"正統風味講究寬河粉的大片米香與焦化層。乾麵條需徹底泡軟並瀝乾水分才能烙出香氣。","en":"Wide noodles catch the char best. Dry noodles must be fully softened and towel-dried before searing.","th":"แช่น้ำอุ่นจนนุ่ม สะเด็ดน้ำให้แห้งสนิทก่อนผัด","ja":"乾燥麺を使う場合は完全に水気を拭き取ってから炒めないと焦げ目がつきません。","ko":"건면은 물기를 키친타월로 완전히 닦아내야 웍에서 바삭하게 눌러붙습니다."},"whereToBuy":{"zh-TW":"東南亞超市冷藏生鮮區","en":"Asian grocery refrigerated noodle aisle","th":"ตลาดสดทั่วไป","ja":"アジア食材店 冷蔵コーナー","ko":"아시안 마트 냉장 코너"}}},{"id":"pork-tenderloin","name":{"zh-TW":"豬梅花肉或里肌肉 (逆紋切薄片)","en":"Pork Collar or Tenderloin (Thinly sliced)","th":"เนื้อหมูหมักนุ่ม","ja":"豚肩ロースまたはヒレ肉（薄切り）","ko":"돼지 안심 또는 목살 (얇게 썬 것)"},"amount":200,"unitMetric":"g","unitUS":"7 oz","isKeyFlavor":true,"thaiName":"เนื้อหมู","thaiPronunciation":"Moo Mak"},{"id":"chinese-broccoli","name":{"zh-TW":"芥藍菜 (梗切斜片，葉切大段)","en":"Chinese Broccoli / Gai Lan (Stems bias-cut, leaves chopped)","th":"ยอดคะน้าสด","ja":"カイラン菜（茎は斜め切り、葉はざく切り）","ko":"카이란 (청경채로 대체 가능, 줄기와 잎 분리)"},"amount":150,"unitMetric":"g","unitUS":"5.3 oz","isKeyFlavor":true,"thaiName":"ผักคะน้า","thaiPronunciation":"Phak Kha-Na"},{"id":"yellow-bean-paste","name":{"zh-TW":"泰式黃豆醬 (Tao Jiew / 豆瓣醬)","en":"Thai Fermented Yellow Soybean Paste (Tao Jiew)","th":"เต้าเจี้ยวบดโม่อิมสี","ja":"タイ黄豆味噌（タオチオ）","ko":"태국 콩된장 (따오찌우)"},"amount":1.5,"unitMetric":"tbsp","unitUS":"1.5 tbsp","isKeyFlavor":true,"thaiName":"เต้าเจี้ยว","thaiPronunciation":"Tao Jiew","substitute":{"substituteName":{"zh-TW":"台式黃豆醬或日本赤味噌 + 1小匙白醬油","en":"Soybean paste (doenjang/miso) + 1 tsp light soy","th":"เต้าเจี้ยวขาว","ja":"日本の粒味噌または赤味噌＋薄口醤油小さじ1","ko":"재래식 된장 1큰술 + 양조간장 1작은술"},"ratio":"1:1","explanation":{"zh-TW":"Tao Jiew 帶有鹹甜天然發酵香氣，是泰式燴麵高湯的靈魂基底。","en":"Tao Jiew imparts savory umami sweetness unique to Thai-Chinese gravies.","th":"เต้าเจี้ยวช่วยให้รสชาติน้ำราดกลมกล่อม","ja":"タオチオは甘じょっぱい発酵の旨味があり、餡の決め手となります。","ko":"따오찌우 특유의 감칠맛과 짠맛이 랏나 소스의 핵심입니다."},"whereToBuy":{"zh-TW":"進口東南亞調味醬專區","en":"Southeast Asian condiment section","th":"ซูเปอร์มาร์เก็ตทั่วไป","ja":"輸入食品店 中華・タイ調味料売場","ko":"수입 식료품점 또는 온라인 태국몰"}}},{"id":"pork-stock","name":{"zh-TW":"優質高湯 (大骨或雞高湯)","en":"Pork or Chicken Broth","th":"น้ำซุปกระดูกหมู","ja":"豚骨または鶏がらスープ","ko":"돼지 사골 또는 닭 육수"},"amount":500,"unitMetric":"ml","unitUS":"2.1 cup","thaiName":"น้ำซุป","thaiPronunciation":"Nam Sup"},{"id":"tapioca-starch","name":{"zh-TW":"木薯粉或太白粉 (兌水調成芡水)","en":"Tapioca Starch or Cornstarch (Dissolved in water)","th":"แป้งมันสำปะหลังหรือแป้งท้าวยายม่อม","ja":"タピオカ澱粉または片栗粉（水溶き）","ko":"타피오카 전분 또는 감자 전분 (물에 갠 것)"},"amount":2.5,"unitMetric":"tbsp","unitUS":"2.5 tbsp","thaiName":"แป้งมัน","thaiPronunciation":"Phaeng Man"},{"id":"dark-sweet-soy","name":{"zh-TW":"黑甜醬油 (老抽)","en":"Dark Sweet Soy Sauce (See Ew Dam)","th":"ซีอิ๊วดำหวาน","ja":"タイ黒甘醤油（シーウダム・ワン）","ko":"태국 다크 스위트 간장 (씨유담)"},"amount":1,"unitMetric":"tbsp","unitUS":"1 tbsp","thaiName":"ซีอิ๊วดำ","thaiPronunciation":"See Ew Dam"},{"id":"garlic-minced","name":{"zh-TW":"大蒜 (拍碎切細末)","en":"Garlic Cloves (Minced)","th":"กระเทียมไทยสับละเอียด","ja":"にんにく（みじん切り）","ko":"다진 마늘"},"amount":4,"unitMetric":"clove","unitUS":"4 clove","thaiName":"กระเทียม","thaiPronunciation":"Kra-Thiam"},{"id":"egg","name":{"zh-TW":"新鮮雞蛋 (打散成蛋液)","en":"Fresh Egg (Beaten for ribbons)","th":"ไข่ไก่สด","ja":"卵（溶き卵）","ko":"달걀 1개 (풀어둔 것)"},"amount":1,"unitMetric":"piece","unitUS":"1 piece","thaiName":"ไข่ไก่","thaiPronunciation":"Khai"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"醃漬滑嫩肉片與處理芥藍","en":"Marinate Tender Pork & Prep Gai Lan Greens","th":"หมักหมูให้นุ่มและหั่นผักคะน้า","ja":"豚肉を柔らかく下味漬けし、カイラン菜を切る","ko":"돼지고기 연육 밑간 및 카이란 손질"},"instruction":{"zh-TW":"豬肉逆紋切薄片，加入 1 茶匙蠔油、1 茶匙生抽、少許糖、白胡椒與 1 茶匙太白粉抓勻醃漬 15 分鐘。芥藍菜粗莖削去老皮斜切厚片，葉片切段洗淨瀝乾備用。","en":"Slice pork thinly against the grain. Massage with 1 tsp oyster sauce, 1 tsp light soy, a pinch of sugar, white pepper, and 1 tsp cornstarch; marinate for 15 mins. Peel tough skin off Gai Lan stems, slice diagonally, and cut leaves into bite-sized segments.","th":"หั่นหมูตามขวาง หมักด้วยซอสหอยนางรม ซีอิ๊วขาว น้ำตาล พริกไทย และแป้งมัน 15 นาที ปอกเปลือกก้านคะน้าหั่นเฉียง หั่นใบเป็นท่อน ล้างพักไว้","ja":"豚肉は繊維を断つように薄切りにし、オイスターソース・薄口醤油・砂糖・白胡椒・片栗粉各大さじ1/2で揉み込み15分置きます。カイランの太い茎は皮を剥き斜め薄切り、葉はざく切りにします。","ko":"돼지고기는 결 반대로 얇게 썰어 굴소스, 간장, 설탕, 백후추, 전분 1작은술을 넣고 조물조물 주물러 15분간 재워둡니다. 카이란 줄기는 억센 겉껍질을 벗겨 어슷썰고 잎은 큼직하게 썹니다."},"durationSeconds":180,"image":"/images/th/rad-na-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"大火炙烙河粉！逼出靈魂鑊氣","en":"Blast-Sear Flat Noodles for Smoky Wok Char","th":"ผัดคั่วเส้นใหญ่ให้หอมไหม้กลิ่นกระทะ","ja":"中華鍋をカンカンに熱し、幅広麺を香ばしく焼き付ける","ko":"센 불에 넓적 쌀국수를 눌러 붙여 불맛 입히기"},"instruction":{"zh-TW":"寬河粉撕散，拌入 1 大匙黑甜醬油均勻上色。鐵鍋大火燒至冒青煙，倒入 1 大匙油晃潤鍋壁，一口氣倒入河粉平攤於鍋底。保持極高溫煎烙 20 秒切勿頻繁翻動，待底部結出金黃焦斑後快速翻面烙香，盛出鋪於深盤中。","en":"Toss separated wide noodles with 1 tbsp dark sweet soy sauce. Heat wok until smoking hot, swirl in 1 tbsp oil, and spread noodles flat across bottom. Let sear undisturbed for 20 seconds to form blistering char spots, flip once to brown the other side, then transfer onto serving bowls.","th":"คลี่เส้นใหญ่คลุกซีอิ๊วดำให้ทั่ว ตั้งกระทะไฟแรงสุดจนควันขึ้น ใส่น้ำมัน 1 ช้อนโต๊ะ เทเส้นลงแผ่ให้แนบก้นกระทะ คั่วทิ้งไว้ 20 วินาทีให้เกรียมหอม สะบัดพลิกด้านแล้วตักใส่จานลึกรอไว้","ja":"麺をほぐし黒甘醤油大さじ1を和えます。煙が出るまで熱した中華鍋に油大さじ1を馴染ませ、麺を一気に広げます。すぐ触らず20秒間じっと焼き付け、焦げ目がついたらサッと返して香ばしさを引き出し、深皿に盛ります。","ko":"넓적 면을 가닥가닥 떼어 다크 스위트 간장 1큰술로 버무립니다. 웍을 연기가 날 때까지 센 불로 달군 뒤 기름을 두르고 면을 쫙 폅니다. 뒤적이지 말고 20초간 지져 누룽지 자국을 낸 뒤 뒤집어 살짝 더 볶아 그릇에 담아둡니다."},"durationSeconds":120,"image":"/images/th/rad-na-step2.jpg","crucialTips":{"zh-TW":"烙河粉時千萬不可狂翻亂炒，否則鍋溫瞬間驟降，河粉會斷碎成爛糊且失去炭火煙燻香！","en":"Do not stir noodles constantly! Let them sizzle stationary against scorching steel to develop smoky wok hei without breaking.","th":"ห้ามใช้ตะหลิวสับหรือคนเส้นไปมาบ่อยๆ เพราะจะทำให้เส้นขาดเละและไม่มีกลิ่นหอมไหม้","ja":"ヘラで絶え間なくかき混ぜないこと！じっくり焼き付けることで麺が切れずに香ばしい香りが生まれます。","ko":"면을 마구 휘저으면 온도가 떨어져 면이 뭉개집니다. 웍 바닥에 가만히 눌러 붙여 지져내야 합니다."}},{"stepNumber":3,"title":{"zh-TW":"爆香黃豆醬與蒜末，煨煮鮮甜肉片與芥藍","en":"Sauté Garlic & Bean Paste, Simmer Pork & Gai Lan","th":"ผัดกระเทียมเต้าเจี้ยว เติมน้ำซุปใส่หมูและคะน้า","ja":"にんにくとタオチオを炒め、スープで豚肉とカイランを煮る","ko":"다진 마늘과 된장 볶고 육수에 고기와 카이란 끓이기"},"instruction":{"zh-TW":"原鍋少許油爆香蒜末與泰式黃豆醬 30 秒至香氣四溢，倒入 500ml 高湯大火煮沸。放入醃好的肉片快速滑散，隨後加入芥藍粗莖煮 1 分鐘，再下嫩綠葉，調入 1 大匙蠔油、1 茶匙糖與少許白胡椒粉。","en":"In same wok, sauté minced garlic and Thai yellow bean paste for 30 seconds until fragrant. Pour in 500ml stock and bring to a rolling boil. Add marinated pork, stirring gently to separate slices. Add Gai Lan stems for 1 min, then add leaves, 1 tbsp oyster sauce, 1 tsp sugar, and white pepper.","th":"ใส่กระเทียมและเต้าเจี้ยวลงผัดจนหอม ใส่น้ำซุป 500 มล. ต้มจนเดือดจัด ใส่หมูหมักลงคนให้กระจายตัว ใส่ก้านคะน้าต้ม 1 นาที ตามด้วยใบ ปรุงรสด้วยซอสหอยนางรม น้ำตาล และพริกไทย","ja":"同じ鍋でにんにくとタオチオを30秒炒めて香りを立たせ、スープ500mlを一気に注ぎ沸騰させます。下味をつけた豚肉をほぐし入れ、カイランの茎を1分煮てから葉を加え、オイスターソース・砂糖・白胡椒で味を調えます。","ko":"팬에 다진 마늘과 따오찌우 된장을 30초간 볶아 향을 낸 뒤 육수 500ml를 붓고 팔팔 끓입니다. 재워둔 돼지고기를 뭉치지 않게 넣고 카이란 줄기를 1분간 익힌 후 잎을 넣고 굴소스, 설탕, 백후추로 간을 맞춥니다."},"durationSeconds":180,"image":"/images/th/rad-na-step3.jpg"},{"stepNumber":4,"title":{"zh-TW":"勾絲滑薄芡、淋入蛋花，滾燙澆汁盛盤","en":"Thicken Glossy Gravy, Swirl Egg & Drench Noodles","th":"ละลายแป้งมันให้น้ำข้นเหนียว ตอกไข่ราดบนเส้นร้อนๆ","ja":"水溶きタピオカ粉でとろみをつけ、溶き卵を回し入れて麺にかける","ko":"전분물로 소스 농도 맞추고 계란물 둘러 면 위에 끼얹기"},"instruction":{"zh-TW":"將木薯水充分攪勻，一邊轉大火一邊緩緩淋入鍋中快速攪動，湯汁瞬間變得濃稠透亮。淋入打散的蛋液劃出金黃絲帶狀蛋花。趁滾燙沸騰立即將整鍋香濃芡汁均勻澆在焦香河粉上，撒上白胡椒粉即可上桌！","en":"Stir tapioca slurry well and stream steadily into boiling gravy while stirring briskly until glossy and thickened. Drizzle in beaten egg in a thin swirl to form silky golden ribbons. Ladle the boiling hot, velvety sauce generously over the charred noodles. Dust with white pepper and serve piping hot!","th":"คนแป้งมันให้ละลาย ค่อยๆ เทลงในน้ำเดือดพร้อมคนต่อเนื่องจนน้ำซุปข้นเหนียวเงางาม รินไข่ไก่เป็นสายให้เป็นริ้วสวย ตักน้ำราดหน้าข้นๆ ราดลงบนเส้นคั่วทันที โรยพริกไทยป่นพร้อมเสิร์ฟ","ja":"水溶きタピオカ粉を混ぜながら細く注ぎ入れ、一気に艶やかなとろみをつけます。溶き卵を細く流し入れてふわっとした卵の花を咲かせたら、熱々のあんを焦がし麺の上から豪快にかけ、白胡椒を振って完成です！","ko":"전분물을 잘 저어 끓는 육수에 조금씩 부어가며 재빠르게 저어 투명하고 걸쭉하게 만듭니다. 푼 달걀을 둥글게 둘러 넣어 부드러운 달걀 꽃을 피운 뒤, 뜨거운 소스를 지져둔 쌀국수 위에 듬뿍 끼얹고 백후추를 뿌려 완성합니다!"},"durationSeconds":90,"image":"/images/th/rad-na-step4.jpg"}],"troubleshooting":[{"id":"rad-na-gravy-watery","problem":{"zh-TW":"芡汁出鍋後很快變稀出水，失去濃稠絲滑口感","en":"Gravy turned watery and thin quickly after serving","th":"น้ำราดหน้าคืนตัวเหลวเป็นน้ำ ไม่เหนียวข้น","ja":"時間が経つと餡がシャバシャバに水っぽく戻ってしまう","ko":"조리 후 얼마 안 가 소스가 묽게 풀어져 물처럼 변해요"},"cause":{"zh-TW":"木薯粉或太白粉下鍋後火候不足未徹底煮沸糊化，澱粉分子受唾液澱粉酶或低溫分解。","en":"Tapioca starch slurry was not cooked at a full rolling boil to complete gelatinization.","th":"แป้งยังไม่สุกเต็มที่ หรือคนแป้งตอนน้ำไม่เดือดจัด","ja":"片栗粉・タピオカ粉を投入した後に完全に沸騰させて糊化（アルファ化）させていないため。","ko":"전분물을 넣은 뒤 소스가 팔팔 끓어 완벽하게 호화(gelatinization)되기 전에 불을 껐기 때문입니다."},"solution":{"zh-TW":"淋入芡水時務必保持大火沸騰，持續攪拌煮透 30-40 秒直至芡汁呈現光澤半透明狀再關火。","en":"Maintain high heat when streaming in slurry; stir continuously for 30-40 seconds at a vigorous boil until glossy before cutting heat.","th":"เทแป้งขณะน้ำเดือดพล่าน คนต่ออีก 30-40 วินาทีจนน้ำซุปใสและเดือดปุดๆ ก่อนปิดไฟ","ja":"必ず沸騰している状態にとろみ水を回し入れ、30〜40秒間グツグツしっかり火を通して透明感が出てから火を止めます。","ko":"전분물을 넣을 때 반드시 센 불을 유지하고, 걸쭉하고 투명해질 때까지 30~40초간 보글보글 충분히 끓여주세요."}}],"proTips":[{"zh-TW":"老饕調味靈魂四寶：泰國人吃 Rad Na 一定會在桌邊依喜好添加「醃辣椒白醋 (Prik Nam Som)」、「泰國細砂糖」與「粗碎乾辣椒」！微酸微甜的醋水能完美平衡濃郁芡汁，讓每一口都無比開胃解膩！","en":"Bangkok Table Quartet: Authentic Thai dining requires seasoning your Rad Na at the table with pickled chili vinegar (Prik Nam Som), a pinch of sugar, and coarse roasted chili flakes to balance the rich savory sauce!","th":"เคล็ดลับความอร่อย: ก่อนทานต้องปรุงด้วยพริกดองน้ำส้มสายชู น้ำตาลทราย และพริกป่นคั่ว ความเปรี้ยวเผ็ดจะช่วยตัดเลี่ยนของน้ำข้นได้อย่างยอดเยี่ยม","ja":"屋台の黄金バランス：タイの食卓では、食べる直前に卓上の「唐辛子入り酢（プリック・ナムソム）」小さじ1〜2、砂糖ひとつまみ、粗挽き唐辛子を加えるのが常識。濃厚な餡がキリッと引き締まります！","ko":"방콕 현지인 꿀팁: 서빙된 랏나에 식탁 위 고추식초(프릭남쏨) 1~2작은술, 설탕 반작은술, 고춧가루를 살짝 둘러 드세요! 산뜻한 산미와 매콤함이 걸쭉한 소스와 어우러져 질리지 않고 끝까지 맛있습니다!"}]},{"country":"th","id":"khao-phat","slug":"khao-phat","title":{"zh-TW":"曼谷街頭 經典泰式香脆炒飯 (Khao Phat)","en":"Bangkok Street Classic Thai Fried Rice (Khao Phat)","th":"ข้าวผัดโบราณริมทาง","ja":"バンコク屋台 定番タイ風パラパラ炒飯（カオパット）","ko":"방콕 길거리 원조 태국식 계란 볶음밥 (카오팟)"},"subtitle":{"zh-TW":"隔夜香米粒粒跳舞，大火嗆入頂級魚露與靈魂辣椒醋露","en":"Glistening jasmine rice grains dancing in high wok heat with fish sauce aroma","th":"ข้าวร่วนเป็นเม็ด หอมกลิ่นกระทะ เสิร์ฟพร้อมพริกน้ำปลาและมะนาว","ja":"強火でパラパラに煽ったジャスミンライスに魚醤の焦がし香","ko":"웍에서 알알이 살아 숨쉬는 안남미에 피시소스의 불향"},"tagline":{"zh-TW":"泰國街頭快炒第一招牌——顆顆分明、蛋香四溢、擠上青檸開胃滿分","en":"The definitive street stall staple: fluffy eggs, crisp aromatics, and zesty fresh lime","th":"อร่อยง่ายๆ สไตล์สตรีทฟู้ด ข้าวร่วนนุ่มหอมฟุ้งทุกคำ","ja":"タイ料理の基本にして究極！ライムを一絞りして味わう絶品チャーハン","ko":"태국 스트리트 푸드의 정점! 라임즙을 톡 짜서 먹는 고슬고슬한 볶음밥"},"heroImage":"/images/th/khao-phat.jpg","difficulty":"easy","prepTimeMinutes":10,"cookTimeMinutes":8,"defaultServings":2,"caloriesPerServing":510,"category":"stirFry","dietaryTags":["classic"],"supportedCookware":["traditional"],"culture":{"originRegion":{"zh-TW":"全泰國普及 (曼谷街頭熱炒經典)","en":"Nationwide Thailand / Bangkok Street Hubs","th":"ทั่วประเทศไทย (อาหารตามสั่งยอดนิยม)","ja":"タイ全土（大衆食堂や屋台の定番メニュー）","ko":"태국 전역 (거리 노점 및 대중식당의 대표 메뉴)"},"famousStreetMarkets":[{"zh-TW":"曼谷 勝利紀念碑周邊熱炒街","en":"Victory Monument Food Street, Bangkok","th":"อนุสาวรีย์ชัยสมรภูมิ กรุงเทพฯ","ja":"バンコク ビクトリーモニュメント周辺の屋台街","ko":"방콕 전승기념탑 인근 먹자골목"},{"zh-TW":"考山路周邊大排檔夜市","en":"Khaosan Road Night Vendors","th":"ถนนข้าวสาร กรุงเทพฯ","ja":"カオサン通り周辺の夜市屋台","ko":"카오산 로드 야시장 노점"}],"historyStory":{"zh-TW":"Khao Phat（ข้าวผัด，Khao 為米飯，Phat 為翻炒）是泰國街頭「隨點隨炒（A-han Tam Sang）」小吃攤最具代表性的靈魂料理。與中式炒飯不同，泰式炒飯最講究泰國茉莉香米（Khao Hom Mali）特有的天然米香與乾爽質地。泰國大廚習慣以猛火將蒜碎爆香，下肉片斷生，隨後推至鍋邊將蛋液滑入熱油中炒成金黃蓬鬆的蛋碎，再一口氣倒入冷飯翻顛裹勻。出鍋前最重要的步驟是沿鍋邊淋入一圈頂級魚露（Nam Pla），高溫瞬間逼出焦糖般的醇厚海味！","en":"Khao Phat is the heartbeat of Thai street food \"made-to-order\" stalls (A-han Tam Sang). Unlike standard Chinese fried rice, Thai cooks rely on chilled Thai Jasmine Rice (Khao Hom Mali) for its distinct floral aroma and non-sticky texture. A roaring carbon steel wok sizzles minced garlic and pork, then eggs are scrambled into fluffy golden curds in the pool of oil before the rice is tossed vigorously. The final crescendo is a splash of premium fish sauce around the searing rim of the wok, vaporizing instantly into rich umami smoke.","th":"ข้าวผัดเป็นราชาแห่งอาหารตามสั่งของไทย จุดเด่นคือใช้ข้าวหอมมะลิเก่าหุงสวยแช่เย็นจนร่วน ไม่แฉะ ผัดด้วยไฟแรงให้ไข่เคลือบเม็ดข้าวหอมฟุ้ง และปรุงรสเค็มหอมด้วยน้ำปลาแท้สะบัดข้างขอบกระทะ เสิร์ฟคู่กับแตงกวา ต้นหอม มะนาว และที่ขาดไม่ได้คือพริกน้ำปลา","ja":"カオパットは、タイの屋台や大衆食堂（アハーン・ตามสั่ง）で最も親しまれている国民食です。最大の特徴は、パラパラとした食感と芳醇な香りを誇るジャスミンライス（カオホムマリ）を使うこと。最大火力の中華鍋でニンニクと具材を炒め、鍋肌で卵をふわふわに泡立ててからご飯を一気に煽ります。仕上げに鍋肌からジュッと垂らすナンプラーの香ばしさと、食べる直前に絞るライムの酸味が食欲を無限にかき立てます。","ko":"카오팟은 주문 즉시 웍을 흔들어 볶아내는 태국의 대표적인 패스트푸드입니다. 찰기가 적고 알알이 흩어지는 최고급 태국 자스민 쌀(카오홈말리)을 차갑게 식혀 사용하는 것이 핵심입니다. 뜨거운 웍에 기름을 두르고 달걀을 부드러운 스크램블로 만든 후 밥과 합체하여 볶아내며, 마지막에 웍 가장자리에 피시소스(남쁠라)를 둘러 불맛을 입힙니다."},"thaiScript":"ข้าวผัดโบราณ","thaiPhonetics":"Khao Phat Boran","audioPronunciationText":"ข้าวผัด","nativeName":"ข้าวผัดโบราณ"},"ingredients":[{"id":"jasmine-rice","name":{"zh-TW":"泰國茉莉香米冷飯 (冷藏隔夜最佳)","en":"Chilled Jasmine Rice (Preferably day-old)","th":"ข้าวหอมมะลิหุงสุกแช่เย็น","ja":"ジャスミンライス冷やご飯（前日のものが最適）","ko":"차갑게 식힌 안남미 밥 (전날 지어둔 밥 추천)"},"amount":350,"unitMetric":"g","unitUS":"12 oz","isKeyFlavor":true,"thaiName":"ข้าวสวย","thaiPronunciation":"Khao Suay","substitute":{"substituteName":{"zh-TW":"蓬萊米或長粒白米 (少水煮硬放涼吹乾)","en":"Long-grain white rice (cooked firm and chilled)","th":"ข้าวขาวเสาไห้","ja":"長粒米または固めに炊いて冷ました白米","ko":"고슬고슬하게 지어 식힌 멥쌀밥"},"ratio":"1:1","explanation":{"zh-TW":"泰國香米水分少、黏性低，炒製時米粒在鐵鍋中自由跳動，不易黏成坨。","en":"Thai jasmine rice provides the quintessential dry, non-sticky fluffiness.","th":"ข้าวเม็ดร่วนสวย ไม่เกาะตัวเป็นก้อนเวลาผัด","ja":"水分が少なくパラリとほぐれやすいお米を使うのが成功の秘訣です。","ko":"수분기가 적어야 웍에서 밥알이 뭉치지 않고 고슬고슬하게 볶아집니다."},"whereToBuy":{"zh-TW":"各大超市糧油專區","en":"Supermarket Asian rice aisle","th":"ซูเปอร์มาร์เก็ตทั่วไป","ja":"スーパー米売場または輸入食品店","ko":"대형마트 또는 수입 식료품점"}}},{"id":"eggs","name":{"zh-TW":"新鮮雞蛋","en":"Fresh Eggs","th":"ไข่ไก่สด","ja":"卵","ko":"달걀 2개"},"amount":2,"unitMetric":"piece","unitUS":"piece","isKeyFlavor":true,"thaiName":"ไข่ไก่","thaiPronunciation":"Khai Gai"},{"id":"sliced-pork","name":{"zh-TW":"豬肉片或雞肉丁 (亦可用鮮蝦仁)","en":"Pork Loin Slices or Chicken/Shrimp","th":"เนื้อหมูหรือกุ้งสด","ja":"豚肉スライス（または鶏肉・エビ）","ko":"돼지고기 안심 또는 닭가슴살/새우"},"amount":120,"unitMetric":"g","unitUS":"4.2 oz","thaiName":"เนื้อหมู","thaiPronunciation":"Nuea Moo"},{"id":"garlic-cloves","name":{"zh-TW":"大蒜末","en":"Garlic Cloves (Minced)","th":"กระเทียมสับ","ja":"にんにく（みじん切り）","ko":"다진 마늘"},"amount":3,"unitMetric":"clove","unitUS":"3 clove","thaiName":"กระเทียม","thaiPronunciation":"Kra-Thiam"},{"id":"chinese-broccoli-stem","name":{"zh-TW":"芥藍菜或洋蔥絲與蔥段","en":"Chinese Broccoli stems, Sliced Onion & Scallions","th":"ผักคะน้าซอยและหอมใหญ่","ja":"カイラン菜（または玉ねぎスライスと青ネギ）","ko":"카이란 줄기 또는 양파 채와 쪽파"},"amount":80,"unitMetric":"g","unitUS":"2.8 oz","thaiName":"ผักคะน้า","thaiPronunciation":"Phak Kha-Na"},{"id":"fish-sauce","name":{"zh-TW":"特級泰國魚露 (靈魂嗆香)","en":"Premium Thai Fish Sauce (Nam Pla)","th":"น้ำปลาแท้ชั้นดี","ja":"プレミアム・ナンプラー","ko":"태국 프리미엄 피시소스 (남쁠라)"},"amount":1.5,"unitMetric":"tbsp","unitUS":"1.5 tbsp","isKeyFlavor":true,"thaiName":"น้ำปลา","thaiPronunciation":"Nam Pla"},{"id":"light-soy","name":{"zh-TW":"生抽 / 白醬油","en":"Light Soy Sauce","th":"ซีอิ๊วขาว","ja":"薄口醤油","ko":"양조간장"},"amount":1,"unitMetric":"tsp","unitUS":"1 tsp","thaiName":"ซีอิ๊วขาว","thaiPronunciation":"See Ew Khao"},{"id":"sugar","name":{"zh-TW":"細砂糖 (提鮮解鹹)","en":"Granulated Sugar","th":"น้ำตาลทราย","ja":"砂糖","ko":"설탕"},"amount":0.5,"unitMetric":"tsp","unitUS":"0.5 tsp","thaiName":"น้ำตาล","thaiPronunciation":"Nam Tan"},{"id":"white-pepper","name":{"zh-TW":"泰式白胡椒粉","en":"Ground White Pepper","th":"พริกไทยป่น","ja":"白胡椒パウダー","ko":"백후추 가루"},"amount":0.5,"unitMetric":"tsp","unitUS":"0.5 tsp","thaiName":"พริกไทยป่น","thaiPronunciation":"Prik Thai"},{"id":"fresh-lime","name":{"zh-TW":"新鮮青檸 (切角隨盤擠汁)","en":"Fresh Lime Wedges","th":"มะนาวผ่าซีก","ja":"ライム（くし形切り）","ko":"신선한 라임 조각"},"amount":1,"unitMetric":"piece","unitUS":"1 piece","isKeyFlavor":true,"thaiName":"มะนาว","thaiPronunciation":"Manao"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"撥散冷香米與切配辛香蔬菜","en":"Fluff Chilled Jasmine Rice & Prep Aromatics","th":"ยีข้าวสวยแช่เย็นให้ร่วนและเตรียมผัก","ja":"冷やご飯をしっかりほぐし、香味野菜を刻む","ko":"식힌 밥알을 뭉침 없이 풀고 채소 손질하기"},"instruction":{"zh-TW":"將冷藏隔夜的泰國茉莉香米放入大碗中，戴上手套輕柔搓散，使米粒顆顆分明無硬塊。大蒜拍碎切末，洋蔥切細絲，芥藍梗削去粗皮切薄片，青蔥切小花備用。","en":"Place chilled cooked jasmine rice into a bowl and gently separate any clumps with clean hands until grains are free-flowing. Mince garlic, slice onion into thin wedges, slice Gai Lan stems on the bias, and finely chop scallions.","th":"นำข้าวหอมมะลิที่แช่เย็นไว้มาใช้มือยีให้เม็ดข้าวแตกออกจากกัน ไม่จับตัวเป็นก้อน สับกระซอยหอมใหญ่ ซอยก้านคะน้าบางๆ และซอยต้นหอมเตรียมไว้","ja":"冷やしたジャスミンライスを手で優しくほぐし、米粒がダマになっていない状態にします。にんにくはみじん切り、玉ねぎは薄切り、カイランの茎は斜め薄切り、青ネギは小口切りにしておきます。","ko":"냉장고에서 꺼낸 자스민 밥을 손으로 살살 비벼 뭉친 덩어리 없이 알알이 흩어지게 만듭니다. 마늘은 다지고 양파는 채 썰며, 카이란 줄기는 어슷썰고 쪽파는 쫑쫑 썰어 준비합니다."},"durationSeconds":120,"image":"/images/th/khao-phat-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"大火熱鍋爆香蒜碎與滑炒肉片","en":"Sauté Minced Garlic & Sear Pork Slices","th":"ตั้งกระทะเจียวกระเทียมและผัดเนื้อสัตว์","ja":"強火で熱した鍋に油を敷き、にんにくとお肉を炒める","ko":"센 불에 마늘을 볶고 고기를 빠르게 익히기"},"instruction":{"zh-TW":"碳鋼炒鍋以最大火燒熱，倒入 2 大匙食用油晃潤鍋壁。放入蒜末與洋蔥絲快速爆炒 20 秒至金黃飄香。倒入豬肉薄片大火快速翻炒 1 分鐘至肉色變白、八分熟，盛到鍋緣一側備用。","en":"Heat carbon steel wok over highest flame, add 2 tbsp oil and swirl around the sides. Toss in minced garlic and sliced onion; stir-fry briskly for 20 seconds until fragrant. Add sliced pork and stir-fry vigorously for 1 minute until 80% cooked, then push to one side.","th":"ตั้งกระทะเหล็กไฟแรง ใส่น้ำมัน 2 ช้อนโต๊ะ กลอกให้ทั่ว ใส่กระเทียมและหอมใหญ่ลงเจียว 20 วินาทีจนหอม ใส่เนื้อหมูลงผัดเร็วๆ จนเริ่มสุก ดันเครื่องไว้ขอบกระทะ","ja":"中華鍋を強火で熱し油大さじ2を回し入れます。にんにくと玉ねぎを加え20秒香りを立たせたら、豚肉を投入し1分ほど手早く炒め、8割火が通ったら鍋の端に寄せます。","ko":"웍을 센 불로 강하게 달군 뒤 기름 2큰술을 두릅니다. 다진 마늘과 양파를 넣고 20초간 볶아 향을 낸 후 돼지고기를 넣고 1분간 빠르게 볶아 80% 익힌 뒤 팬 한쪽으로 밀어둡니다."},"durationSeconds":90,"image":"/images/th/khao-phat-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"鍋底熱油滑炒金黃蓬鬆雞蛋","en":"Scramble Fluffy Golden Eggs in Wok Cavity","th":"ตอกไข่ลงก้นกระทะ ยีให้ฟูเหลืองทอง","ja":"空いた鍋底に卵を割り入れ、半熟スクランブルを作る","ko":"빈 공간에 달걀을 깨 넣고 몽글몽글 볶기"},"instruction":{"zh-TW":"在炒鍋中央空出的油池中打入 2 顆雞蛋。待蛋白底面起泡凝固約 5 秒後，用鍋鏟快速劃圈推散蛋黃，將雞蛋炒成大塊金黃膨鬆的半熟滑蛋，隨即與旁邊的肉片快速翻炒合體。","en":"In the cleared center pool of hot oil, crack in 2 fresh eggs. Let the whites bubble and set for 5 seconds, then use spatula in swift circular motions to break yolks into large, airy, golden curds before folding together with the resting pork.","th":"ตอกไข่ 2 ฟองลงตรงกลางกระทะ ปล่อยให้ไข่ขาวเริ่มเซ็ตตัว 5 วินาที ใช้ตะหลิวยีไข่แดงเป็นลิ่มๆ ฟูนุ่ม แล้วตลบหมูข้างกระทะลงมาผัดเคล้าเข้าด้วยกัน","ja":"空いた中央に卵2個を割り入れます。白身がブクブクと固まり始めたらヘラで円を描くように崩し、大粒でふわふわの半熟炒り卵を作ったら、横の肉と合わせます。","ko":"기름이 고인 팬 중앙에 달걀 2개를 깨 넣습니다. 흰자 바닥이 익기 시작하면 5초 뒤 주걱으로 원을 그리며 큼직하고 몽글몽글한 반숙 스크램블을 만들어 고기와 섞어줍니다."},"durationSeconds":60,"image":"/images/th/khao-phat-step3.jpg"},{"stepNumber":4,"title":{"zh-TW":"猛火下香米翻顛裹色，鍋邊嗆魚露盛盤","en":"Blast-Fry Rice, Sear Fish Sauce at Rim & Plate","th":"ใส่ข้าวผัดคลุกเคล้า ปรุงรสน้ำปลาขอบกระทะ เสิร์ฟพร้อมพริกน้ำปลา","ja":"ご飯を投入し強火で煽り、鍋肌からナンプラーを回し入れて仕上げる","ko":"밥을 넣고 센 불에 웍질, 가장자리에 피시소스 둘러 완성"},"instruction":{"zh-TW":"一口氣倒入撥散的香米與芥藍梗片，開足最大火連續顛翻鐵鍋 2 分鐘，用鍋鏟輕壓米粒使其顆顆裹滿蛋香油光。沿著滾燙鍋緣淋入 1.5 大匙魚露、少許生抽與半茶匙糖，激發出強烈焦香鑊氣！撒入蔥花與白胡椒粉翻勻，出鍋倒扣成半球形，搭配黃瓜片與青檸角上桌。","en":"Dump in fluffed jasmine rice and Gai Lan stems. Over maximum heat, toss and press with spatula continuously for 2 minutes until every grain dances and is coated in golden egg sheen. Drizzle 1.5 tbsp fish sauce, soy sauce, and sugar directly against the scorching wok rim to blast caramelizing aroma! Toss with scallions and white pepper, mold into a dome, and serve with cucumber slices and lime.","th":"เทข้าวสวยและก้านคะน้าลงไป เร่งไฟแรงสุด ใช้ตะหลิวกดและสะบัดกระทะ 2 นาทีจนเม็ดข้าวร่วนเงางามสะท้อนแสง ราดน้ำปลา ซีอิ๊วขาว และน้ำตาลทรายรอบขอบกระทะให้เกิดควันหอมไหม้ โรยต้นหอมและพริกไทย คลุกเคล้าตักใส่ถ้วยกดคว่ำลงจาน แนบแตงกวาและมะนาว","ja":"ほぐしたご飯とカイランの茎を一気に入れます。最大火力でヘラを使って米をほぐしながら2分間豪快に鍋をあおります。熱々の鍋肌からナンプラー大さじ1.5、薄口醤油、砂糖を回し入れ、ジュワッと香ばしい煙を米全体にまとわせます。青ネギと白胡椒を散らし、お椀でドーム型に抜いて皿に盛り、きゅうりとライムを添えます。","ko":"풀어둔 밥과 카이란 줄기를 쏟아붓고 최강 화력에서 2분간 주걱으로 밥알을 누르며 힘차게 웍질합니다. 펄펄 끓는 웍 가장자리에 피시소스 1.5큰술, 간장, 설탕을 둘러 불맛을 쫘악 입힙니다! 쪽파와 백후추를 뿌려 섞은 뒤 밥공기에 눌러 담아 접시에 볼록하게 엎어놓고, 오이와 라임을 곁들여 냅니다."},"durationSeconds":150,"image":"/images/th/khao-phat-step4.jpg"}],"troubleshooting":[{"id":"khao-phat-mushy-rice","problem":{"zh-TW":"炒飯黏黏糊糊、軟爛成團，沒有粒粒分明的乾爽感","en":"Fried rice turned out soggy, clumpy and mushy instead of fluffy and dry","th":"ข้าวผัดแฉะ เม็ดข้าวเกาะติดกันเป็นก้อน ไม่ร่วนแห้ง","ja":"チャーハンがベチャッとして米が団子状にくっついてしまった","ko":"볶음밥이 고슬고슬하지 않고 떡처럼 질척거려요"},"cause":{"zh-TW":"1. 使用剛煮好帶有大量水氣的熱飯；2. 鍋子溫度不足導致米飯被醬汁浸泡出水；3. 醬汁直接倒在米心上而非鍋緣。","en":"1. Used freshly steamed warm rice full of moisture; 2. Insufficient wok temperature; 3. Poured sauce directly on top of rice rather than searing on hot wok rim.","th":"ใช้ข้าวร้อนเพิ่งหุงเสร็จ หรือไฟไม่แรงพอทำให้มีน้ำขัง","ja":"1. 炊きたての水分が多い温かいご飯を使った。2. 火力が弱く水分が飛ばなかった。3. 調味料をご飯の真上に直接かけてしまった。","ko":"1. 갓 지은 뜨겁고 수분 많은 밥을 썼거나, 2. 웍 화력이 약했거나, 3. 양념을 밥 위에 직접 부어 밥이 젖었기 때문입니다."},"solution":{"zh-TW":"務必使用冷藏至少 4 小時的隔夜飯；若現煮米飯需比平時減少 15% 水分並攤平吹涼。調味汁必須「沿滾燙鍋邊嗆入」讓水氣瞬間蒸發。","en":"Always use rice chilled in the fridge for at least 4 hours. If cooking fresh rice, reduce water by 15% and spread out on tray to steam dry. Always drizzle sauces around the hot wok perimeter.","th":"ต้องใช้ข้าวแช่เย็นอย่างน้อย 4 ชั่วโมง และราดน้ำปลาที่ข้างกระทะเพื่อให้น้ำระเหยกลายเป็นไอหอม","ja":"必ず冷蔵庫で4時間以上冷やしたご飯を使用してください。炊きたての場合は水を15％減らして固めに炊き、バットに広げて粗熱と水分を飛ばします。調味料は必ず鍋肌から注ぎます。","ko":"반드시 냉장고에서 4시간 이상 식힌 밥을 쓰세요. 즉석에서 밥을 지을 때는 물을 15% 줄이고 쟁반에 넓게 펴서 식혀야 합니다. 양념은 꼭 웍 가장자리에 둘러주세요."}}],"proTips":[{"zh-TW":"泰國街頭靈魂：吃 Khao Phat 必配自製「辣椒魚露 (Prik Nam Pla)」！在小碟中將 2 條切碎的紅綠朝天椒浸泡在 2 大匙特級魚露與少許檸檬汁中。吃前淋上一茶匙，再把新鮮青檸汁擠在炒飯上，酸香、鹹鮮與微辣瞬間在口中引爆！","en":"The Prik Nam Pla Magic: Never eat Khao Phat plain! Mix 2 chopped bird's eye chilies with 2 tbsp fish sauce, a squeeze of lime, and a pinch of sugar in a saucer. Spoon a few drops over the rice with a fresh squeeze of lime for explosive vibrancy!","th":"พริกน้ำปลาคือหัวใจ: ผสมพริกขี้หนูซอย น้ำปลาแท้ และบีบมะนาวนิดหน่อย ตักราดบนข้าวผัดคู่กับบีบมะนาวสด จะช่วยชูรสให้กลมกล่อมจนหยุดกินไม่ได้","ja":"現地の絶対的ルール：カオパットは「プリック・ナムプラー（唐辛子入り魚醤）」とライムで完成します！小皿に刻み唐辛子とナンプラー、少量のレモン汁を合わせ、炒飯に回しかけてライムをキュッと絞ると異次元の美味しさになります！","ko":"프릭남쁠라의 마법: 태국 현지인처럼 드시려면 종지에 송송 썬 쥐똥고추, 피시소스 2큰술, 라임즙을 섞어 볶음밥에 살짝 끼얹고, 생라임을 듬뿍 짜서 드세요! 감칠맛과 상큼함이 폭발합니다!"}]},{"country":"th","id":"moon-shrimp-cake","slug":"moon-shrimp-cake","title":{"zh-TW":"泰式金黃酥脆 月亮蝦餅 (Moon Shrimp Cake)","en":"Thai Crispy Golden Moon Shrimp Cake (Pia Goong Thot)","th":"เปี๊ยะกุ้งทอดพระจันทร์ (ทอดมันกุ้งแผ่นบางกรอบ)","ja":"タイ風サクサク黄金 海老すり身の月餅揚げ（トードマン・クン・パオ）","ko":"골든 크리스피 문 쉬림프 케이크 (달빛 새우전 / 토드만꿍 편)"},"subtitle":{"zh-TW":"100% 鮮蝦摔打極致彈牙，極薄春捲皮金黃香脆，沾裹酸甜紫蘇梅醬","en":"100% springy minced prawn filling between wafer-thin wrappers with sweet plum dip","th":"เนื้อกุ้งเด้งสู้ฟัน ห่อแป้งเปาะเปี๊ยะบางกรอบสีทอง จิ้มน้ำจิ้มบ๊วยเจี่ยหวานอมเปรี้ยว","ja":"海老のすり身がプリップリ！極薄春巻き皮で挟み揚げ、甘酸っぱい梅ソースで","ko":"100% 통새우 살을 치대 탱글탱글한 속을 채운 바삭한 원형 새우전과 매실 소스"},"tagline":{"zh-TW":"台泰名廚共創的傳奇名菜！外皮脆如薄紙、內餡多汁厚實爆汁","en":"A legendary fusion of Thai seafood mastery and paper-thin crispy perfection","th":"แป้งกรอบบางเฉียบ ไส้กุ้งทะลัก กัดคำไหนก็กรุบกรอบ","ja":"外はパリッパリ、中は驚くほどジューシーで弾力のある海老の旨味","ko":"겉은 파사삭 부서지는 피, 속은 육즙 가득 차오르는 새우 살의 환상적 식감"},"heroImage":"/images/th/moon-shrimp-cake.jpg","difficulty":"medium","prepTimeMinutes":25,"cookTimeMinutes":10,"defaultServings":4,"caloriesPerServing":460,"category":"mains","dietaryTags":["classic","pescatarian"],"supportedCookware":["traditional","airFryer"],"culture":{"originRegion":{"zh-TW":"台泰融合飲食文化 (曼谷高級海鮮餐廳盛行)","en":"Thai-Taiwanese Culinary Fusion / Bangkok Seafood Dining","th":"การผสมผสานวัฒนธรรมไทย-ไต้หวัน (ร้านอาหารทะเลชื่อดัง)","ja":"タイ・台湾の食文化融合（バンコクの海鮮名店で人気）","ko":"태국-대만 퓨전 해산물 요리 (방콕 해산물 레스토랑의 명물)"},"famousStreetMarkets":[{"zh-TW":"曼谷 湄南河濱碼頭夜市 (Asiatique The Riverfront)","en":"Asiatique The Riverfront, Bangkok","th":"เอเชียทีค เดอะ ริเวอร์ฟร้อนท์ กรุงเทพฯ","ja":"アジアティーク・ザ・リバーフロント","ko":"아시아티크 더 리버프론트 야시장"},{"zh-TW":"曼谷 喬德夜市 (Jodd Fairs)","en":"Jodd Fairs Night Market, Bangkok","th":"ตลาดจ๊อดแฟร์ กรุงเทพฯ","ja":"ジョッドフェアーズ ナイトマーケット","ko":"조드페어 야시장"}],"historyStory":{"zh-TW":"月亮蝦餅是泰式料理史上一段傳奇的美味佳話！其核心工藝源於泰國正統宮廷點心「金錢蝦餅（Tod Mun Goong ทอดมันกุ้ง）」，主廚們將 100% 純草蝦泥經過反覆摔打至天然蛋白質釋放起膠。隨後為追求極致酥脆與視覺張力，泰菜主廚將彈牙蝦泥填入兩張晶透超薄的圓形春捲皮中，油炸時中央隆起宛如夜空滿月，起鍋後沿直徑八等分切出放射狀金黃三角射線。如今這道菜不僅紅遍全球泰式餐館，更回流至曼谷各大湄南河畔海鮮名店與觀光夜市！","en":"The Moon Shrimp Cake is an iconic culinary legend born from Thai seafood craftsmanship. Inspired by royal Thai Tod Mun Goong (prawn patties), chefs take fresh whole tiger prawns, de-vein and slap the mince vigorously until natural proteins bind into an exceptionally bouncy texture. The mixture is sandwiched between two paper-thin circular spring roll wrappers. When deep-fried, the cake expands like a golden full moon, before being sliced into 8 radiant triangular rays. Served with tangy sweet plum sauce (Nam Chim Buay), it is a world-renowned dining centerpiece.","th":"เปี๊ยะกุ้งทอดพระจันทร์เป็นการพัฒนาต่อยอดจากทอดมันกุ้งโบราณ โดยนำเนื้อกุ้งสดล้วนๆ มานวดและฟาดกับกะละมังจนเหนียวเด้ง นำมาทาลงบนแผ่นแป้งเปาะเปี๊ยะบางเฉียบประกบหน้าหลัง ทอดในน้ำมันร้อนจนพองกลมสีทองคล้ายพระจันทร์เต็มดวง แล้วตัดเป็น 8 ชิ้นสามเหลี่ยม จิ้มน้ำจิ้มบ๊วยเจี่ยหวานสดชื่น เป็นเมนูทะเลที่ได้รับความนิยมไปทั่วโลก","ja":"月亮蝦餅（ムーンシュリンプケーキ）は、タイ王室伝統の「トードマンクン（海老のすり身揚げ）」をルーツとする名物料理です。新鮮なブラックタイガーの身を徹底的に叩いてボウルに打ちつけ、プリプリの弾力を極限まで引き出します。これを2枚の円形極薄春巻きの皮で挟み、油で丸ごと揚げると満月のように黄金色にふっくらと膨らみます。放射状に8等分カットし、甘酸っぱい特製梅ソース（ナムチム・ブワイ）につけて食します。","ko":"문 쉬림프 케이크(달빛 새우전)는 태국 전통 새우 크로켓인 '토드만꿍(Tod Mun Goong)'에서 진화한 요리입니다. 생 새우살을 칼등으로 으깬 뒤 볼에 수십 번 패대기쳐서 단백질의 찰기를 극대화합니다. 얇은 원형 춘권피 2장 사이에 새우 소를 평평하게 채우고 튀겨내면 보름달처럼 둥글고 노릇하게 부풀어 오르며, 8조각으로 썰어 새콤달콤한 태국 매실 소스(남찜부어이)에 찍어 먹습니다."},"thaiScript":"เปี๊ยะกุ้งทอดพระจันทร์","thaiPhonetics":"Pia Goong Thot Phra Chan","audioPronunciationText":"เปี๊ยะกุ้งทอด","nativeName":"เปี๊ยะกุ้งทอดพระจันทร์"},"ingredients":[{"id":"tiger-prawns","name":{"zh-TW":"新鮮鮮草蝦仁 (去腸泥徹底吸乾水分)","en":"Fresh Tiger Prawns (Peeled, deveined & paper-towel dried)","th":"เนื้อกุ้งขาวหรือกุ้งกุลาดำสดแกะเปลือก","ja":"無頭バナメイ海老またはブラックタイガー（背ワタ除去・水気完全除去）","ko":"생 새우살 (내장 제거 후 키친타월로 물기 완벽 건조)"},"amount":350,"unitMetric":"g","unitUS":"12.3 oz","isKeyFlavor":true,"thaiName":"เนื้อกุ้งสด","thaiPronunciation":"Nuea Goong"},{"id":"spring-roll-wrappers","name":{"zh-TW":"薄圓形春捲皮 (越薄越脆)","en":"Thin Round Spring Roll Wrappers (or square cut to circle)","th":"แผ่นแป้งเปาะเปี๊ยะกลมบาง","ja":"極薄春巻きの皮（丸型または正方形を丸くカット）","ko":"원형 얇은 춘권피 2장"},"amount":2,"unitMetric":"piece","unitUS":"2 sheets","isKeyFlavor":true,"thaiName":"แผ่นแป้งเปาะเปี๊ยะ","thaiPronunciation":"Phaeng Po-Pia"},{"id":"egg-white","name":{"zh-TW":"新鮮蛋白 (增加滑順與保水度)","en":"Egg White","th":"ไข่ขาว","ja":"卵白","ko":"달걀흰자"},"amount":1,"unitMetric":"piece","unitUS":"1 white","thaiName":"ไข่ขาว","thaiPronunciation":"Khai Khao"},{"id":"tapioca-starch","name":{"zh-TW":"木薯粉或玉米澱粉","en":"Tapioca Starch or Cornstarch","th":"แป้งมันหรือแป้งข้าวโพด","ja":"片栗粉またはコーンスターチ","ko":"감자전분 또는 옥수수전분"},"amount":1,"unitMetric":"tbsp","unitUS":"1 tbsp","thaiName":"แป้งข้าวโพด","thaiPronunciation":"Phaeng"},{"id":"sesame-oil","name":{"zh-TW":"純香油 (提香去腥)","en":"Pure Sesame Oil","th":"น้ำมันงา","ja":"ごま油","ko":"참기름"},"amount":1,"unitMetric":"tsp","unitUS":"1 tsp","thaiName":"น้ำมันงา","thaiPronunciation":"Nam Man Nga"},{"id":"white-pepper","name":{"zh-TW":"白胡椒粉","en":"Ground White Pepper","th":"พริกไทยขาวป่น","ja":"白胡椒","ko":"백후추"},"amount":0.5,"unitMetric":"tsp","unitUS":"0.5 tsp","thaiName":"พริกไทย","thaiPronunciation":"Prik Thai"},{"id":"fish-sauce","name":{"zh-TW":"特級魚露或鹽","en":"Thai Fish Sauce or Sea Salt","th":"น้ำปลาหรือเกลือ","ja":"ナンプラーまたは塩","ko":"피시소스 또는 소금"},"amount":1,"unitMetric":"tsp","unitUS":"1 tsp","thaiName":"น้ำปลา","thaiPronunciation":"Nam Pla"},{"id":"plum-sauce","name":{"zh-TW":"泰式紫蘇酸梅醬 (Nam Chim Buay / 蘸料靈魂)","en":"Thai Sweet Plum Dipping Sauce (Nam Chim Buay)","th":"น้ำจิ้มบ๊วยเจี่ยหวานอมเปรี้ยว","ja":"タイ特製プラムソース（甘酸っぱい梅ソース）","ko":"태국식 스위트 매실 소스 (남찜부어이)"},"amount":3,"unitMetric":"tbsp","unitUS":"3 tbsp","isKeyFlavor":true,"thaiName":"น้ำจิ้มบ๊วย","thaiPronunciation":"Nam Chim Buay","substitute":{"substituteName":{"zh-TW":"泰式甜辣醬 (Sweet Chili Sauce) 兌 1 小匙蜂蜜或檸檬汁","en":"Sweet Chili Sauce mixed with 1 tsp honey and lemon juice","th":"น้ำจิ้มไก่ผสมน้ำส้มสายชู","ja":"スイートチリソース＋レモン汁少々","ko":"스위트 칠리소스에 꿀과 레몬즙을 살짝 섞은 것"},"ratio":"1:1","explanation":{"zh-TW":"酸梅醬果香清冽微酸，能完美化解炸蝦餅的油脂感。","en":"Sweet plum sauce provides gentle fruity acidity that cuts through fried richness.","th":"ช่วยตัดเลี่ยนของของทอดได้อย่างดีเยี่ยม","ja":"梅の清涼な酸味が揚げ物の油っぽさをスッキリ切ってくれます。","ko":"매실의 새콤달콤한 풍미가 튀김의 기름진 맛을 완벽하게 잡아줍니다."},"whereToBuy":{"zh-TW":"東南亞超市沾醬專櫃","en":"Asian condiment aisle","th":"ซูเปอร์มาร์เก็ตทั่วไป","ja":"アジア食材店 ソース売場","ko":"아시안 식료품점 또는 온라인몰"}}}],"steps":[{"stepNumber":1,"title":{"zh-TW":"鮮蝦吸乾摔打起膠，調味摔出彈性","en":"Dry, Slap & Whip Shrimp Paste for Bouncy Texture","th":"ซับกุ้งให้แห้ง โขลกและฟาดเนื้อกุ้งให้เหนียวเด้ง","ja":"海老の水気を拭き取り、叩いてボウルに打ちつけ弾力を出す","ko":"새우살 물기 제거 후 치대어 탄력 있는 반죽 만들기"},"instruction":{"zh-TW":"蝦仁洗淨後用廚房紙巾「徹底吸乾」表面水分（至關重要！）。三分之二的蝦仁用刀背拍扁再剁成細緻泥狀，另外三分之一切成小蝦丁保留爽脆口感。放入碗中加入蛋白、太白粉、白胡椒、香油與魚露，沿同一方向用力攪拌至起膠，再抓起蝦泥朝碗底用力摔打 20 次，直到質地緊實彈手。","en":"Rinse prawns and THOROUGHLY dry with paper towels (crucial for texture!). Flatten two-thirds of the prawns with the side of a heavy cleaver and mince into fine paste; coarsely chop the remaining one-third into chunks for crunch. Place in bowl with egg white, starch, white pepper, sesame oil, and fish sauce. Vigorously stir in one direction until gelatinous, then lift the paste and slam it down into the bowl 20 times until firm and springy.","th":"ล้างกุ้งและใช้กระดาษทิชชู่ซับน้ำให้แห้งสนิท ใช้มีดตบกุ้ง 2/3 ส่วนให้แบนแล้วสับละเอียด อีก 1/3 ส่วนหั่นเป็นชิ้นหยาบ ผสมไข่ขาว แป้งมัน พริกไทย น้ำมันงา และน้ำปลา คนไปทางเดียวกันจนเหนียว แล้วหยิบขึ้นมาฟาดกับกะละมัง 20 ครั้งจนเนื้อเด้งสู้มือ","ja":"海老は洗ってペーパータオルで「完全に水分を吸い取ります」（最重要！）。2/3は包丁の背で潰して細かく叩き、残りの1/3は食感を残すため粗みじんにします。ボウルに入れ、卵白・片栗粉・白胡椒・ごま油・ナンプラーを加え、同一方向に粘りが出るまで練り上げたら、タネをボウル底に20回力強く打ちつけて弾力を生み出します。","ko":"새우는 씻은 뒤 키친타월로 '물기를 완벽하게' 제거합니다. 2/3 분량은 칼등으로 으깬 뒤 잘게 다지고, 1/3은 식감을 위해 굵게 썹니다. 볼에 달걀흰자, 전분, 백후추, 참기름, 피시소스를 넣고 한 방향으로 끈기가 생길 때까지 치댄 후, 반죽을 들어 볼 바닥에 20번 강하게 내리쳐 탱글탱글한 탄력을 완성합니다."},"durationSeconds":300,"image":"/images/th/moon-shrimp-cake-step1.jpg","crucialTips":{"zh-TW":"蝦仁若殘留水分，內餡會出水鬆散！摔打步驟能讓肌原纖維蛋白徹底網狀化，是蝦餅彈牙多汁的不傳之秘。","en":"Excess moisture makes filling soggy and crumbly. The slapping process mechanically activates myofibrillar proteins for restaurant bounce.","th":"หากกุ้งไม่แห้ง ไส้จะแฉะหลุดร่อน การฟาดเนื้อกุ้งจะช่วยสร้างความเด้งกรุบกรอบตามธรรมชาติ","ja":"水分が残っていると餡がバラバラになります。ボウルに叩きつけることでプロ級のプリプリ食感が生まれます。","ko":"새우에 물기가 남아있으면 소가 질척거리고 분리됩니다. 볼에 내리치는 과정이 탱글한 식감의 핵심입니다."}},{"stepNumber":2,"title":{"zh-TW":"鋪滿蝦泥封皮，均勻排氣扎孔防鼓包","en":"Spread Filling, Sandwich Wrappers & Prick Vents","th":"เกลี่ยไส้กุ้งประกบแผ่นแป้ง เจาะรูระบายอากาศ","ja":"春巻きの皮に海老餡を平らに広げ、空気抜きの穴を開ける","ko":"춘권피에 새우 소를 평평하게 펴 바르고 구멍 뚫기"},"instruction":{"zh-TW":"將一張圓形春捲皮平鋪在盤中，抹少許蛋白或水於外緣。將彈牙蝦泥倒在中心，用抹刀由內向外均勻推平至厚度約 1-1.5 公分，邊緣留 0.5 公分空白。蓋上第二張春捲皮，用手掌由中心向外輕壓擠出所有氣泡並貼緊。最後拿牙籤在正反兩面密密麻麻扎上 30-40 個小細孔！","en":"Lay one round wrapper flat on a tray and moisten the outer rim. Mound the shrimp paste in the center and spread evenly outward with an offset spatula to a thickness of 1-1.5 cm, leaving a 0.5 cm border. Cover with second wrapper, pressing gently from center to perimeter to eliminate air pockets. CRUCIAL: Pierce 30-40 small pinholes on both sides using a toothpick!","th":"วางแผ่นเปาะเปี๊ยะแผ่นแรกลง ทาขอบด้วยไข่ขาว เกลี่ยไส้กุ้งให้เรียบเสมอกันหนาประมาณ 1-1.5 ซม. ปิดทับด้วยแผ่นที่สอง ใช้มือกดไล่ฟองอากาศให้แนบสนิท ใช้ไม้จิ้มฟันจิ้มรูพรุนทั่วทั้งสองด้าน 30-40 รู","ja":"トレイに春巻きの皮を1枚敷き、フチに卵白を塗ります。中央に海老餡をのせ、ヘラで厚さ1〜1.5cmに均一に平らに伸ばします。もう1枚の皮を重ね、中心から外側へ優しく押して中の空気を抜きます。最重要：爪楊枝で両面に30〜40箇所プツプツと小さな穴を開けます！","ko":"쟁반에 춘권피 1장을 깔고 가장자리에 달걀흰자를 바릅니다. 새우 소를 올려 두께 1~1.5cm가 되도록 평평하게 펴 바릅니다. 다른 춘권피로 덮고 손바닥으로 중심에서 바깥쪽으로 부드럽게 눌러 공기를 완전히 뺍니다. 【핵심 비법】 이쑤시개로 앞뒷면에 30~40개의 구멍을 촘촘히 뚫어줍니다!"},"durationSeconds":180,"image":"/images/th/moon-shrimp-cake-step2.jpg","crucialTips":{"zh-TW":"務必扎孔排氣！蝦肉受熱會產生高溫蒸汽，如果沒扎孔，春捲皮會瞬間膨脹成氣球與蝦泥分離脫落！","en":"You MUST prick holes! As steam expands during cooking, unvented wrappers will balloon up like a football and detach from the shrimp!","th":"ต้องเจาะรูระบายอากาศเสมอ! มิฉะนั้นไอน้ำข้างในจะดันจนแผ่นแป้งพองบวมหลุดออกจากเนื้อกุ้ง","ja":"必ず穴を開けてください！穴を開けないと揚げた時に水蒸気で皮が風船のように膨らみ、餡から剥がれてしまいます。","ko":"반드시 구멍을 뚫어야 합니다! 새우가 익으면서 생기는 수증기가 빠져나가지 못하면 춘권피가 풍선처럼 부풀어 새우 살과 껍질이 분리됩니다."}},{"stepNumber":3,"title":{"zh-TW":"中火慢炸定型金黃，大火逼油逼出極致酥脆","en":"Fry to Blistered Golden Crunch (or Air Fry)","th":"ทอดไฟกลางให้สุกสีทอง เร่งไฟแรงไล่น้ำมันให้กรอบสะท้าน","ja":"中火でじっくりキツネ色に揚げ、仕上げに強火で油を切る（エアフライヤー対応）","ko":"중불에 노릇하게 튀겨내고 센 불에 바삭하게 기름 빼기 (에어프라이어 가능)"},"instruction":{"zh-TW":"油鍋加熱至 160°C（竹筷插下四周冒均勻小細泡）。雙手平托蝦餅滑入油鍋中，轉中火慢炸約 3 分鐘至定型變硬，翻面續炸 2-3 分鐘至兩面均勻微金黃。最後轉大火拉高油溫至 180°C 猛炸 30 秒，逼出外皮油脂並炸出金黃微凸的酥脆氣泡，立刻撈出立起瀝油。","en":"Heat oil in a wide pan to 160°C (320°F - wooden chopstick bubbles gently). Gently slide the cake into oil, frying over medium heat for 3 minutes until firm, flip and fry for 2-3 minutes until golden. Raise heat to 180°C (356°F) for final 30 seconds to expel oil and blister the skin into crackling perfection, then lift and drain upright.","th":"ตั้งกระทะน้ำมันที่ 160°C ค่อยๆ หย่อนแผ่นกุ้งลงทอดด้วยไฟกลาง 3 นาทีจนอยู่ตัว พลิกกลับด้านทอดต่อ 2-3 นาทีจนเหลือง เร่งไฟแรงสุด 30 วินาทีเพื่อไล่น้ำมันและทำให้แป้งพองกรอบ ตักขึ้นพักสะเด็ดน้ำมันในแนวตั้ง","ja":"揚げ油を160℃に熱し、海老餅をそっと滑り込ませます。中火で3分揚げて固まったら裏返し、さらに2〜3分揚げて両面を薄いきつね色にします。最後に強火にして油温を180℃まで上げ、30秒間表面をカリッと油切りし、立てかけて油を切ります。","ko":"팬에 식용유를 160도로 달군 후 새우전을 부드럽게 밀어 넣습니다. 중불에서 3분간 튀겨 형태가 잡히면 뒤집어 2~3분간 튀깁니다. 마지막 30초 동안 센 불로 온도를 180도까지 올려 표면의 기름을 쫙 빼며 바삭한 기포를 낸 뒤, 건져내 세워서 기름을 뺍니다."},"durationSeconds":360,"image":"/images/th/moon-shrimp-cake-step3.jpg","cookwareVariations":[{"cookware":"airFryer","tempAndSetting":"190°C (375°F) for 12 mins","instructionOverride":{"zh-TW":"【氣炸鍋模式】：在蝦餅雙面用刷子均勻刷上一層食用油。氣炸鍋預熱 190°C，放入炸籃氣炸 8 分鐘，翻面再刷少許油氣炸 3-4 分鐘，直至雙面金黃起酥膨脹，完全不油膩！","en":"【Air Fryer Mode】: Generously brush both sides of shrimp cake with cooking oil. Preheat air fryer to 190°C (375°F). Air fry for 8 minutes, flip, brush lightly with oil and cook for another 3-4 minutes until blistered, golden and crispy!","th":"【หม้อทอดไร้น้ำมัน】: ทาน้ำมันพืชให้ทั่วทั้งสองด้าน วอร์มหม้อทอดที่ 190°C นำลงทอด 8 นาที พลิกด้านทาซ้ำอีกนิด ทอดต่อ 3-4 นาทีจนเหลืองกรอบน่ารับประทาน ไร้น้ำมันส่วนเกิน","ja":"【エアフライヤーモード】：海老餅の両面にハケで薄く油を塗ります。190℃に予熱したエアフライヤーで8分焼き、裏返して再度薄く油を塗り3〜4分、きつね色に膨らむまで加熱します。驚くほどヘルシーでカリカリ！","ko":"【에어프라이어 모드】: 새우전 양면에 식용유를 붓으로 골고루 발라줍니다. 190도로 예열된 에어프라이어에 넣고 8분간 조리한 뒤, 뒤집어서 기름을 살짝 덧발라 3~4분간 더 구워내면 기름기 쏙 빠진 바삭한 새우전이 완성됩니다!"}}]},{"stepNumber":4,"title":{"zh-TW":"俐落分切八角滿月射線，佐泰式酸甜梅子醬","en":"Cut into 8 Radiant Wedges & Serve with Plum Sauce","th":"ตัดแบ่ง 8 ชิ้นรูปสามเหลี่ยมพระจันทร์ เสิร์ฟคู่กับน้ำจิ้มบ๊วย","ja":"満月のように8等分に放射線状カットし、特製梅ソースを添える","ko":"방사형으로 8등분하여 새콤달콤 매실 소스와 함께 담아내기"},"instruction":{"zh-TW":"趁熱將蝦餅移至熟食砧板上，拿鋒利的刀由中心直切成十字四等分，再各對切成八道金黃三角扇形。擺盤時將三角尖端朝外或排成圓盤滿月造型，正中央放上一碟泰式紫蘇酸梅醬（Nam Chim Buay）即可趁熱享用！","en":"Transfer piping hot shrimp cake to a cutting board. Using a sharp chef knife, cut cleanly in a cross into quarters, then diagonally into 8 radiating triangular wedges. Arrange the crisp wedges radiating outward like a full moon around a bowl of Thai sweet plum dipping sauce (Nam Chim Buay). Serve immediately while blazing hot!","th":"วางแผ่นกุ้งลงบนเขียง ใช้มีดคมๆ กดตัดเป็น 4 ส่วน แล้วตัดทะแยงมุมแบ่งเป็น 8 ชิ้นสามเหลี่ยม จัดเรียงลงจานกลมให้ปลายแหลมชี้ออก วางถ้วยน้ำจิ้มบ๊วยเจี่ยไว้ตรงกลาง เสิร์ฟร้อนๆ กรอบฟินทันที","ja":"熱々のうちにまな板へ移し、よく切れる包丁で十字に4等分、さらに対角線で8枚の三角形にサクッと切り分けます。円形に並べて中央にタイ特製梅ソース（ナムチム・ブワイ）の小皿を置き、揚げたてのカリカリ食感を楽しみます！","ko":"뜨거울 때 도마에 올리고 잘 드는 칼로 십자 모양 4등분 후, 대각선으로 다시 잘라 총 8조각의 방사형 삼각 피스를 만듭니다. 원형 접시에 둥글게 둘러 담고 가운데에 태국식 스위트 매실 소스(남찜부어이)를 곁들여 바로 드세요!"},"durationSeconds":60,"image":"/images/th/moon-shrimp-cake-step4.jpg"}],"troubleshooting":[{"id":"moon-shrimp-cake-layer-separation","problem":{"zh-TW":"油炸過程中外皮鼓大包、炸好後春捲皮脫落分離","en":"Skin puffed up into a balloon during frying and detached from filling","th":"แผ่นแป้งพองลมหลุดลอยแยกออกจากเนื้อกุ้ง","ja":"揚げている間に皮が風船のように膨らみ、海老餡から剥がれてしまった","ko":"튀기는 동안 피가 풍선처럼 부풀어 오르고 속과 껍질이 분리됐어요"},"cause":{"zh-TW":"1. 春捲皮正反面未用牙籤扎透排氣孔；2. 封皮時皮與蝦泥之間殘留空氣未用手掌推平；3. 油溫過高外皮瞬間熟硬鼓脹。","en":"1. Forgot to prick vent holes with a toothpick; 2. Air pockets trapped between skin and filling; 3. Initial oil temperature was too high causing instant surface ballooning.","th":"1. ไม่ได้เจาะรูพรุนบนแผ่นแป้ง; 2. มีฟองอากาศติดอยู่ด้านใน; 3. น้ำมันร้อนจัดเกินไปตั้งแต่แรก","ja":"1. 爪楊枝で空気穴を開けていなかった。2. 皮を重ねた際に中央から空気を押し出していなかった。3. 油温が高すぎた。","ko":"1. 이쑤시개로 구멍을 뚫지 않았거나, 2. 조립 시 피와 새우 사이에 공기가 갇혔거나, 3. 기름 온도가 너무 높아 급격히 팽창했기 때문입니다."},"solution":{"zh-TW":"封皮時手掌由中心往外撫平推擠出所有空氣，務必拿牙籤在正反兩面密密麻麻戳滿 30-40 個小孔，並以 160°C 中溫入鍋下油。","en":"Always smooth out air pockets from center to edges with palms, prick 30-40 holes across both surfaces, and slide gently into medium 160°C (320°F) oil.","th":"ใช้มือกดรีดอากาศออกให้หมด และต้องใช้ไม้จิ้มฟันจิ้มรูระบายอากาศ 30-40 รูทั่วแผ่นเสมอ","ja":"皮を貼る際は中心から手のひらで空気を完全に押し出し、両面に爪楊枝で30〜40箇所の穴を開け、160℃の油に静かに入れてください。","ko":"손바닥으로 가운데부터 밀어 공기를 완전히 빼주고, 앞뒤로 이쑤시개 구멍을 30~40개 촘촘히 뚫은 뒤 160도 중온에서 튀기기 시작하세요."}}],"proTips":[{"zh-TW":"沾醬與擺盤之神：月亮蝦餅的最佳搭檔絕對是透亮的「泰式紫蘇酸梅醬 (Nam Chim Buay)」！微酸甘甜的梅子香氣能將蝦肉天然的甘甜提升到極致。趁熱用刀切時請「一刀壓切到底」聽見喀嚓酥脆聲，切面平整不破皮！","en":"Chef Cutting & Dip Secret: Pair with authentic Thai Sweet Plum Sauce (Nam Chim Buay). The gentle tart sweetness heightens the natural seafood sugars. When slicing, press straight down firmly with a single stroke to hear the audible crunch without crushing the layers!","th":"เทคนิคเสิร์ฟระดับภัตตาคาร: ต้องทานคู่กับน้ำจิ้มบ๊วยเจี่ยเท่านั้น ความเปรี้ยวหวานละมุนจะขับรสหวานธรรมชาติของเนื้อกุ้งออกมาอย่างมหัศจรรย์ เวลาตัดให้ใช้มีดกดครั้งเดียวลงตรงๆ แป้งจะไม่แตกเละ","ja":"名店の盛り付けとソース：月亮蝦餅には「プラムソース（ナムチム・ブワイ）」が絶対の相棒です。梅の甘酸っぱさが海老の甘味を何倍にも引き立てます。切る際は包丁を前後にギコギコ動かさず、上から「一気に押し切り」すると美しい断面になります！","ko":"플레이팅 및 소스 비법: 달빛 새우전은 무조건 '스위트 매실 소스(남찜부어이)'와 함께 드셔야 본고장의 맛이 납니다. 자를 때는 칼을 톱질하듯 썰지 말고 위에서 아래로 '한 번에 꾹 눌러서' 썰어야 피가 깨지지 않고 단면이 깨끗하게 나옵니다!"}]}];
